window.__Q=window.__Q||{};window.__Q["tcm/3/A1"]=[{"q":"既清实热，又清虚热的药物是","o":["决明子","栀子","石膏","知母","寒水石"],"a":3,"e":"知母苦甘寒，归肺胃肾经，既清热泻火以除实热，又滋阴润燥以退骨蒸虚热，实热虚热兼顾。石膏、寒水石、栀子专清气分实热，无滋阴之力；决明子清肝明目、润肠通便，均不能清虚热"},{"q":"下列除哪项外，均为龟甲的功效","o":["滋阴潜阳","益肾强骨","养血补心","固经止崩","软坚散结"],"a":4,"e":"龟甲滋阴潜阳、益肾强骨、养血补心、固经止崩，为滋阴潜阳要药。软坚散结是鳖甲、牡蛎之长，鳖甲并能退虚热，牡蛎咸寒软坚，龟甲无此功"},{"q":"蝉蜕配胖大海除清肺外，又能","o":["通鼻窍","止咳平喘","凉血止血","清利头目","利咽开音"],"a":4,"e":"蝉蜕利咽开音、疏散风热，胖大海清肺利咽、开音润肠，两者相须，善治咽喉肿痛、声音嘶哑。通鼻窍为苍耳子、辛夷之职；止咳平喘属杏仁、苏子；凉血止血、清利头目均非二药所长"},{"q":"香附的功效为","o":["理气调经","理气健脾","理气散寒","理气杀虫","理气燥湿"],"a":0,"e":"香附疏肝解郁、理气宽中、调经止痛，主入肝经，为妇科调经要药，称“气病之总司，女科之主帅”。理气健脾为陈皮所主；理气燥湿属苍术、厚朴；理气杀虫、散寒均非香附之功"},{"q":"既能平抑肝阳，又能疏肝解郁，祛风明目、止痒的药是","o":["柴胡","薄荷","蒺藜","白僵蚕","石决明"],"a":2,"e":"蒺藜平肝解郁、活血祛风、明目止痒，既能平抑肝阳又能疏肝解郁，治肝阳上亢、肝郁气滞及风热目痒。柴胡、薄荷虽疏肝解表，不能平肝潜阳、明目止痒；石决明平肝明目而无疏肝解郁、祛风止痒"},{"q":"入汤剂需后下的药物是","o":["磁石、牡蛎","蒲黄、海金沙","薄荷、白豆蔻","人参、鹿茸","芒硝、阿胶"],"a":2,"e":"薄荷、白豆蔻含挥发油，久煎则有效成分散失，故入汤剂宜后下。磁石、牡蛎质重难溶宜先煎；蒲黄、海金沙细小宜包煎；人参、鹿茸贵重宜另煎；芒硝溶化、阿胶烊化，均非后下"},{"q":"有清热凉血、活血化瘀之功，常用治肠痈的药物是","o":["玄参","金银花","牡丹皮","生地黄","姜黄"],"a":2,"e":"牡丹皮清热凉血、活血化瘀，能散肠中瘀热，为治肠痈腹痛要药。玄参清热凉血解毒而不活血；生地黄清热凉血养阴；金银花清热解毒消痈；姜黄活血行气通经，均无凉血活血治肠痈之能"},{"q":"下列功效中，属于对症治疗的是","o":["止血","安神","开窍","助阳","泻下"],"a":0,"e":"止血直接制止出血，针对症状本身，属对症治疗。助阳补益虚损属扶正固本，泻下驱逐实邪属祛邪去因，二者针对病因病机，为对因治疗；安神、开窍亦多针对痰迷、神失所养之病机"},{"q":"不属于阿胶功效的是","o":["补血","滋阴","清肝","润肺","止血"],"a":2,"e":"阿胶补血、滋阴、润肺、止血，为补血止血要药，治血虚萎黄、虚劳咳血、崩漏。清肝泻火是龙胆草、夏枯草、青黛之功，阿胶无清肝作用"},{"q":"均归心经的补阴药是","o":["麦冬、百合、龟甲","石斛、天冬、百合","龟甲、黄精、鳖甲","北沙参、玉竹、桑椹","枸杞子、女贞子、墨旱莲"],"a":0,"e":"麦冬归心肺胃经，百合归心肺经，龟甲归肝肾心经，三者均入心经且为补阴药。石斛、天冬归胃肺肾经，不入心；黄精、枸杞子、女贞子、墨旱莲主入肝肾，桑椹、玉竹、北沙参亦不以心经为归"},{"q":"解鱼蟹中毒最宜用的药物是","o":["葛根，菊花","紫苏叶，生姜","生姜，葛根","生姜，白芷","紫苏叶，半夏"],"a":1,"e":"紫苏叶、生姜均能解鱼蟹毒，治食鱼蟹后吐泻腹痛，紫苏兼发表散寒，生姜兼温中止呕。葛根解肌退热、生津；菊花疏散风热、平肝；白芷祛风通窍；半夏燥湿化痰、降逆止呕，均无解鱼蟹毒之功"},{"q":"砒石内服用治冷哮的每次用量是","o":["0、001～0、002g","0、002～0、004g","0、04～0、06g","0、06～0、1g","0、1～0、2g"],"a":1,"e":"砒石有大毒，内服每次0、002～0、004g，多入丸散，治冷哮、疟疾。0、001g以下量过小难奏效，0、04g以上已近中毒量，0、1g以上可致死亡，均非冷哮常用量"},{"q":"桑叶与菊花均具有的功效是","o":["疏肝解郁","利咽开音","清肺润燥","清热解毒","清肝明目"],"a":4,"e":"桑叶疏散风热、清肺润燥、清肝明目；菊花疏散风热、平肝明目、清热解毒，二者共有的功效是清肝明目，治目赤昏花。疏肝解郁属柴胡、薄荷；利咽开音属蝉蜕、胖大海；清肺润燥仅桑叶有；清热解毒仅菊花有"},{"q":"芦根、栀子、淡竹叶均具有的功效是","o":["止咳","止血","解毒","利尿","生津"],"a":3,"e":"芦根清热生津、除烦止呕兼利尿；栀子清热利湿、泻火除烦；淡竹叶清热除烦、利尿，三药均利尿，治热淋水肿。生津为芦根所独有；解毒为栀子所兼；止咳、止血均非三药共有"},{"q":"下列除哪项外均为苦味药的作用","o":["清热泻火","泄降逆气","收敛固涩","通泻大便","燥湿坚阴"],"a":2,"e":"苦味能泄能燥能坚，可清热泻火、泄降逆气、通泻大便、燥湿坚阴。收敛固涩是酸味药的作用，如五味子、山茱萸，苦味无此效"},{"q":"药性辛、热，有毒，并具有补肾阳、强筋骨、祛寒湿功效的药物是","o":["续断","杜仲","仙茅","巴戟天","淫羊藿"],"a":2,"e":"仙茅辛热有毒，补肾阳、强筋骨、祛寒湿，治肾阳不足、寒湿痹痛。续断、杜仲补肝肾强筋骨但性温无毒；巴戟天、淫羊藿补肾阳祛风湿，性温而不热、无毒"},{"q":"能温中散寒，行气止痛的药物是","o":["丁香","草果","厚朴","吴茱萸","荜澄茄"],"a":4,"e":"荜澄茄辛温，温中散寒、行气止痛，治胃寒脘腹冷痛、呕吐。丁香温中降逆、补肾助阳；草果燥湿温中、除痰截疟；厚朴下气除满、燥湿消痰；吴茱萸散寒止痛、降逆止呕、助阳止泻，均非温中行气止痛之专药"},{"q":"治带下病，宜选用","o":["百部","白果","款冬花","桑白皮","马兜铃"],"a":1,"e":"白果敛肺化痰定喘、止带缩尿，为治带下白浊、尿频遗尿常用药。百部润肺止咳杀虫；款冬花润肺化痰止咳；桑白皮泻肺平喘、利水消肿；马兜铃清肺化痰止咳，均无止带之功"},{"q":"补骨脂、蛤蚧的相同功效是","o":["纳气平喘","消风祛斑","益气养血","温经止血","固肾安胎"],"a":0,"e":"补骨脂补肾助阳、纳气平喘、温脾止泻；蛤蚧补肺益肾、纳气平喘，二者均入肾，治肾不纳气之虚喘。消风祛斑、温经止血、固肾安胎、益气养血分别属防风、艾叶、杜仲、黄芪之类，非二药共有"},{"q":"牛膝配伍石膏、知母主要用于","o":["月经不调、痛经闭经","肝肾亏虚之筋骨无力","风寒湿痹之手足麻木","胃火上炎之口舌生疮","血热妄行之吐血、衄血"],"a":3,"e":"牛膝善引血下行、引火下行，配石膏、知母清胃泻火，使上炎之火下调，治胃火上炎之口舌生疮、牙痛。月经不调、闭经属瘀血或气血失调，非此配伍所主；肝肾亏虚筋骨无力宜补肝肾药；血热吐衄当凉血，均非本配伍所宜"},{"q":"生姜能减轻或清除半夏的毒性，这种配伍关系称为","o":["相须","相使","相恶","相反","相杀"],"a":4,"e":"相杀指一种药物能减轻或消除另一种药物的毒副作用，生姜能解半夏、天南星之毒，故为相杀。相须为性能相近药同用增效；相使为助药增强主药功效；相恶为互相牵制而减效；相反为合用反增毒性，均不符"},{"q":"既能祛风解表，又能止痉，用治破伤风的药物是","o":["荆芥","防风","独活","紫苏叶","羌活"],"a":1,"e":"防风祛风解表、胜湿止痛、止痉，为治破伤风抽搐常用药，药性平和，风寒风热均可。荆芥解表散风、透疹止血但无止痉；独活、羌活祛风湿止痛，主散下焦、上半身风湿；紫苏叶发表散寒、行气宽中，均无止痉治破伤风之功"},{"q":"归肝经的药物不包括","o":["夏枯草","密蒙花","青葙子","决明子","鸭跖草"],"a":4,"e":"鸭跖草归肺胃小肠经，清热解毒、利水消肿，不入肝经。夏枯草清肝明目散结、密蒙花清肝养肝明目、青葙子清肝明目、决明子清肝明目润肠，四者均为归肝经之清热明目药"},{"q":"既能平肝潜阳，又能清肝明目的药物是","o":["柴胡","磁石","牡蛎","赭石","石决明"],"a":4,"e":"石决明咸寒，平肝潜阳、清肝明目，为治肝阳上亢、目赤昏花要药。磁石、牡蛎、赭石虽能潜阳，但无清肝明目之功；柴胡疏肝解郁、升举阳气，反升提肝阳，非潜阳之品"},{"q":"平性药的含义是指","o":["寒、热之性不甚明显的药物","作用比较缓和的药物","升浮、沉降作用趋向不明显的药物","性味甘淡的药物","寒热之性均具备的药物"],"a":0,"e":"平性指药物寒热偏性不明显，作用较缓和，但仍属四气之一，并非无寒热之性。作用缓和是平性的表现而非定义；升降浮沉不明显指作用趋向；甘淡为味而非性；寒热均具备之说不成立"},{"q":"治寒疝腹痛，首选","o":["干姜","花椒","丁香","高良姜","小茴香"],"a":4,"e":"小茴香辛温，散寒止痛、理气和胃，主入肝肾，为治寒疝腹痛之要药，兼治少腹冷痛、痛经。干姜温中散寒、回阳通脉；花椒温中止痛、杀虫止痒；丁香温中降逆；高良姜温胃散寒止痛，均非寒疝首选"},{"q":"功能温经止血，为妇科常用药的是","o":["小蓟","艾叶","三七","茜草","地榆"],"a":1,"e":"艾叶辛温，温经止血、散寒调经、安胎，为妇科温经止血要药，治虚寒崩漏、胎动不安。小蓟、地榆凉血止血，治血热出血；三七化瘀止血；茜草凉血止血活血，均非温经之品"},{"q":"关于药物的基本作用，说法错误的是","o":["祛邪去因","扶正固本","注重配伍","协调脏腑功能","纠正阴阳盛衰"],"a":2,"e":"药物基本作用为祛邪去因、扶正固本、协调脏腑功能、纠正阴阳盛衰。注重配伍是组方用药的方法原则，不属于药物本身的基本作用范畴"},{"q":"关于副作用说法错误的是","o":["是指药物用量过多时产生的不适反应","一般较轻微","停药后可消失","与治疗需求无关","对机体危害不大"],"a":0,"e":"副作用指在常规治疗剂量下出现的与治疗目的无关的不适反应，一般较轻微，停药后可消失，与治疗需求无关，对机体危害不大。用量过多产生的不适反应属毒性反应，非副作用"},{"q":"为治寒滞肝经诸痛之主药，用于寒滞肝经之寒疝腹痛，厥阴头痛，寒凝痛经及寒湿脚气肿痛等证的药物是","o":["草果","豆蔻","乌药","木瓜","吴茱萸"],"a":4,"e":"吴茱萸辛热苦，散寒止痛、降逆止呕、助阳止泻，主入肝经，为治寒滞肝经诸痛之主药，寒疝腹痛、厥阴头痛、痛经、寒湿脚气皆宜。草果燥湿温中；豆蔻化湿行气温中；乌药行气止痛温肾；木瓜舒筋活络化湿，均非寒滞肝经之主药"},{"q":"首创按药物自然属性分类的本草著作是","o":["《神农本草经》","《本草纲目拾遗》","《证类本草》","《本草经集注》","《新修本草》"],"a":3,"e":"陶弘景《本草经集注》首创按药物自然属性分类，分玉石、草木、虫兽、果、菜、米食等类。《神农本草经》按上中下三品分类；《证类本草》为唐慎微所撰；《本草纲目拾遗》为赵学敏补充之作；《新修本草》为唐代官修本草"},{"q":"能补火助阳，散寒止痛，温通经脉，引火归元的药物是","o":["桂枝","葛根","肉桂","胡椒","升麻"],"a":2,"e":"肉桂辛甘大热，补火助阳、散寒止痛、温通经脉、引火归元，为温里补火之要药。桂枝温通经脉、助阳化气，无补火助阳、引火归元之力；葛根解肌升津；胡椒温中散寒；升麻发表升阳，均无此功"},{"q":"狗脊的功效是","o":["祛风湿，壮筋骨，通经络","祛风湿，强筋骨，补肾阳","祛风湿，强筋骨，安胎元","祛风湿，强筋骨，利水","祛风湿，补肝肾，强腰膝"],"a":4,"e":"狗脊苦甘温，祛风湿、补肝肾、强腰膝，治肝肾不足之腰膝酸软、风湿痹痛。续断补肝肾强筋骨；巴戟天、仙茅补肾阳强筋骨；威灵仙、秦艽祛风湿通经络，均无补肝肾、强腰膝之全效"},{"q":"素有“夏月麻黄”之称的药物是","o":["白芷","香薷","羌活","桂枝","防风"],"a":1,"e":"香薷辛微温，发汗解表、化湿和中、利水消肿，夏月感寒湿者用之，故称“夏月麻黄”。白芷祛风通窍、止痛排脓；羌活、防风祛风胜湿；桂枝温通经脉、助阳化气，均无化湿和中、代麻黄解夏月之表之功"},{"q":"竹茹的功效是","o":["止咳化痰，降逆和胃","化痰行水，降逆止呕","清热化痰，除烦止呕","燥湿化痰，降逆止呕","温肺止咳，和胃止呕"],"a":2,"e":"竹茹甘微寒，清热化痰、除烦止呕，治痰热咳嗽、胃热呕哕、心烦失眠。半夏燥湿化痰、降逆止呕，性温，治湿痰寒饮；旋覆花降气化痰止呕；生姜温肺止咳和胃止呕，均非清热化痰之品"},{"q":"既能凉血止血，又能活血通经的药物是","o":["大蓟","白及","茜草","血余炭","苎麻根"],"a":2,"e":"茜草苦寒，凉血止血、活血化瘀兼能通经，止血而不留瘀，治血热妄行之出血兼瘀滞。大蓟凉血止血、散瘀消痈但无通经；白及收敛止血、消肿生肌；血余炭收敛止血、化瘀利尿；苎麻根凉血止血、安胎清热，均非活血通经之品"},{"q":"肠中蕴热，致便血、痔血，首选","o":["小蓟","大蓟","槐花","茜草","苎麻根"],"a":2,"e":"槐花苦微寒，凉血止血、清肝泻火，主入大肠经，为治肠中蕴热之便血、痔血要药。小蓟、大蓟凉血止血但偏治血淋或痈肿；茜草凉血止血兼活血；苎麻根凉血止血兼安胎，均非痔血便血之首选"},{"q":"下列除哪项以外均是乌药的主治病证","o":["遗尿","痛经","寒疝腹痛","寒凝腹胀","寒湿痹痛"],"a":4,"e":"乌药辛温，行气止痛、温肾散寒，治寒疝腹痛、经行腹痛、遗尿尿频、胸腹胀痛。寒湿痹痛当用独活、威灵仙、附子等祛风湿散寒药，乌药无祛风湿通痹之功"},{"q":"桑白皮与葶苈子均有的功效是","o":["泻肺平喘，化瘀消瘿","清热化痰，息风止痉","泻肺平喘，利水消肿","软坚散结，利尿通淋","清肺化痰，清肠疗痔"],"a":2,"e":"桑白皮泻肺平喘、利水消肿，清泻肺热；葶苈子泻肺平喘、利水消肿，力猛，治肺壅喘满、水肿。化瘀消瘿属莪术、海藻；息风止痉属羚羊角、僵蚕；软坚散结、利尿通淋属海藻、海金沙；清肠疗痔属槐花、地榆，均非二药共有"},{"q":"大青叶的功效是","o":["凉血止血","凉血消班","凉血止痢","凉血活血","凉血安神"],"a":1,"e":"大青叶苦寒，清热解毒、凉血消班，治温毒发斑、喉痹痄腮。凉血止血属大蓟、地榆；凉血止痢属白头翁；凉血活血属赤芍、牡丹皮；凉血安神非大青叶所有，故以凉血消班为其特征功效"},{"q":"砒石内服功效是","o":["通便","劫痰平喘","温肾壮阳","杀虫止痛","祛风燥湿"],"a":1,"e":"砒石大毒，外用蚀疮去腐，内服劫痰平喘、截疟，治寒痰哮喘、疟疾。杀虫止痛、祛风燥湿、通便、温肾壮阳均非砒石内服功效，且砒石用量极小，须严格控制"},{"q":"具化浊降脂作用，可治高脂血症的药物是","o":["茯苓","泽泻","猪苓","香加皮","冬瓜皮"],"a":1,"e":"泽泻甘淡寒，利水渗湿、泄热、化浊降脂，治水肿、高脂血症。茯苓、猪苓利水渗湿但无化浊降脂；香加皮祛风湿强筋骨；冬瓜皮利水消肿，均无降脂之功"},{"q":"能利水消肿，治水肿、脚气肿痛的药物是","o":["青皮","陈皮","苦楝皮","合欢皮","大腹皮"],"a":4,"e":"大腹皮辛微温，行气宽中、行水消肿，治胃肠气滞、水肿、脚气肿痛。青皮破气疏肝；陈皮理气健脾燥湿；苦楝皮杀虫疗癣；合欢皮解郁安神、活血消肿，均无利水消肿治脚气之功"},{"q":"细辛的功效不包括","o":["祛风散寒","通窍","止痛","温中止呕","温肺化饮"],"a":3,"e":"细辛解表散寒、祛风止痛、通窍、温肺化饮，治风寒表证、头痛、鼻塞、寒痰咳喘。温中止呕是生姜、半夏、丁香之功，细辛无温中止呕之效"},{"q":"凉血不留瘀，活血不动血，又能退无汗骨蒸的药物是","o":["赤芍","白薇","生地黄","牡丹皮","郁金"],"a":3,"e":"牡丹皮清热凉血、活血散瘀，善退无汗骨蒸，治温毒发斑、经闭痛经、痈肿疮毒。赤芍清热凉血、散瘀止痛但无退骨蒸；白薇凉血清虚热，有汗无汗皆可；生地黄清热凉血养阴；郁金活血行气、清心凉血，均无凉血不留瘀、活血不动血、退无汗骨蒸之特长"},{"q":"血热所致的脱发，宜选用的药物是","o":["槐花","蒲黄","白及","侧柏叶","白茅根"],"a":3,"e":"侧柏叶苦涩微寒，凉血止血、化痰止咳、生发乌发，治血热妄行之脱发、须发早白。槐花凉血止血、清肝泻火；蒲黄收敛止血、化瘀；白及收敛止血、消肿生肌；白茅根凉血止血、清热利尿，均无生发乌发之功"},{"q":"均可治疗湿热证的药组是","o":["黄芩、金银花","黄连、野菊花","黄柏、大血藤","黄芩、穿心莲","龙胆、败酱草"],"a":3,"e":"黄芩苦寒，清热燥湿、泻火解毒，清上焦湿热；穿心莲苦寒，清热解毒、燥湿，二者均治湿热证。黄连、黄柏、龙胆虽清热燥湿，但配伍的野菊花、大血藤、败酱草偏于清热解毒消痈，非治湿热之主药，金银花亦以清热解毒为主"},{"q":"薤白的功效除行气导滞外，还有以下哪项","o":["燥湿化痰","疏肝解郁","通阳散结","清热解毒","温肾助阳"],"a":2,"e":"薤白辛温，通阳散结、行气导滞，为治胸痹之要药，善散胸中阴寒、通阳气。燥湿化痰属半夏、陈皮；疏肝解郁属柴胡、香附；清热解毒属金银花、连翘；温肾助阳属附子、肉桂，均非薤白之功"},{"q":"下列药物的用法错误的是","o":["牡蛎入汤剂宜先煎","钩藤入汤剂不宜久煎","雷丸入汤剂宜先煎","砂仁入汤剂宜后下","附子入汤剂宜先煎"],"a":2,"e":"雷丸含蛋白酶，加热至60℃以上即失效，宜研末冲服或入丸散，不入汤剂煎煮。牡蛎、附子质重或有毒宜先煎；钩藤、砂仁含挥发油或不耐热宜后下，均用法正确"},{"q":"具有清热凉血，养阴生津作用的药物是","o":["生地黄","紫草","水牛角","牡丹皮","赤芍"],"a":0,"e":"生地黄甘苦寒，清热凉血、养阴生津，治热入营血、阴虚内热、津伤口渴。紫草凉血活血、解毒透疹；水牛角清热凉血解毒；牡丹皮清热凉血活血但无养阴生津；赤芍清热凉血、散瘀止痛，均无养阴生津之效"},{"q":"为肺胃气逆之要药的是","o":["芥子","桔梗","旋覆花","川贝母","黄药子"],"a":2,"e":"旋覆花苦辛咸微温，降气化痰、降逆止呕，善降肺胃上逆之气，为肺胃气逆之要药，治咳喘痰多、呕吐呃逆。芥子温肺化痰、利气散结；桔梗宣肺利咽、祛痰排脓，性升提；川贝母润肺化痰止咳；黄药子化痰散结、凉血降火，均非降肺胃气逆之品"},{"q":"蝉蜕煎服时的用量是","o":["0、05～0、1g","3～6g","15～60g","0、002～0、004g","0、3～0、6g"],"a":1,"e":"蝉蜕煎服常用量3～6g，疏散风热、利咽开音、透疹止痒、明目退翳、息风止痉。0、05～0、1g、0、3～0、6g量过小，多为麝香、牛黄等贵重药用量；0、002～0、004g为砒石用量；15～60g量过大，非蝉蜕所宜"},{"q":"治气虚下陷，脱肛，子宫脱垂，崩漏下血的药物是","o":["菊花","淡豆豉","升麻","薄荷","蝉蜕"],"a":2,"e":"升麻辛微甘微寒，发表透疹、清热解毒、升举阳气，善升提下陷之中气，治气虚下陷之脱肛、子宫脱垂、崩漏下血。菊花、薄荷、蝉蜕疏散风热；淡豆豉解表除烦，均无升阳举陷之功"},{"q":"南沙参具有而北沙参不具有的功效是","o":["化痰","生津","养胃阴","清肺热","补肺阴"],"a":0,"e":"南沙参养阴清肺、益胃生津、化痰、益气；北沙参养阴清肺、益胃生津，无化痰、益气之功。生津、养胃阴、清肺热、补肺阴为二者共有，唯化痰为南沙参所独"},{"q":"归经含义是指","o":["药物具有的升、降、浮、沉的作用趋向","药物具有的寒、热、温、凉四种性质","药物具有的辛、甘、酸、苦、咸五种滋味","药物对于机体某部分的选择性作用","药物对于机体有无毒副作用"],"a":3,"e":"归经指药物对机体某脏腑经络的选择性作用，说明药物作用部位。升降浮沉指作用趋向；四气指寒热温凉；五味指辛甘酸苦咸；有毒无毒指安全性，均非归经含义"},{"q":"土鳖虫的药性是","o":["辛，平","辛、苦，温","甘、咸，平","咸，寒；有小毒","苦，温；有大毒"],"a":3,"e":"土鳖虫咸寒有小毒，破血逐瘀、续筋接骨，治跌打损伤、筋伤骨折、瘀血经闭。辛温、苦温之品属温性活血药；甘咸平多为胶类补益药；辛苦温有毒如川乌、草乌，均与土鳖虫药性不符"},{"q":"性平的补阴药是","o":["麦冬","枸杞子","北沙参","墨旱莲","明党参"],"a":1,"e":"枸杞子甘平，滋补肝肾、益精明目，为性平之补阴药。麦冬、北沙参、明党参微寒；墨旱莲甘酸寒，均非平性"},{"q":"豆蔻与肉豆蔻均具有的功效是","o":["芳香化湿","涩肠止泻","理气安胎","疏肝理气","温中行气"],"a":4,"e":"豆蔻化湿行气、温中止呕；肉豆蔻涩肠止泻、温中行气，二者共有温中行气。芳香化湿仅豆蔻有；涩肠止泻仅肉豆蔻有；疏肝理气、理气安胎均非二药之功"},{"q":"下列除哪项外，均为龙骨的主治病症","o":["心神不宁","目暗不明","肝阳眩晕","滑脱不禁","疮疡不敛"],"a":1,"e":"龙骨镇惊安神、平肝潜阳、收敛固涩，煅用收湿敛疮，治心神不宁、肝阳眩晕、滑脱不禁、疮疡不敛。目暗不明当用枸杞子、菊花、石决明等明目药，龙骨无明目之功"},{"q":"既平肝又疏肝的药物是","o":["香附","柴胡","赭石","蒺藜","罗布麻"],"a":3,"e":"蒺藜平肝解郁、祛风明目、止痒，既能平肝阳又能疏肝气，治肝阳上亢、肝郁气滞。香附、柴胡疏肝而无平肝之功；赭石、罗布麻平肝而无疏肝之效，均非兼具者"},{"q":"治疗肝肾亏虚，两目干涩，视物昏花，宜首选","o":["龟甲","黄精","鳖甲","枸杞子","墨旱莲"],"a":3,"e":"枸杞子甘平，滋补肝肾、益精明目，为治肝肾亏虚、两目干涩、视物昏花之要药。龟甲、鳖甲滋阴潜阳；黄精补气养阴；墨旱莲滋阴凉血，均无明目之专功"},{"q":"驱虫药服用的适宜时间是","o":["饭前","饭后","空腹","睡前","随时"],"a":2,"e":"驱虫药宜空腹服用，使药物在肠道内保持较高浓度，充分接触虫体而增强驱虫效果。饭前、饭后、睡前、随时服用均不能保证药物与虫体充分接触，影响疗效"},{"q":"较之大黄，虎杖所独有的功效是","o":["止咳化痰","利胆退黄","清热解毒","活血化瘀","凉血止血"],"a":0,"e":"虎杖利湿退黄、清热解毒、散瘀止痛、止咳化痰；大黄泻下攻积、清热泻火、凉血解毒、逐瘀通经、利湿退黄。利胆退黄、清热解毒、活血化瘀为二者共有，止咳化痰为虎杖所独有，凉血止血则大黄具备"},{"q":"辛味药临床一般治疗","o":["大便燥结","表证及气滞血瘀证","呕吐呃逆","瘿瘤瘰疬","久泻久痢"],"a":1,"e":"辛味能散能行，具有发散表邪、行气活血作用，主治外感表证及气滞血瘀证。大便燥结宜苦寒泻下或润下；呕吐呃逆宜降逆止呕；瘿瘤瘰疬宜软坚散结；久泻久痢宜涩肠固脱，均非辛味所主"},{"q":"治肝肾阴虚，腰膝酸软，潮热骨蒸，盗汗，遗精，消渴等，首选","o":["山药","地骨皮","白芍","黄精","熟地黄"],"a":4,"e":"熟地黄甘微温，补血滋阴、益精填髓，为治肝肾阴虚之腰膝酸软、潮热骨蒸、盗汗、遗精、消渴之要药。山药补脾肺肾、益气养阴但力缓；地骨皮凉血退蒸；白芍养血敛阴柔肝；黄精补气养阴，均非滋阴填精之首选"},{"q":"栀子用治热淋涩痛，因其能","o":["泻火除烦","清热利湿","凉血解毒","消肿止痛","凉血止血"],"a":1,"e":"栀子苦寒，泻火除烦、清热利湿、凉血解毒，清利下焦湿热，故治热淋涩痛。泻火除烦、凉血解毒、消肿止痛虽为栀子功效，但与热淋涩痛无直接对应；凉血止血非栀子所长，故以清热利湿为是"},{"q":"既能疏肝破气，又能消积化滞的药物是","o":["陈皮","青皮","枳实","木香","香附"],"a":1,"e":"青皮苦辛温，疏肝破气、消积化滞，治肝郁气滞之胁痛、乳房胀痛及食积腹痛。陈皮理气健脾燥湿，性较和缓；枳实破气消积但不疏肝；木香行气止痛、健脾消食；香附疏肝解郁、调经止痛而无破气消积之力"},{"q":"白前与前胡均具有的功效是","o":["疏散风热","清热解毒","利水消肿","利咽开音","降气祛痰"],"a":4,"e":"白前辛甘微温，降气化痰止咳；前胡苦辛微寒，降气化痰、疏散风热，二者共有降气祛痰。疏散风热仅前胡有；利咽开音属蝉蜕、胖大海；利水消肿属葶苈子、桑白皮；清热解毒属清热药，均非二药共有"},{"q":"能回阳通脉，温中散寒，温肺化饮的药物是","o":["丁香","肉桂","干姜","小茴香","高良姜"],"a":2,"e":"干姜辛热，温中散寒、回阳通脉、温肺化饮，治脾胃寒证、亡阳厥逆、寒饮咳喘。丁香温中降逆、补肾助阳；肉桂补火助阳、引火归元；小茴香、高良姜温中散寒止痛，均无回阳通脉、温肺化饮之全效"},{"q":"不具有利水消肿功效的药物是","o":["桑白皮","合欢皮","大腹皮","五加皮","茯苓皮"],"a":1,"e":"合欢皮解郁安神、活血消肿，无利水消肿之功。桑白皮泻肺平喘、利水消肿；大腹皮行气宽中、行水消肿；五加皮祛风湿、利水消肿；茯苓皮利水消肿，四者均可治水肿"},{"q":"能敛肺平喘，止带缩尿的药物是","o":["白果","枇杷叶","葶苈子","马兜铃","桑白皮"],"a":0,"e":"白果甘苦涩平，敛肺化痰定喘、止带缩尿，治哮喘痰多、带下白浊、尿频遗尿。枇杷叶清肺止咳、降逆止呕；葶苈子泻肺平喘、利水消肿；马兜铃清肺化痰止咳；桑白皮泻肺平喘、利水消肿，均无止带缩尿之功"},{"q":"远志的使用方法及注意点不包括","o":["用量不宜过大","胃溃疡者慎用","痰火内盛者慎用","化痰止咳多蜜炙用","痈疽疮毒患者慎用"],"a":4,"e":"远志用量不宜过大，过量易致恶心呕吐；对胃有刺激性，胃溃疡者慎用；性温燥，痰火内盛者慎用；化痰止咳多蜜炙以缓和刺激性。远志能祛痰开窍、消散痈肿，可用治痈疽疮毒，故痈疽疮毒患者慎用不属其使用注意"},{"q":"治疗疮痈肿毒宜首选的药物是","o":["薄荷","牛蒡子","蔓荆子","桑叶","蝉蜕"],"a":1,"e":"牛蒡子辛寒，疏散风热、宣肺透疹、解毒利咽、散结消肿，为治疮痈肿毒、痄腮丹毒、咽喉肿痛之要药。薄荷、桑叶疏散风热但解毒散结之力弱；蔓荆子疏散风热、清利头目；蝉蜕利咽开音、透疹止痉，均无解毒消肿治疮痈之长"},{"q":"传统加强药物的止血之功，常用的炮制方法是","o":["酒炙","蜜炙","炒炭","炒焦","盐水炙"],"a":2,"e":"炒炭使药物部分炭化，产生或增强止血作用，如地榆炭、侧柏炭、茜草炭。酒炙活血通络、引药上行；蜜炙补中润肺、缓和药性；炒焦增强消食；盐水炙引药入肾，均非增强止血之常法"},{"q":"人参、麦冬治疗热伤气阴、汗多口渴，常配伍的药是","o":["黄精","乌梅","天花粉","生地黄","五味子"],"a":4,"e":"人参、麦冬配五味子即生脉散，益气养阴、收敛止汗、生津止渴，治热伤气阴、汗多口渴。黄精、天花粉、生地黄养阴生津但无收敛止汗；乌梅敛肺生津但益气力弱，均非本配伍之宜"},{"q":"性味苦寒的药物大多具有的功效是","o":["祛风散寒","芳香化湿","清热燥湿","利水渗湿","活血温经"],"a":2,"e":"苦能泄能燥，寒能清热，苦寒药多具清热燥湿、泻火解毒之功，治湿热、实热证。祛风散寒属辛温药；芳香化湿属芳香化湿药；利水渗湿属甘淡药；活血温经属辛温行血药，均非苦寒药所长"},{"q":"莲子与五味子均可用治","o":["久咳虚喘","自汗盗汗","津伤口渴","崩漏下血","心悸失眠"],"a":4,"e":"莲子养心安神、补脾止泻、益肾涩精；五味子宁心安神、收敛固涩、益气生津，二者均可用治心悸失眠。久咳虚喘、自汗盗汗、津伤口渴为五味子所主，莲子不具此功；崩漏下血非二者所主"},{"q":"决明子用于润肠通便，应注意的是","o":["先煎","不宜久煎","包煎","另煎","烊化"],"a":1,"e":"决明子用于润肠通便宜生用并打碎，久煎则其有效成分破坏、润肠之力减弱，故不宜久煎。先煎用于矿石贝壳类；包煎用于细小种子及绒毛类；另煎用于贵重药；烊化用于胶类，均非决明子润肠之所宜"},{"q":"治疗丹毒，痄腮，宜首选的药物是","o":["葛根","柴胡","牛蒡子","蝉蜕","薄荷"],"a":2,"e":"牛蒡子辛寒，疏散风热、宣肺透疹、解毒利咽、散结消肿，善治风热上攻之痄腮、丹毒、咽喉肿痛。葛根解肌退热、生津；柴胡疏肝解表升阳；蝉蜕利咽开音、透疹；薄荷疏散风热、清利头目，均无解毒散结消痈之长"},{"q":"增强延胡索止痛作用的炮制加工方法是","o":["蜜炙","醋炙","酒炙","盐水炙","姜汁炙"],"a":1,"e":"延胡索醋炙后，其生物碱与醋酸结合成易溶于水的醋酸盐，止痛有效成分溶出增加，止痛作用增强。蜜炙补中润肺；酒炙活血通络、引药上行；盐水炙引药入肾；姜汁炙温中止呕，均不能增强延胡索止痛"},{"q":"五倍子、仙鹤草均具有的功效是","o":["收敛止血","解毒截疟","补虚强壮","敛肺降火","固精止遗"],"a":0,"e":"五倍子酸涩，敛肺降火、涩肠止泻、固精止遗、收敛止血、收湿敛疮；仙鹤草收敛止血、截疟、止痢、解毒、补虚，二者共有收敛止血。解毒截疟、补虚强壮仅仙鹤草有；敛肺降火、固精止遗仅五倍子有"},{"q":"治疗痰浊痹阻、胸阳不振的胸痹，常与薤白配伍的药物是","o":["桔梗","丹参","瓜蒌","前胡","浙贝母"],"a":2,"e":"瓜蒌宽胸散结、清热化痰、润肠通便，与薤白通阳散结相须为用，治痰浊痹阻、胸阳不振之胸痹。桔梗宣肺祛痰、排脓；丹参活血祛瘀、通经止痛；前胡降气化痰；浙贝母清热化痰散结，均无与薤白相须通阳散结之能"},{"q":"皂荚不具有的功效是","o":["祛痰","开窍","散结","消肿","行气"],"a":4,"e":"皂荚辛温，祛痰止咳、开窍通闭、散结消肿，外用杀虫止痒，无行气之功。祛痰、开窍、散结、消肿均为皂荚所有，故以行气为不具备之功效"},{"q":"既养心安神，又敛汗生津的药是","o":["远志","丹参","酸枣仁","合欢皮","夜交藤"],"a":2,"e":"酸枣仁养心补肝、宁心安神、敛汗、生津，为治虚烦不眠、惊悸多梦之要药，且能敛汗生津。远志宁心安神、祛痰开窍但无敛汗生津；丹参凉血安神；合欢皮解郁安神；夜交藤养血安神，均无敛汗生津之效"},{"q":"治疗筋脉挛急疼痛的药物，大多是何味药","o":["酸","苦","甘","辛","咸"],"a":2,"e":"甘味能补、能缓、能和，具有缓急止痛作用，筋脉挛急疼痛多用甘味药，如芍药甘草汤。酸味收敛固涩；苦味泄降燥湿；辛味发散行气；咸味软坚散结，均无缓急止痛之能"},{"q":"哪项不是确定药物剂量的依据","o":["药材的质量","药物的颜色","有毒无毒","患者的体质","患者的病势"],"a":1,"e":"确定剂量依据包括药物性质（有毒无毒、质地轻重）、剂型、配伍、患者体质与病势等。药物颜色与药效、毒性无必然联系，不作为确定剂量的依据"},{"q":"功能活血化瘀，凉血解毒，解郁安神的药是","o":["川芎","桃仁","红花","西红花","益母草"],"a":3,"e":"西红花活血化瘀、凉血解毒、解郁安神，治经闭瘀阻、温毒发斑、忧郁痞闷。红花活血通经、散瘀止痛，性温，无凉血解毒、解郁安神之功；川芎、桃仁、益母草活血祛瘀，亦无凉血解郁之效"},{"q":"既能治疗温邪伤阴夜热早凉，又能治疗阴虚骨蒸潮热的药物是","o":["黄柏","青蒿","地骨皮","胡黄连","牡丹皮"],"a":1,"e":"青蒿苦辛寒，退虚热、凉血、解暑、截疟，善治温邪伤阴之夜热早凉、阴虚骨蒸潮热。黄柏、知母泻火坚阴退蒸；地骨皮凉血除蒸；胡黄连退虚热、清疳热，均无解暑截疟、透热外出之长，青蒿治夜热早凉独具特色"},{"q":"小儿疳积，厌食，腹大，消瘦，毛发焦枯，现低热不退，首选的药物是","o":["地骨皮","山楂","槟榔","银柴胡","茯苓"],"a":3,"e":"银柴胡甘微寒，退虚热、清疳热，为治小儿疳积发热、消瘦、低热不退之要药。地骨皮凉血退蒸、清肺降火；山楂消食化积；槟榔杀虫消积、行气；茯苓健脾渗湿，均无清疳热之专功"},{"q":"升药主含","o":["水银","氧化砷","硫酸钠","氧化铁","硫酸铝钾"],"a":0,"e":"升药为水银与火硝、明矾等炼制而成的汞剂，主含氧化汞，汞为其核心成分，故以水银作为原料药。氧化砷为砒霜；硫酸钠为芒硝；氧化铁为赭石；硫酸铝钾为明矾，均与升药成分不符"},{"q":"主治疥癣、梅毒、疮疡溃烂的药物是","o":["硫黄","轻粉","硼砂","炉甘石","蛇床子"],"a":1,"e":"轻粉外用杀虫、攻毒、敛疮，治疥癣、梅毒、疮疡溃烂。硫黄解毒杀虫疗疮，为疥疮要药但治梅毒力逊；硼砂清热解毒、防腐；炉甘石收湿敛疮、明目；蛇床子杀虫止痒、温肾壮阳，均无治梅毒之效"},{"q":"长于止痛，善治风寒头痛、牙痛、风湿痹痛等寒痛证及少阴头痛的药物是","o":["荆芥","防风","香薷","苍耳子","细辛"],"a":4,"e":"细辛辛温，祛风解表、止痛、通窍、温肺化饮，止痛力强，善治风寒头痛、牙痛、风湿痹痛及少阴头痛。荆芥、防风解表祛风但止痛力弱；香薷化湿和中；苍耳子通鼻窍、祛风湿，均无治少阴头痛之专长"},{"q":"紫菀的功效是","o":["止咳平喘，润肠通便","清肺止咳，降逆止呕","润肺下气，消痰止咳","润肺下气止咳，杀虫灭虱","化痰止咳平喘，润肠通便"],"a":2,"e":"紫菀辛甘苦微温，润肺下气、消痰止咳，治痰多咳嗽、咯痰不爽，温而不燥，润而不腻。止咳平喘、润肠通便为杏仁、苏子之类；清肺止咳、降逆止呕为枇杷叶；润肺下气止咳、杀虫灭虱为百部，均非紫菀功效"},{"q":"性平，能宣肺祛痰的药物是","o":["芥子","桔梗","前胡","白前","竹茹"],"a":1,"e":"桔梗苦辛平，宣肺、利咽、祛痰、排脓，性平，治咳嗽痰多、咽痛音哑、肺痈吐脓。芥子辛温；前胡、竹茹微寒；白前微温，均非性平之品，且无宣肺之能"},{"q":"荆芥穗长于","o":["祛风","止血","透疹","消疮","止痛"],"a":0,"e":"荆芥穗为荆芥之花穗，辛微温，发汗解表力强，长于祛风解表，治风寒感冒、头痛、风疹瘙痒。止血多用荆芥炭；消疮、透疹虽荆芥亦有，但穗以祛风解表见长；止痛非荆芥所长"},{"q":"不属于珍珠母主治病症的是","o":["阳亢眩晕","目赤肿痛","视物昏花","惊悸失眠","惊痫抽搐"],"a":4,"e":"珍珠母咸寒，平肝潜阳、清肝明目、镇惊安神，治阳亢眩晕、目赤肿痛、视物昏花、惊悸失眠。惊痫抽搐当用羚羊角、牛黄、全蝎、蜈蚣等息风止痉药，珍珠母无息风止痉之功"},{"q":"薤白配瓜蒌善于治疗","o":["胸痹","胃肠气滞","肠燥便秘","肺热咳嗽","月经不调"],"a":0,"e":"薤白通阳散结、行气导滞，瓜蒌宽胸散结、清热化痰，二药相须，为治胸阳不振、痰浊痹阻之胸痹要方。胃肠气滞宜木香、枳实；肠燥便秘宜火麻仁、郁李仁；肺热咳嗽宜黄芩、桑白皮；月经不调宜香附、当归，均非本配伍所主"},{"q":"苏木的功效是","o":["活血定痛，止血生肌","活血续伤，补肾强骨","破血逐瘀，续筋接骨","散结消肿，通络止痛","活血祛瘀，消肿止痛"],"a":4,"e":"苏木甘咸平，活血祛瘀、消肿止痛，治瘀血经闭、跌打损伤、瘀肿疼痛。活血定痛、止血生肌为三七之类；活血续伤、补肾强骨为骨碎补；破血逐瘀、续筋接骨为土鳖虫；散结消肿、通络止痛为乳香、没药，均非苏木功效概括"},{"q":"《本草经集注》的作者是","o":["陶弘景","李时珍","赵学敏","唐慎微","葛洪"],"a":0,"e":"陶弘景为南朝梁代医家，整理《神农本草经》并增补成《本草经集注》，首创按自然属性分类。李时珍著《本草纲目》；赵学敏著《本草纲目拾遗》；唐慎微著《证类本草》；葛洪著《肘后备急方》，均非《本草经集注》作者"},{"q":"均有滋阴潜阳功效的药组是","o":["龟甲、鳖甲","龟甲、百合","鳖甲、麦冬","石斛、百合","天冬、龟甲"],"a":0,"e":"龟甲滋阴潜阳、益肾强骨、养血补心；鳖甲滋阴潜阳、退虚热、软坚散结，二者均能滋阴潜阳，治阴虚阳亢、虚风内动。百合、麦冬养阴润肺；石斛益胃生津；天冬润肺滋肾；黄精补气养阴，均无潜阳之功"},{"q":"味甘淡，性寒，善清下焦、膀胱湿热的药物是","o":["茯苓","泽泻","猪苓","香加皮","玉米须"],"a":1,"e":"泽泻甘淡寒，利水渗湿、泄热、化浊降脂，性寒清下焦膀胱湿热，治热淋、水肿。茯苓、猪苓、玉米须利水渗湿但性平，无清下焦湿热之专功；香加皮祛风湿强筋骨；冬瓜皮利水消肿，均非清下焦膀胱湿热之主药"},{"q":"白芍不具有的功效是","o":["养血","润肺","敛阴","柔肝止痛","平抑肝阳"],"a":1,"e":"白芍养血敛阴、柔肝止痛、平抑肝阳，治血虚萎黄、月经不调、胁痛、头痛眩晕。润肺为百合、麦冬、川贝母之功，白芍无润肺之效"},{"q":"下列药组中均可活血、行气的是","o":["丹参、三七","莪术、红花","丹参、川芎","延胡索、三七","延胡索、莪术"],"a":4,"e":"延胡索活血行气止痛，莪术破血行气、消积止痛，二者均能活血、行气。丹参活血调经、凉血消痈，无行气；三七化瘀止血、活血定痛；红花活血通经、散瘀止痛，均无行气之功"},{"q":"既能治疗肾虚作喘，又能治疗五更泄泻的药物是","o":["沉香","磁石","补骨脂","肉苁蓉","吴茱萸"],"a":2,"e":"补骨脂辛苦大温，补肾助阳、纳气平喘、温脾止泻，治肾虚作喘、五更泄泻。沉香行气止痛、温中止呕、纳气平喘但不止泻；磁石镇惊安神、纳气平喘；肉苁蓉补肾阳、益精血、润肠；吴茱萸散寒止痛、助阳止泻但不纳气平喘，均非二者兼备"},{"q":"可助阳解表，可用于治疗阳虚外感风寒的药物是","o":["附子","花椒","胡椒","吴茱萸","高良姜"],"a":0,"e":"附子辛甘大热，补火助阳、散寒止痛，配麻黄、细辛可助阳解表，治阳虚外感风寒，如麻黄附子细辛汤。花椒、胡椒、高良姜温中散寒；吴茱萸散寒止痛、助阳止泻，均无助阳解表之功"},{"q":"不属于白术药性及功效特点的是","o":["消食","燥湿","补脾气","归脾胃经","甘温苦燥"],"a":0,"e":"白术苦甘温，补气健脾、燥湿利水、止汗、安胎，甘温苦燥，主归脾胃经。消食为山楂、神曲、麦芽之功，白术无消食化积之效"},{"q":"温通经脉，擅治寒凝血瘀证的药物是","o":["肉桂","丁香","附子","吴茱萸","小茴香"],"a":0,"e":"肉桂辛甘大热，补火助阳、散寒止痛、温通经脉、引火归元，温通血脉以散寒凝，治寒凝血瘀之经闭、痛经、癥瘕。丁香温中降逆；附子回阳救逆、补火助阳；吴茱萸散寒止痛；小茴香散寒止痛、理气和胃，均无温通经脉治寒凝血瘀之专长"},{"q":"性味辛平，有毒，性善走窜，搜风定搐力强，为息风止痉要药的是","o":["地龙","全蝎","蜈蚣","僵蚕","蕲蛇"],"a":1,"e":"全蝎辛平有毒，性善走窜，息风镇痉、攻毒散结、通络止痛，为息风止痉要药，治惊风抽搐、破伤风。蜈蚣辛温有毒，力更猛；地龙咸寒，清热息风；僵蚕咸辛平，祛风定惊、化痰散结；蕲蛇甘咸温，祛风通络，均非辛平有毒、搜风定搐之全蝎"},{"q":"肺热咳嗽，胃热呕吐，痰火内扰烦躁，宜用","o":["竹茹","百部","桔梗","瓜蒌","浙贝母"],"a":0,"e":"竹茹甘微寒，清热化痰、除烦止呕，治肺热咳嗽、胃热呕吐、痰火内扰之心烦失眠。百部润肺止咳杀虫；桔梗宣肺祛痰排脓；瓜蒌清热化痰、宽胸散结；浙贝母清热化痰散结，均无清胃热止呕、除烦之效"},{"q":"属于“疗热以寒药”治疗原则的是","o":["用附子、干姜治疗腹中冷痛、脉沉无力","用茯苓、猪苓治疗水肿、小便不利","用黄芩、连翘治疗发热咽痛、舌红尿赤","用五味子、莲子治疗盗汗遗精","用麻黄、薄荷治疗外感表证"],"a":2,"e":"疗热以寒药指热证用寒凉药治疗，黄芩、连翘苦寒清热，治发热咽痛、舌红尿赤之热证。附子、干姜治腹中冷痛属疗寒以热药；茯苓、猪苓利水；五味子、莲子收敛固涩；麻黄、薄荷解表，均非寒药治热之例"},{"q":"青黛的用法是","o":["入煎剂先煎","入煎剂后下","入煎剂包煎","入丸散冲服","入煎剂单煎"],"a":3,"e":"青黛为极细粉末，难溶于水，不入煎剂，宜入丸散或冲服。先煎用于矿石贝壳类；后下用于芳香易挥发药；包煎用于细小种子及绒毛类；单煎用于贵重药，均非青黛之法"},{"q":"内能宣通脏腑，通达气血，外能透达经络，散瘀消肿止痛的药是","o":["三棱","红花","桃仁","泽兰","乳香"],"a":4,"e":"乳香活血行气止痛、消肿生肌，内能宣通脏腑气血，外能透达经络，散瘀消肿止痛，治瘀血阻滞诸痛、疮疡肿痛。三棱破血行气；红花、桃仁活血祛瘀；泽兰活血调经、利水消肿，均无内外通达、消肿生肌之全效"},{"q":"温中止泻宜煨用的药物是","o":["五倍子","罂粟壳","肉豆蔻","石榴皮","海螵蛸"],"a":2,"e":"肉豆蔻煨制后温中行气、涩肠止泻力增强，且除去部分油脂，减少对胃的刺激，治脾肾虚寒之久泻久痢。五倍子、罂粟壳、石榴皮、海螵蛸虽能涩肠止泻或收敛，但不以煨用温中止泻为特点"},{"q":"能够减轻或消除热证的药物，其药性一般属于","o":["寒、热","寒、凉","温、凉","温、微寒","平"],"a":1,"e":"寒凉药能减轻或消除热证，具有清热、泻火、解毒、凉血等作用。温热药治寒证；平和之品作用缓和；寒热并用药针对寒热错杂，均非减轻热证之药性"},{"q":"治疗肝郁气滞有热诸痛，最宜选用","o":["青皮","木香","枳实","川楝子","荔枝核"],"a":3,"e":"川楝子苦寒，行气止痛、泄热，主入肝经，善治肝郁气滞有热之胁痛、脘腹胀痛，性寒能清肝火。青皮、木香、枳实行气止痛但性温或平，无清热之功；荔枝核行气散结、祛寒止痛，治寒疝，均非有热诸痛所宜"},{"q":"下列哪味中药适用于寒湿痹证","o":["附子","花椒","胡椒","高良姜","荜澄茄"],"a":0,"e":"附子辛甘大热，补火助阳、散寒除湿、止痛，善治寒湿痹痛、周身骨节冷痛。花椒、胡椒、高良姜、荜澄茄温中散寒，主入脾胃，无祛风湿、通痹止痛之功"},{"q":"关于芳香化湿药的论述，错误的是","o":["多辛、温，主归脾、胃经","入汤剂多宜后下","多具利小便作用","主治湿阻中焦证","易耗伤气阴"],"a":2,"e":"芳香化湿药多辛温香燥，主归脾胃经，化湿醒脾、行气和胃，入汤剂多宜后下以防挥发油散失，但辛温香燥易耗伤气阴。利小便为利水渗湿药之功，芳香化湿药不具利小便作用"},{"q":"既能凉血止血，又能散瘀消肿的药物是","o":["小蓟","茜草","白及","侧柏叶","白茅根"],"a":0,"e":"小蓟甘凉，凉血止血、散瘀解毒消痈，治血热妄行之出血及热毒疮痈，止血兼能散瘀消肿。茜草凉血止血兼活血通经；白及收敛止血、消肿生肌；侧柏叶凉血止血、化痰生发；白茅根凉血止血、清热利尿，均非散瘀消肿之凉血止血药"},{"q":"不属于郁金功效的是","o":["活血止痛","行气解郁","消肿生肌","利胆退黄","清心凉血"],"a":2,"e":"郁金活血止痛、行气解郁、清心凉血、利胆退黄，治气滞血瘀、热病神昏、黄疸。消肿生肌为乳香、没药、白及之功，郁金无此效"},{"q":"归经是指药物","o":["对机体某部分的选择性作用","对机体的作用趋向","与经络间的密切关系","与药物之间的功能差异","说明对某些经络的毒性"],"a":0,"e":"归经指药物对机体某部分（脏腑经络）的选择性作用，反映药物作用的部位与范围。作用趋向指升降浮沉；与经络关系表述笼统；药物间功能差异指功效比较；对经络毒性之说与归经无关"},{"q":"煅用能治疗胃痛泛酸的中药是","o":["钩藤","天麻","牡蛎","龙骨","牛黄"],"a":2,"e":"煅牡蛎收敛制酸，治胃痛泛酸；生牡蛎平肝潜阳、软坚散结、清热。钩藤息风定惊；天麻息风止痉；龙骨镇惊安神、收敛固涩，但制酸力逊；牛黄清心开窍、清热解毒，均无制酸止痛之专长"},{"q":"治疗消渴属肺脾肾三脏不足，气阴两虚者，宜选用","o":["麦冬","黄芪","党参","山药","白术"],"a":3,"e":"山药甘平，益气养阴、补脾肺肾，治消渴属肺脾肾三脏不足、气阴两虚者，能补气养阴、生津止渴。麦冬、党参、黄芪偏补一脏；白术健脾燥湿，无养阴生津之效，均非三脏同调之品"},{"q":"甘寒滑利，善清热利尿，渗湿止泻，治淋证、水肿无论虚实皆宜的药物是","o":["滑石","海金沙","车前子","木通","通草"],"a":2,"e":"车前子甘寒滑利，利尿通淋、渗湿止泻、清肝明目、清肺化痰，治淋证、水肿、暑湿泄泻，无论虚实皆可配伍应用。滑石清热解暑、收湿敛疮；海金沙通淋止痛；木通、通草清心火或通气下乳，均无渗湿止泻、虚实皆宜之特点"},{"q":"胃寒湿阻气滞呕吐，治宜首选的药物是","o":["生姜","半夏","豆蔻","竹茹","苍术"],"a":2,"e":"豆蔻化湿行气、温中止呕，善治胃寒湿阻气滞之呕吐。生姜温中止呕但无化湿行气；半夏燥湿化痰、降逆止呕，治湿痰呕吐；竹茹清胃热止呕；苍术燥湿健脾但无止呕之功"},{"q":"可用于痰壅咳喘的清热解毒药是","o":["鱼腥草","射干","马勃","蒲公英","穿心莲"],"a":1,"e":"射干苦寒，清热解毒、祛痰止咳平喘，善治痰壅咳喘、咽喉肿痛，为治痰多咳喘之清热解毒药。鱼腥草清热解毒、消痈排脓；马勃清热解毒、利咽止血；蒲公英清热解毒、消痈散结；穿心莲清热解毒、燥湿，均无祛痰平喘之专长"},{"q":"既能解表散风，又能透疹消疮、止血的药物是","o":["生姜","细辛","桂枝","荆芥","紫苏叶"],"a":3,"e":"荆芥辛微温，解表散风、透疹消疮，炒炭止血，为治外感表证、麻疹不透、风疹瘙痒及出血证常用药。生姜发汗解表、温中止呕；细辛、桂枝解表散寒但无透疹消疮止血；紫苏叶行气宽中，均无解表散风兼透疹消疮止血之全效"},{"q":"赤石脂、地榆的共同功效是","o":["涩肠止泻，解毒","涩肠止泻，生肌","凉血止血，敛疮","收敛止血，敛疮","解毒敛疮，止血"],"a":3,"e":"赤石脂甘酸涩温，涩肠止泻、收敛止血、收湿生肌敛疮；地榆苦酸微寒，凉血止血、解毒敛疮，二者共有收敛止血、敛疮。涩肠止泻、生肌仅赤石脂有；凉血止血仅地榆有；解毒敛疮虽地榆具备，但非二者共有"},{"q":"能治疥癣及梅毒的中药是","o":["轻粉","白矾","硫黄","蛇床子","土荆皮"],"a":0,"e":"轻粉外用杀虫、攻毒、敛疮，治疥癣、梅毒、疮疡溃烂。白矾解毒杀虫、燥湿止痒；硫黄杀虫疗疮，为疥疮要药；蛇床子杀虫止痒；土荆皮杀虫止痒，均无治梅毒之专长"},{"q":"为引药入肝经宜","o":["蜜炙","酒炙","醋炙","盐水炙","姜汁炙"],"a":2,"e":"醋味酸，入肝经，醋炙可引药入肝，增强活血止痛、疏肝理气作用，并能降低毒性。蜜炙补中润肺、缓急；酒炙活血通络、引药上行；盐水炙引药入肾；姜汁炙温中止呕，均非引药入肝之法"},{"q":"下列哪项不属于“十八反”的药物","o":["甘草反甘遂","乌头反贝母","藜芦反半夏","甘草反大戟","乌头反瓜蒌"],"a":2,"e":"十八反中乌头反半夏、瓜蒌、贝母、白蔹、白及；甘草反海藻、大戟、甘遂、芫花；藜芦反人参、沙参、丹参、玄参、细辛、芍药。藜芦不反半夏，故该项不属十八反"},{"q":"下列除哪一味药物，均为孕妇慎用药","o":["车前子","滑石","木通","瞿麦","地肤子"],"a":4,"e":"车前子、滑石、木通、瞿麦均性滑利，能通淋利水，孕妇服用易动胎气，故慎用或忌用。地肤子清热利湿、祛风止痒，作用较和缓，不属孕妇慎用的滑利通淋药"},{"q":"为增强药物止呕的作用宜","o":["蜜炙","酒炙","醋炙","盐水炙","姜汁炙"],"a":4,"e":"姜汁辛温，温中止呕、和胃降逆，姜汁炙可增强药物止呕作用，并缓和药物刺激性。蜜炙润肺补中；酒炙活血；醋炙入肝止痛；盐水炙入肾，均无增强止呕之效"},{"q":"具有发汗解表，温中止呕，温肺止咳功效的药物是","o":["麻黄","桂枝","紫苏叶","白芷","生姜"],"a":4,"e":"生姜辛微温，发汗解表、温中止呕、温肺止咳，为呕家圣药，治风寒感冒、胃寒呕吐、风寒咳嗽。麻黄发汗平喘、利水；桂枝温通经脉；紫苏叶解表行气；白芷祛风通窍、止痛，均无温中止呕、温肺止咳之全效"},{"q":"辛味药物的作用是","o":["发散，行气","补益，软坚","燥湿，通泄","收敛，固涩","软坚，缓急"],"a":0,"e":"辛味能散能行，具有发散表邪、行气活血作用。补益、软坚为甘味、咸味之功；燥湿、通泄为苦味之功；收敛固涩为酸味之功；缓急为甘味之功，均非辛味所主"},{"q":"具有能补、能缓作用的药物是","o":["黄芪","党参","龙眼","甘草","当归"],"a":3,"e":"甘草甘平，补脾益气、清热解毒、祛痰止咳、缓急止痛、调和诸药，甘味能补能缓，故甘草具补益与缓急止痛之效。黄芪、党参、龙眼肉、当归虽补益，但无缓急止痛、调和诸药之能"},{"q":"功能解毒疗疮，杀虫止痒，为治疗疥疮要药的是","o":["硫黄","硼砂","白矾","苦参","蛇床子"],"a":0,"e":"硫黄酸温有毒，外用解毒杀虫疗疮，为治疥疮之要药，治疥癣、秃疮、阴蚀恶疮。硼砂清热解毒、防腐；白矾解毒杀虫、燥湿止痒；苦参清热燥湿、杀虫；蛇床子杀虫止痒、温肾壮阳，均无治疥疮之专功"},{"q":"功能祛风湿止痛，善治下半身风湿痹痛的药物是","o":["羌活","独活","牛膝","威灵仙","防风"],"a":1,"e":"独活辛苦微温，祛风除湿、通痹止痛，主入肾经，善治下半身腰膝腿足风湿痹痛。羌活善治上半身风湿痹痛；牛膝活血通经、引血下行；威灵仙通络止痛，性猛善走；防风祛风胜湿，均无善治下半身痹痛之专长"},{"q":"关于薏苡仁健脾止泻的使用方法，叙述正确的是","o":["生用","炒用","蜜炙","先煎","研末冲服"],"a":1,"e":"薏苡仁生用利水渗湿、清热排脓、除痹，炒用则健脾止泻力增强，治脾虚泄泻。蜜炙、先煎、研末冲服均非薏苡仁健脾止泻的常规用法"},{"q":"薏苡仁除能利水渗湿，健脾止泻，除痹外，还能","o":["宁心","泄热","排脓","强筋骨","解暑"],"a":2,"e":"薏苡仁除利水渗湿、健脾止泻、除痹外，还能排脓、解毒散结，治肺痈、肠痈。宁心为茯苓、酸枣仁；泄热为栀子、黄芩；强筋骨为五加皮、杜仲；解暑为香薷、荷叶，均非薏苡仁之功"},{"q":"药性具有升降两向性，功能上行头目、下行血海的药是","o":["肉桂","牛膝","川芎","益母草","鸡血藤"],"a":2,"e":"川芎辛温，活血行气、祛风止痛，辛香走窜，上行头目、下行血海，为血中之气药，治头痛、月经不调。肉桂温里助阳引火归元；牛膝引血下行；益母草活血调经、利水；鸡血藤补血活血通络，均无上行头目、下行血海两向之性"},{"q":"功能补益心脾、养血安神的药物是","o":["当归","阿胶","何首乌","龙眼肉","熟地黄"],"a":3,"e":"龙眼肉甘温，补益心脾、养血安神，治思虑过度、劳伤心脾之惊悸怔忡、健忘失眠。当归、熟地黄补血但无补心脾、安神之专功；阿胶滋阴补血止血；何首乌补肝肾、益精血，均无补益心脾安神之效"},{"q":"黄柏与苍术的共同功效是","o":["祛风","发汗","解毒","泻火","燥湿"],"a":4,"e":"黄柏苦寒，清热燥湿、泻火除蒸、解毒疗疮；苍术辛苦温，燥湿健脾、祛风散寒，二者共有燥湿之功，如二妙散治湿热下注。祛风、发汗仅苍术有；解毒、泻火仅黄柏有，均非二者共有"},{"q":"薄荷和牛蒡子不具有，而蝉蜕具有的功效是","o":["解毒，祛痰","退翳，止痉","利咽，透疹","宣肺，润肠","清肝，疏肝"],"a":1,"e":"蝉蜕疏散风热、利咽开音、透疹、明目退翳、息风止痉，治目生翳障、惊风抽搐、破伤风。薄荷、牛蒡子虽疏散风热、利咽透疹，但无明目退翳、息风止痉之功；解毒祛痰、宣肺润肠、清肝疏肝亦非蝉蜕与二药之别"},{"q":"常用于治疗肾阳虚衰、筋骨痿软、风湿痹痛、麻木拘挛的药物是","o":["蛤蚧","益智仁","阳起石","威灵仙","淫羊藿"],"a":4,"e":"淫羊藿辛甘温，补肾阳、强筋骨、祛风湿，治肾阳虚衰之筋骨痿软、风湿痹痛、麻木拘挛。蛤蚧补肺益肾、纳气平喘；益智仁温脾暖肾、固气涩精；阳起石温肾壮阳；威灵仙祛风湿、通络止痛但无补肾强筋骨之效"},{"q":"既能透散外邪，又能宣散邪热的药物是","o":["菊花","柴胡","蝉蜕","淡豆豉","牛蒡子"],"a":3,"e":"淡豆豉苦辛甘平，解表、除烦、宣发郁热，既能透散外邪，又能宣散邪热，治外感表证、虚烦不眠。菊花、牛蒡子疏散风热；柴胡、蝉蜕透邪解表，均无宣发郁热、除烦之专长"},{"q":"知母用于阴虚肠燥便秘，因其能","o":["清热泻火","除烦止渴","滋阴润燥","清热凉血","养阴清热"],"a":2,"e":"知母苦甘寒，清热泻火、滋阴润燥，阴虚肠燥便秘者用之，取其滋阴润肠之效。清热泻火、除烦止渴虽为知母之功，但与便秘无直接对应；清热凉血、养阴清热非知母治肠燥便秘之机制"},{"q":"称为交通心肾，安定神志之佳品的药物是","o":["朱砂","远志","酸枣仁","柏子仁","夜交藤"],"a":1,"e":"远志宁心安神、祛痰开窍、消散痈肿，能沟通心肾、安定神志，为交通心肾之佳品。朱砂镇心安神、清热解毒；酸枣仁、柏子仁养心安神；夜交藤养血安神，均无交通心肾、祛痰开窍之能"},{"q":"有良好的降血压作用，临床多用于高血压的药物是","o":["夏枯草","半边莲","淡竹叶","天花粉","鸭跖草"],"a":0,"e":"夏枯草苦辛寒，清肝明目、散结消肿，有良好的降血压作用，临床多用于高血压属肝热者。半边莲清热解毒、利水消肿；淡竹叶清热除烦、利尿；天花粉清热生津、消肿排脓；鸭跖草清热解毒、利水，均无清肝降压之专功"},{"q":"既能清心豁痰，又能开窍醒神，为凉开之品的是","o":["黄连","牛黄","珍珠","石菖蒲","羚羊角"],"a":1,"e":"牛黄苦凉，清心豁痰、开窍醒神、清热解毒、息风止痉，为凉开之品，治热病神昏、中风痰迷。黄连清热燥湿、泻火解毒但无开窍；石菖蒲开窍豁痰、醒神，性温属温开；珍珠安神定惊、明目；羚羊角平肝息风、清热，均无清心豁痰凉开之全效"},{"q":"下列关于天麻来源、使用部位正确的是","o":["兰科，根","兰科，块根","兰科，块茎","百合科，块根","百合科，块茎"],"a":2,"e":"天麻为兰科植物天麻的干燥块茎，主产于贵州、云南等地，息风止痉、平抑肝阳、祛风通络。其药用部位为块茎而非根或块根；百合科植物如川贝母、知母等，与天麻来源不同"},{"q":"中药炮制的常用固体辅料不含以下哪项","o":["麦麸","米","砂","泥","土"],"a":3,"e":"常用固体辅料有麦麸、米、砂、土、蛤粉、滑石粉等，砂作传热介质使药物质地酥脆，土能温中和胃、增强补脾之效，麦麸与米亦各健脾和中。泥不属于炮制辅料，与砂、土形似而质异，不能混用"},{"q":"黄连与胡黄连均能治疗","o":["肺热咳嗽","小儿疳热","湿热泻痢","高热神昏","阴虚骨蒸潮热"],"a":2,"e":"黄连清热燥湿、泻火解毒，尤清中焦湿热，为治湿热泻痢要药；胡黄连退虚热、清湿热，亦治湿热泻痢，此为二者共有。肺热咳嗽项实为黄芩、桑白皮所主；小儿疳热与阴虚骨蒸潮热虽胡黄连可治，黄连不具此功；高热神昏属热陷心包，非二者所共有"},{"q":"车前子的用法是","o":["先煎","后下","研末冲服","泡服","包煎"],"a":4,"e":"车前子为细小种子类药材，直接入煎易漂浮、粘锅并使药液浑浊，故须包煎。先煎适用于矿石、贝壳及有毒药；后下适用于芳香含挥发油药；研末冲服与泡服多针对贵重或易溶药，均非车前子用法"},{"q":"功擅清热解毒，凉血止痢的药物是","o":["穿心莲","连翘","白头翁","山豆根","熊胆粉"],"a":2,"e":"白头翁清热解毒、凉血止痢，尤善清大肠血分热毒，为治热毒血痢之要药。穿心莲虽清热解毒燥湿，主用于湿热泻痢而非血痢；连翘清热解毒、消肿散结，偏治温病与疮痈；山豆根、熊胆粉长于利咽、清肝，均非凉血止痢之品"},{"q":"白芍与熟地黄的共同适应证为","o":["表虚自汗","须发早白","疮疡肿毒","腰膝酸软","阴虚盗汗"],"a":4,"e":"白芍养血敛阴、柔肝止痛、平抑肝阳，熟地黄补血滋阴、益精填髓，二者均入阴分，能滋阴敛汗，共治阴虚盗汗。表虚自汗为黄芪、白术所固；须发早白属精血亏虚，白芍无填精之功；腰膝酸软为肝肾不足，非白芍所主；疮疡肿毒与二者无涉"},{"q":"养阴而不滋腻恋邪，善治阴虚外感的药物是","o":["麦冬","天冬","玉竹","百合","鳖甲"],"a":2,"e":"玉竹养阴润燥、生津止渴，滋阴而不滋腻恋邪，故阴虚外感最宜。麦冬、天冬滋阴力强而偏滋腻，易助湿留邪；百合润肺清心，敛阴力弱；鳖甲滋阴潜阳、软坚散结，更非治外感之品"},{"q":"治疗风湿痹证日久，累及肝肾的最佳药物组合是","o":["防己、独活","五加皮、桑寄生","黄柏、苍术","秦艽、薏苡仁","苍术、桑枝"],"a":1,"e":"五加皮与桑寄生均能祛风湿、补肝肾、强筋骨，标本兼顾，为风湿痹证日久累及肝肾之最佳配伍。防己、独活虽祛风湿止痛，无补肝肾之效；黄柏、苍术清热燥湿，主治湿热下注；秦艽、薏苡仁、桑枝均偏祛邪，无补益肝肾之功"},{"q":"硼砂内服可用治","o":["胃热呕吐","痰热咳嗽","肝火头痛","寒痰寒饮","热淋涩痛"],"a":1,"e":"硼砂内服清肺化痰，外用清热解毒、消肿防腐，痰热咳嗽为其内服主治。胃热呕吐当用黄连、竹茹；肝火头痛宜龙胆、夏枯草；寒痰寒饮属温化范畴，非硼砂所宜；热淋涩痛为利尿通淋药所主"},{"q":"既能袪风湿，又能利水而性寒的药物是","o":["五加皮","秦艽","防己","豨莶草","雷公藤"],"a":2,"e":"防己祛风湿、止痛、利水消肿，性寒，尤宜风湿热痹与水肿。五加皮性温，补肝肾、利水而无寒性；秦艽虽性平，退虚热而无利水之功；豨莶草、雷公藤祛风湿力强，均无利水消肿之能"},{"q":"外用可以治疗斑秃的药物有","o":["淫羊藿","肉苁蓉","吴茱萸","补骨脂","益智仁"],"a":3,"e":"补骨脂补肾助阳、固精缩尿、温脾止泻、纳气平喘，外用可治白癜风、斑秃，故外用治斑秃选之。淫羊藿、肉苁蓉、益智仁虽补肾阳，无外用祛斑生发之用；吴茱萸温中散寒、疏肝下气，与斑秃无涉"},{"q":"被誉为“呕家圣药”的药物是","o":["紫苏叶","生姜","香薷","桂枝","荆芥"],"a":1,"e":"生姜辛温，解表散寒、温中止呕、温肺止咳，还能解鱼蟹毒，止呕功著，被誉为呕家圣药。紫苏叶、香薷虽解表，无温中止呕之专功；桂枝温通经脉、助阳化气；荆芥解表散风，均非呕家要药"},{"q":"以下哪项关于剂量确定依据的说法不妥的是","o":["入汤剂用药剂量较大，入丸散剂量较小","质轻之品用量宜少，质重之品用量宜大","祛邪为主时，用量宜重；补虚为主时，用量宜轻","一般来说，男女用量差别不大","单味药成方用量宜大，复方中药物用量宜小"],"a":2,"e":"剂量当据邪正虚实权衡，补虚宜重以冀缓补见效，祛邪宜轻、中病即止，以免伤正，故祛邪宜重、补虚宜轻之说未妥。入汤剂量大于丸散、质重大于质轻、单方大于复方及男女用量差别不大，均为确定剂量的通行依据"},{"q":"患者风寒湿痹，肢体麻木，关节疼痛，治以活血行气，祛风止痛。最宜选用的药是","o":["艾叶","川芎","羌活","郁金","延胡索"],"a":1,"e":"川芎活血行气、祛风止痛，为血中气药，上行下达，善治风湿痹痛、肢体麻木及跌打损伤，契合活血行气、祛风止痛之治。艾叶温经止血、散寒调经；羌活解表胜湿止痛，无活血行气之功；郁金、延胡索虽活血行气止痛，无祛风之用"},{"q":"患者产后乳汁不下，乳房红肿疼痛，诊为乳痈。最宜选用的药是","o":["赤芍","泽兰","木通","鸡血藤","王不留行"],"a":4,"e":"王不留行活血通经、下乳消肿，善通血脉、利乳窍，为产后乳汁不下及乳痈肿痛之要药。赤芍清热凉血、散瘀止痛；泽兰活血调经、利水消肿；木通利尿通淋、通经下乳，无消肿疗痈之效；鸡血藤养血活血、舒筋活络"},{"q":"具有补肾助阳、固精缩尿功效的药物是","o":["车前子","决明子","牛蒡子","使君子","沙苑子"],"a":4,"e":"沙苑子补肾固精、养肝明目，兼具补肾助阳与固精缩尿之效。车前子利尿通淋、渗湿止泻；决明子清热明目、润肠通便；牛蒡子疏散风热、透疹利咽；使君子杀虫消积，均属不同功效类别"},{"q":"苦杏仁的功效是","o":["止咳平喘，润肠通便","止咳平喘，解痉止痛","止咳平喘，降气化痰","止咳平喘，利水消肿","止咳平喘，清肠消痔"],"a":0,"e":"苦杏仁降气止咳平喘、润肠通便，内含苦杏仁苷，水解生成微量氢氰酸而镇咳，质润多脂故润肠。解痉止痛、利水消肿、清肠消痔、降气化痰皆非其所有，分别近于白芍、葶苈子、槐角、苏子之类"},{"q":"用于阳虚外感及寒痰停饮、鼻渊的药物是","o":["荆芥","紫苏叶","生姜","苍耳子","细辛"],"a":4,"e":"细辛解表散寒、祛风止痛、通窍、温肺化饮，辛温峻烈，能助阳解表，主治阳虚外感、寒痰停饮及鼻渊头痛。荆芥、紫苏叶、生姜解表力缓，无温肺化饮、通鼻窍之专功；苍耳子散风寒、通鼻窍，无温肺化饮、助阳解表之效"},{"q":"蒲黄的用药部位为","o":["叶","花粉","果实","根茎","花穗"],"a":1,"e":"蒲黄为香蒲科植物水烛香蒲等的干燥花粉，药用部位即花粉，生用活血化瘀、行水，炒炭收敛止血。叶、果实、根茎、花穗均非其药用部位，仅花粉入药"},{"q":"当归的道地产区是","o":["山东","云南","甘肃","四川","广西"],"a":2,"e":"当归道地产区为甘肃岷县，素有中国当归之乡之称，以质优油润著称。山东道地阿胶、云南道地三七、四川道地川芎黄连、广西道地肉桂，均非当归产地"},{"q":"马勃的功效是","o":["清肺利咽","清热凉血","清心安神","清肝明目","清热燥湿"],"a":0,"e":"马勃清热解毒、利咽、止血，善治咽喉肿痛、音哑及出血证，以清肺利咽见长。清热凉血属生地、玄参；清心安神属黄连、莲子心；清肝明目属菊花、决明子；清热燥湿属黄芩、黄连"},{"q":"尤善清中上焦湿热的药物是","o":["黄连","黄芩","黄柏","龙胆","秦皮"],"a":1,"e":"黄芩清热燥湿、泻火解毒、止血、安胎，尤善清中上焦湿热与肺火。黄连偏清中焦心胃之火，黄柏专清下焦湿热，龙胆清肝胆实火，秦皮清肝明目、收涩止痢，各有所重"},{"q":"具有清热泻火，养肝明目，退翳功效的药物是","o":["夏枯草","密蒙花","蝉蜕","决明子","鸭跖草"],"a":1,"e":"密蒙花清热泻火、养肝明目、退翳，为眼科常用药，善治目赤肿痛、翳障遮睛。夏枯草清肝明目、散结消肿，无退翳之功；蝉蜕疏散风热、明目退翳，无清热泻火、养肝之效；决明子清热明目、润肠通便；鸭跖草清热解毒、利水"},{"q":"根据脏腑经络病变部位而选药的药性理论是","o":["四气","五味","升降浮沉","归经","有毒无毒"],"a":3,"e":"归经指药物对脏腑经络病变的选择性作用，以脏腑经络理论为基础，据此按病位选药。四气言药性寒热温凉，五味言辛甘酸苦咸，升降浮沉言作用趋向，有毒无毒言安全性，均非依病变部位选药的理论"},{"q":"能截疟， 用治疟疾的药物不包括","o":["槟榔","仙鹤草","大青叶","青蒿","草果"],"a":2,"e":"槟榔、仙鹤草、青蒿、草果均能截疟，用治疟疾；大青叶清热解毒、凉血消斑，无截疟之功，故不包括。青蒿为治疟要药，尤善治温疟；草果燥湿截疟，善治寒湿疟；槟榔、仙鹤草亦能截疟"},{"q":"治疗中风偏瘫，胸痹心痛，眩晕头痛，首选的药物是","o":["葛根","淡豆豉","牛蒡子","薄荷","蝉蜕"],"a":0,"e":"葛根解肌退热、生津止渴、升阳止泻，且能通经活络、扩张血管，现代常用于中风偏瘫、胸痹心痛、眩晕头痛。淡豆豉解表除烦；牛蒡子疏散风热、利咽透疹；薄荷疏散风热、清利头目；蝉蜕疏散风热、利咽开音，均无此心脑血管之用"},{"q":"多服、久服易导致肝功能损害的药物是","o":["皂荚","礞石","黄药子","苦杏仁","天南星"],"a":2,"e":"黄药子解毒散结、凉血降火，然含毒性成分，多服久服易损肝功能，为有名的肝毒性中药。皂荚、天南星有毒而主刺激黏膜；礞石、苦杏仁毒性重在呼吸中枢，均不以肝损害著称"},{"q":"既能解毒明目退翳，又能收湿止痒的药物是","o":["砒石","滑石","硼石","炉甘石","寒水石"],"a":3,"e":"炉甘石解毒明目退翳、收湿止痒、敛疮生肌，为眼科外用要药。砒石剧毒，蚀疮去腐；滑石利尿通淋、清热解暑、外用敛疮；硼砂清热解毒、消肿防腐；寒水石清热泻火，均无明目退翳兼收湿止痒之组合"},{"q":"葶苈子的功效是","o":["清肺止咳，降逆止呕","泻肺平喘，行水消肿","止咳平喘，解痉止痛","润肺下气，消痰止咳","降气止咳平喘，润肠通便"],"a":1,"e":"葶苈子泻肺平喘、行水消肿，力猛，善治痰涎壅肺之喘咳及水肿、胸腹积水。清肺止咳、降逆止呕为枇杷叶、旋覆花之属；解痉止痛非本类；润肺下气、消痰止咳为紫菀、款冬花；降气止咳平喘、润肠通便为苦杏仁"},{"q":"止血药主要归何经","o":["心、肝、脾经","肺、脾、肾经","心、脾、肾经","肝、脾、肾经","心、肝、肾经"],"a":0,"e":"止血药主归心、肝、脾经，心主血脉、肝藏血、脾统血，出血与三脏关系最密。肺、肾经虽与部分止血药相关，如白茅根归肺、地榆归肝，但非止血药归属主流；心、脾、肾或肝、脾、肾之组合均非通行答案"},{"q":"三棱与莪术多醋制后用，目的是为了加强什么作用","o":["祛瘀止痛","生津止渴","收敛固涩","引药入肝","消食化积"],"a":0,"e":"三棱、莪术醋制后增强祛瘀止痛之力，醋酸收涩入肝，行血中之滞而缓急止痛。生津止渴属甘寒药；收敛固涩属酸涩药；引药入肝虽为醋制一般作用，此处主要为增强活血止痛；消食化积属山楂、莱菔子"},{"q":"何首乌炮制的目的是","o":["便于贮藏","便于制剂","改变性能","矫味矫臭","引药入经"],"a":2,"e":"何首乌生用截疟、解毒、润肠通便，制后用补肝肾、益精血、乌须发，炮制改变其性能，故目的为改变性能。便于贮藏、便于制剂为多数炮制共性，非首乌特有；矫味矫臭多用于动物药；引药入经为辅料炮制作用"},{"q":"外用具有消风祛斑功效的药物有","o":["菟丝子、补骨脂","菟丝子、沙苑子","补骨脂、益智仁","补骨脂、沙苑子","菟丝子、益智仁"],"a":0,"e":"菟丝子、补骨脂外用均能消风祛斑，治白癜风、斑秃等，取其补肾助阳、光泽肌肤之效。沙苑子、益智仁无外用祛斑之功，故含此二者之组均非。补骨脂温肾助阳、固精缩尿；菟丝子补肾益精、养肝明目"},{"q":"治温病热陷心包，最适宜的药物是","o":["寒水石","芦根","知母","石膏","竹叶卷心"],"a":4,"e":"竹叶卷心清心泻火、除烦，善清心经之热，温病热陷心包、神昏谵语用之清心解毒。寒水石、石膏清气分实热；芦根清肺胃热、生津；知母滋阴降火，均不专入心包"},{"q":"长于滋阴退热除蒸的药物是","o":["鳖甲","青蒿","牡丹皮","枸杞子","女贞子"],"a":0,"e":"鳖甲滋阴潜阳、退热除蒸、软坚散结，善治阴虚发热、骨蒸劳热、盗汗，为滋阴退热除蒸之要药。青蒿退虚热、凉血、解暑、截疟，无滋阴之功；牡丹皮清热凉血、活血散瘀；枸杞子、女贞子滋补肝肾，退热除蒸力弱"},{"q":"有小毒，孕妇禁用的是","o":["苏木","雪竭","儿茶","土鳖虫","自然铜"],"a":3,"e":"土鳖虫破血逐瘀、续筋接骨，有毒，孕妇禁用，小毒之性明确。苏木、儿茶、血竭活血疗伤而无小毒孕妇禁用之标；自然铜散瘀止痛、接骨疗伤，孕妇慎用而非禁用"},{"q":"既能平肝潜阳，又能软坚散结的药物是","o":["钩藤","蒺藜","牡蛎","天麻","珍珠母"],"a":2,"e":"牡蛎咸寒，平肝潜阳、重镇安神、软坚散结、收敛固涩，既能潜阳又能软坚。钩藤、天麻、蒺藜、珍珠母虽平肝息风或潜阳，均无软坚散结之功"},{"q":"既能补脾益肺，又能养血生津的药物是","o":["山药","党参","白术","甘草","西洋参"],"a":1,"e":"党参补中益气、健脾益肺、养血生津，气血双补而性平，故补脾益肺又养血生津。山药补脾肺肾、益气养阴，无养血之效；白术健脾益气、燥湿利水；甘草补脾益气、清热解毒、调和诸药；西洋参补气养阴、清热生津，均无养血之功"},{"q":"药性平和而不峻，归肝、脾经，既善活血调经 ，又芳香舒脾而行水消肿的药是","o":["牛膝","泽兰","苏木","鸡血藤","王不留行"],"a":1,"e":"泽兰活血调经、利水消肿，性平和而不峻烈，归肝脾经，兼芳香舒脾行水，为妇科活血调经常用药。牛膝活血通经、补肝肾、利尿通淋、引血下行；苏木活血疗伤；鸡血藤养血活血；王不留行通经下乳，均无芳香舒脾行水之特点"},{"q":"止血不留瘀，化瘀不伤正，为外伤科要药的是","o":["白及","蒲黄","地榆","三七","白茅根"],"a":3,"e":"三七化瘀止血、活血定痛，止血而不留瘀、化瘀而不伤正，为外伤科要药。白及收敛止血、消肿生肌，性涩留瘀；蒲黄止血化瘀；地榆凉血止血；白茅根凉血止血、清热利尿，均非外伤科要药"},{"q":"下列哪项不是薄荷的功效","o":["疏散风热","清利头目","利咽","除湿","透疹"],"a":3,"e":"薄荷疏散风热、清利头目、利咽、透疹、疏肝行气、辟秽，无除湿之功。疏散风热、清利头目、利咽、透疹皆其正品功效，除湿当用藿香、佩兰、苍术等芳香化湿或苦燥之品"},{"q":"温通经脉，散寒止痛，可治阳虚寒凝之阴疽的药组是","o":["麻黄、肉桂","附子、干姜","乌药、花椒","丁香、小茴香","桂枝、吴茱萸"],"a":0,"e":"麻黄、肉桂相伍，麻黄开腠达表、散寒通滞，肉桂温通经脉、补火助阳，共温通经脉、散寒止痛，为阳和汤治阳虚寒凝阴疽之核心。附子、干姜温里散寒，重在回阳救逆、温中；乌药、花椒行气温中；丁香、小茴香温中理气，均非阴疽专配"},{"q":"具有活血化瘀，敛肺平喘，化浊降脂功效的药物是","o":["山楂","泽泻","虎杖","丹参","银杏叶"],"a":4,"e":"银杏叶活血化瘀、通络止痛、敛肺平喘、化浊降脂，故具活血化瘀、敛肺平喘、化浊降脂之效。山楂消食化积、活血散瘀；泽泻利水渗湿、泄热；虎杖利湿退黄、清热解毒、散瘀止痛、化痰止咳；丹参活血调经、凉血消痈，均无敛肺平喘、化浊降脂之组合"},{"q":"通草甘淡渗湿，微寒清降，功效是","o":["利尿通利，清心除烦","利尿通淋，清热解暑","利尿通淋，渗湿止泻","清热利湿，通气下乳","清热利湿，祛风止痒"],"a":3,"e":"通草甘淡微寒，清热利湿、通气下乳，善治湿热淋证及产后乳汁不下。利尿通淋、清心除烦为木通；利尿通淋、清热解暑为滑石；利尿通淋、渗湿止泻为车前子；清热利湿、祛风止痒为地肤子"},{"q":"治三焦热盛，高热烦躁，火毒疮疡，目赤肿痛，小便短赤，首选的药物是","o":["石膏","知母","栀子","天花粉","芦根"],"a":2,"e":"栀子泻火除烦、清热利湿、凉血解毒，清泻三焦火邪，主治三焦热盛之高热烦躁、火毒疮疡、目赤肿痛、小便短赤。石膏、知母清气分实热，重在壮热烦渴；天花粉清热生津；芦根清热生津、止呕，均无清泻三焦火毒之力"},{"q":"治肝风内动证，蜈蚣常与之相须为用的是","o":["地龙","钩藤","蕲蛇","僵蚕","全蝎"],"a":4,"e":"全蝎与蜈蚣均息风镇痉、攻毒散结、通络止痛，相须为用，治肝风内动、惊风抽搐效佳。地龙清热息风、通络、利尿；钩藤息风定惊、清热平肝；蕲蛇祛风通络、定惊；僵蚕息风止痉、化痰散结，均非蜈蚣相须之药"},{"q":"朱砂、轻粉的主要毒性成分是","o":["汞","皂苷","内脂","强心苷","毒蛋白"],"a":0,"e":"朱砂、轻粉均为汞化合物，主要毒性成分为汞，朱砂含硫化汞，轻粉含氯化亚汞。皂苷、强心苷、毒蛋白、内酯分别属于皂苷类、强心苷类、毒蛋白类及内酯类成分，均非此二药毒性之源"},{"q":"硫黄、蛇床子均适用的病症是","o":["虚喘","疮疡","寒湿带下","肾虚阳痿","寒湿痹痛"],"a":3,"e":"硫黄补火助阳通便，蛇床子温肾壮阳、燥湿祛风杀虫，二者均归肾经而壮阳，同治肾虚阳痿。虚喘多属肺肾气虚，非二者所主；疮疡非蛇床子主治；寒湿带下为蛇床子所治而硫黄不具；寒湿痹痛非二者共有"},{"q":"下列除哪项外，均为苦味药的作用","o":["清泻火热","淡渗利湿","泻火存阴","通泄大便","降泄逆气"],"a":1,"e":"苦味药能清泻火热、泻火存阴、通泄大便、降泄逆气，苦还能燥湿、坚阴。淡渗利湿为淡味药之功，如茯苓、猪苓，不属苦味作用，故为除外项"},{"q":"北沙参和麦冬都具有的功效是","o":["清心肺之热","清心肝之热","补心肾之阴","补肝肾之阴","养肺胃之阴"],"a":4,"e":"北沙参养阴清肺、益胃生津，麦冬养阴润肺、益胃生津、清心除烦，二者均归肺胃，共具养肺胃之阴之效。清心肺之热非北沙参所专；补心肾、补肝肾之阴属熟地、枸杞、龟板；清心肝之热属黄连、龙胆"},{"q":"不属于青皮主治病证的是","o":["胸胁胀痛","乳房胀痛","食积腹痛","疝气疼痛","呕吐呃逆"],"a":4,"e":"青皮疏肝破气、消积化滞，主治胸胁胀痛、乳房胀痛、疝气疼痛及食积腹痛。呕吐呃逆为胃气上逆，属陈皮、半夏、旋覆花、丁香所主，青皮无降逆止呕之功，故不属其主治"},{"q":"既能滋阴，又能止血的药是","o":["阿胶","白芍","当归","龙眼肉","熟地黄"],"a":0,"e":"阿胶补血滋阴、润燥、止血，既滋阴又止血，为血虚阴虚兼出血之要药。白芍养血敛阴、柔肝止痛，无止血之功；当归补血活血、调经止痛；龙眼肉补心脾、益气血；熟地黄补血滋阴、填精，均无止血之效"},{"q":"既能祛风湿，通经络，止痹痛，又能清虚热，退黄疸的药物是","o":["威灵仙","秦艽","独活","防己","徐长卿"],"a":1,"e":"秦艽祛风湿、通经络、止痹痛，且能清虚热、退黄疸，为风药中之润剂，主治风湿痹痛、骨蒸潮热、湿热黄疸。威灵仙、独活、防己、徐长卿虽祛风湿止痛，均无清虚热、退黄疸之功"},{"q":"广藿香的功效是","o":["行气，温中","燥湿，消积","化湿，行气","化湿，解暑","温中，除痰"],"a":3,"e":"广藿香化湿、解暑、止呕，为湿浊中阻、暑湿表证及呕吐之要药。行气温中属砂仁、白豆蔻；燥湿消积属苍术、厚朴；化湿行气属砂仁；温中除痰属半夏、干姜，均非广藿香功效"},{"q":"土鳖虫除破血逐瘀外，尚能","o":["补肝肾","活血消肿","通络止痛","生肌敛疮","续筋接骨"],"a":4,"e":"土鳖虫破血逐瘀、续筋接骨，为伤科接骨要药，主治跌打损伤、筋伤骨折、瘀血经闭。补肝肾属杜仲、续断；活血消肿属三七；通络止痛属威灵仙、全蝎；生肌敛疮属白及、龙骨，均非其功"},{"q":"麻黄与香薷均有的功效是","o":["和胃","止痉","止咳","平喘","利水"],"a":4,"e":"麻黄发汗解表、宣肺平喘、利水消肿，香薷发汗解表、化湿和中、利水消肿，二者均有发汗解表与利水之功，共有者为利水。和胃、止痉非麻黄所具；止咳为杏仁、紫菀；平喘虽麻黄有而香薷无，非共有"},{"q":"中药剂量，通常是指","o":["每味药的成人一日量","一剂药的成人一次量","重病患者的成人一日量","轻病患者的成人一次量","每味药的儿童一日量"],"a":0,"e":"中药剂量通常指每味药的成人一日量，是临床处方常用度量。一剂药的一次量、重病或轻病患者的用量均为特定情形，非剂量定义；儿童一日量需按年龄折算，不在通常所指之列"},{"q":"枇杷叶的主治证不包括","o":["肺热咳嗽","胃热呕逆","烦热口渴","水肿尿少","气逆喘急"],"a":3,"e":"枇杷叶清肺止咳、降逆止呕，主治肺热咳嗽、气逆喘急及胃热呕逆、烦热口渴。水肿尿少属肺脾肾气化失常，当用葶苈子、桑白皮、茯苓、泽泻等，枇杷叶无利水消肿之功"},{"q":"有生肌敛疮功效，外用可治手足皴裂的药物是","o":["艾叶","蒲黄","白及","三七","仙鹤草"],"a":2,"e":"白及收敛止血、消肿生肌，外用生肌敛疮，可治手足皴裂、疮疡溃烂不敛及外伤出血。艾叶温经止血、散寒调经；蒲黄止血化瘀；三七化瘀止血、定痛；仙鹤草收敛止血、补虚，均无生肌敛疮治皴裂之效"},{"q":"朱砂入药的正确炮制方法是","o":["水飞","炙","煅","煨","淬"],"a":0,"e":"朱砂主要含硫化汞，入药须水飞，借水力研磨取极细粉，除去杂质及可溶性汞盐，降低毒性。炙、煅多用于矿物坚固或增强收敛；煨用于减去刺激性；淬用于磁性或坚硬矿物，均非朱砂炮制法"},{"q":"眼科外治目赤翳障，烂弦风眼，最宜选用","o":["砒石","升药","铅丹","硫磺","炉甘石"],"a":4,"e":"炉甘石解毒明目退翳、收湿止痒、敛疮，为眼科外治目赤翳障、烂弦风眼之要药。砒石、升药蚀疮去腐，毒性剧烈；铅丹拔毒生肌；硫黄解毒杀虫疗疮，均非眼科明目退翳之品"},{"q":"治风寒感冒，巅顶头痛，最宜选用的药物是","o":["羌活","防风","白芷","柴胡","藁本"],"a":4,"e":"藁本祛风解表、胜湿止痛，善入膀胱经而达巅顶，为治风寒感冒、巅顶头痛之要药。羌活善治太阳经头痛及上半身痛；防风祛风解表、胜湿止痛；白芷治阳明经前额痛；柴胡治少阳头痛，均非巅顶专药"},{"q":"在治疗风寒咳喘时，苦杏仁配伍麻黄主要起下列何项作用","o":["止咳化痰，降气平喘","发散风寒，宣肺平喘","发汗解表，化痰止咳","发散风寒，泻肺平喘","宣肺止咳，化痰平喘"],"a":1,"e":"麻黄发散风寒、宣肺平喘，杏仁降肺气、止咳平喘，一宣一降，配伍治风寒咳喘重在发散风寒、宣肺平喘。降气化痰、发汗解表、化痰止咳、泻肺平喘各偏执一端，未概括麻黄宣肺与杏仁降气相辅相成之全貌"},{"q":"能化痰止咳，清利湿热，活血化瘀的药物是","o":["枇杷叶","矮地茶","葶苈子","马兜铃","桑白皮"],"a":1,"e":"矮地茶化痰止咳、清利湿热、活血化瘀，主治咳嗽痰多、湿热黄疸、跌打损伤。枇杷叶清肺止咳、降逆止呕；葶苈子泻肺平喘、行水消肿；马兜铃清肺化痰、止咳平喘；桑白皮泻肺平喘、利水消肿，均无清利湿热、活血化瘀之组合"},{"q":"石斛善治","o":["肺气虚证","肝血虚证","胃阴虚证","肾阳虚证","气阴两虚证"],"a":2,"e":"石斛益胃生津、滋阴清热，善治胃阴虚及热病津伤，为养胃阴要药。肺气虚当补肺气，用黄芪、人参；肝血虚用当归、白芍；肾阳虚用附子、肉桂；气阴两虚用西洋参、山药，均非石斛所主"},{"q":"涩味药物与下列何种药物作用相似","o":["苦味","咸味","酸味","辛味","甘味"],"a":2,"e":"酸味与涩味均能收敛固涩，作用相似，故涩味药物与酸味相近。苦味清泄燥湿；咸味软坚散结；辛味发散行气；甘味补益和中，均与涩味之收敛固涩不同"},{"q":"味辛行散，长于行气除胀的消食药是","o":["附子","莲子","白芥子","莱菔子","紫苏子"],"a":3,"e":"莱菔子辛行，消食除胀、降气化痰，为消食药中行气除胀之佳品。附子回阳救逆、补火助阳，非消食药；莲子补脾止泻、益肾养心；白芥子温肺化痰、利气散结；紫苏子降气化痰、止咳平喘、润肠，均非行气除胀之消食药"},{"q":"不宜与赤石脂同用的药物是","o":["乌头","人参","肉桂","硫黄","禹余粮"],"a":2,"e":"赤石脂与肉桂相畏，十九畏有官桂善能调冷气、若逢石脂便相欺之说，故不宜同用。乌头反半夏、瓜蒌等；人参畏五灵脂；硫黄畏朴硝；禹余粮与赤石脂同类，无相畏关系"},{"q":"具有纳气平喘、温脾止泻功效的药物是","o":["淫羊藿","巴戟天","肉苁蓉","益智仁","补骨脂"],"a":4,"e":"补骨脂补肾助阳、纳气平喘、温脾止泻、固精缩尿，为温肾纳气、温脾止泻之要药。淫羊藿、巴戟天补肾阳、祛风湿，无纳气平喘、温脾止泻；肉苁蓉补肾阳、益精血、润肠；益智仁温脾止泻、固精缩尿，无纳气平喘"},{"q":"汤剂需要先煎，久煎的药物是","o":["肉桂","附子","薄荷","吴茱萸","车前子"],"a":1,"e":"附子有毒，所含乌头双酯型生物碱需久煎水解以降低毒性，故汤剂须先煎、久煎。肉桂含挥发油，宜后下或焗服；薄荷芳香，后下；吴茱萸不需久煎；车前子细小，宜包煎，均非先煎久煎之列"},{"q":"穿心莲有泻火解毒之功，善治的病证是","o":["肠痈","肺痈","乳痈","疔疮","口疮"],"a":1,"e":"穿心莲清热解毒、凉血、燥湿、消肿，善清肺热，为治肺痈、肺热咳喘之要药。肠痈多属湿热瘀滞，大黄、牡丹皮、红藤主之；乳痈属肝胃郁热，蒲公英主之；疔疮、口疮虽可治，非其最善之证"},{"q":"黄连用治湿热泻痢，腹痛里急后重，常配伍的药物是","o":["陈皮","龙胆","青皮","木香","香附"],"a":3,"e":"黄连清热燥湿、泻火解毒，治湿热泻痢腹痛、里急后重，配木香行气止痛，气行则后重自除。陈皮理气健脾、燥湿化痰；青皮疏肝破气；龙胆清肝胆实火；香附疏肝理气、调经止痛，均无行气导滞治里急后重之专功"},{"q":"被誉为“东方医学巨典”的著作是","o":["《本草纲目拾遗》","《神农本草经》","《本草纲目》","《新修本草》","《本草经集注》"],"a":2,"e":"本草纲目为明代李时珍所撰，集历代本草之大成，被誉东方医学巨典。本草纲目拾遗为清代赵学敏补遗之作；神农本草经为最早本草；新修本草为唐代官修、图文对照之本草；本草经集注为陶弘景所撰"},{"q":"以下哪个是江苏的道地药材","o":["薄荷","山药","菊花","麦冬","白术"],"a":0,"e":"薄荷道地产于江苏，称苏薄荷，为江苏道地药材。山药道产河南，称怀山药；菊花道产浙江、安徽、河南，分别称杭菊、滁菊、亳菊、怀菊；麦冬道产浙江、四川；白术道产浙江、安徽，均非江苏所主"},{"q":"既能清泄三焦火邪，又善清心泻火而除烦的药物是","o":["石膏","芦根","知母","天花粉","栀子"],"a":4,"e":"栀子清泻三焦火邪、泻火除烦、清热利湿、凉血解毒，善清心泻火而除烦，主治热病心烦、三焦火盛。石膏、知母偏清气分壮热；芦根清肺胃热、生津；天花粉清热生津，均不专清三焦火邪与心火除烦"},{"q":"使用化痰药治疗癫痫惊厥者，最常配伍","o":["清热药、消食药","补虚药、消食药","安神药、理气药","安神药、泻下药","平肝息风药、安神药"],"a":4,"e":"癫痫惊厥多与肝风、痰迷心窍相关，化痰药治此最常配平肝息风药以治本、安神药以定惊。清热药、消食药仅清化痰热或消食积；补虚药扶正；泻下药逐痰，均非化痰药治癫痫惊厥之常配"},{"q":"功效生津止渴，能治疗热病口渴，消渴的药物是","o":["葛根","淡豆豉","牛蒡子","薄荷","蝉蜕"],"a":0,"e":"葛根解肌退热、生津止渴、升阳止泻，能鼓舞胃气上行，滋生津液，主治热病口渴、消渴。淡豆豉解表除烦；牛蒡子疏散风热、利咽透疹；薄荷疏散风热；蝉蜕疏散风热、利咽开音，均无生津止渴治消渴之功"},{"q":"七情配伍中，可以降低药物功效的是","o":["相须","相使","相杀","相畏","相恶"],"a":4,"e":"相恶指两药合用，一药能使另一药功效降低甚至丧失，如人参恶莱菔子。相须、相使增强疗效；相杀为一药减另一药毒性；相畏为自身毒性被他药减轻，均不涉及降低药物功效"},{"q":"辛香透散，既清虚热，又解暑热的药物是","o":["黄柏","知母","青蒿","白薇","薄荷"],"a":2,"e":"青蒿辛香透散，退虚热、凉血、解暑、截疟，既清虚热又解暑热，为治温病暑热及骨蒸虚热之要药。黄柏、知母滋阴降火而无解暑；白薇凉血清虚热而无解暑；薄荷疏散风热，均无清虚热兼解暑之组合"},{"q":"附子的主治证不包括","o":["亡阳四肢厥冷","风寒湿痹疼痛","虚寒脘腹冷痛","寒饮伏肺喘嗽","阳虚外感风赛"],"a":3,"e":"附子补火助阳、散寒止痛、温经通脉、回阳救逆，主治亡阳厥冷、阳虚寒凝之脘腹冷痛、风寒湿痹、阳虚外感。寒饮伏肺喘嗽当温肺化饮，用细辛、干姜、麻黄，附子无温肺化饮止咳平喘之效"},{"q":"属于“十八反”的配伍药对是","o":["甘草与海藻","丁香与郁金","人参与五灵脂","川芎与牛膝","三棱与莪术"],"a":0,"e":"甘草与海藻属十八反，藻戟遂芫俱战草，甘草反海藻、大戟、甘遂、芫花。丁香与郁金、人参与五灵脂、三棱与莪术属十九畏；川芎与牛膝无相反相畏关系"},{"q":"牛膝除可逐瘀通经外又能","o":["行气解郁","引火归元","利水通淋","祛风通络","消积止痛"],"a":2,"e":"牛膝活血通经、补肝肾、强筋骨、利尿通淋、引血下行，故逐瘀通经外又能利水通淋。行气解郁属香附、郁金；引火归元属肉桂；祛风通络属威灵仙、秦艽；消积止痛属三棱、莪术"},{"q":"淫羊藿具有的功效是","o":["补肾阳、安胎元","补肾阳、祛风湿","祛风湿、退虚热","补肾阳、止咳喘","祛风湿、止泻痢"],"a":1,"e":"淫羊藿补肾阳、强筋骨、祛风湿，主治肾阳虚衰、阳痿遗精及风湿痹痛。安胎属黄芩、砂仁、桑寄生；退虚热属青蒿、鳖甲；止咳喘属杏仁、苏子；止泻痢属黄连、葛根，均非淫羊藿功效"},{"q":"既用于治疗肺痈，又可治疗肠痈的药是","o":["桃仁","赤芍","大血藤","鱼腥草","牡丹皮"],"a":0,"e":"桃仁活血祛瘀、润肠通便、止咳平喘，善治瘀血诸证，并可用于肺痈、肠痈，取其活血散瘀、通腑排脓之效。大血藤、牡丹皮偏治肠痈；鱼腥草偏治肺痈；赤芍清热凉血、散瘀止痛，均非肺痈肠痈兼治之品"},{"q":"紫草的药用部分是","o":["根","全草","花粉","果实","种子"],"a":0,"e":"紫草药用部分为根，含紫草素等，凉血活血、解毒透疹，主治血热毒盛、麻疹紫暗、疮疡湿疹。全草、花粉、果实、种子均非紫草药用部位，仅根入药"},{"q":"内能燥湿健脾，外能散风寒，除痹发表的药物是","o":["白术","独活","藁本","苍术","广藿香"],"a":3,"e":"苍术燥湿健脾、祛风散寒、明目，内能燥湿健脾以治湿阻中焦，外能散风寒、除痹发表以治风湿痹证、风寒表证。白术健脾益气、燥湿利水、止汗安胎，无祛风散寒发表之效；独活、藁本无健脾燥湿；广藿香化湿解暑止呕"},{"q":"蜂房具有的功效是","o":["截疟杀虫","祛痰平喘","开窍醒神","祛风止痛","燥湿止带"],"a":3,"e":"蜂房祛风止痛、消肿散结、解毒杀虫，善治风湿痹痛、牙痛、疮疡肿毒、瘰疬。截疟杀虫属青蒿、槟榔；祛痰平喘属杏仁、苏子；开窍醒神属麝香、冰片；燥湿止带属黄柏、白芷，均非蜂房之功"},{"q":"《名医别录》有“主妇人生子不下”的记载，故孕妇慎用的药物是","o":["薄荷","牛蒡子","蝉蜕","升麻","柴胡"],"a":2,"e":"蝉蜕疏散风热、利咽开音、透疹止痒、明目退翳、息风止痉，《名医别录》载其主妇人生子不下，故孕妇慎用。薄荷、牛蒡子疏散风热；升麻、柴胡升举阳气、解表，均无此孕妇慎用之特殊记载"},{"q":"治疗肝阳上亢，头晕头痛，首选的药物是","o":["菊花","升麻","牛蒡子","蝉蜕","薄荷"],"a":0,"e":"菊花疏散风热、平肝明目、清热解毒，善清肝火、平肝阳，为治肝阳上亢、头晕头痛之首选。升麻、柴胡升举阳气；牛蒡子、薄荷疏散风热；蝉蜕疏散风热、利咽，均无平肝潜阳之功"},{"q":"砂仁不具备的功效是","o":["安胎","化湿","平喘","温中","行气"],"a":2,"e":"砂仁化湿行气、温中止泻、安胎，主治湿浊中阻、脾胃虚寒、胎动不安，无平喘之功。安胎、化湿、温中、行气皆其正品功效，平喘当用麻黄、杏仁、苏子、葶苈子等，故砂仁不具备"},{"q":"可用治肺痈、肠痈的药物是","o":["茯苓","泽泻","冬瓜皮","猪苓","薏苡仁"],"a":4,"e":"薏苡仁利水渗湿、健脾止泻、除痹排脓、解毒散结，性微寒，能清肺肠之热毒，可用治肺痈、肠痈。茯苓、猪苓、泽泻利水渗湿，无排脓消痈之效；冬瓜皮利水消肿，亦无此功"},{"q":"下面为相反配伍的药物是","o":["大戟与乌头","芫花与海藻","乌头与半夏","贝母与瓜蒌","丹参与芍药"],"a":2,"e":"乌头与半夏属十八反，本草明言十八反，乌头反半夏、瓜蒌、贝母、白蔹、白及。大戟与乌头无相反关系；芫花与海藻不反；贝母与瓜蒌同反乌头而彼此不反；丹参与芍药属十九畏，非相反"},{"q":"咳喘兼大便秘结者，宜选用","o":["紫苏叶","紫苏梗","紫苏子","车前子","葶苈子"],"a":2,"e":"紫苏子降气化痰、止咳平喘、润肠通便，性润降，最宜咳喘兼大便秘结者，肺气降则喘咳平，肠润则便通。紫苏叶、紫苏梗解表行气宽中；车前子利尿通淋、渗湿止泻；葶苈子泻肺平喘、行水消肿，均无润肠通便之效"},{"q":"既可用于血热出血，又可用于热壅血滞的药物是","o":["赤芍","青黛","生地黄","玄参","贯众"],"a":0,"e":"赤芍清热凉血、散瘀止痛，既清血分之热以治血热出血，又散血分之滞以治热壅血滞，一举两得。生地黄、玄参清热凉血、养阴，无散瘀之力；青黛、贯众清热解毒、凉血止血，亦无活血散瘀之效"},{"q":"地肤子药性苦降辛散，寒清，主入肾、膀胱经，其功效是","o":["清利湿热，利胆退黄","清利湿热，通淋止痛","利尿通淋，清热解暑","利湿退黄，利尿通淋","清热利湿，祛风止痒"],"a":4,"e":"地肤子苦降辛散、性寒，主入肾膀胱经，清热利湿、祛风止痒，为治皮肤瘙痒、湿疹、阴痒之要药。清利湿热、利胆退黄属茵陈；通淋止痛属石韦、瞿麦；清热解暑属滑石；利湿退黄属金钱草，均非地肤子功效"},{"q":"治少阳证之要药是","o":["菊花","柴胡","牛蒡子","蝉蜕","薄荷"],"a":1,"e":"柴胡疏散退热、疏肝解郁、升举阳气，善疏解少阳半表半里之邪，为治少阳证寒热往来之要药。菊花平肝明目；牛蒡子疏散风热、利咽；蝉蜕利咽开音、息风；薄荷疏散风热、清利头目，均非少阳专药"},{"q":"既可用于惊风癫痫，又能用于淋证，癃闭的药物是","o":["琥珀","龙骨","车前子","柏子仁","酸枣仁"],"a":0,"e":"琥珀镇惊安神、活血散瘀、利尿通淋，既能定惊止痉治惊风癫痫，又能通淋利尿治淋证、癃闭。龙骨镇心安神、平肝潜阳、收敛固涩；车前子利尿通淋；柏子仁、酸枣仁养心安神，均无利尿通淋或定惊之兼备"},{"q":"车前子是常用利尿通淋药，其主治病证不包括","o":["湿热淋证","小便不利之水泻","脾虚湿盛泄泻","寒湿痹证","暑湿泄泻"],"a":3,"e":"车前子利尿通淋、渗湿止泻、明目、祛痰，主治湿热淋证、小便不利之水泻、脾虚湿盛泄泻及暑湿泄泻。寒湿痹证属寒湿阻络，当温经散寒、祛风除湿，车前子性寒渗利，非所宜，故不包括"},{"q":"花椒为药食两用中药，作为药用时煎服的用量为","o":["1～3g","1～5g","2～5g","3～6g","3～10g"],"a":3,"e":"花椒煎服常用量为三至六克，药食两用，温中止痛、杀虫止痒。一至三克、一至五克、二至五克均低于常用量；三至十克偏高，非花椒常规煎服剂量"},{"q":"五味子和乌梅的共同功效是","o":["益气滋阴","补肾宁心","安蛔止痛","敛肺生津","涩精止遗"],"a":3,"e":"五味子收敛固涩、益气生津、补肾宁心，乌梅敛肺止咳、涩肠止泻、生津、安蛔，二者均酸收敛肺、生津止渴，共有功效为敛肺生津。益气滋阴、补肾宁心仅五味子具之；安蛔止痛仅乌梅有；涩精止遗主要五味子，均非共有"},{"q":"升药的功效是","o":["杀虫止痒","止血敛疮","拔毒去腐","清热解毒","消痈散结"],"a":2,"e":"升药即红升丹，拔毒去腐、生肌，为外科提脓祛腐要药，主治痈疽溃后、腐肉不脱。杀虫止痒属硫黄、蛇床子；止血敛疮属白及、三七；清热解毒属金银花、连翘；消痈散结属蒲公英、夏枯草，均非升药之功"},{"q":"治疗阳明腑实，大黄、芒硝配伍甘草的主要目的是","o":["缓急止痛","健脾益气","调和药性","清热解毒","行气止痛"],"a":2,"e":"大黄、芒硝泻下攻积、软坚润燥，配伍甘草意在缓和峻下之力、调和药性，使泻下而不伤正。缓急止痛为芍药甘草汤之用；健脾益气属参、芪；清热解毒属芩、连；行气止痛属木香、延胡索，均非此处配伍甘草之目的"},{"q":"治肺热伤阴，燥咳无痰，最适宜的药物是","o":["石膏","寒水石","知母","栀子","淡竹叶"],"a":2,"e":"知母清热泻火、滋阴润燥，上能清肺热、润肺燥，治肺热伤阴、燥咳无痰最宜。石膏、寒水石清气分实热而无滋阴润燥；栀子泻火除烦、清利三焦；淡竹叶清心利尿，均不能润燥止咳"},{"q":"炒用可使其苦寒及滑肠之性略减的药物是","o":["菊花","升麻","牛蒡子","蝉蜕","柴胡"],"a":2,"e":"牛蒡子辛苦寒，疏散风热、利咽透疹、解毒散肿，且润肠通便，炒用可缓和苦寒及滑肠之性。菊花、升麻、蝉蜕、柴胡均无滑肠之弊，无需炒制以减苦寒滑肠，故非所指"},{"q":"桑枝的功效是","o":["祛风除湿，通络止痛，杀虫止痒","袪风通络，凉血消肿","祛风湿，通经络，止泻痢","祛风，通络，活血，下乳","袪风湿，利关节"],"a":4,"e":"桑枝祛风湿、利关节、通经络，尤宜风湿痹痛、关节不利、屈伸困难。祛风除湿、通络止痛、杀虫止痒为伸筋草、威灵仙之类；凉血消肿为豨莶草、秦艽；通经络、止泻痢为秦艽；祛风通络、活血下乳为穿山甲、王不留行"},{"q":"其气清芬，能清热利湿，治疗湿温暑湿的是","o":["滑石","金钱草","虎杖","茵陈","木通"],"a":3,"e":"茵陈气清芬，清利湿热、利胆退黄，善治湿热黄疸，亦可用于湿温、暑湿等证。滑石清热利湿、解暑，无芳香化浊之性；金钱草、虎杖利湿退黄；木通利尿通淋、清心火，均无清芬化湿治湿温之特点"},{"q":"尤善治疔毒的药物是","o":["蒲公英","鱼腥草","紫花地丁","重楼","大青叶"],"a":2,"e":"紫花地丁清热解毒、凉血消肿，尤善治疔毒，为疔疮肿毒之要药。蒲公英善治乳痈；鱼腥草善治肺痈；重楼清热解毒、消肿止痛，善治痈肿疔毒但非最专；大青叶清热解毒、凉血消斑，均非疔毒首选"},{"q":"运用凉血止血药时，常配何类药以加强疗效","o":["清热凉血药","滋阴润燥药","收敛止血药","化瘀止血药","活血化瘀药"],"a":0,"e":"凉血止血药性寒凉，用于血热出血，常配清热凉血药以助清血分之热，源清则流自洁。滋阴润燥治阴虚出血；收敛止血治无瘀出血；化瘀止血治瘀血出血；活血化瘀治血瘀经闭，均非凉血止血之常配"},{"q":"擅长通经下乳，为治产后乳汁不下之要药的是","o":["水蛭","三棱","莪术","穿山甲","蒲公英"],"a":3,"e":"穿山甲活血消癥、通经下乳、消肿排脓，性善走窜，通经下乳之力强，为治产后乳汁不下之要药。水蛭、三棱、莪术破血逐瘀，无通乳之效；蒲公英消痈散结、通乳，力逊且非通经要药"},{"q":"妊娠禁用药应除外","o":["牵牛","桃仁","巴豆","莪术","水蛭"],"a":1,"e":"桃仁活血祛瘀、润肠通便、止咳平喘，属妊娠慎用药而非禁用药。牵牛、巴豆、莪术、水蛭毒性较强或药性猛烈，均为妊娠禁用药，故妊娠禁用药中应除外桃仁"},{"q":"慎用温经止血药的病证为","o":["瘀血之出血证","气虚之出血证","阳虚之出血证","脾虚之出血证","血热妄行之出血证"],"a":4,"e":"温经止血药性温热，专治虚寒出血，血热妄行之出血证慎用，以免助热动血、加重出血。瘀血出血当化瘀止血；气虚出血当补气摄血；阳虚、脾虚出血多属虚寒，可用温经止血，均非所忌"},{"q":"既能解表散寒、行气宽中安胎，又能解鱼蟹毒的药物是","o":["紫苏叶","砂仁","黄芩","桑寄生","白术"],"a":0,"e":"紫苏叶解表散寒、行气宽中、安胎，并能解鱼蟹毒，治风寒感冒、脾胃气滞、胎动不安及食鱼蟹中毒。砂仁化湿行气、温中安胎，无解表散寒、解鱼蟹毒之功；黄芩清热安胎；桑寄生、白术补虚安胎，均无解表与解毒之能"},{"q":"龟甲、鳖甲的煎煮方法是","o":["先煎","后下","包煎","烊化","冲服"],"a":0,"e":"龟甲、鳖甲为动物甲壳，质地坚硬，有效成分不易溶出，须先煎久煎。后下用于芳香易挥发药；包煎用于细小种子、绒毛、易粘锅药；烊化用于胶类；冲服用于贵重或液体药，均非甲壳类用法"},{"q":"可随时采收的药材是","o":["矿物药","动物药","根类植物药","叶类植物药","果实类植物药"],"a":0,"e":"矿物药化学性质稳定，不受季节影响，故可随时采收。动物药多有季节活动规律；根类植物药宜秋后春前采挖；叶类宜开花前或盛花期采收；果实类宜成熟时采收，均有特定时令"},{"q":"清虚热药的药性特点是","o":["性寒凉，主归肺、胃经","性寒凉，主归肝、肾经","性温热，主归肺、肝经","性温热，主归心、肺经","性寒凉，主归胃、肾经"],"a":1,"e":"清虚热药多性寒凉，主归肝、肾经，以清虚热、退骨蒸为主，治阴虚内热、骨蒸潮热、盗汗。性寒凉而主肺胃经多属清气分实热药；性温热药主治寒证，与清虚热之性相反；归胃肾经组合非清虚热药归经主流"},{"q":"在“十八反”中，下列除哪味药物外均与乌头相反","o":["玄参","白及","贝母","瓜蒌","半夏"],"a":0,"e":"乌头反半夏、瓜蒌、贝母、白蔹、白及，玄参不在其列，故除外玄参。白及、贝母、瓜蒌、半夏均为乌头相反之药，配伍可增毒性，属十八反禁忌"},{"q":"五加皮的功效是","o":["袪风湿，补肝肾，安胎","袪风湿，补肝肾，调冲任","袪风湿，补肝肾，利水","袪风湿，强筋骨，补肾阳","袪风湿，强筋骨，止血"],"a":2,"e":"五加皮祛风湿、补肝肾、强筋骨、利水消肿，为风湿痹痛、筋骨无力及水肿之常用药。安胎属桑寄生、杜仲；调冲任属当归、阿胶；补肾阳属淫羊藿、巴戟天；止血属仙鹤草、三七，均非五加皮之功"},{"q":"不具有生津止渴功效的药是","o":["麦冬","山药","鳖甲","玉竹","天花粉"],"a":2,"e":"鳖甲滋阴潜阳、退热除蒸、软坚散结，无生津止渴之功。麦冬、玉竹、天花粉均养阴生津止渴；山药益气养阴、生津止渴，均具生津之效，故鳖甲为不具有者"},{"q":"大剂量久服可导致水钠潴留，引起浮肿的药物是","o":["黄芪","人参","甘草","党参","白术"],"a":2,"e":"甘草大剂量或久服可引起水钠潴留，导致浮肿、血压升高，与其甘草酸成分的皮质激素样作用有关。黄芪、人参、党参、白术虽补气，无此水钠潴留致浮肿之典型不良反应"},{"q":"既能润肠通便，又能润肺止咳的药物是","o":["火麻仁","郁李仁","松子仁","柏子仁","决明子"],"a":2,"e":"松子仁润肠通便、润肺止咳，质润多脂，兼能滋养肺阴，故润肠兼润肺止咳。火麻仁、郁李仁润肠通便而无润肺止咳；柏子仁养心安神、润肠；决明子清热明目、润肠，均无润肺止咳之效"},{"q":"外敷能发泡，皮肤过敏者忌用的药物是","o":["芥子","桔梗","半夏","天南星","白附子"],"a":0,"e":"芥子温肺化痰、利气散结、通络止痛，外敷可发泡，皮肤过敏者忌用。桔梗宣肺、利咽、祛痰、排脓；半夏、天南星、白附子燥湿化痰、祛风解痉，外敷虽可刺激，但以发泡忌过敏著称者为芥子"},{"q":"枇杷叶止咳平喘的机制是","o":["宣肺","润肺","清肺","敛肺","泻肺"],"a":2,"e":"枇杷叶清肺止咳、降逆止呕，其止咳平喘机制在于清泄肺热、降肺气，肺热清、肺气降则咳喘自平。宣肺属麻黄、桔梗；润肺属百合、川贝母；敛肺属五味子、罂粟壳；泻肺属葶苈子、桑白皮，均非枇杷叶之机制"},{"q":"味甘，性凉，善走肌肤以利尿消肿，治疗夏日水肿胀满，小便不利的药物是","o":["香加皮","猪苓","茯苓","薏苡仁","冬瓜皮"],"a":4,"e":"冬瓜皮甘凉，善走肌肤，利尿消肿，兼清热解暑，为治夏日水肿胀满、小便不利之要药。香加皮祛风湿、强筋骨、利水；猪苓、茯苓利水渗湿；薏苡仁利水健脾，均无走肌肤、清暑治夏日水肿之特点"},{"q":"治蛔虫、绦虫及虫积腹痛者，宜选用","o":["甘遂","京大戟","芫花","巴豆霜","牵牛子"],"a":4,"e":"牵牛子泻下逐水、去积杀虫，能驱杀蛔虫、绦虫，并治虫积腹痛。甘遂、京大戟、芫花泻水逐饮，无杀虫之功；巴豆霜峻下冷积、逐水退肿，亦无驱虫之效，故宜牵牛子"},{"q":"香附醋制的目的是","o":["减低毒性","便于制剂","加强防腐","加强止痛作用","加强活血作用"],"a":3,"e":"香附疏肝解郁、理气宽中、调经止痛，醋制后增强疏肝止痛之力，故目的为加强止痛作用。减低毒性非香附所需；便于制剂为共性；加强防腐、加强活血均非香附醋制之主要目的"},{"q":"穿心莲可用治湿热泻痢、湿疹，主要是因其能","o":["泻火解毒","清热燥湿","清利湿热","凉血消肿","祛风除湿"],"a":1,"e":"穿心莲清热解毒、燥湿，善清湿热，湿热泻痢、湿疹皆由湿热所致，故取清热燥湿之功。泻火解毒偏治热毒炽盛；清利湿热偏于清利小便；凉血消肿治血热痈肿；祛风除湿治风湿痹痛，均非治湿热泻痢湿疹之主因"},{"q":"芡实与白芷均可用治","o":["头痛","带下","遗精滑精","脾虚久泻","疮痈肿毒"],"a":1,"e":"芡实益肾固精、补脾止泻、除湿止带，白芷祛风解表、胜湿止痛、止带，二者均可用治带下。头痛、疮痈肿毒为白芷所主而芡实无；遗精滑精、脾虚久泻为芡实所主而白芷无，故共有者为带下"},{"q":"海螵蛸与赤石脂均具有的功效是","o":["收敛止血，敛疮","收敛止血，制酸","涩肠止泻，敛疮","涩肠止泻，生肌","固精缩尿，止血"],"a":0,"e":"海螵蛸收敛止血、制酸止痛、收湿敛疮、涩精止带，赤石脂涩肠止泻、收敛止血、外用收湿敛疮生肌，二者共有收敛止血、敛疮。制酸仅海螵蛸有；涩肠止泻、生肌主要赤石脂；固精缩尿非二者共有"},{"q":"下列哪项不是甘草的归经","o":["脾经","肺经","胃经","肝经","心经"],"a":3,"e":"甘草归心、肺、脾、胃经，不归肝经，故肝经为其所无。脾、肺、胃、心经皆为甘草归经，甘草补脾益气、祛痰止咳、清热解毒、调和诸药，作用部位与肝经无涉"},{"q":"均可治水肿、脚气的药物是","o":["防己、五加皮、独活","防己、五加皮、木瓜","五加皮、蕲蛇、防己","防己、威灵仙、木瓜","桑寄生、防己、五加皮"],"a":1,"e":"防己利水消肿、祛风湿止痛，五加皮祛风湿、强筋骨、利水，木瓜舒筋活络、和胃化湿、利湿，三药均可用治水肿、脚气。独活、蕲蛇、威灵仙、桑寄生虽祛风湿，无利水消肿或治脚气之效，故组合不当"},{"q":"血竭、儿茶的相同功效是","o":["活血止血，生肌敛疮","活血疗伤，通络止痛","活血定痛，清肺化痰","活血疗伤，补肾强骨","散瘀止痛，消食化积"],"a":0,"e":"血竭活血定痛、化瘀止血、生肌敛疮，儿茶活血止痛、止血、收湿生肌敛疮，二者相同功效为活血止血、生肌敛疮。通络止痛、补肾强骨、清肺化痰、消食化积均非二者共有"},{"q":"下列哪项是淡味药的作用","o":["软坚散结","活血祛瘀","疏肝理气","利水渗湿","泻下通便"],"a":3,"e":"淡味药能利水渗湿，主治水肿、小便不利，如茯苓、猪苓、薏苡仁。软坚散结属咸味；活血祛瘀属辛、苦味；疏肝理气属辛味；泻下通便属苦味，均非淡味作用"},{"q":"最早采用图文对照编写方法的本草著作是","o":["《神农本草经》","《证类本草》","《本草经集注》","《本草拾遗》","《新修本草》"],"a":4,"e":"新修本草为唐代官修本草，采用图文对照的编写方法，是世界上最早的由国家颁行的药典性本草。神农本草经为最早本草但无图；本草经集注、本草拾遗无图文对照；证类本草为宋代，晚于新修本草"},{"q":"黄芩治疗血热便血，常配伍的药是","o":["地榆","三七","黄连","白及","艾叶"],"a":0,"e":"黄芩清热燥湿、泻火解毒、凉血止血，治血热便血常配地榆，地榆凉血止血、解毒敛疮，尤宜下焦血热之便血、痔血。三七化瘀止血；黄连清热燥湿、泻火；白及收敛止血；艾叶温经止血，均非黄芩治血热便血之常配"},{"q":"缓和甘遂、大戟、芫花毒烈之性，宜选用","o":["甘草","大枣","白芍","生姜","花椒"],"a":1,"e":"甘遂、大戟、芫花毒烈，泻水逐饮力强，十枣汤中用大枣缓和其毒烈之性、顾护脾胃，故宜大枣。甘草与甘遂、大戟、芫花相反，不可同用；白芍、生姜、花椒均无缓和三药毒烈之性之效"},{"q":"既能开窍醒神，又能凉肝息风的药物是","o":["冰片","钩藤","牛黄","石菖蒲","苏合香"],"a":2,"e":"牛黄清心凉肝、豁痰开窍、息风止痉，既能开窍醒神治热病神昏，又能凉肝息风治惊风抽搐。冰片、苏合香开窍醒神而无凉肝息风；钩藤息风定惊而无开窍；石菖蒲开窍豁痰、醒神，无凉肝息风之功"},{"q":"确定归经学说的理论基础是","o":["阴阳学说","脏腑经络理论","药性理论","药味理论","五行学说"],"a":1,"e":"归经学说以脏腑经络理论为基础，说明药物对特定脏腑经络病变的选择性作用。阴阳、五行学说为工具理论；药性理论涵盖四气五味等；药味理论仅言五味，均非归经确立之直接理论基础"},{"q":"善治阴虚劳嗽，肺燥咳嗽的药对为","o":["知母、黄柏","桑叶、菊花","金银花、连翘","知母、川贝母","天花粉、栀子"],"a":3,"e":"知母滋阴润燥、清热泻火，川贝母润肺化痰、止咳散结，二者相配，滋阴润肺、化痰止咳，善治阴虚劳嗽、肺燥咳嗽。知母、黄柏滋阴降火，偏治骨蒸；桑叶、菊花疏散风热；金银花、连翘清热解毒；天花粉、栀子清热，均非润肺止咳之药对"},{"q":"性微寒的行气药是","o":["木香","香附","沉香","薤白","枳实"],"a":4,"e":"枳实破气消积、化痰散结，性微寒，为行气药中性偏寒者。木香、沉香、薤白性温，香附性平，均无微寒之性，故性微寒的行气药为枳实"},{"q":"主治妇女虚寒证崩漏下血、胎漏的药是","o":["白及","艾叶","三七","大蓟","白茅根"],"a":1,"e":"艾叶温经止血、散寒调经、安胎，辛温，善治妇女虚寒性崩漏下血、胎漏及月经不调。白及、大蓟、白茅根性寒凉，凉血止血，治血热出血；三七化瘀止血，均无温经散寒安胎之效"},{"q":"具有调和营卫之效的配伍是","o":["金银花与连翘","大黄与芒硝","麻黄与桂枝","桂枝与白芍","桂枝与甘草"],"a":3,"e":"桂枝解肌发表、调和营卫，白芍养血敛阴、柔肝止痛，一散一收，相须为用，共奏调和营卫之效，如桂枝汤。金银花与连翘清热解毒；大黄与芒硝泻下软坚；麻黄与桂枝发汗解表；桂枝与甘草辛甘化阳，均非调和营卫之配伍"},{"q":"既能温经止血，又能温中止痛的药物是","o":["干姜","炮姜","生姜","白及","艾叶"],"a":1,"e":"炮姜温经止血、温中止痛，性温，主治脾胃虚寒之吐血、便血、崩漏及腹痛腹泻。干姜温中散寒、回阳通脉；生姜解表散寒、温中止呕；白及收敛止血；艾叶温经止血、散寒调经，均无温中止痛之兼备"},{"q":"苦泄性平，袪风湿而善达四肢经络，通利关节，尤宜于风湿热痹，肩臂、关节酸痛麻木的药物是","o":["桑枝","防己","豨莶草","秦艽","威灵仙"],"a":0,"e":"桑枝苦泄性平，袪风湿、利关节、通经络，善达四肢经络，尤宜风湿热痹及肩臂关节酸痛麻木。防己、秦艽、豨莶草、威灵仙虽祛风湿，无善达四肢经络、专治肩臂痛之特点"},{"q":"味咸辛，性平，息风止痉兼能化痰，适用于惊风、癫痫夹有痰热的是","o":["地龙","全蝎","蜈蚣","僵蚕","钩藤"],"a":3,"e":"僵蚕咸辛性平，息风止痉、祛风止痛、化痰散结，并能清热，适用于惊风、癫痫夹痰热者。地龙清热息风、通络；全蝎、蜈蚣息风镇痉、攻毒散结，无化痰之功；钩藤息风定惊、清热平肝，均无化痰散结之效"},{"q":"海藻的功效是","o":["消痰软坚","降逆止呕","泻肺平喘","燥湿化痰","祛风止痛"],"a":0,"e":"海藻消痰软坚散结、利水消肿，咸寒，善治瘰疬、瘿瘤、痰核。降逆止呕属半夏、旋覆花；泻肺平喘属葶苈子、桑白皮；燥湿化痰属半夏、陈皮；祛风止痛属白芷、川芎，均非海藻功效"},{"q":"补骨脂具有的功效是","o":["重镇安神、纳气平喘","温肾助阳、纳气平喘","疏肝理气、纳气平喘","温肾助阳、润肠通便","温肾助阳、燥湿止带"],"a":1,"e":"补骨脂温肾助阳、纳气平喘、温脾止泻、固精缩尿，为温肾纳气平喘之要药。重镇安神属磁石、朱砂；疏肝理气属香附、柴胡；润肠通便属肉苁蓉、当归；燥湿止带属黄柏、白芷，均非补骨脂功效"},{"q":"治疗瘰疬、瘿瘤等证的药物具有的药味是","o":["苦","甘","咸","涩","淡"],"a":2,"e":"咸味药能软坚散结、泻下通便，瘰疬、瘿瘤多为痰火郁结、坚硬不消，故治以咸味药如海藻、昆布、牡蛎。苦味清泄燥湿；甘味补益和中；涩味收敛固涩；淡味利水渗湿，均无软坚散结之功"},{"q":"具有行气、燥湿、消积、降气平喘功效的药物是","o":["紫苏叶","厚朴","砂仁","香附","白豆蔻"],"a":1,"e":"厚朴行气、燥湿、消积、下气平喘，为湿滞伤中、脘腹胀满、食积气滞及痰饮咳喘之要药。紫苏叶解表散寒、行气宽中；砂仁化湿行气、温中安胎；香附疏肝理气、调经；白豆蔻化湿行气、温中止呕，均无燥湿消积、降气平喘之全效"},{"q":"如下炮制后不能降低毒副作用的中药是","o":["斑蝥米炒","砒石升华","巴豆制霜","马兜铃蜜炙","千金子制霜"],"a":1,"e":"砒石升华仅为提纯精制，毒性成分三氧化二砷仍在，不能降低毒副作用，故为不能降低者。斑蝥米炒、巴豆制霜、千金子制霜均能降低毒性；马兜铃蜜炙可缓和苦寒及胃肠刺激，均属减毒炮制"},{"q":"既可凉血止血，又能清肝明目的药物是","o":["大蓟","槐花","白及","苎麻根","白茅根"],"a":1,"e":"槐花凉血止血、清肝泻火，既能治血热出血，尤善清肝火而明目，治肝火上炎之目赤头痛。大蓟、白茅根、苎麻根凉血止血而无清肝明目；白及收敛止血，均无凉血止血兼清肝明目之效"},{"q":"防风的功效不包括","o":["胜湿","止痉","止痛","祛风","止呕"],"a":4,"e":"防风祛风解表、胜湿止痛、止痉，并能祛风止痒、升脾阳，无止呕之功。胜湿、止痛、祛风皆其正品功效，止呕当用半夏、生姜、竹茹、陈皮等，故防风功效不包括止呕"},{"q":"治感冒夹惊，风热头痛，最宜选用的药是","o":["僵蚕","天麻","钩藤","珍珠","羚羊角"],"a":2,"e":"钩藤甘凉，归肝、心包经，功能清热平肝、息风定惊，既能清风热之邪以止头痛，又可定惊止搐，故感冒夹惊、风热头痛用之最宜。天麻甘平，主息风止痉、平抑肝阳，善治肝阳上亢及惊风，无清散风热之功。羚羊角咸寒，清热力强，主治热极生风、肝火上炎，非风热表证所宜"},{"q":"外感风热，应选择何种性味的药物","o":["辛、温","辛、凉","甘、寒","苦、寒","甘、温"],"a":1,"e":"辛味能散能行，具发散作用；凉性属寒凉，可清热。外感风热须辛以发散风热、凉以清泄热邪，故宜辛凉。辛温之品发散力强但性温助热，适用于风寒表证，用治风热反助热势。甘寒、苦寒虽能清热，却缺乏发散透邪之力，不能解除表郁，均非所宜"},{"q":"石膏煎服的用量是","o":["5～10g","10～15g","10～20g","10～30g","15～60g"],"a":4,"e":"石膏为清气分实热要药，生用内服煎汤常用量为十五至六十克，大剂量应用可增至更大量，故以十五至六十克为规范用量。五至十克、十至十五克剂量偏小，难以奏清泻气分大热之效。十至二十克、十至三十克虽在常用范围内，但非教材规定足量，均不如十五至六十克准确"},{"q":"能祛风痰，善治中风，口眼㖞斜的药物是","o":["前胡","白前","旋覆花","白附子","胖大海"],"a":3,"e":"白附子辛温有毒，功能祛风痰、定惊搐、解毒散结止痛，善治风痰壅盛之中风、口眼㖞斜及破伤风，为祛头面风痰之要药。前胡、白前均降气化痰，前者兼疏散风热，后者性温化痰，皆无祛风定惊之能。旋覆花降气化痰、降逆止呕，胖大海清肺利咽，均不治风痰口㖞"},{"q":"既能补血，又能活血的药是","o":["红花","当归","川芎","何首乌","熟地黄"],"a":1,"e":"当归甘辛温，归肝、心、脾经，既能补血，又能活血，且可调经止痛、润肠通便，为补血活血要药，故补血兼活血首推当归。熟地黄、何首乌长于补血，熟地黄偏滋腻，何首乌兼益精，二者均无活血之功。红花、川芎虽能活血，却以行血为主，不具备补血作用"},{"q":"治疗心阴虚，虚热上扰之心悸、失眠者，宜选用","o":["黄精","天冬","鳖甲","百合","南沙参"],"a":3,"e":"百合甘寒，归肺、心经，功能养阴润肺、清心安神，能养心阴、清虚热而宁心，恰宜心阴虚、虚热上扰之心悸失眠。天冬、南沙参均养肺胃之阴，天冬偏滋肾，南沙参兼益气，皆不入心经安神。鳖甲滋阴潜阳、退热除蒸，长于退虚热而非宁心，故均非的选"},{"q":"半夏与陈皮合用可以增强燥湿化痰的作用，属于哪种配伍关系","o":["相畏","相杀","相须","相反","相恶"],"a":2,"e":"相须指性能功效相类似的药物配合应用，可增强原有疗效。半夏与陈皮均能燥湿化痰，二者性味归经相近，合用燥湿化痰之力倍增，正属相须。相使为一主一辅、辅药提高主药疗效；相畏、相杀围绕毒性制约；相反指合用增毒；相恶指降低原有功效，均与非毒性功效增强不符"},{"q":"下列不属于硫黄适用范围的是","o":["疥癣","湿疹","阴疽疮疡","虚寒便秘","虫蛇咬伤"],"a":4,"e":"硫黄酸温有毒，外用解毒杀虫疗疮，治疥癣、湿疹、阴疽疮疡；内服补火助阳通便，治虚寒便秘、阳痿。虫蛇咬伤需解毒消肿、活血通络，非硫黄所主，故不属其适用范围。疥癣、湿疹为其外用主治，阴疽疮疡取其温通解毒，虚寒便秘取其补火通便，皆在适用范围之内"},{"q":"可以作为麻醉剂使用的止咳平喘药是","o":["川乌","草乌","姜黄","蟾酥","洋金花"],"a":4,"e":"洋金花辛温有毒，功能平喘止咳、镇痛解痉，为曼陀罗之花，含莨菪碱、东莨菪碱，有显著麻醉镇痛作用，是古方麻沸散主药，可作麻醉剂使用。川乌、草乌虽有大毒、能祛风散寒止痛，但无止咳平喘与麻醉之用。姜黄行气活血通经，蟾酥解毒止痛开窍，均非止咳平喘兼麻醉之品"},{"q":"药物四气确定的依据是","o":["从人体的感官感觉出来的","从疾病的性质中总结出来的","从药物作用于机体所发生的反应概括出来的","从药物生长的气候环境总结出来的","从药物的主治中总结出来的"],"a":2,"e":"四气是寒、热、温、凉四种药性，依据药物作用于机体后所发生的反应及所获疗效概括而出，能减轻或消除热证者为寒凉，能减轻或消除寒证者为温热。从人的感官感觉判断仅为口尝滋味，从疾病性质或药物生长环境总结均未切中本质。主治是药性应用结果，并非确定四气的依据"},{"q":"能祛风止痛，可用治风湿痹痛的药物是","o":["菊花","柴胡","桑叶","淡豆豉","蔓荆子"],"a":4,"e":"蔓荆子辛苦微寒，功能疏散风热、清利头目、祛风止痛，既能治风热头痛目赤，又可祛经络之风而止风湿痹痛，故为选项中唯一可用治风湿痹痛者。菊花、桑叶虽能疏散风热、清利头目，均无祛风通络止痛之效。柴胡解表退热、疏肝升阳，淡豆豉解表除烦，皆不治痹痛"},{"q":"妊娠禁用的药物不包括的是","o":["巴豆","肉桂","莪术","三棱","麝香"],"a":1,"e":"妊娠禁用药多为剧毒或药性峻烈之品，巴豆峻下逐水、莪术破血行气、三棱破血消积、麝香活血通经开窍，均能伤胎动血，属禁用之列。肉桂辛热，虽能温里助阳，但药性相对和缓，属于妊娠慎用而非禁用，故不在禁用药物之内"},{"q":"气滞妊娠呕恶、不思饮食、脘腹胀闷、胎动不安者，治应首选的药物是","o":["生姜","厚朴","竹茹","砂仁","黄芩"],"a":3,"e":"砂仁辛温芳香，功能化湿行气、温中止泻、安胎，既可行气宽中而除脘腹胀闷、恶心纳差，又能行气安胎以治胎动不安，故气滞妊娠呕恶首选。生姜温中止呕但无行气安胎之功。厚朴燥湿行气消积，力猛不宜妊娠。竹茹清热化痰止呕，黄芩清热安胎，均不兼顾气滞与呕恶、胎动"},{"q":"琥珀入药用法多为","o":["先煎","包煎","另煎","烊化兑服","研末冲服"],"a":4,"e":"琥珀为古代松科植物树脂化石，质地坚硬，主要含树脂与挥发成分，有效成分不溶于水且遇热易破坏，故不入汤剂，多研末冲服或入丸散。先煎适用于矿石贝壳类有效成分难溶者，包煎用于细小种子或有毛药材，另煎多用于贵重药材，烊化针对胶类，均非琥珀用法"},{"q":"合欢皮与首乌藤的安神作用特点是","o":["合欢皮祛痰开窍，首乌藤养血补心","合欢皮解郁悦心，首乌藤补养阴血","合欢皮清心凉肝，首乌藤滋养心肝","合欢皮潜纳浮阳，首乌藤补气养血","合欢皮交通心肾，首乌藤疏肝理气"],"a":1,"e":"合欢皮甘平，归心、肝经，功能解郁安神、活血消肿，善解心郁而悦心安神，治情志不遂之虚烦失眠。首乌藤甘平，养血安神、祛风通络，通过补养阴血以宁心，治阴虚血少之失眠。远志、石菖蒲祛痰开窍，非二药所长；珍珠、龙骨重镇安神，属镇心而非解郁或补血"},{"q":"具强心利尿作用，但有毒，服用不宜过量的药物是","o":["滑石","通草","香加皮","泽泻","猪苓"],"a":2,"e":"香加皮辛苦温，有毒，功能祛风湿、强筋骨、利水消肿，含强心苷类成分，具强心利尿作用，但毒性较大，服用不宜过量，以免损伤心脏。滑石、通草、泽泻、猪苓虽均能利水渗湿，但药性平和，无强心作用，亦无明显毒性，与香加皮强心兼有毒的特点截然不同"},{"q":"生地黄与玄参除能清热凉血外，又均能","o":["定惊","养阴","活血","散结","透疹"],"a":1,"e":"生地黄与玄参均属清热凉血药，生地黄功能清热凉血、养阴生津，玄参功能清热凉血、滋阴降火、解毒散结，二者除清营凉血外，皆能滋养阴液，故共通之处为养阴。定惊为羚羊角、牛黄所主，活血为牡丹皮、赤芍所主，散结为玄参、牡蛎所主，透疹为蝉蜕、葛根所主，均非二者共有"},{"q":"肺虚久咳、咽痛失音，最宜选用的药是","o":["蝉蜕","射干","青果","桔梗","诃子"],"a":4,"e":"诃子酸涩平，归肺、大肠经，功能涩肠止泻、敛肺止咳、降火利咽，既能敛肺气治久咳不止，又能清降虚火而利咽开音，最宜肺虚久咳、咽痛失音。蝉蜕疏散风热、利咽开音，主治风热咽哑，非久咳所宜。射干、青果清热解毒利咽，桔梗宣肺祛痰利咽，均无敛肺治久咳之功"},{"q":"黄连与石膏的共同主治是","o":["胃火牙痛","湿热泻痢","血热吐衄","目赤肿痛","骨蒸劳热"],"a":0,"e":"黄连苦寒，清中焦湿热与心胃之火；石膏甘辛大寒，清气分实热与肺胃之火。二者均能清泄胃火，故共同主治胃火上炎之牙痛。湿热泻痢为黄连所主，石膏不燥湿止痢。血热吐衄多取犀角、生地之类，目赤肿取决明子、夏枯草，骨蒸劳热取知母、黄柏，均非二者共有主治"},{"q":"具有发散作用的药味是","o":["咸","酸","苦","辛","甘"],"a":3,"e":"五味之中，辛味能散能行，具有发散表邪、行气活血的作用，解表药多属辛味，故具发散作用者为辛。酸味收敛固涩，与发散相反。苦味能泄能燥，主清泄燥湿。甘味能补能和能缓，主补益调和。咸味软坚散结、泻下，均无发散之能"},{"q":"既能止血，又具补虚之功的药物是","o":["白及","蒲黄","地榆","侧柏叶","仙鹤草"],"a":4,"e":"仙鹤草苦涩平，功能收敛止血，兼能补虚、截疟、止痢，为止血要药且具强壮补虚之功，凡出血而体虚者用之尤宜。白及收敛止血、消肿生肌，无补虚之能。蒲黄、地榆、侧柏叶均能止血，蒲黄兼化瘀利尿，地榆凉血，侧柏叶凉血，皆无补虚作用，故兼具止血与补虚者唯仙鹤草"},{"q":"地锦草与马齿苋相同的功效是","o":["清热燥湿","收敛止血","利湿退黄","凉血止痢","清肝明目"],"a":3,"e":"地锦草与马齿苋均属清热解毒药，地锦草功能清热解毒、凉血止血，马齿苋功能清热解毒、凉血止血止痢，二者皆能清血分之热而凉血止痢，故相同功效为凉血止痢。清热燥湿为黄连、黄芩所主；收敛止血为白及、仙鹤草所主；利湿退黄为茵陈所主；清肝明目为决明子、夏枯草所主，均非二药共有"},{"q":"山茱萸急救固脱的用量是","o":["1～3g","3～6g","6～12g","20～30g","60～120g"],"a":3,"e":"山茱萸酸涩微温，功能补益肝肾、收涩固脱，常用量六至十二克，但遇大汗虚脱、元气欲脱之危急证，须重用二十至三十克乃至更大量以敛汗固脱，故急救固脱用二十至三十克。一至三克、三至六克剂量过轻，难以固脱。六十至一百二十克剂量过大，非急救常规用量"},{"q":"桑螵蛸与海螵蛸的共同功效是","o":["收敛止血","制酸止痛","固精止遗","收湿敛疮","补肾助阳"],"a":2,"e":"桑螵蛸甘咸平，功能固精缩尿、补肾助阳；海螵蛸咸涩微温，功能收敛止血、涩精止带、制酸止痛、收湿敛疮。二者均入肾经，皆能涩精而固精止遗，故为其共同功效。收敛止血、制酸止痛、收湿敛疮仅为海螵蛸所有，补肾助阳仅为桑螵蛸所具，皆非二者共有"},{"q":"柴胡的功效是","o":["利咽","透疹","疏肝解郁","凉血止血","清利头目"],"a":2,"e":"柴胡辛苦微寒，归肝、胆经，功能解表退热、疏肝解郁、升举阳气，善疏泄肝气而解郁，治肝郁气滞之胁痛、月经不调。利咽为桔梗、射干所主，透疹为蝉蜕、葛根所主，凉血止血为生地、地榆所主，清利头目为薄荷、蔓荆子所主，均非柴胡功效"},{"q":"治疗外感风热，咳嗽痰多，咽痛音哑，胸闷不舒者，应首选的药物是","o":["百部","桔梗","川贝母","苦杏仁","旋覆花"],"a":1,"e":"桔梗苦辛平，归肺经，功能宣肺、利咽、祛痰、排脓，能开宣肺气而祛痰宽胸、利咽开音，宜于外感风热之咳嗽痰多、咽痛音哑、胸闷不舒。百部润肺止咳，偏治虚劳久咳；川贝母润肺化痰，主燥咳；苦杏仁降气止咳，无利咽宽胸之能；旋覆花降气化痰，皆非首选"},{"q":"枳实配白术常用于治疗","o":["肝郁气滞","脾虚气滞","痰湿阻滞","寒凝气滞","肺气壅滞"],"a":1,"e":"枳实辛苦微寒，破气消积、化痰散痞；白术苦甘温，健脾益气。二药相伍，消补兼施，白术健脾以治本，枳实消痞以治标，共治脾虚气滞、食积不化之脘腹痞满，即枳术丸之意。肝郁气滞宜柴胡、香附，痰湿阻滞宜苍术、厚朴，寒凝气滞宜吴茱萸，肺气壅滞宜桔梗、葶苈子，均非此配伍所主"},{"q":"消食化积，又能疏肝理气的药物是","o":["青皮","香附","瓜蒌","郁金","麦芽"],"a":4,"e":"麦芽甘平，归脾、胃、肝经，功能消食健胃、回乳消胀，兼能疏肝解郁，既助消化谷食积滞，又可调畅肝气，故消食化积兼疏肝理气首推麦芽。青皮、香附虽疏肝理气，但无消食化积之功。瓜蒌清热化痰宽胸，郁金活血行气利胆，均无消食与疏肝兼备之效"},{"q":"泻水逐饮，药力峻猛，尤“能泄脏腑之水湿”的药物是","o":["甘遂","京大戟","芫花","巴豆霜","牵牛子"],"a":1,"e":"京大戟苦辛寒，有毒，功能泻水逐饮、消肿散结，泻水逐饮之力峻猛，善泄脏腑之水湿，主治水肿胀满、痰饮积聚。甘遂善行经隧之水湿，力更峻烈；芫花善治胸腹积水并杀虫；巴豆霜峻下冷积；牵牛子泻水通便、杀虫，四者虽均峻下，但泄脏腑水湿一语专指京大戟"},{"q":"砂仁入汤剂煎煮时应","o":["先煎","后下","另煎","包煎","烊化"],"a":1,"e":"砂仁含大量挥发油，为主要有效成分，久煎则挥发散失而药效降低，故入汤剂宜后下，于煎毕前短时入煎。先煎用于矿石贝壳类及有毒药久煎减毒，另煎用于贵重药材，包煎用于细小种子、绒毛或有黏液之品，烊化用于胶类药物，均不适合砂仁"},{"q":"具有化湿、解暑功效的药组是","o":["广藿香、佩兰","苍术、厚朴","砂仁、白豆蔻","陈皮、青皮","茯苓、玉竹"],"a":0,"e":"广藿香与佩兰均芳香，归脾、胃、肺经，广藿香化湿、止呕、解暑，佩兰化湿、解暑，二者均既能化在里之湿浊，又可解暑热外邪，故为化湿解暑药组。苍术、厚朴燥湿行气力强而无解暑之效。砂仁、白豆蔻化湿行气温中，陈皮、青皮理气，茯苓、玉竹或利水或养阴，皆不解暑"},{"q":"下列药物尤善治寒邪偏盛之风湿痹痛的是","o":["独活","川乌","木瓜","乌梢蛇","威灵仙"],"a":1,"e":"川乌辛热有大毒，功能祛风除湿、散寒止痛，其性大热，散寒止痛力最强，尤宜寒邪偏盛、痛势较剧之痛痹。独活善治下半身风湿痹痛，散寒力不及川乌。木瓜舒筋活络、化湿，主筋脉拘挛。乌梢蛇、威灵仙虽祛风通络止痛，但散寒之力均远逊川乌，非寒重痛剧首选"},{"q":"可用治久泻、久痢的药组是","o":["山茱萸、桑螵蛸","覆盆子、桑螵蛸","金樱子、覆盆子","金樱子、石榴皮","山茱萸、石榴皮"],"a":3,"e":"金樱子酸涩平，涩肠止泻、固精缩尿止带；石榴皮酸涩温，涩肠止泻、止血杀虫。二药均入大肠经，善于涩肠固脱，治久泻久痢、滑脱不禁。山茱萸、覆盆子偏固精缩尿，桑螵蛸固精缩尿，均不涩肠止泻，故含这些药的配伍皆非治久泻久痢之选"},{"q":"既可以疏肝气，又可以理脾胃之气的药物是","o":["枳实","沉香","薤白","柿蒂","佛手"],"a":4,"e":"佛手辛苦温，归肝、脾、胃、肺经，功能疏肝理气、和胃止痛、燥湿化痰，既能疏泄肝气之郁，又能理脾胃之气而宽中和胃，故疏肝气兼理脾胃之气者首选。枳实破气消积，主胃肠积滞。沉香降气纳肾，薤白通阳散结，柿蒂降气止呃，均无疏肝与和胃并行之效"},{"q":"胸腹水肿实证兼喘咳者，宜选用","o":["茯苓","泽泻","昆布","海藻","葶苈子"],"a":4,"e":"葶苈子辛苦大寒，归肺、膀胱经，功能泻肺平喘、利水消肿，泻肺中水饮而平喘，通调水道而消水肿，宜胸腹水肿实证兼喘咳者。茯苓、泽泻、猪苓虽利水消肿，但无泻肺平喘之功。昆布、海藻消痰软坚、利水，主瘰疬瘿瘤，均不治水饮喘咳"},{"q":"乳香、没药均有的功效是","o":["活血定痛、行气解郁","活血止痛、通经活络","活血定痛、消肿生肌","活血定痛、凉血消痈","祛风通络，行气解郁"],"a":2,"e":"乳香与没药均为树脂类药，功能活血止痛、消肿生肌，相须为用，治瘀血阻滞之痛证及疮疡肿痛、久溃不敛。行气解郁为香附、郁金所主，非二药所有。通经活络为鸡血藤所主。凉血消痈为牡丹皮、赤芍所主。乳香、没药无凉血之性，亦不以通络见长"},{"q":"干姜配伍附子，可降低附子的毒性，属于","o":["相须","相使","相恶","相杀","相反"],"a":3,"e":"相杀指一种药物能减轻或消除另一种药物的毒性或副作用。干姜辛热，能降低附子的毒烈之性，故干姜配附子属相杀。相须指功效相近药合用增效，附子与干姜虽可相须助阳，但题干着眼于降低毒性，故不取相须。相恶为降低原有功效，相反为合用增毒，相使为主辅增效，均与减毒无关"},{"q":"能益气活血、通脉平喘的药物是","o":["饴糖","沙棘","红景天","绞股蓝","刺五加"],"a":2,"e":"红景天甘涩寒，归脾、肺经，功能健脾益气、清肺止咳、活血化瘀、通脉平喘，既能益气，又能活血通脉、止咳平喘，故益气活血、通脉平喘首推红景天。饴糖温中补虚，无活血平喘之功。沙棘止咳祛痰、活血，但益气力弱。绞股蓝、刺五加益气，均无通脉平喘之效"},{"q":"治疗噫气，呕吐，旋覆花配伍赭石，可增强","o":["凉血止血之功","消痰行水之功","平肝潜阳之功","降逆下气之功","重镇安神之功"],"a":3,"e":"旋覆花苦辛咸微温，降气化痰、降逆止呕；赭石苦寒，平肝潜阳、重镇降逆、凉血止血。二者均善降逆，旋覆花降肺胃之气，赭石降肝胃之气，相配增强降逆下气、止呕止呃之功。凉血止血、平肝潜阳、重镇安神、消痰行水虽各为赭石或旋覆花所有，但非二药配伍之主要目的"},{"q":"祛风湿药的主要功效是","o":["祛除风湿，舒筋活络","祛除风湿，活血止痛","祛除风湿，强筋健骨","祛除风湿，解除痹痛","祛除风湿，温经止痛"],"a":3,"e":"祛风湿药以祛除肌表经络之风湿邪气为主要作用，风湿去则经络通、痹痛止，故其主要功效概括为祛除风湿、解除痹痛。舒筋活络为部分药物兼有之功，非全类共性。活血止痛、强筋健骨、温经止痛或为兼效，或仅个别药物所具，均不足以概括本类药物的主要功效"},{"q":"下列各项中，用药方法错误的是","o":["薄荷后下","车前子包煎","龙骨先煎","人参另煎","旋覆花烊化"],"a":4,"e":"旋覆花的花序带绒毛，直接入汤剂易刺激咽喉，须包煎，使其有效成分煎出而绒毛不混悬，故烊化说法有误。薄荷含挥发油宜后下，车前子细小且含黏液质宜包煎，龙骨为矿石宜先煎，人参贵重宜另煎，四者用法均正确，唯旋覆花当包煎而非烊化"},{"q":"能燥湿化痰，治顽痰咳嗽宜用","o":["百部","款冬花","浙贝母","天南星","桑白皮"],"a":3,"e":"天南星苦辛温，有毒，功能燥湿化痰、祛风解痉，其燥湿化痰之力较强，善治湿痰、寒痰及顽痰咳嗽，痰多黏稠难咯者尤宜。百部、款冬花润肺止咳，偏治虚咳久咳。浙贝母清热化痰，主痰热咳嗽。桑白皮泻肺平喘，均无燥湿化痰治顽痰之效"},{"q":"既能发汗解表，又能平冲降气的药物是","o":["荆芥","防风","细辛","白芷","桂枝"],"a":4,"e":"桂枝辛甘温，归心、肺、膀胱经，功能发汗解肌、温通经脉、助阳化气、平冲降气，既解肌发汗治风寒表证，又能平冲降逆治奔豚气逆。荆芥、防风虽解表但无平冲降气之功。细辛、白芷解表散寒、祛风止痛，不降冲气。桂枝兼解表与平冲，故为所宜"},{"q":"石膏治疮疡不敛，湿疹，水火烫伤，其用法是","o":["生石膏，外用","生石膏，冲服","煅石膏，内服","煅石膏，外用","生石膏，打碎先煎"],"a":3,"e":"石膏生用与煅用功效迥异：生石膏清热泻火、除烦止渴，内服治气分实热；煅石膏收湿敛疮、生肌止血，专供外用，治疮疡不敛、湿疹、水火烫伤。生石膏冲服或打碎先煎均为内服之法，不治外伤；煅石膏内服非其常规用法，故煅石膏外用最为恰当"},{"q":"半边莲的功效是","o":["利湿退黄","利尿消肿","祛瘀止痛","祛风止痒","利湿通淋"],"a":1,"e":"半边莲甘寒，归心、小肠、肺经，功能清热解毒、利尿消肿，尤善利尿以消水肿，治大腹水肿、面目浮肿及毒蛇咬伤。利湿退黄为茵陈、金钱草所主；祛瘀止痛为桃仁、延胡索所主；祛风止痒为荆芥、白鲜皮所主；利湿通淋为车前子、瞿麦所主，均非半边莲功效"},{"q":"风寒表证、风热表证均常配伍使用的药对是","o":["麻黄，桂枝","羌活，白芷","紫苏叶，生姜","荆芥，防风","藁本，苍耳子"],"a":3,"e":"荆芥与防风均辛温，但性较平和，功能祛风解表，风寒表证、风热表证皆可配伍使用：荆芥配薄荷、银花治风热，配麻黄、桂枝治风寒；防风亦然，为祛风解表之通用药对。麻黄、桂枝辛温力强，专风寒；羌活、白芷、藁本、苍耳子偏治风寒夹湿或头面诸痛，不通用"},{"q":"为增强牡丹皮的活血祛瘀作用，入汤剂宜","o":["盐水炙","酒炙","醋炙","姜汁炙","蜜炙"],"a":1,"e":"酒能行血活血，药材酒炙可增强活血祛瘀作用，牡丹皮酒炙后活血散瘀之力增强，故为增强其活血祛瘀，入汤剂宜酒炙。盐水炙引药入肾、增强滋阴降火，醋炙增强收敛止痛或入肝，姜汁炙温中止呕，蜜炙补中润燥，均与增强活血祛瘀无直接关系"},{"q":"内服能散寒劫痰平喘、截疟的药是","o":["砒石","硫黄","铅丹","升药","轻粉"],"a":0,"e":"砒石辛大热，有大毒，内服能劫痰平喘、截疟，性大热可散寒，治寒痰喘咳、疟疾，外用蚀疮去腐。硫黄补火助阳通便，无劫痰平喘截疟之功。铅丹、轻粉外用杀虫攻毒，内服作用不同。升药专供外用蚀疮去腐，不作内服，均非散寒劫痰平喘截疟之品"},{"q":"不具止血和利尿双重功效的药物是","o":["大蓟","小蓟","蒲黄","白茅根","血余炭"],"a":0,"e":"大蓟甘苦凉，功能凉血止血、散瘀解毒消痈，能止血但无利尿之功，故不具备止血与利尿双重功效。小蓟兼能利尿，治血淋；蒲黄止血化瘀兼利尿；白茅根凉血止血兼清热利尿；血余炭收敛止血兼化瘀利尿，四者均兼具止血与利尿，唯大蓟无利尿作用"},{"q":"金银花清热解暑，治暑热烦渴，宜选用","o":["制露","生用","蜜炙","酒炙","研粉"],"a":0,"e":"金银花露由金银花蒸馏制得，气味清芬，功能清热解暑、生津止渴，为治暑热烦渴的佳品，故金银花清热解暑宜用制露。生用甘寒，清热解毒之力强，主温病发热、疮痈；蜜炙增强润肺；酒炙助活血；研粉多外用，均非解暑烦渴之适宜剂型"},{"q":"两药合用，一种药物能使另一种药物原有的功效降低或丧失，这种配伍关系是","o":["相反","相畏","相杀","相恶","相使"],"a":3,"e":"相恶指两药合用，一种药物能使另一种药物原有功效降低甚至丧失，即相互牵制而减效，如人参恶莱菔子。相反指合用产生或增强毒性；相畏、相杀围绕毒性的减轻与消除，属减毒范畴；相使为一主一辅以辅增效，皆非功效降低，故所述关系为相恶"},{"q":"生地黄不具有的功效是","o":["凉血","养阴","生津","清热","解毒"],"a":4,"e":"生地黄甘苦寒，归心、肝、肾经，功能清热凉血、养阴生津，主治热入营血、阴虚内热、津伤口渴，并无解毒之功。凉血、养阴、生津、清热均为其固有功效。清热解毒多取金银花、连翘、黄连之属，与生地黄清营凉血、滋阴生津的作用取向不同，故解毒非生地黄所具"},{"q":"旋覆花配赭石同用，可增强","o":["行水之功","潜阳之功","凉血止血之功","镇惊安神之功","降逆下气之功"],"a":4,"e":"赭石重镇降逆，善降上逆之胃气与肝气；旋覆花消痰下气、降逆止呕。二者相伍，一重镇一下气，协同增强降逆下气、止呕止呃之效，治噫气、呕吐。行水、潜阳、凉血止血、镇惊安神虽分别为二药兼有之效，但配伍主旨在于降逆，其余均非合用所增强"},{"q":"陈皮与佛手相同的功效是","o":["疏肝破气","理气消积","祛寒止痛","燥湿化痰","健脾利水"],"a":3,"e":"陈皮与佛手均辛苦温、归脾肺经，陈皮理气健脾、燥湿化痰，佛手疏肝理气、和胃止痛、燥湿化痰，二者皆能燥湿化痰，故为其相同功效。疏肝破气为青皮所主，理气消积为枳实所主，祛寒止痛为吴茱萸、丁香所主，健脾利水为白术、茯苓所主，均非二药共有"},{"q":"既能敛肺止咳，又能生津止渴的药物是","o":["乌梅","诃子","石榴皮","肉豆蔻","赤石脂"],"a":0,"e":"乌梅酸涩平，归肝、脾、肺、大肠经，功能敛肺止咳、涩肠止泻、生津止渴、安蛔止痛，既能收敛肺气以止咳，又能生津液以止渴，故敛肺止咳兼生津止渴首选乌梅。诃子敛肺利咽但无生津之功。石榴皮、肉豆蔻、赤石脂均涩肠止泻，不敛肺生津"},{"q":"瞿麦为治淋证常用药，除利尿通淋外，还能","o":["祛风止痒","杀虫，止痒","通气下乳","活血通经","清心除烦"],"a":3,"e":"瞿麦苦寒，归心、小肠经，功能利尿通淋、活血通经，既为治淋证要药，又能活血通经，治闭经、月经不调。祛风止痒、杀虫止痒多为地肤子、苦参所主；通气下乳为通草、木通所主；清心除烦为栀子、淡竹叶所主，均非瞿麦功效"},{"q":"龙眼肉的功效是","o":["健脾益气，养血滋阴","益气复脉，滋阴养血","滋阴补血，生津润燥","养心益肝，宁心安神","补益心脾，养血安神"],"a":4,"e":"龙眼肉甘温，归心、脾经，功能补益心脾、养血安神，既补心脾之气，又养血以宁心，治思虑过度、劳伤心脾之惊悸怔忡、健忘失眠，为养心安神之品。健脾益气养血滋阴多指山药、黄精之类；益气复脉为炙甘草汤中人参、桂枝之效；滋阴补血生津润燥为熟地、阿胶所主；养心益肝宁心为酸枣仁所主"},{"q":"劳嗽久咳，倦怠乏力，食欲不振、神疲体倦、舌干苔少者，宜首选","o":["石斛","黄精","百合","麦冬","玉竹"],"a":1,"e":"黄精甘平，归脾、肺、肾经，功能补气养阴、健脾、润肺、益肾，既补脾胃之气阴而治倦怠乏力、食欲不振，又润肺养阴治劳嗽久咳，兼顾气阴两虚，故劳嗽久咳兼脾虚者首选。石斛、麦冬、玉竹偏养胃肺之阴，无补气健脾之力；百合润肺清心，亦不补气，均非所宜"},{"q":"既能燥湿祛风，又能杀虫止痒的药物是","o":["硫黄","苦参","白矾","土槿皮","蛇床子"],"a":4,"e":"蛇床子辛苦温，有小毒，功能燥湿祛风、杀虫止痒、温肾壮阳，外用治阴痒带下、湿疹疥癣，能燥湿祛风并杀虫止痒。硫黄、白矾、土槿皮虽能杀虫止痒，但硫黄偏补火，白矾偏收敛，土槿皮无祛风之效。苦参清热燥湿杀虫，性寒无温燥祛风之功，故所宜者为蛇床子"},{"q":"气味芳香、成分易挥发的药物宜","o":["先煎","后下","布包煎","另煎","烊化兑服"],"a":1,"e":"气味芳香、含挥发性成分的药物久煎则有效成分随水蒸气散失，须在其他药煎好前短时入煎，即后下，如薄荷、砂仁、豆蔻。先煎用于矿石贝壳及毒性药久煎；布包煎用于细小种子、绒毛或黏液质药；另煎用于贵重药；烊化用于胶类，均非芳香易挥发药的常规用法"},{"q":"治疗肾阴亏虚，眩晕耳鸣，内热消渴，最宜选用药物是","o":["麦冬","天冬","百合","玉竹","南沙参"],"a":1,"e":"天冬甘苦寒，归肺、肾经，功能养阴润燥、清肺生津，质润入肾，能滋肾阴、清虚火，治肾阴亏虚之眩晕耳鸣、内热消渴。麦冬归心肺胃，养阴润肺益胃，不入肾经；百合润肺清心；玉竹、南沙参养肺胃之阴，均无滋补肾阴之功，故肾阴亏虚者最宜天冬"},{"q":"下列哪一组性味的药物，作用趋向一般属于升浮","o":["甘、辛、凉","辛、苦、热","辛、甘、温","甘、淡、寒","酸、咸、热"],"a":2,"e":"升浮药多具辛、甘味与温、热性，质地轻清，作用趋向上升外达，如麻黄、桂枝、柴胡等，辛能发散、甘能补益升提、温能助阳升腾。咸、酸、苦味及寒凉之品多沉降；甘、淡、寒药性偏渗利清降，酸、咸、热组合亦非升浮，故升浮者当属辛、甘、温"},{"q":"枳实可用于治疗","o":["月经不调","虫积腹痛","胁肋疼痛","胃寒呕吐","胃肠积滞"],"a":4,"e":"枳实苦辛微寒，功能破气消积、化痰散痞，力猛善消胃肠实热积滞，治腹满胀痛、大便不通、泻痢后重。月经不调宜香附、当归；虫积腹痛宜使君子、槟榔；胁肋疼痛宜柴胡、郁金；胃寒呕吐宜丁香、生姜，均非枳实破气消积之所主"},{"q":"能益气助阳的药物是","o":["党参","人参","附子","太子参","吴茱萸"],"a":1,"e":"人参甘微苦微温，大补元气、补脾益肺、生津安神，阳气互根，气旺则阳亦得助，故人参益气之中兼具助阳之效。党参、太子参补气但无温阳之力；附子、吴茱萸虽助阳散寒，却无补气之功，二者皆不能益气与助阳兼备，故能益气助阳者为人参"},{"q":"自然铜的功效是","o":["活血疗伤，散瘀止痛","破血逐瘀，续筋接骨","散瘀止痛，续筋接骨","活血消肿，舒筋活络","散结消肿，通络止痛"],"a":2,"e":"自然铜辛平，归肝经，功能散瘀止痛、续筋接骨，为伤科要药，治跌打损伤、瘀肿疼痛及骨折筋断。破血逐瘀、续筋接骨多指土鳖虫之类，力更峻猛；活血疗伤、散瘀止痛为骨碎补、血竭所主；活血消肿、舒筋活络为鸡血藤所主；散结消肿、通络止痛为马钱子所主"},{"q":"外用蚀疮去腐，内服劫痰平喘的药物是","o":["升药","砒石","轻粉","硼砂","红升丹"],"a":1,"e":"砒石大热大毒，外用蚀疮去腐，内服劫痰平喘、截疟，治寒痰喘咳、疟疾及恶疮腐肉不脱。升药、红升丹专供外用提脓去腐，不作内服。轻粉外用杀虫攻毒，内服泻下逐水，无劫痰平喘之效。硼砂清热消痰、解毒防腐，多外用，故蚀疮去腐兼劫痰平喘者唯砒石"},{"q":"马钱子的功效是","o":["活血疗伤，散瘀止痛","破血逐瘀，续筋接骨","散瘀止痛，接骨疗伤","活血消肿，舒筋活络","散结消肿，通络止痛"],"a":4,"e":"马钱子苦寒，有大毒，功能散结消肿、通络止痛，善治风湿顽痹、麻木瘫痪、跌打损伤及痈疽肿痛，通络止痛力峻。活血疗伤、散瘀止痛为骨碎补、血竭所主；破血逐瘀、续筋接骨为土鳖虫所主；散瘀止痛、接骨疗伤为自然铜所主；活血消肿、舒筋活络为鸡血藤所主"},{"q":"治外感风寒夹湿表证，头痛身痛者，首选的药物是","o":["荆芥","生姜","薄荷","紫苏叶","羌活"],"a":4,"e":"羌活辛苦温，归膀胱、肾经，功能解表散寒、祛风除湿、止痛，善治外感风寒夹湿之表证，尤宜头痛身痛、肢节酸重，且善治上半身痹痛。荆芥、薄荷、紫苏叶虽解表，无祛湿止痛之功；生姜温中止呕，发散力弱，故风寒夹湿身痛首选羌活"},{"q":"雪莲花的功效是","o":["祛风湿，壮筋骨，解毒","祛风湿，强筋骨，补肾阳","祛风湿，强筋骨，安胎元","祛风湿，强筋骨，利水","祛风湿，补肝肾，强腰膝"],"a":1,"e":"雪莲花甘苦温，归肝、肾经，功能祛风湿、强筋骨、补肾阳、调经止血，治风湿痹痛、腰膝软弱、肾虚阳痿及月经不调。壮筋骨、解毒非其典型功效；强筋骨安胎为桑寄生、杜仲所主；强筋骨利水为五加皮所主；补肝肾强腰膝为杜仲、续断所主，均非雪莲花准确功效"},{"q":"既能解毒、除湿，又能通利关节的药物是","o":["金银花","蒲公英","鱼腥草","薏苡仁","土茯苓"],"a":4,"e":"土茯苓甘淡平，归肝、胃经，功能解毒、利湿、通利关节，善解梅毒、汞毒，治梅毒筋骨挛痛、淋浊、带下、痈肿。金银花、蒲公英、鱼腥草虽清热解毒，无通利关节与除湿之专效；薏苡仁利水渗湿、健脾，无解毒之功，故解毒除湿兼通利关节者当属土茯苓"},{"q":"患者便秘，头晕头痛，烦躁易怒，惊痫抽搐，宜选用清肝泻火之","o":["大黄","芒硝","番泻叶","石膏","芦荟"],"a":4,"e":"芦荟苦寒，归肝、胃、大肠经，功能泻下通便、清肝泻火、杀虫疗疳，既能泻热通便治热结便秘，又清肝火而治头晕头痛、烦躁惊痫，恰合便秘兼肝火之证。大黄、芒硝、番泻叶虽泻下，无清肝定惊之功；石膏清气分热，不泻下，故宜清肝泻火之芦荟"},{"q":"佩兰的功效是","o":["燥湿行气，温中止呕","燥湿行气，消积平喘","化湿行气，温中止呕","化湿开胃，发表解暑","燥湿温中，除痰截疟"],"a":3,"e":"佩兰辛平，归脾、胃、肺经，功能化湿、解暑，气味芳香，能化湿浊而开心胃、解暑热而治暑湿烦渴，故化湿开胃、发表解暑为其功效。燥湿行气温中止呕为草豆蔻、厚朴所主；化湿行气温中止呕为砂仁、白豆蔻所主；燥湿温中除痰截疟为草果所主，均非佩兰"},{"q":"五味子的主治病证不包括","o":["自汗盗汗","便血崩漏","遗精滑精","久泻不止","失眠多梦"],"a":1,"e":"五味子酸甘温，归肺、心、肾经，功能收敛固涩、益气生津、补肾宁心，治久咳虚喘、自汗盗汗、遗精滑精、久泻不止、心悸失眠。便血崩漏需凉血止血或收敛止血，非五味子所主，故不属其主治。自汗盗汗、遗精滑精、久泻不止、失眠多梦均在五味子主治之内"},{"q":"治疗外感风寒兼脾胃气滞胸脘满闷、恶心呕逆者，宜首选","o":["荆芥","防风","白芷","细辛","紫苏"],"a":4,"e":"紫苏辛温，归肺、脾经，功能解表散寒、行气宽中、解鱼蟹毒，既发散风寒以治表证，又行气宽中而除胸脘满闷、恶心呕逆，最宜外感风寒兼脾胃气滞者。荆芥、防风、白芷、细辛虽能解表散寒，均无行气宽中之功，不能兼顾气滞呕逆，故首选紫苏"},{"q":"能沉降的药物性味多为","o":["辛、酸、温","苦、咸、温","辛、甘、凉","甘、辛、温","酸、苦、寒"],"a":4,"e":"沉降药多具酸、苦、咸味与寒、凉性，质地重实，作用趋向下行内敛，如大黄、黄连、龙骨之属，酸能收敛、苦能降泄、寒能清热降火。辛、甘、温多升浮；辛、酸温或苦、咸温组合不符沉降一般规律；辛、甘、凉偏升散，故沉降之性味当属酸、苦、寒"},{"q":"在补益气血方中，能发挥鼓舞气血生长作用的药物是","o":["干姜","附子","肉桂","丁香","吴茱萸"],"a":2,"e":"肉桂辛甘大热，功能补火助阳、散寒止痛、温通经脉、引火归元，于大队补益气血药中少佐肉桂，可温阳通脉、鼓舞气血生长，增强补益之效，如十全大补汤。干姜温中，附子回阳，丁香温中降逆，吴茱萸疏肝下气，虽皆温热，均无鼓舞气血生长之特长"},{"q":"不具有安胎功效的药物是","o":["黄芩","黄连","紫苏叶","砂仁","杜仲"],"a":1,"e":"安胎药中，黄芩清热安胎，紫苏叶行气安胎，砂仁化湿行气安胎，杜仲补肝肾安胎，各有专长。黄连苦寒，功能清热燥湿、泻火解毒，主清心胃之火，虽有清热之功，但无安胎之效，故不具有安胎功效者为黄连"},{"q":"既治水肿，小便不利，又治风湿痹证日久，腰膝酸痛的药物是","o":["千年健","桑寄生","五加皮","猪苓","防己"],"a":2,"e":"五加皮辛苦温，归肝、肾经，功能祛风湿、补肝肾、强筋骨、利水消肿，既能祛风湿止痹痛，又补肝肾强筋骨而治痹证日久腰膝酸痛，且能利水治水肿、小便不利。千年健、桑寄生虽祛风湿强筋骨，无利水之功；猪苓、防己利水，无补肝肾强筋骨之效"},{"q":"能破气消积功效的药物是","o":["陈皮","香附","枳实","沉香","川楝子"],"a":2,"e":"枳实苦辛微寒，功能破气消积、化痰散痞，作用峻猛，善破胃肠气结而消积导滞，治腹满胀痛、积滞泻痢。陈皮理气健脾，力缓不破气；香附疏肝理气调经；沉香降气纳肾；川楝子行气止痛、清肝火，四者均无破气消积之峻效"},{"q":"温肺化饮，善治寒饮喘咳的药物是","o":["花椒","干姜","肉桂","吴茱萸","小茴香"],"a":1,"e":"干姜辛热，归脾、胃、肺经，功能温中散寒、回阳通脉、温肺化饮，能温肺散寒化饮，治寒饮停肺之喘咳痰多清稀，为温肺化饮要药。花椒温中止痛、杀虫；肉桂补火助阳；吴茱萸疏肝下气；小茴香散寒止痛、理气和胃，均无温肺化饮之功"},{"q":"骨碎补可用于腰痛脚弱、耳鸣耳聋，取其哪个功效","o":["通络止痛","活血疗伤","补肾强骨","散结消肿","破血逐瘀"],"a":2,"e":"骨碎补苦温，归肝、肾经，功能补肾强骨、续伤止痛，肾主骨、开窍于耳，肾虚则腰痛脚弱、耳鸣耳聋，骨碎补补肾强骨故能治之。通络止痛、活血疗伤、散结消肿、破血逐瘀或为伤科他药之功，均不能直接针对肾虚之腰痛耳鸣，唯补肾强骨切中病机"},{"q":"肉桂煎服的用量为","o":["1～3g","1～5g","3～6g","3～10g","3～15g"],"a":1,"e":"肉桂辛甘大热，气味芳香，含挥发油，久煎易损失药效，煎服常用量为一至五克，宜后下或焗服，研末冲服用量更小。三至六克、三至十克、三至十五克剂量偏大，温热燥烈易伤阴动火。一至三克虽在范围内但偏小，故一至五克为肉桂煎服的规范用量"},{"q":"性寒，滑肠通便，气虚便溏者慎用的药物是","o":["薄荷","牛蒡子","蝉蜕","升麻","柴胡"],"a":1,"e":"牛蒡子辛苦寒，功能疏散风热、宣肺透疹、解毒利咽，其性寒凉，且富含油脂，能滑肠通便，气虚便溏者服之更易腹泻，故宜慎用。薄荷、蝉蜕、柴胡、升麻虽均辛凉或升散，无滑肠通便之弊，不致便溏"},{"q":"川乌的功效是","o":["祛风止痛，活血通络","祛风通络，凉血消肿","祛风通络，定惊止痉","祛风除湿，散寒止痛","祛风除湿，活血通络"],"a":3,"e":"川乌辛热有大毒，功能祛风除湿、散寒止痛，善散经络间风寒湿邪，止痛力强，治风湿痹痛、心腹冷痛。祛风通络凉血消肿为防己、赤芍之类；定惊止痉为白花蛇、全蝎所主；活血通络为鸡血藤所主；祛风除湿活血通络为独活、威灵仙所主，均非川乌散寒止痛之专长"},{"q":"长于清泻下焦湿热的药是","o":["黄芩","黄连","黄柏","马尾连","白鲜皮"],"a":2,"e":"黄柏苦寒，归肾、膀胱、大肠经，功能清热燥湿、泻火除蒸、解毒疗疮，性沉降，主入下焦，长于清泻下焦湿热，治湿热下注之带下、淋浊、脚气、湿疹。黄芩偏清上焦肺火，黄连偏清中焦心胃火，马尾连、白鲜皮虽清热燥湿，均无清下焦湿热之专长"},{"q":"少妇产后，因感冒未哺乳，致一侧乳房肿硬疼痛，因不愿服中药，外敷宜首选的药物是","o":["芒硝","大黄","鱼腥草","紫花地丁","大血藤"],"a":0,"e":"芒硝咸苦寒，功能泻下通便、润燥软坚、清火消肿，外用能清热消肿、回乳，治乳痈肿痛、乳房胀硬，故产后乳汁淤积、乳房肿硬疼痛不愿内服者宜外敷芒硝。大黄、鱼腥草、紫花地丁、大血藤虽清热解毒消痈，多内服或治他处疮痈，非回乳消肿外敷首选"},{"q":"功似火麻仁，兼行大肠气滞的药物是","o":["柏子仁","松子仁","桃仁","苦杏仁","郁李仁"],"a":4,"e":"郁李仁辛苦甘平，功能润肠通便、利水消肿，质润多脂，润肠通便之功与火麻仁相似，且能行大肠气滞，促进肠蠕动而通便，故功似火麻仁兼行大肠气滞者首选郁李仁。柏子仁、松子仁润肠兼养心；桃仁、苦杏仁降肺气、活血，均无行大肠气滞之效"},{"q":"具有清热，解毒，滋阴功效的药物是","o":["生地黄","玄参","赤芍","牡丹皮","紫草"],"a":1,"e":"玄参甘苦咸寒，归肺、胃、肾经，功能清热凉血、滋阴降火、解毒散结，既清解热毒，又滋养阴液，故清热、解毒、滋阴三者兼备。生地黄清热凉血、养阴生津，无解毒之功；赤芍、牡丹皮、紫草凉血活血或透疹，均无滋阴与解毒并举之效"},{"q":"艾叶的道地产地是","o":["辽宁","广东","青海","四川","湖北"],"a":4,"e":"艾叶为菊科植物艾的干燥叶，全国多处有产，以湖北蕲州所产者最为道地，称蕲艾，品质最优，故道地产地为湖北。辽宁、广东、青海、四川、湖北诸产地中，唯湖北蕲艾历史悠久、疗效著称，其余产地所产质量与声誉均不及，故湖北为艾叶道地产地"},{"q":"下列哪项不是温热性能所表示的作用","o":["温里","开窍","补火","温经","回阳"],"a":1,"e":"温热性药物所示作用多为温里散寒、补火助阳、温经通脉、回阳救逆等，体现扶阳祛寒之能。开窍指辛香走窜、通关开窍醒神，主要与药物的辛香走窜之性相关，非温热性能所概括。温里、补火、温经、回阳皆属温热药未必之作用，故开窍不属温热性能范畴"},{"q":"善祛经络风痰的药物是","o":["半夏","白前","芥子","天南星","旋覆花"],"a":3,"e":"天南星苦辛温，有毒，功能燥湿化痰、祛风解痉，走经络而善祛风痰，治风痰阻络之中风、口眼㖞斜、半身不遂及癫痫惊风。半夏燥湿化痰，主脾胃湿痰；白前、旋覆花降气化痰；芥子温肺化痰、利气散结，均善治脏腑之痰而无祛经络风痰之专长"},{"q":"既能涩肠止泻，又能清热燥湿的药物是","o":["椿皮","刺猬皮","白鲜皮","石榴皮","地骨皮"],"a":0,"e":"椿皮苦涩寒，归大肠、肝经，功能清热燥湿、涩肠止泻、止血止带、杀虫，既能清大肠湿热，又能涩肠固脱，故涩肠止泻兼清热燥湿首推椿皮。刺猬皮化瘀止血；白鲜皮清热燥湿、祛风解毒，无涩肠之功；石榴皮涩肠止血但无清热燥湿之效；地骨皮退虚热、凉血，均非所宜"},{"q":"功效有某种共性的药物配合应用，辅药能增强主药的疗效","o":["相反","相恶","相杀","相畏","相使"],"a":4,"e":"相使指以一药为主、另一药为辅，二药合用时辅药能提高主药疗效，如黄芪配茯苓治水肿，茯苓助黄芪利水。相反为合用增毒；相恶为减效；相畏为自身毒性被他药减轻；相杀为他药减轻自身毒性，四者皆非主辅增效，故辅药增强主药疗效者属相使"},{"q":"龟甲与鳖甲的共同功效是","o":["养血补心","益肾强骨","软坚散结","固经止崩","滋阴潜阳"],"a":4,"e":"龟甲与鳖甲均咸寒，归肝、肾经，皆能滋阴潜阳，治阴虚阳亢、虚风内动。龟甲兼益肾健骨、养血补心、固经止血；鳖甲兼退热除蒸、软坚散结。养血补心、益肾强骨为龟甲所独有，软坚散结、固经止崩亦各有专属，唯滋阴潜阳为二者共有"},{"q":"既能祛风通络，又能定惊止痉的药物是","o":["独活","防己","蕲蛇","海风藤","木瓜"],"a":2,"e":"蕲蛇甘咸温，有毒，归肝经，功能祛风通络、定惊止痉，善治风湿顽痹、中风半身不遂、小儿惊风、破伤风，为祛风通络、定惊止痉之要药。独活、海风藤、木瓜虽祛风湿通络，无定惊止痉之效；防己祛风湿止痛、利水，亦不止痉，故兼具二者者唯蕲蛇"},{"q":"胃十二指肠溃疡者慎服，用量过大易致恶心呕吐的药物是","o":["半夏","桔梗","黄药子","苦杏仁","天南星"],"a":1,"e":"桔梗苦辛平，功能宣肺、利咽、祛痰、排脓，其性升散，用量过大易刺激胃黏膜而致恶心呕吐，胃十二指肠溃疡者服之易加重刺激，故宜慎服。半夏燥湿化痰，天南星燥湿祛风；黄药子、苦杏仁虽有一定毒性或刺激，均无桔梗这样明显的催吐与溃疡刺激之弊"},{"q":"下列哪项不属沉降药性范畴","o":["利水","潜阳","收敛","开窍","清火"],"a":3,"e":"沉降药性主下行向内，作用多为清热泻火、泻下通便、利水渗湿、潜阳息风、收敛固涩、止咳平喘等。利水、潜阳、收敛、清火均属沉降范畴。开窍药辛香走窜，作用趋向升散外达，属升浮之性，不属沉降，故不属沉降药性范畴者为开窍"},{"q":"能渗湿利水，分清泌浊，治疗湿盛小便不利之水泻的药物是","o":["滑石","车前子","木通","通草","瞿麦"],"a":1,"e":"车前子甘寒，归肝、肾、肺、小肠经，功能利尿通淋、渗湿止泻、明目、祛痰，能渗湿利水、分清泌浊，使水湿从小便而去，治湿盛水泻、小便不利，即利小便以实大便。滑石、木通、通草、瞿麦虽均利尿通淋，无渗湿止泻、分清泌浊之功，故治水泻首选车前子"},{"q":"不属于解表药使用注意的是","o":["体虚汗多者忌服","淋病者慎用","热病津亏者忌服","疮疡初起兼表证者忌服","失血兼表证者慎服"],"a":3,"e":"解表药辛散，体虚汗多、热病津亏、失血兼表证者用之易耗气伤津动血，故忌用或慎用；淋家津亏，发汗更伤津液，亦所忌。疮疡初起兼表证者，正可借解表药辛散透邪、消散痈肿，属于适用范围，而非禁忌，故疮疡初起兼表证者忌服不属解表药使用注意"},{"q":"能温中降逆，补肾助阳的药物是","o":["丁香","附子","生姜","细辛","紫苏"],"a":0,"e":"丁香辛温，归脾、胃、肾经，功能温中降逆、散寒止痛、温肾助阳，既能温中焦而降胃气止呕呃，又能温肾助阳，故温中降逆兼补肾助阳者首选丁香。附子补火助阳、回阳，无降逆止呕之功；生姜温中止呕，无补肾之效；细辛、紫苏解表散寒，均无温中降逆与助阳兼备"},{"q":"治疗痰热咳喘，中风痰迷，惊痫癫狂首选的药物是","o":["半夏","竹茹","竹沥","瓜蒌","川贝母"],"a":2,"e":"竹沥甘寒，归心、肺、肝经，功能清热豁痰、定惊利窍，性寒滑利，善化热痰、开闭窍，治痰热咳喘、中风痰迷、惊痫癫狂。半夏燥湿化痰，性温；竹茹清热化痰、除烦止呕，力较缓和；瓜蒌清热化痰宽胸；川贝母润肺止咳，均无豁痰定惊开窍之峻效"},{"q":"既能清热凉血，又能活血化瘀的药物是","o":["紫花地丁","生地黄","玄参","牡丹皮","水牛角"],"a":3,"e":"牡丹皮苦辛微寒，归心、肝、肾经，功能清热凉血、活血化瘀，既清营血之热，又活血散瘀，治温毒发斑、血热吐衄、瘀血经闭、痈肿疮毒。紫花地丁清热解毒；生地黄、玄参清热凉血养阴；水牛角清热凉血解毒，均无活血化瘀之功，故清热凉血兼活血者推牡丹皮"},{"q":"陈皮主要用于","o":["脾胃气滞证","肝郁气滞证","肝寒气滞证","寒凝气滞证","食积气滞证"],"a":0,"e":"陈皮辛苦温，归脾、肺经，功能理气健脾、燥湿化痰，主入脾胃，善行脾胃气滞，治脘腹胀满、嗳气呕逆、纳呆，故脾胃气滞证为其主治。肝郁气滞宜柴胡、香附；肝寒气滞宜吴茱萸、小茴香；寒凝气滞宜丁香、高良姜；食积气滞宜枳实、山楂，均非陈皮所长"},{"q":"反映药物影响人体阴阳盛衰倾向的中药性能是","o":["四气","五味","升降浮沉","归经","毒性"],"a":0,"e":"四气即寒、热、温、凉，反映药物影响人体阴阳盛衰、寒热变化的作用倾向，是概括药性阴阳属性的核心性能。五味指药物滋味及作用；升降浮沉反映作用趋向；归经示作用部位；毒性示毒烈有无，皆不直接反映阴阳盛衰之倾向，故能反映者为四气"},{"q":"善治胃痛吐酸、湿疮湿疹的药是","o":["山茱萸","覆盆子","桑螵蛸","金樱子","海螵蛸"],"a":4,"e":"海螵蛸咸涩微温，归肝、肾经，功能收敛止血、涩精止带、制酸止痛、收湿敛疮，其制酸止痛可治胃痛泛酸，收湿敛疮可治湿疹湿疮，故胃痛吐酸、湿疮湿疹首选。山茱萸、覆盆子、金樱子、桑螵蛸均偏固精缩尿，无制酸止痛、收湿敛疮之效"},{"q":"主入中焦，功能温经止血的药物是","o":["生姜","干姜","炮姜","艾叶","三七"],"a":2,"e":"炮姜为干姜炮制而成，辛热之性稍减，主入中焦脾胃，功能温经止血、温中止痛，善治中焦虚寒之吐血、便血、崩漏。生姜解表温中止呕，不入止血；干姜温中回阳，无止血之功；艾叶温经止血，主入下焦胞宫；三七化瘀止血，均非主入中焦温经止血之品"},{"q":"乳香的入药部位是","o":["树脂","根茎","果实","树皮","花粉"],"a":0,"e":"乳香为橄榄科植物乳香树及同属植物树皮切口渗出的树脂，干燥后入药，故其入药部位为树脂，树脂类成分决定了其活血止痛、消肿生肌的功效。根茎、树皮、果实、花粉均非乳香来源；没药亦为树脂，与乳香相类，而根茎、树皮、果实、花粉类药材功效各异，不与乳香同"},{"q":"功能补气升阳，善治中气下陷的药物是","o":["升麻","柴胡","黄芪","党参","人参"],"a":2,"e":"黄芪甘微温，归脾、肺经，功能补气升阳、固表止汗、利水消肿、托毒排脓、敛疮生肌，善补脾肺之气并升举阳气，治中气下陷之久泻脱肛、内脏下垂。升麻、柴胡虽升阳，但以解表透疹、疏肝为主，无补气之功；党参、人参补气，无升阳举陷之专长"},{"q":"酸枣仁的主治病症不包括","o":["惊悸多梦","虚烦不眠","津伤口渴","体虚多汗","肠燥便秘"],"a":4,"e":"酸枣仁甘酸平，归肝、胆、心经，功能养心补肝、宁心安神、敛汗、生津，治虚烦不眠、惊悸多梦、体虚多汗、津伤口渴。肠燥便秘需养血润肠或润下，酸枣仁无润肠通便之功，不属其主治。惊悸多梦、虚烦不眠、体虚多汗、津伤口渴皆在酸枣仁主治之列"},{"q":"下列哪味是治疗肝肾亏虚胎动不安之要药","o":["络石藤","香加皮","桑寄生","五加皮","千年健"],"a":2,"e":"桑寄生苦甘平，归肝、肾经，功能祛风湿、补肝肾、强筋骨、安胎，既能补肝肾之虚，又能固冲任而安胎，为治肝肾亏虚胎动不安之要药。络石藤、海风藤祛风通络；香加皮、五加皮、千年健虽祛风湿强筋骨，均无补肝肾安胎之效，故胎动不安首选桑寄生"},{"q":"具有止血、安胎功效的药组是","o":["紫苏叶、桑寄生","砂仁、菟丝子","黄芩、苎麻根","杜仲、续断","白术、小蓟"],"a":2,"e":"黄芩苦寒，功能清热燥湿、泻火解毒、止血、安胎；苎麻根甘寒，功能凉血止血、安胎、清热解毒。二药均能清热止血并安胎，治血热胎动不安、吐血崩漏。紫苏叶、砂仁能安胎但不止血；杜仲、续断、菟丝子补肝肾安胎，无止血之功；白术健脾安胎，小蓟止血无安胎之效"},{"q":"淫羊藿、巴戟天的相同功效是","o":["补肾阳、强筋骨、祛风湿","补肾阳、益精血、托疮毒","补肾阳、止咳喘、退虚热","补肝肾、强筋骨、安胎元","补肝肾、止崩漏、益气血"],"a":0,"e":"淫羊藿与巴戟天均辛甘温，归肝、肾经，皆能补肾阳、强筋骨、祛风湿，治肾阳虚之阳痿遗精、筋骨痿软及风湿痹痛。益精血、托疮毒多指黄芪、鹿茸之类；止咳喘、退虚热为蛤蚧、知母所主；强筋骨安胎为桑寄生、杜仲所主；止崩漏益气血非二药所长"},{"q":"外用具有腐蚀赘疣作用的药物是","o":["鸦胆子","青蒿","白头翁","马齿苋","地锦草"],"a":0,"e":"鸦胆子苦寒，有小毒，功能清热解毒、燥湿杀虫、止痢截疟，外用有腐蚀赘疣作用，可治赘疣、鸡眼。青蒿退虚热、截疟；白头翁、马齿苋、地锦草清热解毒凉血止痢，均无腐蚀赘疣之效。外用蚀疮去腐、腐蚀赘疣为鸦胆子独有，故赘疣外治首选鸦胆子"},{"q":"下列除哪项外均是概括中药作用的基本性质和特征","o":["归经","四气五味","升降浮沉","毒性","配伍七情"],"a":4,"e":"中药性能是概括药物作用基本性质与特征的理论，包括四气五味、升降浮沉、归经、毒性等，分别从药性寒热、滋味作用、作用趋向、作用部位及毒烈程度加以归纳。配伍七情描述药物配伍后的相互关系，如相须、相使、相畏等，属配伍理论而非药物性能，故不属性能范畴"},{"q":"陈皮、枳实的共同功效为","o":["健脾","化痰","散寒","杀虫","利水"],"a":1,"e":"陈皮功能理气健脾、燥湿化痰，枳实功能破气消积、化痰散痞，二者均入脾胃经，皆能化痰，故化痰为其共同功效。健脾仅为陈皮所有，枳实无健脾之功；散寒、杀虫、利水既非陈皮亦非枳实所长，分别宜温里药、驱虫药与利水药，故二药共有者唯化痰"},{"q":"生姜解生半夏毒的配伍关系是","o":["相使","相须","相杀","相恶","相反"],"a":2,"e":"相杀指一种药物能减轻或消除另一种药物的毒性。生半夏有毒，生姜能解其毒，故生姜解生半夏毒属相杀。相须为功效相近增效；相使为主辅增效；相恶为降低药效；相反为合用后产生或增强毒性，四者均与解半夏毒无关，故所述为相杀"},{"q":"为凉肝息风止痉之要药，因其清热力强，心肝火盛，热极生风者尤宜的是","o":["天麻","牛黄","蜈蚣","钩藤","羚羊角"],"a":4,"e":"羚羊角咸寒，归肝、心经，功能平肝息风、清肝明目、清热解毒，性寒清热力强，为凉肝息风止痉之要药，心肝火盛、热极生风之惊狂抽搐尤宜。天麻甘平，息风止痉但不清热；牛黄清心豁痰；蜈蚣、钩藤虽息风止痉，清热之力与凉肝之专均不及羚羊角"},{"q":"为治泻痢要药的药物是","o":["知母","黄芩","黄连","白术","茯苓"],"a":2,"e":"黄连苦寒，归心、脾、胃、肝、胆、大肠经，功能清热燥湿、泻火解毒，尤善清中焦湿热，湿热蕴结大肠则泻痢，黄连清热燥湿解毒，为治湿热泻痢之要药。知母滋阴降火；黄芩偏清上焦；白术健脾燥湿；茯苓利水渗湿，均无清热燥湿止痢之专长"},{"q":"因气味香烈，入煎剂需炮制去油减少对消化道刺激的药是","o":["莪术","苏木","没药","血竭","延胡索"],"a":2,"e":"乳香、没药均为树脂类，气味香烈，对胃有刺激，入煎剂易致恶心呕吐，须经炮制去油以减轻消化道刺激，故没药入煎剂宜炮制去油。莪术、苏木、血竭、延胡索虽多活血祛瘀，或为破血，或为止痛，但无因气味香烈需去油以护胃的炮制要求，故所述药为没药"},{"q":"治寒湿偏重之腰腿疼痛较著者，宜选","o":["羌活","络石藤","独活","豨莶草","防己"],"a":2,"e":"独活辛苦微温，归肾、膀胱经，功能祛风除湿、通痹止痛，性善下行，主入肾经，尤宜下半身风寒湿痹，治寒湿偏重之腰腿疼痛较著者。羌活善治上半身痹痛；络石藤、豨莶草性偏寒凉，宜风湿热痹；防己祛风湿止痛、利水，均无独活温散下行、专治腰腿寒湿之特长"},{"q":"骨碎补可用于治疗","o":["皮肤瘙痒","痈疽疮毒","风湿顽痹","血瘀经闭","肾虚牙痛久泻"],"a":4,"e":"骨碎补苦温，归肝、肾经，功能补肾强骨、续伤止痛，肾虚则牙齿松动、牙痛，肾阳不足则久泻，骨碎补补肾强骨、温肾止泻，故可治肾虚牙痛、久泻。皮肤瘙痒宜祛风止痒药；痈疽疮毒宜清热解毒药；风湿顽痹宜祛风湿药；血瘀经闭宜活血药，均非骨碎补所主"},{"q":"不属于百合功效的是","o":["养肺阴","润肺燥","滋肾阴","养胃阴","清心安神"],"a":2,"e":"百合甘寒，归肺、心经，功能养阴润肺、清心安神，能养肺阴、润肺燥、养胃阴而清心安神，治肺燥咳嗽、劳嗽咯血及虚烦惊悸、失眠多梦。百合不入肾经，无滋肾阴之功，肾阴虚宜熟地黄、山茱萸、枸杞子之类，故滋肾阴不属于百合功效"},{"q":"大剂量使用会损害视神经的药物是","o":["蒲公英","紫花地丁","贯众","野菊花","板蓝根"],"a":2,"e":"贯众苦寒，有小毒，功能清热解毒、杀虫、凉血止血，其所含绵马酸类成分对视神经有损害作用，大剂量或长期服用可引起视力障碍甚至失明，故用之宜慎。蒲公英、紫花地丁、野菊花、板蓝根虽均清热解毒，无损害视神经之弊，故大剂量伤视神经者为贯众"},{"q":"黄芩不具有的功效是","o":["燥湿","泻火","解毒","止血","除蒸"],"a":4,"e":"黄芩苦寒，归肺、胆、脾、大肠、小肠经，功能清热燥湿、泻火解毒、止血、安胎，尤清上焦肺热。燥湿、泻火、解毒、止血皆为其功效。除蒸即退虚热、除骨蒸，为知母、黄柏、青蒿、地骨皮、鳖甲所主，黄芩无退虚热除蒸之功，故除蒸非黄芩所具"},{"q":"治疗湿热带下，苦参常配伍的药组是","o":["瞿麦、黄芩","茵陈、石韦","木通、金银花","白鲜皮、地肤子","硼砂、土荆皮"],"a":3,"e":"苦参苦寒，功能清热燥湿、杀虫、利尿，治湿热下注之带下、阴痒，常配伍白鲜皮、地肤子等清热燥湿、祛风止痒之品，外洗内服以增强清热燥湿止带止痒之效。瞿麦、木通利水通淋；茵陈、石韦利湿；硼砂、土荆皮外用杀虫，均非治湿热带下的常用配伍"},{"q":"应用麻黄根时宜注意的是","o":["孕妇忌用","儿童忌用","肺虚者忌用","有表邪者忌用","年老体弱者忌用"],"a":3,"e":"麻黄根甘平，归肺经，专于固表止汗，治自汗、盗汗，其性收敛，无发散之功。若外感表邪未解而用之，收敛留邪，使表邪不得外达，故有表邪者忌用。孕妇、儿童、年老体弱并非麻黄根禁忌；肺虚自汗正宜用之固表，均非应用麻黄根时的注意点"},{"q":"中药驱虫药宜","o":["睡前服","小剂量频服","空腹顿服","饭后服","随时服"],"a":2,"e":"驱虫药宜空腹顿服，此时胃肠内食物少，药物浓度高，可充分与虫体接触而增强驱虫效果，服后并宜观察排虫情况。小剂量频服使药物浓度不足，难以驱虫；饭后服则食物稀释药液、阻碍接触虫体；睡前服、随时服均不符合驱虫药空腹顿服的给药原则"},{"q":"内服涩肠止泻，外用收湿敛疮的药物是","o":["乌梅","禹余粮","赤石脂","罂粟壳","金樱子"],"a":2,"e":"赤石脂甘涩温，归胃、大肠经，功能涩肠止泻、收敛止血，外用收湿敛疮、生肌，内服治久泻久痢、便血崩漏，外用治疮疡不敛、湿疹。乌梅、禹余粮、金樱子、罂粟壳虽能涩肠止泻，均无外用收湿敛疮之功，故内服涩肠止泻兼外用收湿敛疮者首选赤石脂"},{"q":"不具备解毒消肿之功的药物是","o":["大蓟","小蓟","白及","大黄","紫珠叶"],"a":2,"e":"大蓟、小蓟均能凉血止血、散瘀解毒消痈；大黄泻下攻积、清热泻火、凉血解毒、逐瘀通经；紫珠叶凉血止血、散瘀解毒消肿，四者皆具解毒消肿之功。白及收敛止血、消肿生肌，虽能消肿，但无清热解毒之效，故不具备解毒消肿之功者为白及"},{"q":"硫黄性温，具有补火助阳功效，内服适用于下列哪项病证","o":["疥癣","湿疹","疮疡","阳痿","风寒湿痹"],"a":3,"e":"硫黄酸温，有毒，内服能补火助阳通便，治肾阳不足之阳痿、虚寒便秘，故补火助阳内服适用于阳痿。疥癣、湿疹、疮疡皆为硫黄外用解毒杀虫疗疮所主，非内服之证；风寒湿痹宜祛风湿散寒药，硫黄无祛风湿止痛之功，故内服适用病证为阳痿"},{"q":"知母用治阴虚火旺之骨蒸潮热，是因其能","o":["清热泻火","除烦止渴","润燥通便","滋阴降火","收湿敛疮"],"a":3,"e":"知母苦甘寒，归肺、胃、肾经，功能清热泻火、滋阴润燥，既清实热，又滋肾阴、降虚火，治阴虚火旺之骨蒸潮热、盗汗遗精，取其滋阴降火之功。清热泻火主气分实热；除烦止渴治热病烦渴；润燥通便治阴虚肠燥；收湿敛疮多为外用，均非治骨蒸潮热的针对功效"},{"q":"青皮的功效为","o":["行气止痛","降气止呃","行气宽中","开郁醒脾","疏肝破气"],"a":4,"e":"青皮苦辛温，归肝、胆、胃经，功能疏肝破气、消积化滞，性较峻烈，善破肝气之郁结，治肝郁气滞之胁痛、乳胀、疝痛。行气止痛为川楝子、延胡索所主；降气止呃为柿蒂、丁香所主；行气宽中为紫苏、陈皮所主；开郁醒脾为甘松所主，均非青皮功效"},{"q":"风湿痹痛，腰膝酸软，小儿行迟，宜选用","o":["五加皮","木瓜","桑枝","络石藤","海风藤"],"a":0,"e":"五加皮辛苦温，归肝、肾经，功能祛风湿、补肝肾、强筋骨、利水消肿，治风湿痹痛、腰膝酸软，且能强筋骨而治小儿行迟、筋骨痿软。木瓜舒筋活络、化湿；桑枝、海风藤、络石藤虽祛风通络，均无补肝肾、强筋骨之效，故痹痛兼腰膝酸软、小儿行迟首选五加皮"},{"q":"鹿茸的药性是","o":["甘、咸，温","甘、苦，温","辛、苦，温","酸、苦，温","辛、甘，温"],"a":0,"e":"鹿茸甘咸温，归肾、肝经，为温补命门、益精血之要药，甘能补、咸入肾、温助阳，故其药性为甘、咸，温。甘苦温、辛苦温、酸苦温或辛甘温等组合或偏燥烈，或入他经，均非鹿茸甘咸温、血肉有情之品补益精阳的性味特点"},{"q":"肉豆蔻治泻痢，是取其何功效","o":["燥湿，健脾","燥湿，升阳","温中，涩肠","温中，升阳","温中，燥湿"],"a":2,"e":"肉豆蔻辛温，归脾、胃、大肠经，功能涩肠止泻、温中行气，治虚寒气滞之泻痢、久泻不止，取其温中散寒、涩肠固脱之功。燥湿健脾、燥湿升阳为苍术、白术、羌活所主；温中升阳、温中燥湿或为干姜、草豆蔻之效，均无肉豆蔻涩肠止泻之专长"},{"q":"桑叶用于风热感冒，或温病初起，温热犯肺，发热、咽痒、咳嗽等症，常相须为用的药物是","o":["菊花","柴胡","升麻","淡豆豉","葛根"],"a":0,"e":"桑叶与菊花均甘寒，功能疏散风热、清肝明目，二者性味功效相类，相须为用，增强疏散风热、清利头目之效，治风热感冒、温病初起之发热咽痒咳嗽，如桑菊饮。柴胡、升麻升阳，葛根解肌升津，淡豆豉解表除烦，均无与桑叶相须疏散风热之专长"},{"q":"医生用桔梗治疗癃闭、便秘，因其能","o":["利水消肿","润肠通便","开宣肺气","荡涤肠胃","釜底抽薪"],"a":2,"e":"桔梗功能开宣肺气，肺主通调水道、主魄门，肺气宣通则水道通调、大肠传导顺畅。若肺气壅闭，则水道不利而癃闭、传导失司而便秘，桔梗开宣肺气，提壶揭盖，故可治癃闭、便秘。利水消肿、润肠通便、荡涤肠胃、釜底抽薪分别属茯苓、火麻仁、大黄之类，非桔梗作用"},{"q":"具有燥湿化痰作用的药物是","o":["青皮","枳实","陈皮","檀香","川楝子"],"a":2,"e":"陈皮辛苦温，归脾、肺经，功能理气健脾、燥湿化痰，脾为生痰之源，陈皮健脾燥湿而化痰，治湿痰咳嗽、痰多胸闷。青皮疏肝破气；枳实破气消积；檀香行气温中；川楝子行气止痛、清肝火，四者均无燥湿化痰之功，故具有燥湿化痰作用者为陈皮"},{"q":"既能平肝、息风止痉，又可内清肝热，外散风热的是","o":["天麻","牛黄","蜈蚣","钩藤","羚羊角"],"a":3,"e":"钩藤甘凉，归肝、心包经，功能息风定惊、清热平肝，既能平肝息风止痉以治肝阳上亢、惊痫抽搐，又可清肝热、散风热而治风热头痛、目赤，故内清肝热、外散风热者宜钩藤。天麻甘平不清热；牛黄清心；蜈蚣性温；羚羊角咸寒，虽清热力强，无外散风热之能"},{"q":"栀子外用的功效是","o":["泻火除烦","清热利湿","凉血解毒","消肿止痛","凉血止血"],"a":3,"e":"栀子苦寒，内服泻火除烦、清热利湿、凉血解毒；外用研末调敷，能清热消肿止痛，治跌打扭伤、疮疡肿痛。泻火除烦、清热利湿、凉血解毒、凉血止血皆为其内服或其他功效，非外用所长。题干问外用之效，故栀子外用的功效为消肿止痛"},{"q":"患者身发斑疹，色紫黯，最宜选用的药是","o":["桃仁","川芎","泽兰","血竭","红花"],"a":4,"e":"斑疹色紫黯为血分瘀滞之象，红花辛温，归心、肝经，功能活血通经、散瘀止痛，善活血化瘀而消斑，治瘀血阻滞之斑疹色暗。桃仁、泽兰虽活血，无消斑之专；川芎行气活血；血竭活血定痛、敛疮生肌，均非治斑疹紫黯之首选，故宜红花"},{"q":"既治痰多喘咳，又治肾虚遗尿，宜选用","o":["白果","百部","款冬花","桑白皮","马兜铃"],"a":0,"e":"白果甘苦涩平，有毒，归肺、肾经，功能敛肺化痰定喘、止带缩尿，既能敛肺气、化痰浊而止咳平喘，治痰多喘咳，又能补肾缩尿而治遗尿尿频，故痰多喘咳兼肾虚遗尿宜白果。百部、款冬花润肺止咳；桑白皮、马兜铃泻肺止咳，均无缩尿止遗之功"},{"q":"治咽喉肿痛，阳毒发斑，首选的药物是","o":["葛根","升麻","蔓荆子","柴胡","薄荷"],"a":1,"e":"升麻辛甘微寒，归肺、脾、胃、大肠经，功能解表透疹、清热解毒、升举阳气，善清阳明热毒，治咽喉肿痛、口舌生疮及阳毒发斑，如升麻葛根汤。葛根解肌升阳；柴胡疏肝升阳；薄荷、蔓荆子疏散风热，均无清热解毒、治阳毒发斑之专长"},{"q":"香附可用于治疗","o":["咳嗽痰多","月经不调","胸痹心痛","湿热痢疾","脚气肿痛"],"a":1,"e":"香附辛微苦甘平，归肝、三焦经，功能疏肝解郁、理气宽中、调经止痛，善疏肝气而调冲任，为妇科调经要药，治肝郁气滞之月经不调、痛经、乳房胀痛。咳嗽痰多宜桔梗、贝母；胸痹心痛宜丹参、薤白；湿热痢疾宜黄连；脚气肿痛宜槟榔、木瓜，均非香附所主"},{"q":"具有养阴生津功效的药物是","o":["生地黄","牡丹皮","赤芍","紫草","金银花"],"a":0,"e":"生地黄甘苦寒，归心、肝、肾经，功能清热凉血、养阴生津，既清营血之热，又滋养阴液、生津止渴，故具有养阴生津功效。牡丹皮清热凉血、活血；赤芍清热凉血、散瘀；紫草凉血活血、解毒透疹；金银花清热解毒，四者均无养阴生津之功"},{"q":"白鲜皮治风湿热痹，常配伍的药是","o":["独活","薏苡仁","羌活","黄连","茯苓"],"a":1,"e":"白鲜皮苦寒，功能清热燥湿、祛风解毒，治风湿热痹、关节肿痛，常配伍薏苡仁等清热利湿舒筋之品，共奏清热祛湿、通痹止痛之效。独活、羌活辛温，宜风寒湿痹；黄连清热燥湿，无祛风通痹之效；茯苓利水渗湿，无清热祛风之功，故白鲜皮治风湿热痹常配薏苡仁"},{"q":"石膏治气分实热证，常与其相须为用的药物是","o":["寒水石","芦根","知母","天花粉","淡竹叶"],"a":2,"e":"石膏与知母均甘寒，功能清热泻火，石膏清气分实热，知母兼滋阴润燥，二者相须为用，清热泻火之力大增，治气分实热证之壮热烦渴、汗出脉洪大，如白虎汤。寒水石、芦根、天花粉、淡竹叶虽能清热，但与石膏相须治气分实热的标准配伍当推知母"},{"q":"我国现存最早的本草专著是","o":["《神农本草经》","《本草纲目》","《证类本草》","《本草品汇精要》","《本草经集注》"],"a":0,"e":"《神农本草经》成书于汉代，是我国现存最早的药学专著，收载药物三百六十五种，分上、中、下三品，奠定了中药学理论基础。《本草经集注》为梁代陶弘景所撰，《证类本草》为宋代，《本草品汇精要》为明代，《本草纲目》为明代李时珍所著，成书均晚于《神农本草经》"},{"q":"赤痢日久，体虚者，宜选用的药物是","o":["槐花","仙鹤草","白头翁","苎麻根","侧柏叶"],"a":1,"e":"仙鹤草苦涩平，功能收敛止血、截疟、止痢、补虚，既能涩肠止痢治赤痢、久痢，又能补虚强壮以顾护体虚，故赤痢日久、体虚者最宜。白头翁清热解毒凉血，主热毒血痢，体虚者非宜；槐花、侧柏叶、苎麻根凉血止血，无补虚止痢之功，均非所宜"},{"q":"既能凉血散瘀，又善清泻肝火的药物是","o":["石膏","赤芍","牡丹皮","黄连","栀子"],"a":1,"e":"赤芍苦寒，归肝经，功能清热凉血、散瘀止痛、清肝火，既清血分之热而凉血散瘀，又泻肝火而治目赤肿痛、胁痛，故凉血散瘀兼清泻肝火首选赤芍。石膏清气分实热；牡丹皮虽凉血活血，清肝火之力不及；黄连、栀子清热泻火，无凉血散瘀之效"},{"q":"既能消痰下气，又能平肝镇惊的药物是","o":["竹沥","礞石","瓦楞子","海浮石","天竺黄"],"a":1,"e":"礞石咸寒，质重坠降，能消痰下气、平肝镇惊，主治顽痰胶结及惊风癫痫。竹沥甘寒，重在清热豁痰，无平肝镇惊之力；瓦楞子咸平，功专消痰化瘀、软坚散结；海浮石清肺化痰、软坚散结；天竺黄清热化痰、清心定惊，均无消痰下气兼平肝之能"},{"q":"硫黄内服的用量范围为","o":["0、5～1、5g","1、5～3g","1、5～3、5g","3～6g","3、5～6g"],"a":1,"e":"硫黄内服常用量1.5～3g，外用适量，功能解毒杀虫疗疮、补火助阳通便。0.5～1.5g剂量偏小，多入丸散；3～6g已超常规内服量，硫黄有毒，过量易中毒；1.5～3.5g、3.5～6g均非教材规定范围"},{"q":"药性甘平，质润多脂，兼有滋养补虚作用的润肠通便药是","o":["火麻仁","郁李仁","松子仁","柏子仁","苦杏仁"],"a":0,"e":"火麻仁甘平，质润多脂，兼能滋养补虚，适用于体虚、老人及产后肠燥便秘。郁李仁辛苦甘平，主润肠下气利水，无滋养之功；松子仁润肠兼润肺；柏子仁养心安神、润肠；苦杏仁降气止咳平喘、润肠，均不具甘平补虚之性"},{"q":"舒筋活络，又能化湿和胃的药物是","o":["独活","伸筋草","海风藤","青风藤","木瓜"],"a":4,"e":"木瓜酸温，归肝脾经，能舒筋活络、化湿和胃，为治风湿痹痛、筋脉拘挛及吐泻转筋之要药。独活祛风湿、止痛、解表；伸筋草祛风除湿、舒筋活络但无化湿和胃；海风藤、青风藤祛风湿、通经络，均无和胃化湿之功"},{"q":"防己的功效是","o":["祛风湿，舒筋络，止痒","祛风湿，清虚热，安胎","祛风湿，止痛，化湿和胃","祛风湿，止痛，安胎","祛风湿，止痛，利水"],"a":4,"e":"防己辛苦寒，祛风湿、止痛、利水，主治风湿痹痛、水肿、脚气，利水作用尤为显著。舒筋络、止痒为秦艽、白鲜皮之类；清虚热、安胎是秦艽、黄芩；化湿和胃为木瓜；止痛、安胎如桑寄生、杜仲，皆非防己功效"},{"q":"性味甘平的药物是","o":["钩藤","珍珠","僵蚕","天麻","羚羊角"],"a":3,"e":"天麻甘平，归肝经，息风止痉、平抑肝阳、祛风通络，性平和故寒热虚实之肝风内动皆可用。钩藤甘凉，珍珠甘咸寒，羚羊角咸寒，三者均偏寒凉；僵蚕咸辛平，偏于祛风痰、散结，非纯甘平之品。天麻甘平入肝，祛风通络并治肢体麻木、手足不遂"},{"q":"既能凉血止血，又兼收敛止血的药物是","o":["大蓟","白及","地榆","三七","白茅根"],"a":2,"e":"地榆苦酸涩微寒，归肝胃大肠经，凉血止血兼收敛止血，尤宜下焦血热之便血、痔血、血痢。大蓟凉血止血、散瘀解毒消痈，无收敛之性；白及收敛止血、消肿生肌但不凉血；三七化瘀止血、活血定痛；白茅根凉血止血、清热利尿，均无凉血与收敛兼备之效"},{"q":"既能袪风湿，又能消骨鲠的药物是","o":["威灵仙","蚕沙","防己","桑寄生","秦艽"],"a":0,"e":"威灵仙辛咸温，性猛善走，祛风湿、通经络、止痛，又能消骨鲠，治诸骨鲠喉。蚕沙祛风除湿、和胃化浊；防己祛风湿、止痛、利水；桑寄生祛风湿、补肝肾、强筋骨、安胎；秦艽祛风湿、通经络、清虚热、利湿退黄，均不能消骨鲠"},{"q":"具有化湿行气，温中止呕功效的药物是","o":["苍术","白术","砂仁","广藿香","佩兰"],"a":2,"e":"砂仁辛温，芳香化湿、行气和中、温中止呕、安胎，主治湿阻中焦、脾胃气滞及胎动不安。苍术辛苦温，燥湿健脾、祛风散寒，无行气止呕；白术健脾益气、燥湿利水、止汗安胎；广藿香化湿、止呕、解暑而偏解表；佩兰化湿解暑，均无温中行气之功"},{"q":"擅治米面薯芋等淀粉类食物积滞证的药物是","o":["山楂","神曲","麦芽","莱菔子","鸡内金"],"a":2,"e":"麦芽甘平，归脾胃肝经，行气消食、健脾开胃、回乳消胀，善消米面薯芋等淀粉类食积。山楂善消肉食油腻之积；神曲消食和胃，善消金石类药积；莱菔子消食除胀、降气化痰；鸡内金消食力强，通治诸积，然消淀粉之积首推麦芽"},{"q":"治肺热喘咳，宜选用的药物是","o":["石膏","淡竹叶","栀子","决明子","夏枯草"],"a":0,"e":"石膏甘辛大寒，归肺胃经，清热泻火、除烦止渴，善清肺经实热，治肺热咳喘常配麻黄、杏仁。淡竹叶清心火、利小便；栀子泻三焦火、凉血解毒；决明子清肝明目、润肠；夏枯草清肝火、散郁结，均不入肺经清肺热以平喘"},{"q":"治疗阳明头痛，牙痛，鼻渊，风湿痹痛宜选用的药物是","o":["防风","葛根","柴胡","羌活","白芷"],"a":4,"e":"白芷辛温，归肺胃大肠经，解表散寒、祛风止痛、宣通鼻窍、燥湿止带、消肿排脓，阳明头痛、牙痛、鼻渊及风湿痹痛皆宜。防风祛风解表、胜湿止痛而善治太阳经；葛根解肌退热、升阳；柴胡疏肝升阳，善治少阳；羌活祛风胜湿止痛，善治太阳头痛"},{"q":"无清热解毒之功的药物是","o":["大蓟","小蓟","大黄","地榆","侧柏叶"],"a":4,"e":"侧柏叶苦涩寒，凉血止血、化痰止咳、生发乌发，并无清热解毒之功。大蓟、小蓟凉血止血兼解毒消痈；大黄泻下攻积、清热泻火、凉血解毒、逐瘀通经；地榆凉血止血、解毒敛疮，四者均具清热解毒之效，唯侧柏叶不具"},{"q":"车前子、旋覆花入汤剂宜","o":["久煎","先煎","布包煎","另行溶化","另煎"],"a":2,"e":"车前子为细小种子，旋覆花带绒毛，二者入汤剂均须布包煎，以免黏锅、漂浮或刺激咽喉。久煎、先煎多针对矿物、贝壳及毒性药；另行溶化用于阿胶等胶类；另煎用于人参等贵重药，皆非此二药之法。包煎可免药液浑浊及绒毛刺激咽喉，为他药所无"},{"q":"桔梗的功效是","o":["润肺，止咳，下气，化痰","宣肺，利咽，清肺，化痰","宣肺，利咽，祛痰，排脓","降气，止咳，祛痰，排脓","降气，止呕，祛痰，排脓"],"a":2,"e":"桔梗苦辛平，归肺经，宣肺、利咽、祛痰、排脓，为肺经引经药，治咳嗽痰多、咽痛音哑、肺痈吐脓。宣肺而非降气为其要点，降气止咳多属苏子、杏仁；清肺化痰非主要功用；止呕为胃气上逆所宜，与桔梗升宣之性相悖"},{"q":"既能袪风湿，又有通经络，平肝功效的药物是","o":["桑枝","臭梧桐叶","防己","秦艽","豨莶草"],"a":1,"e":"臭梧桐叶辛苦甘平，祛风除湿、通经络、平肝，治风湿痹痛、肢体麻木及肝阳上亢之头痛眩晕。桑枝祛风湿、通经络而善治上肢痹痛，无平肝之功；防己祛风湿、止痛、利水；秦艽清虚热；豨莶草祛风湿、通经络、清热解毒，均无平肝之效"},{"q":"生大黄攻下，宜","o":["先煎","后下","久煎","包煎","另煎"],"a":1,"e":"生大黄含蒽醌类成分，久煎易破坏致泻下之力减弱，故用于攻下宜后下，或以沸水泡服。先煎多用于矿物、贝壳类；久煎反削弱泻下；包煎针对细小种子及绒毛药；另煎用于贵重药，均非大黄攻下之法。生大黄后下则泻下力峻，久煎则力缓，熟大黄泻下更为和缓"},{"q":"既能清热化痰，又能清心定惊的药物是","o":["瓜蒌","礞石","竹茹","海蛤壳","天竺黄"],"a":4,"e":"天竺黄甘寒，归肺肝心经，清热化痰、清心定惊，主治热痰咳嗽、中风痰迷、小儿惊风。瓜蒌清热化痰、宽胸散结、润肠；礞石消痰下气、平肝镇惊，重在坠痰；竹茹清热化痰、除烦止呕；海蛤壳清肺化痰、软坚散结，均无清心定惊之功"},{"q":"既能补阴，又能补气的药物是","o":["百合","玉竹","石斛","黄精","天冬"],"a":3,"e":"黄精甘平，归脾肺肾经，补气养阴、健脾、润肺、滋肾，气阴双补，主治脾胃气虚、肺虚燥咳、肾虚精亏。百合、玉竹、石斛、天冬均偏甘寒，专于养阴润燥，无补气之功，唯黄精气阴兼顾、补益脾肺肾"},{"q":"下列除哪项外，均属于药性升降沉浮的确定依据","o":["药物的剂型","药物的效用","药物的性味","药物的质地轻重","入药部位"],"a":0,"e":"升降浮沉的确定依据为药物性味、质地轻重、入药部位与效用：辛甘升浮、苦酸咸沉降，花叶质轻升浮、矿物贝壳质重沉降，根与花叶部位有别，作用趋向亦相关。剂型只影响服用与疗效发挥，不作为确定升降浮沉的依据"},{"q":"麦冬的功效是","o":["滋补肝肾，益精明目","养阴生津，润肺清心","滋阴补血，生津润燥","润肺化痰，养阴和胃","滋补肝肾，凉血止血"],"a":1,"e":"麦冬甘微苦微寒，归心肺胃经，养阴润肺、益胃生津、清心除烦，主治肺燥干咳、津伤口渴、心烦失眠。滋补肝肾、益精明目为枸杞子；滋阴补血、生津润燥为熟地黄；润肺化痰、养阴和胃为沙参类；滋补肝肾、凉血止血为旱莲草"},{"q":"桂枝不适宜的病证是","o":["风寒表实证","血热出血证","痰饮证","阳虚胸痹","血滞经闭"],"a":1,"e":"桂枝辛甘温，发汗解肌、温通经脉、助阳化气，性温升散，血热出血者用之助热动血，故不宜。风寒表实证、痰饮证、阳虚胸痹、血滞经闭皆属寒、滞、阳虚之证，正是桂枝温通所宜，非其禁忌。桂枝温通经脉而助阳，血热妄行者服之必增出血之势"},{"q":"常与连翘相须为用，治疗风热表证、温热初起的药物是","o":["金银花","大青叶","板蓝根","穿心莲","薄荷"],"a":0,"e":"金银花甘寒，清热解毒、疏散风热，与连翘相须为用，共治风热表证、温热病初起及疮痈肿毒。大青叶、板蓝根清热解毒、凉血利咽，重在凉血解毒；穿心莲清热燥湿解毒；薄荷疏散风热、清利头目、利咽透疹，均不与连翘构成相须之配"},{"q":"下列哪味药物善温助心肾之阳，可用于治疗心阳不足之胸痹心痛，心悸气短","o":["附子","丁香","吴茱萸","小茴香","高良姜"],"a":0,"e":"附子辛甘大热，归心肾脾经，补火助阳、散寒止痛、回阳救逆，上助心阳、下温肾阳，可治心阳不足之胸痹心痛、心悸气短。丁香温中降逆、温肾助阳而偏胃；吴茱萸散寒止痛、降逆止呕、助阳止泻；小茴香散寒止痛、理气和胃；高良姜温胃止痛，均不主心阳"},{"q":"苦参与蛇床子的共同功效是","o":["清热，止痢","杀虫，燥湿","利尿，清热","温阳，止痛","祛风，解毒"],"a":1,"e":"苦参苦寒，清热燥湿、杀虫、利尿；蛇床子辛苦温，燥湿祛风、杀虫止痒、温肾壮阳，二者均具杀虫、燥湿之功。止痢为苦参治湿热痢疾所独有；利尿清热属苦参；温阳止痛、祛风解毒非二者共有，寒温之性迥异，共性唯杀虫燥湿"},{"q":"治热病气津两伤所致的口渴、多汗、脉大无力，除用石膏、知母外，还宜配伍","o":["人参","牡蛎","黄连","酸枣仁","山茱萸"],"a":0,"e":"热病气津两伤见口渴、多汗、脉大无力，于石膏、知母清热生津之外，配人参大补元气、生津止渴，益气以生津。牡蛎咸寒，敛阴潜阳、止汗，无补气生津；黄连苦寒燥湿，反伤津；酸枣仁养心安神；山茱萸补益肝肾、收敛固涩，均非气津两伤所宜"},{"q":"莲子、远志的共同功效是","o":["平肝安神","交通心肾","补脾止泻","益肾涩精","祛痰止咳"],"a":1,"e":"莲子甘涩平，补脾止泻、益肾涩精、养心安神；远志苦辛温，安神益智、祛痰开窍、消散痈肿，二者均能交通心肾而安神。平肝安神非二者共有；补脾止泻、益肾涩精仅莲子有；祛痰止咳为远志之功，均非共同功效"},{"q":"不宜与半夏、瓜蒌、贝母、白及、白蔹同用的药物是","o":["肉桂","人参","丁香","附子","吴茱萸"],"a":3,"e":"附子与半夏、瓜蒌、贝母、白及、白蔹相反，属十八反，同用增毒。肉桂、丁香、吴茱萸虽为温里药，均不在十八反之列；人参反藜芦，亦不与上述诸药相反。故唯有附子存在此类配伍禁忌。附子辛热有毒，与上述寒凉药同用更助其毒，故列为禁忌"},{"q":"治疗肠燥便秘，宜选用","o":["桑叶","桑枝","桑椹","桑寄生","桑白皮"],"a":2,"e":"桑椹甘酸寒，滋阴补血、生津润燥，主治肝肾阴虚、眩晕耳鸣、心悸失眠及肠燥便秘。桑叶疏散风热、清肺润燥；桑枝祛风湿、通经络；桑寄生补肝肾、强筋骨、安胎；桑白皮泻肺平喘、利水消肿，均无润肠通便之功"},{"q":"下列药物中，无安胎功效的药物是","o":["紫苏叶","砂仁","黄芩","桑寄生","广藿香"],"a":4,"e":"广藿香化湿、止呕、解暑，并无安胎之功。紫苏叶解表散寒、行气宽中而能安胎；砂仁化湿行气、温中安胎；黄芩清热燥湿、泻火解毒、凉血安胎；桑寄生祛风湿、补肝肾、安胎，四者均有安胎作用，唯藿香不具"},{"q":"鳖甲的临床应用不包括","o":["阴虚阳亢","阴虚风动","失眠健忘","阴虚内热","癥瘕积聚"],"a":2,"e":"鳖甲咸寒，滋阴潜阳、退热除蒸、软坚散结，主治阴虚阳亢、阴虚风动、阴虚内热及癥瘕积聚。失眠健忘多属心脾两虚、心肾不交，须养心安神，非鳖甲所主，故不列入其临床应用。鳖甲咸寒走血分，专主阴虚与瘀结，与养心安神无涉"},{"q":"能清热解毒，消痈，下乳，舒筋通脉的药物是","o":["金银花","蚤休","漏芦","蒲公英","紫花地丁"],"a":2,"e":"漏芦苦寒，清热解毒、消痈散结、通经下乳、舒筋通脉，主治乳痈肿痛、乳汁不下及痹痛筋脉拘挛。金银花清热解毒、疏散风热；蚤休清热解毒、消肿止痛、息风定惊；蒲公英清热解毒、消痈散结；紫花地丁清热解毒、凉血消肿，均无下乳、舒筋通脉之功"},{"q":"治温热病热入营血，神昏舌绛，宜首选的药组是","o":["金银花、连翘","大青叶、板蓝根","穿心莲、贯众","大青叶、青黛","贯众、青黛"],"a":0,"e":"金银花、连翘均甘寒，清热解毒、疏散风热，且能清营透热，寓“透热转气”之意，为温热病热入营血、神昏舌绛之首选药组。大青叶、板蓝根、青黛重在凉血解毒消斑；穿心莲、贯众清热燥湿解毒或杀虫，均无清营透热之能"},{"q":"常用于治疗肝肾不足、腰膝酸软、妊娠漏血、胎动不安的药物","o":["黄芩","竹茹","白术","生姜","杜仲"],"a":4,"e":"杜仲甘温，补肝肾、强筋骨、安胎，主治肝肾不足之腰膝酸痛、筋骨无力及妊娠漏血、胎动不安。黄芩清热安胎，属热证所宜；竹茹清热化痰、除烦止呕；白术健脾益气安胎；生姜解表散寒、温中止呕，均无补肝肾、强筋骨之功"},{"q":"治疗元气大脱兼冷汗淋漓、四肢厥冷、脉微欲绝者，人参常配伍","o":["麦冬","白术","附子","黄芪","五味子"],"a":2,"e":"元气大脱兼冷汗淋漓、四肢厥冷、脉微欲绝为亡阳虚脱，人参大补元气，配附子补火助阳、回阳救逆，如参附汤。麦冬养阴生津；白术健脾益气；黄芪补气升阳；五味子收敛固涩，皆不能回阳救逆，故非此证配伍首选"},{"q":"不具有清肝明目作用的药物是","o":["车前子","决明子","青葙子","紫苏子","羚羊角"],"a":3,"e":"紫苏子辛温，降气化痰、止咳平喘、润肠通便，并无清肝明目作用。车前子、决明子、青葙子均能清肝明目；羚羊角咸寒，平肝息风、清肝明目、清热解毒，四者皆有明目之功，唯紫苏子所主在肺与大肠"},{"q":"贯众性寒，有凉血止血之功，炒炭后具有的功效是","o":["涩肠止泻","收敛止血","固精缩尿","固表止汗","敛肺止咳"],"a":1,"e":"贯众多生用清热解毒、凉血止血、杀虫；炒炭后寒性减、涩性增，功专收敛止血，用于多种出血证。涩肠止泻为诃子、肉豆蔻；固精缩尿为桑螵蛸、覆盆子；固表止汗为黄芪、麻黄根；敛肺止咳为五味子，均非贯众炭之效"},{"q":"下列除哪项外，均是莪术的主治病证","o":["癥瘕积聚","心腹瘀痛","血瘀经闭","风湿痹痛","食积脘腹胀痛"],"a":3,"e":"莪术辛苦温，行气破血、消积止痛，主治癥瘕积聚、瘀血经闭、心腹瘀痛及食积脘腹胀痛。风湿痹痛须祛风湿药主治，莪术专入气血分破血行气，无祛风湿、通经络之效，故不属其主治病证。莪术入肝脾气分血分，破血行气之力峻，非祛风湿之品"},{"q":"广藿香最适于治疗哪种呕吐","o":["胃寒呕吐","胃热呕吐","胃虚呕吐","胃有湿热呕吐","脾胃湿浊呕吐"],"a":4,"e":"广藿香芳香化浊、和中止呕，善治湿浊中阻所致呕吐，为治呕要药。胃寒呕吐宜生姜、丁香；胃热呕吐宜黄连、竹茹；胃虚呕吐宜党参、半夏；胃有湿热呕吐宜黄连、芦根，均非藿香所主。藿香芳香化浊而不偏寒热，湿浊中阻之呕逆最为适宜"},{"q":"具有清肝泻火，明目退翳功效的药物是","o":["夏枯草","野菊花","青葙子","决明子","鸭跖草"],"a":2,"e":"青葙子苦寒，清肝泻火、明目退翳，主治肝火上炎之目赤肿痛、目生翳障。夏枯草清肝火、散郁结、明目，重在散结；野菊花清热解毒；决明子清肝明目、润肠通便；鸭跖草清热解毒、利水消肿，均无明目退翳之专长"},{"q":"治头虱、阴道滴虫，宜选用","o":["百部","紫菀","枇杷叶","苦杏仁","洋金花"],"a":0,"e":"百部甘苦微温，润肺下气止咳、杀虫灭虱，外用可治头虱、体虱、蛲虫及阴道滴虫。紫菀润肺化痰止咳；枇杷叶清肺止咳、降逆止呕；苦杏仁降气止咳平喘、润肠；洋金花平喘止咳、解痉定痛，均无杀虫灭虱之用"},{"q":"下列哪味中药可用治中焦寒凝气滞之脘腹胀痛","o":["肉桂","丁香","花椒","吴茱萸","小茴香"],"a":4,"e":"小茴香辛温，散寒止痛、理气和胃，主入肝脾胃肾经，善治中焦寒凝气滞之脘腹胀痛、寒疝腹痛。肉桂补火助阳、温通经脉；丁香温中降逆、温肾助阳；花椒温中止痛、杀虫止痒；吴茱萸散寒止痛、降逆止呕，均偏温里助阳而非理气和中"},{"q":"为引药入肾及增强药物补肾的作用宜","o":["蜜炙","酒炙","醋炙","盐水炙","姜汁炙"],"a":3,"e":"盐味咸入肾，盐水炙可引药入肾经并增强补肾作用，如盐杜仲、盐黄柏。蜜炙补中润肺、缓急；酒炙活血通络、升提；醋炙入肝、增强止痛；姜汁炙温中散寒、止呕，各自引经不同，均不入肾。盐水炙后引药下行入肾，增强滋阴降火或补肾固精之效"},{"q":"可用治热毒血痢，便下脓血的药物是","o":["金银花","连翘","大青叶","鱼腥草","蒲公英"],"a":0,"e":"金银花甘寒，清热解毒，兼凉血止痢，为治热毒血痢、便下脓血之要药。连翘清热解毒、消肿散结；大青叶凉血解毒消斑；鱼腥草清热解毒、消痈排脓，善治肺痈；蒲公英清热解毒、消痈散结，善治乳痈，均非治血痢首选"},{"q":"治疗肾虚小儿鸡胸，囟门不合，宜首选","o":["鳖甲","麦冬","龟甲","玉竹","百合"],"a":2,"e":"龟甲咸甘寒，滋阴潜阳、益肾强骨、养血补心、固经止崩，主治肾虚骨痿、小儿鸡胸、囟门不合及阴虚潮热。鳖甲滋阴潜阳、软坚散结，无益肾强骨；麦冬养阴润肺；玉竹养阴润燥；百合养阴润肺清心，均不能强骨"},{"q":"荆芥的功效是","o":["解表透疹，消疮止血","发表通窍，胜湿止痛","发表止痉，消疮止泻","发表止痛，利水消肿","消疮止泻，透疹止血"],"a":0,"e":"荆芥辛微温，解表散风、透疹、消疮，炒炭可收敛止血，为发表散风通用之品。发表通窍、胜湿止痛为白芷、苍耳子；发表止痉、消疮止泻非其功；发表止痛、利水消肿为麻黄；消疮止泻、透疹止血诸项组合错乱，均非荆芥功效"},{"q":"下列配伍中属于“十九畏”的药物是","o":["大戟与甘草","贝母与乌头","乌头与瓜萎","官桂与赤石脂","芍药与藜芦"],"a":3,"e":"十九畏载“官桂善能调冷气，若逢石脂便相欺”，官桂与赤石脂相畏。大戟与甘草、贝母与乌头、乌头与瓜蒌、芍药与藜芦均属十八反内容，非十九畏所载，二者不可混淆。十九畏与十八反同属配伍禁忌而内容各异，须分别记忆"},{"q":"马勃与马齿苋的共同功效是","o":["止痢","止血","止汗","止痒","止痛"],"a":1,"e":"马勃辛平，清热解毒、利咽、止血，治咽喉肿痛及出血证；马齿苋酸寒，清热解毒、凉血止血、止痢，二者均能止血。止痢仅马齿苋具备；止汗、止痒、止痛均非二者共有之功效，故共性唯止血。二药皆性寒而清血分之热，故生用或炒炭均能止出血"},{"q":"菊花与升麻均具有的功效是","o":["生津止渴","通经活络","升举阳气","清热解毒","清肝明目"],"a":3,"e":"菊花甘苦微寒，疏散风热、平肝明目、清热解毒；升麻辛微甘微寒，解表透疹、清热解毒、升举阳气，二者均具清热解毒。生津止渴、通经活络非二者所有；升举阳气仅升麻有；清肝明目仅菊花有，共性唯清热解毒"},{"q":"用治肝阳上亢的头痛眩晕，宜选用的药是","o":["白芍","当归","川芎","白芷","熟地黄"],"a":0,"e":"白芍苦酸微寒，养血敛阴、柔肝止痛、平抑肝阳，善治肝阳上亢之头痛眩晕及肝郁胁痛。当归补血活血、调经止痛；川芎活血行气、祛风止痛，性温升散，肝阳上亢忌用；白芷祛风止痛；熟地黄补血滋阴，均无平抑肝阳之功"},{"q":"清泄的含义是","o":["栀子、黄芩清热泻火，用治火热上炎、目赤口苦之证","大黄泻下通便，用治热结便秘","枇杷叶降泄胃气，用治胃气上逆的呕吐呃逆","黄连、黄柏清热燥湿，用治湿热证","杏仁降泄肺气，用治肺气上逆的咳喘"],"a":0,"e":"清泄指清热泻火，栀子、黄芩苦寒清热泻火，用治火热上炎之目赤口苦。大黄泻下通便属通泄；枇杷叶降胃气止呕、杏仁降肺气止咳均属降泄；黄连、黄柏清热燥湿属燥湿，皆非清泄本义。苦寒者多主清泄，与降泄、通泄、燥湿诸法各有所指"},{"q":"优质大黄的典型特点是","o":["狮子头","菊花心","蟾蜍皮","锦纹","云锦花团"],"a":3,"e":"大黄断面具锦纹（星点，即异型维管束），为品质优良的重要鉴别特征。狮子头为党参顶端性状；菊花心为黄芪、甘草等断面特征；蟾蜍皮、云锦花团均非大黄的鉴别术语。锦纹为断面异常维管束形成的黄棕相间花纹"},{"q":"大黄配伍茵陈、栀子治疗黄疸，是因其功能","o":["清热解毒","清热泻火","除湿退黄","泻下攻积","活血化瘀"],"a":2,"e":"大黄泻下攻积、清热泻火、凉血解毒、逐瘀通经，配茵陈、栀子可清利湿热、利胆退黄，以治湿热黄疸。清热解毒、清热泻火、泻下攻积、活血化瘀虽皆为其功，但治黄疸取除湿退黄、通腑泄热之效，故功在除湿退黄"},{"q":"七情配伍中，可以降低药物毒副作用的是","o":["相恶、相使","相杀、相反","相须、相恶","相杀、相畏","相须、相使"],"a":3,"e":"相畏指一药毒性被另一药减轻，相杀指一药能减轻另一药毒性，二者同指减毒配伍，如半夏畏生姜、生姜杀半夏毒。相须、相使增强疗效；相恶降低药效；相反增强毒性，均非降低毒副作用之配伍。相畏、相杀实为一事之两面，均属七情配伍中减毒之法"},{"q":"长于温脾胃之阳，祛脾胃之寒，为温中散寒之要药的是","o":["干姜","丁香","花椒","胡椒","小茴香"],"a":0,"e":"干姜辛热，归脾胃肾心肺经，温中散寒、回阳通脉、温肺化饮，专温脾胃之阳、祛脾胃之寒，为温中散寒要药。丁香温中降逆、温肾助阳；花椒温中止痛、杀虫止痒；胡椒温中散寒、下气消痰；小茴香散寒止痛、理气和胃，均非温中之要药"},{"q":"药物的升降浮沉是指","o":["药物有无毒副作用","作用部位的选择性","作用趋向性","药物有无补泻作用","药物作用的峻猛与否"],"a":2,"e":"升降浮沉指药物作用于人体的趋向性，升浮主上行向外，沉降主下行向内。有无毒副作用属毒性；作用部位选择性属归经；有无补泻属补泻；作用峻猛与否属药力强弱，均非升降浮沉之含义。升降浮沉以作用趋向为核心，与毒性、归经、补泻各有所别"},{"q":"黄柏与生地黄的共同主治是","o":["肺热咳嗽","骨蒸劳热","肠燥便秘","疮痈肿毒","津伤口渴"],"a":1,"e":"黄柏苦寒，清热燥湿、泻火除蒸、解毒疗疮，善退虚热、泻相火；生地黄甘苦寒，清热凉血、养阴生津，二者均可治阴虚骨蒸劳热。肺热咳嗽、肠燥便秘、疮痈肿毒、津伤口渴皆非二者共同主治。黄柏退虚热、生地凉血养阴，合则滋阴降火，共治骨蒸"},{"q":"具有活血止痛，止咳平喘功效的药物是","o":["穿山龙","老鹳草","丝瓜络","络石藤","路路通"],"a":0,"e":"穿山龙苦平，祛风除湿、活血通络、止咳平喘，兼能活血止痛，用于风湿痹痛、跌打损伤及咳嗽痰喘。老鹳草祛风通络、止泻；丝瓜络通经活络、解毒消肿；络石藤祛风通络、凉血消肿；路路通祛风活络、利水通经，均无止咳平喘之功"},{"q":"外用可杀虫疗疮的泻水逐饮药是","o":["甘遂","京大戟","芫花","商陆","番泻叶"],"a":2,"e":"芫花辛苦温有毒，泻水逐饮、祛痰止咳，外用杀虫疗疮，可治头疮、顽癣。甘遂、京大戟泻水逐饮、消肿散结，外用消肿而无杀虫疗疮专长；商陆泻下利水、消肿散结；番泻叶泻热行滞通便，属攻下药，均非泻水逐饮兼杀虫疗疮之选"},{"q":"以下哪项不是沉降药物的作用","o":["清热泻火","收敛固涩","平肝潜阳","开通心窍","镇惊安神"],"a":3,"e":"沉降药主下行向内，具清热泻火、收敛固涩、平肝潜阳、镇惊安神、降逆止呕、泻下等作用。开通心窍属升浮宣通之性，如麝香、冰片辛香走窜，主上行开窍，非沉降药物作用。沉降之品多主下行向内，开窍药辛香走窜上行，其性相反"},{"q":"杜仲具有的功效是","o":["补肝肾、安胎","补肾阳、止汗","补肾阳、平喘","补肝肾、明目","退虚热、安胎"],"a":0,"e":"杜仲甘温，补肝肾、强筋骨、安胎，主治肝肾不足之腰膝酸痛、筋骨无力及胎动不安。补肾阳、止汗非其功；补肾阳、平喘为补骨脂、核桃仁；补肝肾、明目为枸杞子、女贞子；退虚热、安胎为黄芩、苎麻根，均非杜仲功效"},{"q":"除哪味药物外，孕妇当慎用","o":["干姜","肉桂","附子","丁香","吴茱萸"],"a":3,"e":"丁香辛温，温中降逆、温肾助阳，药性相对平和，不属孕妇慎用之列。干姜、肉桂、附子均辛热，温里助火，吴茱萸辛苦热且有小毒，辛热动火之品孕妇当慎用，唯丁香不在其例。温里药多辛热动火，孕妇用之恐动胎气，丁香则相对平和"},{"q":"清热药的性味多是","o":["苦寒","辛寒","咸寒","甘寒","酸寒"],"a":0,"e":"清热药多苦寒，苦能泄能燥，寒能清热，故清泄火热、燥湿解毒之力较强。辛寒、甘寒、咸寒、酸寒虽可见于个别药，如石膏甘辛大寒、玄参咸寒，但非清热药共性之性味，主流仍为苦寒。苦寒之品既清火热又燥湿邪，故清热药以苦寒者居多数"},{"q":"以下哪个是东北的道地药材","o":["枸杞","山药","牛膝","当归","鹿茸"],"a":4,"e":"鹿茸主产东北，为关药代表，功能壮肾阳、益精血、强筋骨。枸杞主产宁夏；山药主产河南，称怀山药；牛膝主产河南，称怀牛膝；当归主产甘肃岷县，均非东北道地产区。关药主产东北，鹿茸、人参、五味子并称东北三宝"},{"q":"蒲黄、旋覆花等药入汤剂宜","o":["包煎","后下","先煎","烊化","冲服"],"a":0,"e":"蒲黄为细小花粉，旋覆花具绒毛，二者入汤剂均须包煎，以免漂浮、黏锅或刺激咽喉。后下用于芳香易挥发药；先煎用于矿物、贝壳；烊化用于胶类；冲服用于贵重细粉，均非此二药之法。包煎可避免细小药末混入药液刺激咽喉，保证服用安全"},{"q":"百部止咳平喘的机制是","o":["宣肺","润肺","清肺","敛肺","泻肺"],"a":1,"e":"百部甘苦微温，润肺下气止咳，性温润而不燥，善治肺燥咳嗽、百日咳及虚劳久咳。宣肺为桔梗、麻黄；清肺为桑叶、黄芩；敛肺为五味子、白果；泻肺为桑白皮、葶苈子，均非百部止咳之机制。百部温润，久咳、虚咳及虫咳皆宜，与宣肺泻肺诸法迥异"},{"q":"善疏散少阳半表半里之邪的药物是","o":["薄荷","牛蒡子","夏枯草","升麻","柴胡"],"a":4,"e":"柴胡辛苦微寒，归肝胆经，解表退热、疏肝解郁、升举阳气，善透泄少阳半表半里之邪，为治寒热往来之要药。薄荷、牛蒡子疏散风热；夏枯草清肝火；升麻解表升阳、清热解毒，均不解少阳之邪。柴胡升举阳气并和解少阳，为治寒热往来之专药"},{"q":"川楝子除具有行气止痛作用外，尚能","o":["疏肝泄热","纳气平喘","清热解毒","活血化瘀","行气消积"],"a":0,"e":"川楝子苦寒，行气止痛、疏肝泄热，主治肝郁化火之胸胁胀痛、疝气疼痛。纳气平喘为沉香所主；清热解毒非其功；活血化瘀属延胡索、川芎；行气消积为青皮、枳实，均非川楝子所长。川楝子性寒，肝郁化火者最宜，虚寒气滞则当慎用"},{"q":"治目赤多泪，目暗不明，齿龈肿痛，首选的药物是","o":["葛根","桑叶","牛蒡子","蔓荆子","薄荷"],"a":3,"e":"蔓荆子辛苦微寒，疏散风热、清利头目、祛风止痛，主治风热上攻之目赤肿痛、多泪、目暗不明及头面诸痛、齿龈肿痛。葛根解肌升阳；桑叶疏散风热、清肺润燥；牛蒡子疏散风热、解毒利咽；薄荷清利头目、利咽，均无明目止痛之专长"},{"q":"属于鹿茸临床主治病证的是","o":["胎动不安，五更泄泻","冲任虚寒，崩漏带下","肠燥便秘，崩漏带下","虚喘气促，骨蒸劳嗽","症瘕积聚，产后少乳"],"a":1,"e":"鹿茸甘咸温，壮肾阳、益精血、强筋骨、调冲任、托疮毒，主治肾阳不足、冲任虚寒之崩漏带下及阳痿早泄。胎动不安、五更泄泻非其主；肠燥便秘属滋阴药所宜；虚喘骨蒸为阴虚；癥瘕积聚、产后少乳非鹿茸所主"},{"q":"入汤剂需先煎的药物是","o":["薄荷、豆蔻","蒲黄、海金沙","人参、阿胶","磁石、牡蛎","龙骨、钩藤"],"a":3,"e":"磁石、牡蛎为矿物、贝壳类，质坚而有效成分难溶，入汤剂须先煎久煎。薄荷、豆蔻芳香含挥发油宜后下；蒲黄、海金沙细小宜包煎；人参宜另煎，阿胶宜烊化；龙骨虽先煎，钩藤则应后下，配对不当。先煎使矿物贝壳有效成分充分析出，余药后入以免久煎失效"},{"q":"续断具有的功效是","o":["补肝肾、止咳喘","补肾阳、消水肿","补肾阳、益气血","补肝肾、续折伤","祛风湿、止泻痢"],"a":3,"e":"续断苦辛微温，补肝肾、强筋骨、续折伤、止崩漏、安胎，主治肝肾不足之腰膝酸软、跌打损伤、骨折及胎动不安。补肝肾、止咳喘非其功；补肾阳、消水肿为仙灵脾、补骨脂；补肾阳、益气血为肉苁蓉；祛风湿、止泻痢属其他药类"},{"q":"既能祛风湿，止痛，又能解表的药物是","o":["威灵仙","木瓜","五加皮","桑枝","独活"],"a":4,"e":"独活辛苦微温，祛风除湿、止痛、解表，善治下半身风湿痹痛，兼治风寒表证。威灵仙祛风湿、通经络、消骨鲠；木瓜舒筋活络、化湿和胃；五加皮祛风湿、补肝肾、强筋骨；桑枝祛风湿、利关节，均无解表之功"},{"q":"既能治疗烦躁不安，心悸失眠，又能治疗瘰疬痰核，瘿瘤的中药是","o":["天麻","钩藤","牡蛎","白僵蚕","羚羊角"],"a":2,"e":"牡蛎咸微寒，重镇安神、潜阳补阴、软坚散结，既能镇心安神治烦躁失眠、心悸，又能软坚散结治瘰疬痰核、瘿瘤。天麻、钩藤息风止痉、平肝阳；白僵蚕祛风定惊、化痰散结但无安神；羚羊角平肝息风、清热解毒，均无安神与软坚兼备之效"},{"q":"党参的主治病证不包括","o":["脾气虚","肺气虚","心气虚","气血两虚","气津两伤"],"a":2,"e":"党参甘平，补中益气、健脾益肺、养血生津，主治脾气虚、肺气虚、气血两虚及气津两伤。心气虚之心悸气短多用人参、黄芪、甘草，党参入脾肺经，不以补心气见长，故不列为主治病证。党参甘平补脾肺，益气生津，性平和而不似人参峻补"},{"q":"川楝子的入药部位是","o":["种子","种仁","果实","孢子","果穗"],"a":2,"e":"川楝子为楝科植物川楝的干燥成熟果实，入药部位即果实。种子、种仁多指桃仁、杏仁等；孢子为海金沙；果穗为夏枯草、桑椹之类，均非川楝子的药用部分。川楝子以成熟果实入药，内含川楝素，有一定毒性"},{"q":"善治寒疝，睾丸偏坠，少腹冷痛，痛经的药物是","o":["丁香","胡椒","花椒","小茴香","高良姜"],"a":3,"e":"小茴香辛温，散寒止痛、理气和胃，主入肝经，善治寒疝腹痛、睾丸偏坠、少腹冷痛及痛经。丁香温中降逆、温肾助阳；胡椒温中散寒、下气消痰；花椒温中止痛、杀虫止痒；高良姜温胃散寒止痛，均不入肝经以治寒疝"},{"q":"具有消积化滞作用的药物是","o":["陈皮","青皮","薤白","大腹皮","川楝子"],"a":1,"e":"青皮苦辛温，疏肝破气、消积化滞，主治肝郁气滞之胁痛、疝气及食积腹痛、癥瘕积聚。陈皮理气健脾、燥湿化痰而力较缓和；薤白通阳散结、行气导滞；大腹皮下气宽中、行水消肿；川楝子行气止痛、疏肝泄热，均无消积化滞之专长"},{"q":"治疗肺热咳嗽不用","o":["石膏","寒水石","知母","芦根","天花粉"],"a":1,"e":"寒水石辛咸寒，清热泻火，主清胃热、利小便，善治温热病高热烦渴，不入肺经，故肺热咳嗽不用。石膏清肺胃实热；知母清热泻火、滋阴润燥；芦根清热生津、清肺热；天花粉清热生津、清肺润燥，均可治肺热咳嗽"},{"q":"苍术尤其善治的痹证证型是","o":["热痹","寒痹","着痹","行痹","顽痹"],"a":2,"e":"苍术辛苦温，燥湿健脾、祛风散寒，湿邪偏重之着痹见关节重着酸痛者最宜。热痹宜秦艽、忍冬藤；寒痹宜附子、川乌；行痹宜防风、羌活；顽痹病程日久、痰瘀阻络，非苍术所主。苍术燥湿之力强，湿邪偏盛之着痹用之最合病机"},{"q":"既能温经止血、散寒调经，外用又能祛湿止痒的是","o":["炮姜","生姜","艾叶","茜草","侧柏叶"],"a":2,"e":"艾叶辛苦温，温经止血、散寒调经，外用祛湿止痒，主治虚寒出血、月经不调、痛经及湿疹瘙痒。炮姜温经止血、温中止痛但无外用止痒；生姜解表散寒、温中止呕；茜草凉血止血、活血；侧柏叶凉血止血、化痰止咳，均不具温经止血兼外用止痒"},{"q":"既可用于治疗血瘀证，又可治疗出血证的药是","o":["姜黄","五灵脂","川芎","红花","延胡索"],"a":1,"e":"五灵脂苦咸温，活血止痛、化瘀止血，主治瘀血阻滞之痛经、跌打伤痛及瘀血出血，为活血止血要药。姜黄活血行气、通经止痛；川芎活血行气、祛风止痛；红花活血通经、散瘀止痛；延胡索活血行气止痛，均无止血之功"},{"q":"下列除哪味药物外，均是妊娠禁用药物","o":["牵牛","桃仁","巴豆","莪术","水蛭"],"a":1,"e":"桃仁苦甘平，活血祛瘀、润肠通便、止咳平喘，属妊娠慎用而非禁用。牵牛子、巴豆、莪术、水蛭毒性较大或破血逐瘀力峻，均属妊娠禁用之品，不可与慎用混同。妊娠禁用药多毒性剧烈或破血力峻，桃仁仅属慎用，用量宜控"},{"q":"补益药其煎煮方法宜选用的是","o":["武火久煎","武火急煎","文火慢煎","武火慢煎","文火略煎"],"a":2,"e":"补益药多质滋腻、成分析出较慢，宜文火慢煎久煎，使有效成分充分溶出。武火久煎、武火急煎、武火慢煎火候过猛，易致药液泛溢或成分破坏；文火略煎则时间不足，均非补益药所宜。补益药文火慢煎则汤液浓稠，有效成分充分析出而药力足"},{"q":"薄荷的功效不包括","o":["清热凉血","疏肝行气","利咽透疹","疏散风热","清利头目"],"a":0,"e":"薄荷辛凉，疏散风热、清利头目、利咽透疹、疏肝行气，并无清热凉血作用。清热凉血属生地黄、玄参、牡丹皮之类；疏肝行气、利咽透疹、疏散风热、清利头目均为薄荷所有之功效。薄荷辛凉轻散，入肺肝经，无一味入血分而清热凉血"},{"q":"尤宜治各种虚汗兼有口渴者的药是","o":["莲子","浮小麦","麻黄根","石榴皮","糯稻根须"],"a":4,"e":"糯稻根须甘平，益胃生津、止汗，善治各种虚汗兼有口渴者。浮小麦甘凉，固表止汗、益气除热，无生津止渴；麻黄根甘平，固表止汗而功专止汗；莲子补脾止泻、养心安神；石榴皮涩肠止泻、止血，均不具生津止渴之功"},{"q":"紫苏子的功效是","o":["润肺下气，止咳平喘","清肺止咳，降逆止呕","止咳平喘，解痉止痛","润肺下气止咳，杀虫灭虱","降气化痰，止咳平喘，润肠通便"],"a":4,"e":"紫苏子辛温，降气化痰、止咳平喘、润肠通便，主治痰壅气逆之咳喘及肠燥便秘。润肺下气、止咳平喘为苦杏仁、紫菀；清肺止咳、降逆止呕为枇杷叶；止咳平喘、解痉止痛为洋金花；润肺下气止咳、杀虫灭虱为百部"},{"q":"可治多种饮食积滞之证，尤善消化油腻，为治肉食积滞的要药是","o":["山楂","神曲","麦芽","莱菔子","鸡内金"],"a":0,"e":"山楂酸甘微温，消食化积、行气散瘀，善消油腻肉食之积，为治肉食积滞要药。神曲消食和胃，善消金石药积；麦芽善消米面淀粉之积；莱菔子消食除胀、降气化痰；鸡内金消食力强，通治诸积，然消肉食首推山楂"},{"q":"既归胃经，又归心经的药物是","o":["石斛","麦冬","桑椹","楮实子","北沙参"],"a":1,"e":"麦冬甘微苦微寒，归心、肺、胃经，养阴润肺、益胃生津、清心除烦，兼归胃与心经。石斛归胃、肾经；桑椹归心、肝、肾经；楮实子归肝、肾经；北沙参归肺、胃经，均不同时归胃经与心经。麦冬养阴生津、清心除烦，心胃阴虚之证最为常用"},{"q":"功能凉血止血，善治血淋、尿血的药物是","o":["大蓟","小蓟","茜草","槐花","白及"],"a":1,"e":"小蓟甘苦凉，凉血止血、散瘀解毒消痈，善治血热妄行之血淋、尿血。大蓟凉血止血、散瘀消痈，主治吐血、咯血及疮痈；茜草凉血止血、活血化瘀；槐花凉血止血、清肝泻火，善治痔血；白及收敛止血、消肿生肌，均非血淋尿血首选"},{"q":"具有解毒散结功效的药物是","o":["玄参","牡丹皮","赤芍","石膏","生地黄"],"a":0,"e":"玄参甘苦咸寒，清热凉血、滋阴降火、解毒散结，主治热毒炽盛之瘰疬、痈肿疮毒。牡丹皮清热凉血、活血化瘀；赤芍清热凉血、散瘀止痛；石膏清热泻火；生地黄清热凉血、养阴生津，均无解毒散结之功"},{"q":"从病证相宜角度，艾叶的最宜主治证是","o":["带下","阴虚咯血","血热出血","肺寒咳喘","下焦虚寒之月经不调，痛经"],"a":4,"e":"艾叶辛苦温，温经止血、散寒调经，主入下焦，散寒温经止痛，最宜下焦虚寒之月经不调、痛经、宫寒不孕。带下多属湿热或脾虚；阴虚咯血、血热出血皆属热证，艾叶辛温助火当忌；肺寒咳喘非其主治，故唯下焦虚寒经痛最宜"},{"q":"不宜与藜芦配伍的药物是","o":["黄连","黄芩","黄柏","龙胆草","苦参"],"a":4,"e":"苦参反藜芦，属十八反，同用增毒。黄连、黄芩、黄柏、龙胆草虽同为清热燥湿药，均不与藜芦相反，唯苦参列于十八反之列，配伍当避。十八反歌诀明言诸参辛芍叛藜芦，苦参即在其中。余药清热燥湿而不犯藜芦之禁"},{"q":"腹部、肛门疾病手术前，或X线腹部摄片，借泻下导滞，清洁肠道，常选用的药物是","o":["番泻叶","牵牛子","巴豆","火麻仁","芒硝"],"a":0,"e":"番泻叶甘苦寒，泻热行滞、通便，小剂量可缓泻，常用于腹部手术前或X线腹部摄片前清洁肠道。牵牛子泻水通便、杀虫；巴豆辛热峻下而毒性大；火麻仁润肠通便而力缓；芒硝泻下软坚、清热，均非肠道准备首选"},{"q":"治疗出血证兼见阴虚、血虚者，宜选用","o":["艾叶","阿胶","三七","茜草","白及"],"a":1,"e":"阿胶甘平，补血止血、滋阴润肺，主治血虚萎黄、多种出血及阴虚证，尤宜出血兼见阴虚、血虚者。艾叶温经止血，宜虚寒出血；三七化瘀止血；茜草凉血止血、活血；白及收敛止血，均无补血滋阴之功"},{"q":"苍术的性味是","o":["辛、甘，温","苦、甘，温","辛、甘，寒","辛、苦，寒","辛、苦，温"],"a":4,"e":"苍术辛苦温，燥湿健脾、祛风散寒、明目，为燥湿健脾要药。辛甘温为防风、白术之类；苦甘温为白术；辛甘寒、辛苦寒均非苍术性味，其辛苦温之性正与燥湿健脾之用相符。苍术辛苦温燥，湿阻中焦之脘腹胀满、食少乏力用之最宜"},{"q":"外祛风湿，内燥脾湿的药物是","o":["秦艽","白术","独活","木通","苍术"],"a":4,"e":"苍术辛苦温，外能祛风散寒除湿以治痹证，内能燥湿健脾以运化水湿，故有外祛风湿、内燥脾湿之谓。秦艽祛风湿、清虚热；白术健脾燥湿、利水止汗而无祛风湿；独活祛风湿止痛；木通利水通淋、清心火，均无内外兼顾之能"},{"q":"对于下部出血病证，应用相应的止血药同时，为增强疗效，常配伍","o":["行气药","活血药","温经药","升阳药","降气药"],"a":3,"e":"下部出血如便血、尿血、崩漏，常于止血药中配升阳药，如柴胡、升麻、荆芥炭，升提中气、固摄血脉以助止血。行气药、活血药、温经药、降气药或动血、或降下，均非下部出血增强疗效之配伍。升阳药升提中气，使血归经而不下泄，下部出血得此而涩止"},{"q":"患者内服50g中药后，症见心悸、恶心、呕吐、腹泻、头晕等强心苷样中毒反应，可能因服用过量的药物是","o":["白薇","槟榔","胡黄连","青蒿","远志"],"a":0,"e":"白薇含强心苷类成分，过量服用可致心悸、恶心、呕吐、腹泻、头晕等强心苷样中毒反应。槟榔含槟榔碱，毒性表现为流涎、震颤；胡黄连、青蒿无明显强心苷样毒性；远志含皂苷，刺激胃黏膜、祛痰，均不致此反应"},{"q":"擅治风热外感，咽喉肿痛的药物是","o":["薄荷","蔓荆子","柴胡","淡豆豉","葛根"],"a":0,"e":"薄荷辛凉，疏散风热、清利头目、利咽透疹、疏肝行气，善治风热外感、咽喉肿痛。蔓荆子疏散风热、清利头目，重在头面痛；柴胡解表退热、疏肝升阳；淡豆豉解表除烦；葛根解肌退热、生津，均无利咽止痛之专长"},{"q":"长于祛痰，又能降气，为肺家要药，咳喘痰多，无论寒热皆可用的药物是","o":["柿蒂","百部","白前","北沙参","苦杏仁"],"a":2,"e":"白前辛苦微温，降气化痰、止咳，性温而不燥，善治咳喘痰多，无论寒热皆可配伍，为肺家要药。柿蒂降气止呃；百部润肺止咳；北沙参养阴清肺；苦杏仁降气止咳平喘、润肠，均无降气化痰、寒热皆宜之特点"},{"q":"下列哪一项不属于血竭的功效","o":["化痰","止血","生肌","活血","敛疮"],"a":0,"e":"血竭甘咸平，活血定痛、化瘀止血、敛疮生肌，主治跌打损伤、瘀血经闭、出血及疮疡不敛。止血、生肌、活血、敛疮均为其所有功效，化痰非血竭所具，故为除外之项。血竭为树脂类药材，专入血分，无化痰宣肺之能"},{"q":"木香的功效是","o":["行气止痛，祛寒","行气止痛，醒脾","行气止痛，利水","行气止痛，调中","行气止痛，解毒"],"a":3,"e":"木香辛苦温，行气止痛、健脾消食，善调中焦气机，主治脾胃气滞之脘腹胀痛、食积不消。行气止痛、祛寒为乌药、沉香；醒脾化湿为砂仁、白豆蔻；利水消肿属茯苓、泽泻；清热解毒更非木香所有，故功在行气止痛、调中"},{"q":"在“十八反”中，下列药物除哪种外均与甘草相反","o":["大戟","海藻","党参","芫花","甘遂"],"a":2,"e":"十八反中甘草反大戟、海藻、芫花、甘遂，四者均与甘草相反。党参不与甘草相反，且二者常相配以益气和中，故党参为应除外之药。甘草反甘遂、大戟、海藻、芫花，党参与甘草同用无相反之虞。十八反所限在于甘草与大戟、海藻、芫花、甘遂四味"},{"q":"不宜与郁金同用的药物是","o":["白芍","丁香","甘草","半夏","细辛"],"a":1,"e":"丁香与郁金相畏，属十九畏“丁香莫与郁金见”，同用降低药效或增不良反应。白芍、甘草、半夏、细辛与郁金无此配伍禁忌；其中半夏反乌头、细辛反藜芦、甘草反甘遂，均与郁金无关。丁香辛温，郁金辛寒，一温一寒且相畏，同用则两相牵制"},{"q":"功专利水渗湿，力胜茯苓，性平而无补益之功的利水消肿药是","o":["薏苡仁","泽泻","香加皮","滑石","猪苓"],"a":4,"e":"猪苓甘淡平，利水渗湿，作用较茯苓为强，且性平无补益之功，专治水肿、小便不利。薏苡仁利水渗湿兼健脾；泽泻利水渗湿、泄热；香加皮祛风湿、强筋骨、利水；滑石利尿通淋、清热解暑，均非力胜茯苓而无补益之利水消肿药"},{"q":"治疗五更泄泻常选用的药物是","o":["沙苑子","补骨脂","肉苁蓉","韭菜子","核桃仁"],"a":1,"e":"补骨脂辛苦大温，补肾助阳、纳气平喘、温脾止泻，善治肾阳不足、命门火衰之五更泄泻，如四神丸。沙苑子补肾固精、养肝明目；肉苁蓉补肾阳、益精血、润肠；韭菜子温阳补虚、固精；核桃仁补肾、温肺、润肠，均无温脾止泻之功"},{"q":"善治头面部风痰，口眼㖞斜的药物是","o":["半夏","芥子","白前","白附子","旋覆花"],"a":3,"e":"白附子辛甘温有毒，祛风痰、定惊搐、解毒散结、止痛，善治风痰壅盛之口眼㖞斜、惊风癫痫及头面诸疾。半夏燥湿化痰、降逆止呕；芥子温肺化痰、利气散结；白前降气化痰；旋覆花消痰降气、止呕，均无祛头面风痰之专长"},{"q":"火麻仁入药，宜","o":["打碎入煎","后下","包煎","另煎","久煎"],"a":0,"e":"火麻仁为种仁，外有坚硬种皮，入汤剂宜打碎入煎，使油脂及有效成分充分煎出。后下用于芳香药；包煎用于细小种子及绒毛药；另煎用于贵重药；久煎非火麻仁特殊要求，打碎方能增效。打碎后种皮破裂，油脂易于煎出，润下之力方能充分"},{"q":"既能润肠通便，又能下气利水的药物是","o":["火麻仁","郁李仁","松子仁","柏子仁","苦杏仁"],"a":1,"e":"郁李仁辛苦甘平，润肠通便、下气利水，主治肠燥便秘及水肿、脚气。火麻仁润肠通便、滋养补虚但无利水；松子仁润肠润肺；柏子仁养心安神、润肠；苦杏仁降气止咳平喘、润肠，均无下气利水之功。郁李仁兼入大小肠经，下气利水，水肿脚气亦可应用"},{"q":"解乌头类药物毒性，宜选用","o":["白蔹","紫苏","半夏","蜂蜜","白扁豆"],"a":3,"e":"蜂蜜甘平，解毒、润燥、止痛，能解乌头类药物毒性，乌头中毒可用蜂蜜解之。白蔹、半夏与乌头相反，同用反增其毒；紫苏解鱼蟹毒；白扁豆解草木毒、和胃化湿，均无解乌头毒之专长。蜂蜜甘缓，既解乌头之毒，又可缓其燥烈之性"},{"q":"与乌头相反的药物应除外","o":["玄参","白及","贝母","瓜蒌","半夏"],"a":0,"e":"十八反中乌头反半夏、瓜蒌、贝母、白及、白蔹。玄参与乌头无相反关系，其所反者为藜芦，故玄参为与乌头相反药物中应除外之药。乌头所反者半夏、瓜蒌、贝母、白及、白蔹，玄参不在其列。玄参所反者为藜芦，与乌头并无相反关系"},{"q":"下列金钱草的主治病证中错误的是","o":["湿热黄疸","石淋，热淋","经闭，癥瘕","痈肿疔疮","毒蛇咬伤"],"a":2,"e":"金钱草甘咸微寒，利水通淋、除湿退黄、解毒消肿，主治石淋、热淋、湿热黄疸、痈肿疔疮及毒蛇咬伤。经闭、癥瘕属血瘀证，须活血化瘀药主治，金钱草无活血通经、破瘀消癥之功，故不属其主治。金钱草善利肝胆湿热而排石，并无活血通经之效"},{"q":"一种药物能够削弱另一种药物的功效的配伍属于","o":["相反","相畏","相杀","相恶","相侮"],"a":3,"e":"相恶指一种药物能破坏或削弱另一种药物的功效，如人参恶莱菔子。相反指两药合用增强毒性；相畏、相杀指减毒配伍；相侮非七情配伍内容，故削弱功效属于相恶。相恶与相反不同，前者减效而不增毒，后者增毒而当禁"},{"q":"按照归经理论，下列哪味药不归心经","o":["栀子","藿香","牛黄","龙眼肉","丹参"],"a":1,"e":"藿香辛微温，归脾、胃、肺经，化湿、止呕、解暑，并不归心经。栀子泻火除烦，归心、肺、三焦经；牛黄清心解毒、开窍；龙眼肉补心脾、养血安神；丹参活血祛瘀、清心除烦，均归心经。藿香归脾胃肺经，化湿和中止呕，为暑湿呕吐之要药"},{"q":"陈皮配半夏的作用是","o":["理气调中","降逆止呕","燥湿化痰","消痞散结","清热化痰"],"a":2,"e":"陈皮辛苦温，理气健脾、燥湿化痰；半夏辛温，燥湿化痰、降逆止呕，二药相配共奏燥湿化痰、理气和中之功，为治湿痰咳嗽的基础配伍。理气调中、降逆止呕、消痞散结各侧重其一，清热化痰属热痰所宜，均非二药相配之主效"},{"q":"能上清心火，下利小便，善导邪热从小便而出的药物是","o":["石膏","知母","芦根","淡竹叶","决明子"],"a":3,"e":"淡竹叶甘淡寒，清热除烦、利尿，上能清心火以除烦，下能利小便而导邪热下行。石膏清肺胃实热；知母清热滋阴；芦根清热生津；决明子清肝明目、润肠，均无清心火与利小便之双向作用。淡竹叶清心火而利小肠，使热邪随小便而去，为导赤常用品"},{"q":"属于“疗寒以热药”治疗原则的是","o":["用附子、干姜治疗腹中冷痛、脉沉无力","用茯苓、猪苓治疗水肿、小便不利","用黄芩、连翘治疗发热咽痛、舌红尿赤","用五味子、莲子治疗盗汗遗精","用麻黄、薄荷治疗外感表证"],"a":0,"e":"“疗寒以热药”属正治，即寒证用热药。附子、干姜辛热，温中散寒、回阳，用治腹中冷痛、脉沉无力之里寒证，正合此则。茯苓、猪苓利水渗湿；黄芩、连翘清热属“疗热以寒药”；五味子、莲子收敛固涩；麻黄、薄荷解表，均非疗寒以热药"},{"q":"鹿茸的临床常用剂量为","o":["0、05～0、1g","0、2～0、5g","1～2g","5～9g","10～30g"],"a":2,"e":"鹿茸甘咸温，为贵重药材，多入丸散或研末冲服，常用量1～2g。0.05～0.1g、0.2～0.5g剂量过小；5～9g、10～30g剂量过大，鹿茸温补峻烈，过量易致躁动、出血，均非规定剂量"},{"q":"下列除哪项外，均为猪苓的临床应用","o":["水肿，小便不利","泄泻","淋证","带下","心悸失眠"],"a":4,"e":"猪苓甘淡平，利水渗湿，主治水肿、小便不利、泄泻、淋证及带下等水湿内停之证。心悸失眠多属心脾两虚、阴虚火旺或痰饮凌心，非猪苓分利水湿之所主，故不列其临床应用。猪苓专于利水渗湿，无养心安神之功，心悸失眠非其主治"},{"q":"药物的副作用是指","o":["配伍不当出现的反应","药不对证出现的不适反应","达不到常规用量不能控制病情","超过常规用量时出现的不良反应","在常规剂量时出现的与疗效无关的不适反应"],"a":4,"e":"副作用指药物在常规剂量下出现的与治疗目的无关的不适反应，系药物固有作用所致。配伍不当、药不对证、超过常规用量所致不良反应分别属配伍失误、辨证不当或中毒，均非副作用之定义。副作用系药物固有作用，与过量、配伍失宜所致反应不同"},{"q":"治疗肺热咳嗽，燥热咳嗽，宜首选的药物是","o":["桑叶","升麻","牛蒡子","蝉蜕","柴胡"],"a":0,"e":"桑叶甘苦寒，疏散风热、清肺润燥、清肝明目，善治风热或肺燥咳嗽。升麻解表升阳、清热解毒；牛蒡子疏散风热、解毒利咽；蝉蜕疏散风热、利咽开音；柴胡解表退热、疏肝，均无清肺润燥止咳之效。桑叶质轻清散，清肺润燥而止咳，肝阳目眩亦其所宜"},{"q":"下列息风止痉药中，均有毒的药组是","o":["蜈蚣、全蝎","全蝎、僵蚕","天麻、钩藤","蜈蚣、僵蚕","羚羊角、牛黄"],"a":0,"e":"蜈蚣、全蝎均为虫类药，辛温有毒，功能息风止痉、通络止痛、攻毒散结。僵蚕无毒性记载；天麻、钩藤甘平或甘凉，平肝息风而无毒；羚羊角、牛黄咸寒，清热解毒、息风，亦无毒，故唯蜈蚣、全蝎二者皆有毒"},{"q":"白果治疗咳喘时，宜配伍何药达到既开肺散邪而不耗肺气，又敛肺平喘而无留邪之弊","o":["百部","杏仁","麻黄","紫菀","款冬花"],"a":2,"e":"白果甘苦涩平，敛肺定喘、收涩止带；麻黄辛温，宣肺散邪、平喘。二药相配，麻黄开肺散邪而不耗气，白果敛肺平喘而不留邪，宣降相因，共治喘咳。百部、杏仁、紫菀、款冬花均偏润降，无宣散开肺之能，不能成此配伍之妙"},{"q":"车前子性降滑利，慎用者除肾虚精滑者外，还有","o":["肺热咳痰者","老年体弱者","怀孕妇女","阴虚火旺者","脾胃虚寒者"],"a":2,"e":"车前子甘寒，性降滑利，能利水通淋、渗湿止泻，肾虚精滑者服之更致滑泄，孕妇服之易动胎气，故二者皆慎用。脾胃虚寒虽不宜寒凉，然非滑利下趋为害；肺热咳痰、老年体弱、阴虚火旺并非其慎用所指"},{"q":"用治正气不足滑脱证者，常用龙骨配","o":["磁石","牡蛎","珍珠","琥珀","珍珠母"],"a":1,"e":"龙骨甘涩平，镇惊安神、平肝潜阳、收敛固涩；牡蛎咸微寒，潜阳补阴、软坚散结、收敛固涩，二者均具收敛固涩之功，相须为用治正气不足之滑脱证，如自汗、盗汗、遗精、带下。磁石、珍珠、琥珀、珍珠母重在镇惊安神或明目，无收敛固涩之效"},{"q":"大青叶与青黛的共同功效是","o":["清热解毒，活血消斑","清热解毒，凉血消斑","清热解毒，泻火定惊","清热解毒，凉血消肿","清热解毒，疏散风热"],"a":1,"e":"大青叶苦寒，清热解毒、凉血消斑；青黛咸寒，清热解毒、凉血消斑、定惊，二者源于同类植物，均具清热解毒、凉血消斑之功。活血消斑非其效；泻火定惊仅青黛有；凉血消肿、疏散风热均非二者共有"},{"q":"黄芩与知母的共同主治是","o":["痈肿疮毒","内热消渴","骨蒸潮热","肠燥便秘","肺热咳嗽"],"a":4,"e":"黄芩苦寒，清热燥湿、泻火解毒，尤清上焦肺火；知母苦甘寒，清热泻火、滋阴润燥，亦清肺热，二者均治肺热咳嗽。痈肿疮毒、内热消渴非二者共有；骨蒸潮热、肠燥便秘为知母所主，故共性为肺热咳嗽"},{"q":"确定归经学说的依据是","o":["阴阳学说","五行学说","药性理论","脏腑经络理论","所治病证"],"a":3,"e":"归经以脏腑经络理论为基础，药物对某脏腑经络病变有选择性治疗作用，则归入该经。阴阳、五行学说属哲学思想，为药性理论之根源；药性理论概括四气五味等；所治病证是判断归经的具体依据，学说确立仍本于脏腑经络理论"},{"q":"长于疏肝破气的药物是","o":["刀豆","乌药","青皮","川楝子","荔枝核"],"a":2,"e":"青皮苦辛温，疏肝破气、消积化滞，力峻善破肝经气滞，主治胁肋胀痛、疝气、乳癖。刀豆温中降逆、补肾助阳；乌药行气止痛、温肾散寒；川楝子行气止痛、疏肝泄热而力较缓和；荔枝核行气散结、祛寒止痛，均无疏肝破气之峻力"},{"q":"治风痰癫狂，常以白矾配伍","o":["郁金","磁石","朱砂","远志","皂荚"],"a":0,"e":"白矾酸涩寒，内服化痰开窍、止泻；郁金辛苦寒，行气解郁、凉血清心、利胆，二药相配化痰开窍、解郁清心，以治风痰癫狂。磁石、朱砂重镇安神；远志祛痰开窍、安神；皂荚祛痰开窍、散结，均无与白矾相须化痰开窍之配伍"},{"q":"附子与干姜共同的功效是","o":["温中散寒，回阳","补火助阳，化饮","散寒止痛，温肺","温通经脉，止痛","温通经脉，温肺"],"a":0,"e":"附子辛甘大热，补火助阳、散寒止痛、回阳救逆；干姜辛热，温中散寒、回阳通脉、温肺化饮，二者均温中散寒、回阳，常相须用于脾胃寒证及亡阳证。补火助阳仅附子有；化饮、温肺仅干姜具；温通经脉为肉桂之功，非二者共有"},{"q":"化湿药的主治证是","o":["湿疹湿疮","风湿痹证","湿阻中焦证","泄泻痢疾","水湿内停病证"],"a":2,"e":"化湿药多辛香温燥，归脾胃经，功能化湿醒脾，主治湿阻中焦之脘腹胀满、食欲不振、恶心呕吐、大便溏泄。湿疹湿疮多外用燥湿止痒；风湿痹证属祛风湿药主治；泄泻痢疾、水湿内停各有专药，均非化湿药主治之本"},{"q":"治亡阳证，宜选的药组是","o":["鹿茸、肉桂","肉桂、人参","肉桂、干姜","附子、肉桂","附子、干姜"],"a":4,"e":"亡阳证见大汗淋漓、四肢厥冷、脉微欲绝，附子大辛大热，回阳救逆、补火助阳；干姜辛热，温中散寒、回阳通脉，二药相须，回阳之力大增，为治亡阳之要组。鹿茸、肉桂补肾助阳；人参补气；肉桂、干姜虽温里而救逆不及附子，故首选附子、干姜"},{"q":"苦味药的作用是","o":["能和能缓","能燥能泄","能收能涩","能下能软","能行能散"],"a":1,"e":"苦味药能泄能燥，泄含清泄、降泄、通泄，燥即燥湿，如黄连清热燥湿、杏仁降肺气、大黄通便。能和能缓为甘味；能收能涩为酸味；能下能软为咸味；能行能散为辛味，各主一类。五味各有所能，临床须据病证之虚实寒热而取舍"},{"q":"既能益肾固精，又能养肝明目的药物是","o":["菊花","苍术","覆盆子","桑螵蛸","金樱子"],"a":2,"e":"覆盆子甘酸微温，益肾固精缩尿、养肝明目，主治肾虚遗精、滑精、遗尿、尿频及肝肾不足之目暗不明。菊花疏散风热、平肝明目；苍术燥湿健脾、明目；桑螵蛸益肾固精但无明目；金樱子固精缩尿、涩肠止泻，均无固精兼明目之效"},{"q":"下列哪项不是桑寄生的功效","o":["祛风湿","补肝肾","强筋骨","安胎","益气"],"a":4,"e":"桑寄生苦甘平，祛风湿、补肝肾、强筋骨、安胎、利水，主治风湿痹痛、肝肾不足之腰膝酸软及胎动不安。益气为补气药之功，桑寄生并无补气作用，故益气非其所有之功效，为除外之项。桑寄生补肝肾、强筋骨而安胎，虽补而不燥，然无补气之力"},{"q":"某医师治疗湿热下注之妇人带下，擅长使用泽泻，其主要功效是","o":["利水渗湿，泄热","利水渗湿，健脾宁心","利水渗湿，健脾止泻","利尿消肿，除痹","利水消肿，清热解暑"],"a":0,"e":"泽泻甘淡寒，利水渗湿、泄热，主治水肿、小便不利、泄泻及下焦湿热，性寒能泄肾与膀胱之热，故可治湿热下注之带下。利水渗湿、健脾宁心为茯苓；健脾止泻为薏苡仁；利尿消肿、除痹为防己、薏苡仁；利水消肿、清热解暑为滑石，均非泽泻之效"},{"q":"蒲公英与漏芦均善治的病证是","o":["乳痈","肠痈","肺痈","湿痹","烫伤"],"a":0,"e":"蒲公英苦甘寒，清热解毒、消痈散结，善治乳痈；漏芦苦寒，清热解毒、消痈散结、通经下乳，亦治乳痈，二者均善治乳痈。肠痈多属大黄、牡丹皮；肺痈属鱼腥草、苇茎；湿痹属祛风湿药；烫伤属地榆、紫草，均非二者所共治"},{"q":"既能镇惊安神，又活血散瘀的药是","o":["朱砂","琥珀","桃仁","川芎","龙骨"],"a":1,"e":"琥珀甘平，镇惊安神、活血散瘀、利尿通淋，主治惊悸失眠、瘀血经闭、跌打损伤及淋证。朱砂镇心安神、清热解毒但无活血；桃仁、川芎活血而无安神；龙骨镇惊安神、收敛固涩而无活血散瘀，唯琥珀安神与活血兼备"},{"q":"既能息肝风，又平肝阳，为止眩晕，定头痛要药的是","o":["钩藤","天麻","蜈蚣","全蝎","僵蚕"],"a":1,"e":"天麻甘平，息风止痉、平抑肝阳、祛风通络，善治肝阳上亢或肝风内动之头痛眩晕，为定眩要药。钩藤息风定惊、清热平肝而力较缓和；蜈蚣、全蝎、僵蚕重在息风止痉、通络，无平肝阳之功，故止眩晕、定头痛首推天麻"},{"q":"性味甘寒，归肺、大肠经的药物是","o":["桔梗","白前","前胡","旋覆花","胖大海"],"a":4,"e":"胖大海甘寒，归肺、大肠经，清热润肺、利咽开音、润肠通便，主治肺热咽痛、声音嘶哑及肠燥便秘。桔梗苦辛平，宣肺利咽；白前辛苦微温，降气化痰；前胡苦辛微寒，降气化痰、疏散风热；旋覆花苦辛咸温，消痰降气，均非甘寒归肺大肠之品"},{"q":"能清热凉血，利尿通淋的药物是","o":["生地黄","车前子","白薇","地骨皮","紫草"],"a":2,"e":"白薇苦咸寒，清热凉血、利尿通淋、解毒疗疮，善治温毒发斑、血热出血及热淋。生地黄清热凉血、养阴生津而不利尿；车前子利尿通淋而不凉血；地骨皮凉血退蒸、清肺；紫草凉血活血、解毒透疹，均无凉血与利尿通淋兼备之效"},{"q":"既能治疗风湿热痹，又能治疗骨蒸潮热的药物是","o":["五加皮","狗脊","防已","桑枝","秦艽"],"a":4,"e":"秦艽苦辛微寒，祛风湿、通经络、清虚热、利湿退黄，性平不燥，善治风湿热痹，又能退虚热治骨蒸潮热。五加皮祛风湿、补肝肾、强筋骨；狗脊祛风湿、补肝肾、强腰膝；防己祛风湿、止痛、利水；桑枝祛风湿、利关节，均无清虚热退蒸之功"},{"q":"能散寒止痛，理气和胃的药物是","o":["陈皮","生姜","木瓜","高良姜","小茴香"],"a":4,"e":"小茴香辛温，散寒止痛、理气和胃，主治寒疝腹痛、睾丸偏坠、少腹冷痛、痛经及胃寒气滞之脘腹胀痛。陈皮理气健脾、燥湿化痰而无散寒；生姜解表散寒、温中止呕；木瓜舒筋化湿；高良姜温胃止痛，均无理气和胃与散寒止痛兼备"},{"q":"具有安神，祛风通络作用的药物是","o":["磁石","灵芝","龙骨","首乌藤","远志"],"a":3,"e":"首乌藤甘平，养血安神、祛风通络，主治失眠多梦及风湿痹痛、肢体麻木。磁石镇惊安神、平肝潜阳；灵芝补气安神、止咳平喘；龙骨镇惊安神、收敛固涩；远志安神益智、祛痰开窍，均无祛风通络之功，唯首乌藤安神兼通络"},{"q":"既能平喘止咳，又能解痉、定痛的药物是","o":["胖大海","枇杷叶","马兜铃","紫苏子","洋金花"],"a":4,"e":"洋金花辛温有毒，平喘止咳、解痉定痛，主治哮喘咳嗽、脘腹冷痛及风湿痹痛，并可用于麻醉。胖大海清热润肺、利咽；枇杷叶清肺止咳、降逆止呕；马兜铃清肺化痰、止咳平喘；紫苏子降气化痰、止咳平喘，均无解痉定痛之效"},{"q":"在应用驱虫药时，为助肠寄生虫排出体外，常配伍","o":["乌梅","大黄","火麻仁","山楂","五味子"],"a":1,"e":"驱虫药多入胃肠杀虫，为助虫体排出体外，常配伍大黄等泻下药，使虫体随大便而下。乌梅酸涩，安蛔止痛；火麻仁润肠通便而力缓，不足以驱虫；山楂消食；五味子收敛固涩，均非助排虫之配伍。驱虫与泻下相配，虫体得以速下，避免滞留肠中更生变端"},{"q":"功效清热凉血活血，解毒透疹的药物是","o":["赤芍","紫草","生地黄","玄参","地骨皮"],"a":1,"e":"紫草甘咸寒，清热凉血、活血、解毒透疹，主治温毒发斑、血热出血及麻疹紫暗不透。赤芍清热凉血、散瘀止痛；生地黄清热凉血、养阴生津；玄参清热凉血、滋阴解毒；地骨皮凉血退蒸、清肺，均无解毒透疹之功"},{"q":"五倍子的入用部位是","o":["卵鞘","虫瘿","孢子","菌核","果实"],"a":1,"e":"五倍子为盐肤木等叶上蚜虫所形成的虫瘿，入药部位即虫瘿，富含鞣质，功能敛肺降火、涩肠止泻、敛汗止血。卵鞘为桑螵蛸；孢子为海金沙；菌核为茯苓、猪苓；果实为五味子之类，均非五倍子药用部分"},{"q":"下列哪一项不属于土鳖虫的应用范围","o":["跌打损伤","血瘀经闭","癥瘕积聚","痈疽疮毒","产后瘀滞腹痛"],"a":3,"e":"土鳖虫咸寒，破血逐瘀、续筋接骨，主治跌打损伤、血瘀经闭、癥瘕积聚及产后瘀滞腹痛。其功专走血分，凡瘀血阻滞之证皆可应用。痈疽疮毒乃热毒壅聚肌肤，治当清热解毒、消肿散结，非破血药所宜。跌打损伤、产后瘀滞腹痛等取其祛瘀生新，癥瘕积聚取其消癥，均与痈疽疮毒的病机不同"},{"q":"不具有明目功效的药物是","o":["夏枯草","密蒙花","青葙子","决明子","鸭跖草"],"a":4,"e":"鸭跖草清热解毒、利水消肿，无明目之功，故为不具明目之品。夏枯草清肝火、散郁结而明目，青葙子清泄肝火以明目，决明子清热明目兼润肠，密蒙花清热养肝、退翳明目，四者均能明目。目疾用药多归肝经，夏枯草与决明子偏清肝火，密蒙花兼养肝，青葙子专清肝火，皆非鸭跖草所具备"},{"q":"能祛风解表，胜湿止痛的药组是","o":["白芷，紫苏叶","藁本，紫苏叶","防风，荆芥","麻黄，香薷","防风，羌活"],"a":4,"e":"防风祛风解表、胜湿止痛、止痉，羌活解表散寒、祛风胜湿、止痛，二者相须，共奏祛风解表、胜湿止痛之功。白芷虽祛风解表、燥湿止痛，紫苏叶偏于发汗解表、行气宽中，胜湿之力不足。荆芥、防风重在祛风解表，麻黄、香薷长于发汗利水，藁本虽胜湿止痛但多配伍他药，均不及防风、羌活组合切题"},{"q":"确定药物寒热、温凉的依据是","o":["神农氏尝百草的体会","《素问》：“寒者热之，热者寒之”","《本经》：“疗寒以热药，疗热以寒药”","药物作用于人体的反应","口尝的滋味"],"a":3,"e":"药物寒热温凉之性，是药物作用于人体后所产生反应的概括，即以机体寒热变化的客观效应为依据。神农尝百草只是用药经验的来源之一，《素问》与《本经》所云属治疗原则，并非确定药性的依据。口尝滋味只能确定五味，不能判定寒热。故四气取决于药物对人体的实际作用反应"},{"q":"桂枝不具有的功效是","o":["发汗解肌","温通经脉","平冲降气","平喘利尿","助阳化气"],"a":3,"e":"桂枝发汗解肌、温通经脉、助阳化气、平冲降气，无平喘利尿之功。麻黄方能宣肺平喘、利水消肿，桂枝虽能温阳化气以助行水，却不直接利尿，亦无平喘之效。发汗解肌、温通经脉、助阳化气、平冲降气皆桂枝本功，平喘利尿实为麻黄所主，二者常被互换设错"},{"q":"下列哪项不是蛇床子的功效","o":["燥湿","化痰","祛风","温肾壮阳","杀虫止痒"],"a":1,"e":"蛇床子燥湿祛风、杀虫止痒、温肾壮阳，主治阴痒带下、湿疹瘙痒及肾虚阳痿，无化痰作用。化痰多取半夏、天南星等燥湿化痰之品，与本药功用于肺无涉。燥湿、祛风、温肾壮阳、杀虫止痒四项均为蛇床子所具，化痰则需苏子、白芥子之属，非蛇床子所有"},{"q":"蕲蛇的主治病证不包括","o":["风湿痹痛","筋骨痿软","中风偏瘫","麻风疥癣","急慢惊风"],"a":1,"e":"蕲蛇祛风、通络、止痉，主治风湿痹痛、中风偏瘫、急慢惊风、破伤风及麻风疥癣。筋骨痿软多由肝肾不足、筋脉失养所致，当补肝肾、强筋骨，非蕲蛇搜风通络所宜。风湿痹痛、中风偏瘫、急慢惊风、麻风疥癣皆取其走窜搜风之力，筋骨痿软需杜仲、牛膝之属"},{"q":"白矾火煅后称为","o":["明矾","胆矾","绛矾","枯矾","绿矾"],"a":3,"e":"白矾火煅后失其结晶水，质疏松，称为枯矾，故名。明矾为白矾之俗称，并非煅制品。胆矾为硫酸铜类矿物，绛矾、绿矾亦另有所指，均与白矾煅制无关。白矾生用解毒杀虫、燥湿止痒，煅后酸涩收敛之性增强，更长于收湿敛疮、止血止泻，名称与炮制方法须对应"},{"q":"性寒通利，肾虚精滑无湿热者忌用的是","o":["泽泻","薏苡仁","香加皮","猪苓","茯苓"],"a":0,"e":"泽泻甘淡寒，利水渗湿、泄热，性寒通利且无补益之功，肾虚精滑而无湿热者服之更易耗伤肾气，故忌用。茯苓甘淡平，健脾宁心，寒热虚实水肿皆可配伍。薏苡仁微寒兼健脾，猪苓利水作用专一但性平，滑利伤正之性均不及泽泻。香加皮祛风湿、强筋骨，非单纯利水之品"},{"q":"湿热泻痢初起，腹痛里急后重，为清除湿热邪气，发挥通因通用作用，常在清热燥湿，行气导滞的黄连、木香中配伍","o":["白头翁","番泻叶","大黄","马齿苋","牵牛子"],"a":2,"e":"大黄苦寒，泻下攻积、清热泻火、凉血解毒、逐瘀通经，湿热泻痢初起用之属通因通用，借泻下清除肠中湿热积滞，邪去则痢止。黄连、木香清热燥湿、行气导滞，配大黄正合其法。白头翁、马齿苋清热解毒凉血，长于止痢而无通下之用；番泻叶、牵牛子虽能泻下，多不用于痢初湿热积滞之配伍"},{"q":"善治脏腑湿痰的药物是","o":["半夏","白前","白附子","天南星","旋覆花"],"a":0,"e":"半夏辛温有毒，燥湿化痰、降逆止呕、消痞散结，为治脏腑湿痰之要药，脾失健运、湿聚成痰者最宜。天南星燥湿化痰、祛风解痉，善治经络风痰及顽痰。白前降气化痰，旋覆花降气化痰、降逆止呕，白附子祛风痰、定惊搐，三者所主皆非脏腑湿痰。半夏兼能和胃降逆，痰湿中阻之呕恶亦甚相宜"},{"q":"麻黄根、黄芪的共同功效是","o":["止带","止汗","止遗","止血","止泻"],"a":1,"e":"麻黄根甘平，专入表分而固表止汗；黄芪甘微温，补气升阳、益卫固表，二者均能通过固护卫表以止汗，故为共同功效。止带、止遗多责之补肾固涩药，止血、止泻各属止血药与涩肠药范畴。麻黄根无补益之力，黄芪亦非收涩之品，二者止汗机理在于固表，与龙骨、牡蛎之敛汗不同"},{"q":"为血肉有情之品的是","o":["鹿茸、阿胶","骨碎补、狗脊","鸡血藤、牛膝","鸡内金、牛黄","肉苁蓉、桑螵蛸"],"a":0,"e":"鹿茸为鹿之幼角，阿胶为驴皮熬制，皆动物药，属血肉有情之品，能峻补精血、益髓壮阳。骨碎补、狗脊、鸡血藤、牛膝、肉苁蓉、桑螵蛸等多为植物或虫类药物，补益之力较缓。鸡内金、牛黄虽来自动物，功在消食、开窍，不以补虚见长。血肉有情之品多味厚质重，善治精血亏虚重症"},{"q":"菊花的功效不包括","o":["疏散风热","平抑肝阳","清肝明目","升举阳气","清热解毒"],"a":3,"e":"菊花疏散风热、平抑肝阳、清肝明目、清热解毒，无升举阳气之功。升举阳气为柴胡、升麻、黄芪之能，柴胡升举清阳、升麻升阳举陷，与菊花轻清上行、清泄肝火之性迥异。疏散风热、平抑肝阳、清肝明目、清热解毒皆为菊花本有功效，尤宜于风热目赤及肝阳上亢之目眩"},{"q":"能消食化积，止泻止痢，行气散瘀，降脂化浊的药物是","o":["黄连","山楂","木香","大黄","白头翁"],"a":1,"e":"山楂酸甘微温，消食化积、行气散瘀、化浊降脂，尤善消肉食油腻之积，并能止泻止痢，现代用于高脂血症。黄连、白头翁清热解毒燥湿以止痢，大黄泻下攻积，木香行气止痛，皆无消食化积、降脂化浊之全功。山楂兼入血分，能散瘀行滞，故食积兼瘀或痢疾初起有积滞者尤宜"},{"q":"可用于治疗白癜风的药组是","o":["鹿茸、淫羊藿","补骨脂、益智仁","巴戟天、肉苁蓉","菟丝子、沙苑子","补骨脂、菟丝子"],"a":4,"e":"补骨脂、菟丝子均能补肾助阳、固精缩尿，二药合用可温养肝肾、祛风祛斑，常用于白癜风、斑秃等皮肤白斑疾患。鹿茸、淫羊藿虽壮阳，白癜风非其主要适应证；巴戟天、肉苁蓉偏于补肾阳、益精血，益智仁偏温脾摄唾。补骨脂兼温肾祛风，菟丝子补肾益精，二者为治白癜风常用药组"},{"q":"长于拔毒化腐的药物是","o":["雄黄","硫磺","升药","明矾","硼砂"],"a":2,"e":"升药由汞、硝石、明矾等升炼而成，功能拔毒、化腐、生肌，为外科提脓去腐之要药，多与煅石膏配伍外用。雄黄解毒杀虫、燥湿祛痰，硫黄解毒杀虫、补火助阳，硼砂清热解毒、清肺化痰，明矾燥湿止痒、解毒杀虫，均不以拔毒化腐见长。升药毒性剧烈，只作外用，不可内服"},{"q":"湿热黄疸患者，医生处方中有：茵陈、栀子、大黄、郁金。不宜再与本方配伍同用的药是","o":["木香","丁香","玄参","鸡内金","金钱草"],"a":1,"e":"方中郁金畏丁香，属十九畏之列，二者同用降低药效或增毒性，故不宜再配丁香。茵陈、栀子、大黄清热利湿退黄，郁金行气活血、利胆退黄，共奏清利湿热之功。木香行气健脾、鸡内金消食、金钱草利湿退黄，与方中药性相合；玄参清热凉血滋阴，虽非主治湿热黄疸，亦无配伍禁忌。丁香辛温，与湿热黄疸病性格格不入"},{"q":"淡渗甘补，药性平和，可治疗寒热虚实各种水肿的药物是","o":["冬瓜皮","茯苓","猪苓","车前子","泽泻"],"a":1,"e":"茯苓甘淡平，利水渗湿、健脾宁心，药性平和，寒热虚实各种水肿均可配伍应用，故称淡渗甘补。猪苓、泽泻、冬瓜皮、车前子虽均能利水，但纯渗利而无补益，虚证水肿久服易伤正。茯苓利水而不伤正，健脾以绝生痰成水之源，寒证配温阳药、热证配清热药皆宜"},{"q":"外用治皮肤瘙痒，并用于温灸的中药是","o":["槐花","炮姜","艾叶","侧柏叶","仙鹤草"],"a":2,"e":"艾叶辛温，温经止血、散寒调经，外用祛湿止痒，煎汤外洗可治皮肤瘙痒，其绒制艾条更为温灸之主要材料。槐花、侧柏叶凉血止血，性偏寒凉，不宜温灸；炮姜温经止血但无外用止痒与灸用之能；仙鹤草收敛止血，亦非灸材。艾叶温通经络，故为针灸灸法所专用"},{"q":"下列需要煎汤代水的药物是","o":["灶心土","金银花","大黄","白芍","黄连"],"a":0,"e":"灶心土即伏龙肝，为久经柴草熏烧的灶底黄土，入汤剂须先煎汤代水，取其温中止呕、温脾止血、涩肠止泻之功。金银花、大黄、白芍、黄连均可常规入煎，无需代水。煎汤代水多用于泥土、石块类或质轻悬浮、易使药液浑浊之品，灶心土正属此类，煎取清液再煎余药"},{"q":"内服须与豆腐同煮的药是","o":["硫黄","雄黄","白矾","胆矾","硼砂"],"a":0,"e":"硫黄有毒，内服须与豆腐同煮以减毒，制品称制硫黄，能补火助阳、通便，温肾散寒。雄黄内服多入丸散，忌火煅；白矾多生用或煅用，胆矾、硼砂外用为主，皆不用豆腐同煮。豆腐同煮是利用豆腐中所含成分吸附、结合毒性物质，降低硫黄毒性，保证内服安全"},{"q":"功能利尿消肿，清热解暑的药物是","o":["玉米须","香加皮","冬瓜皮","泽泻","猪苓"],"a":2,"e":"冬瓜皮甘凉，利尿消肿、清热解暑，主治水肿胀满、小便不利及暑热烦渴。玉米须利尿消肿、利湿退黄，无清热解暑之功；香加皮祛风湿、强筋骨、利水，性温有毒；泽泻、猪苓利水渗湿，皆不解暑。冬瓜皮性凉能清暑热，且利水而不伤阴，故水肿兼暑热者最宜"},{"q":"宜首选升浮类药物治疗的是","o":["外感风寒","里实便秘","肝阳头痛","胃热呕吐","肺热鼻衄"],"a":0,"e":"升浮药具有升阳、发表、祛风、散寒、涌吐、开窍等作用趋向，病位在上、在表、病势下陷者宜之。外感风寒邪在肌表，须辛温发散、升浮解表，故首选升浮类药。里实便秘当用大黄、芒硝沉降攻下；肝阳头痛宜平肝潜阳、重镇降逆；胃热呕吐、肺热鼻衄皆宜清降，若用升浮则助热上逆"},{"q":"人参与莱菔子配伍，莱菔子削弱人参补气作用，这种关系称为","o":["相须","相使","相畏","相恶","相杀"],"a":3,"e":"莱菔子辛甘平，消食除胀、降气化痰，能削弱人参补气之功，人参恶莱菔子，此即相恶，指两药合用使一方或双方功效降低。相须指功效相似药同用相互增强；相使指主辅相配，辅药提高主药功效；相畏、相杀指一种药物抑制另一种药物毒性，与人参补气被削弱的情形不同"},{"q":"细辛的性味是","o":["辛温","辛寒","苦寒","苦温","甘温"],"a":0,"e":"细辛辛温，有小毒，祛风散寒、通窍止痛、温肺化饮，主治风寒表证、头风头痛、风寒湿痹及寒饮喘咳。辛寒、苦寒皆属寒凉药性，与细辛温散之性相反；苦温虽温但味苦降泄，甘温则偏补益。细辛辛能发散、温能散寒，故为辛温之品，用于阳虚外感亦取其温经散寒之力"},{"q":"味甘能解酒毒的药物是","o":["升麻","柴胡","蝉蜕","葛根","淡竹叶"],"a":3,"e":"葛根甘辛凉，解肌退热、生津止渴、升阳止泻、通经活络，且味甘能解酒毒，治酒毒伤中、恶心呕吐。升麻、柴胡虽能升阳，无解酒毒之用；蝉蜕疏散风热、利咽开窍，淡竹叶清热除烦利尿，均不解酒。葛根花与葛根均能解酒，其生津之功亦有助于缓解酒后烦渴"},{"q":"某女，50岁。带下色黄、质稠15天，近日又见肺热咳嗽，宜选用的药物是","o":["地肤子","萹蓄","海金沙","虎杖","茵陈"],"a":3,"e":"虎杖利湿退黄、清热解毒、散瘀止痛、化痰止咳，既能清下焦湿热以治带下黄稠，又能清肺化痰止咳，故湿热带下兼肺热咳嗽者宜之。地肤子、萹蓄利尿通淋、杀虫止痒，海金沙通淋排石，均不治肺热咳嗽；茵陈清利湿热、利胆退黄，长于黄疸，无止咳化痰之效"},{"q":"能散寒止痛，降逆止呕，助阳止泻的药物是","o":["柴胡","葛根","附子","砂仁","吴茱萸"],"a":4,"e":"吴茱萸辛热，散寒止痛、降逆止呕、助阳止泻，主治寒疝腹痛、厥阴头痛、胃寒呕吐及脾肾阳虚之五更泄泻。附子回阳救逆、补火助阳、散寒止痛，但无降逆止呕、助阳止泻之专能；柴胡、葛根升散退热，砂仁化湿行气、温中止泻，皆不具备散寒止痛与降逆止呕兼备的特点"},{"q":"治疗表虚不固的自汗，最宜选用","o":["牡蛎","龙骨","黄芪","白芍","酸枣仁"],"a":2,"e":"黄芪甘微温，补气升阳、益卫固表，表虚卫气不固之自汗，用之益气固表以止汗，最宜。牡蛎、龙骨咸寒或甘平，长于敛阴止汗，多用于阴虚盗汗或虚阳浮越，非表虚不固所宜；白芍养血敛阴，酸枣仁养心安神、敛汗，均无补气固表之功。表虚自汗本在气虚，故补气固表为正治"},{"q":"阳气虚弱患者最宜选用","o":["红参","生晒参","西洋参","太子参","人参叶"],"a":0,"e":"红参为人参蒸制而成，性偏温，火大、力足，长于大补元气、回阳救逆、益气摄血，阳气虚弱者最宜。生晒参性平，偏于补气生津；西洋参、太子参性凉或平，补气兼养阴，适宜气阴两虚；人参叶苦寒，清暑生津，补益力弱。阳气虚弱宜温补，故红参为首选"},{"q":"内服补中、润燥，外用生肌敛疮的药物是","o":["甘草","黄芪","蜂蜜","大枣","刺五加"],"a":2,"e":"蜂蜜甘平，内服补中缓急、润肺止咳、滑肠通便，外用可清热解毒、生肌敛疮，涂敷疮疡及烫伤创面。甘草、大枣虽补中，无外用生肌敛疮之长；黄芪补气升阳、托毒生肌，重在益气而非润燥；刺五加补气健脾、补肾安神，无润燥滑肠之效。蜂蜜质润，故内润脏腑、外护创面"},{"q":"妊娠禁用药多为","o":["峻猛剧毒之品","破气行滞之品","活血祛瘀之品","攻下通肠之品","辛热滑利之品"],"a":0,"e":"妊娠禁用药多为毒性剧烈或药性峻猛之品，如砒霜、水银、斑蝥、马钱子、三棱、莪术、牵牛子、麝香等，用之易致堕胎或伤胎。破气行滞、活血祛瘀、攻下通肠、辛热滑利之品多属慎用范畴，药力较禁用药缓和。妊娠用药禁忌以峻猛剧毒为禁，以行血、破气、攻下、辛热滑利为慎，二者程度不同"},{"q":"天南星用牛胆汁拌制的目的是","o":["降低毒性","增强疗效","改变性状","改变性能","矫臭矫味"],"a":3,"e":"天南星用牛胆汁拌制后为胆南星，药性由温燥变为凉润，功能由燥湿化痰、祛风解痉转为清热化痰、息风定惊，属改变性能。降低毒性多用生姜、明矾炮制；改变性状指形质变化，非胆制之要；增强疗效、矫臭矫味均非主要目的。胆南星苦凉，适用于痰热咳嗽、惊风癫痫"},{"q":"既能内行气血、通经止痛，又能外散风寒湿邪的药是","o":["姜黄","郁金","牛膝","羌活","独活"],"a":0,"e":"姜黄辛温，破血行气、通经止痛，内行气血以治胸胁刺痛、经闭腹痛、跌打损伤，外散风寒湿邪以治风湿肩臂疼痛。郁金行气活血、凉血清心，性寒无散风寒之能；牛膝活血通经、补肝肾、引血下行；羌活、独活皆祛风湿、止痛，无行血中之气、通经止痛之功。姜黄善治肩臂痛即取其外散风寒湿邪"},{"q":"既能清热凉血，又能活血散瘀的药组是","o":["玄参、生地黄","地骨皮、牡丹皮","知母、黄柏","赤芍、牡丹皮","大黄、芒硝"],"a":3,"e":"赤芍苦寒，清热凉血、散瘀止痛；牡丹皮苦辛微寒，清热凉血、活血散瘀，二者均入血分，既清血分之热又散血中之瘀。玄参、生地黄清热凉血、养阴生津，无活血散瘀之力；地骨皮清虚热、凉血，知母、黄柏滋阴降火；大黄、芒硝泻下攻积。赤芍、牡丹皮配伍常用于温毒发斑、血瘀经闭等"},{"q":"雄黄适用于癫痫，与其具有的什么功效相关","o":["解毒","燥湿","开窍","祛痰","活血"],"a":3,"e":"雄黄辛温有毒，解毒杀虫、燥湿祛痰、截疟，癫痫多因痰浊蒙蔽清窍，其治癫痫正取祛痰开闭之功。解毒、燥湿虽为雄黄所有，但与癫痫病机无直接对应；开窍为麝香、石菖蒲之能，雄黄并无开窍之名；活血亦非其主治。雄黄祛痰之力用于痰饮咳喘、癫痫惊狂，故与题干相应"},{"q":"外感风寒表证内兼湿阻中焦证治宜首选","o":["广藿香","豆蔻","五加皮","砂仁","茯苓"],"a":0,"e":"广藿香辛微温，芳香化浊、和中止呕、发表解暑，外感风寒表证兼湿阻中焦之脘痞呕恶者最宜，故为首选。豆蔻、砂仁化湿行气、温中止呕，重在理中而无解表之功；五加皮祛风湿、强筋骨；茯苓利水渗湿、健脾宁心，皆不能外散风寒。广藿香表里兼顾，化湿而不碍解表"},{"q":"虎杖对于孕妇慎用，除考量其通利作用较强外，相关因素还有","o":["清热解暑","解毒消肿","通淋排石","散瘀止痛","止咳化痰"],"a":3,"e":"虎杖散瘀止痛、通经，能行血中之滞，孕妇用之恐动血伤胎，故除通利作用较强外，散瘀止痛亦是慎用之由。清热解暑、解毒消肿虽其所有，与动血之虞无关；通淋排石亦属通利范畴，非题干所求之其他因素；止咳化痰更与胎前禁忌无涉。虎杖兼入血分，故血虚、孕妇及无瘀者慎用"},{"q":"肝阳上亢、头痛眩晕，伴胃气上逆、呕吐嗳气，最宜选用的药是","o":["赭石","石决明","生龙骨","杭白芍","灵磁石"],"a":0,"e":"赭石苦寒，平肝潜阳、重镇降逆、凉血止血，既能镇肝阳之上亢以止头痛眩晕，又能降胃气之上逆以止呕吐嗳气。石决明、生龙骨、灵磁石虽能平肝潜阳、镇惊安神，均无降逆止呕之功；杭白芍养血柔肝、缓急止痛，力薄不能镇降。赭石重镇，肝胃并治，故为最宜"},{"q":"治肺燥咳嗽宜蜜炙用的药物是","o":["菊花","桑叶","牛蒡子","蝉蜕","柴胡"],"a":1,"e":"桑叶苦甘寒，疏散风热、清肺润燥、清肝明目，蜜炙后润肺止咳之力增强，治肺燥咳嗽宜蜜炙用。菊花、牛蒡子、蝉蜕、柴胡虽能疏散风热，均无润肺燥之能，且多生用。桑叶清肺润燥兼清肝，蜜炙甘润以养肺阴，故燥咳痰少者用之最合"},{"q":"治上部出血证，止血药宜配伍的药物类别是","o":["降气药","活血药","升阳药","行气药","清热凉血药"],"a":0,"e":"上部出血多因气火上逆、血随气升，止血药中加入降气药，使气降火降、血归其位，故治上部出血宜配降气药。升阳药助气上升，反致血随气上逆，最为禁忌；活血药、行气药虽能调畅气血，无降逆引血下行之专功；清热凉血药用于血热出血，但不针对气逆病机"},{"q":"具有行气止痛，温肾纳气功效的药物是","o":["香附","青皮","沉香","木香","佛手"],"a":2,"e":"沉香辛苦温，行气止痛、温中止呕、纳气平喘，气滞脘腹胀痛及肾虚气不归元之虚喘用之皆宜。香附疏肝理气、调经止痛，专于肝郁气滞；青皮破气疏肝、消积化滞，力猛而无纳气之功；木香行气调中，佛手疏肝理气、和胃化痰，均不温肾纳气。沉香质重沉降，故能纳气归肾"},{"q":"既能治疗肝阳上亢的头晕目眩，又可治疗吐血、衄血、崩漏的中药是","o":["赭石","蒺藜","珍珠","羚羊角","白僵蚕"],"a":0,"e":"赭石苦寒，既能平肝潜阳以治肝阳上亢之头晕目眩，又能凉血止血以治吐血、衄血、崩漏，一药而两擅其功。蒺藜祛风明目、疏肝解郁；珍珠安神定惊、明目消翳；羚羊角平肝息风、清肝明目，均不能止血；白僵蚕祛风定惊、化痰散结，更无平肝与止血之用"},{"q":"朱砂的主治病症不包括","o":["心悸失眠","惊风癫痫","疮痈肿毒","咽喉肿痛","肺热咳嗽"],"a":4,"e":"朱砂甘寒有毒，清心镇惊、安神解毒，主治心悸失眠、惊风癫痫、疮痈肿毒及咽喉肿痛。肺热咳嗽当用清肺化痰止咳之品，如黄芩、桑白皮、前胡之类，朱砂无清肺止咳之功。心悸失眠取其一镇心安神，惊风癫痫取其镇惊，疮痈、咽痛取其清热解毒，皆与肺热咳嗽不同"},{"q":"具有敛肺止咳作用的药物大多具有何种药味","o":["辛","甘","酸","苦","咸"],"a":2,"e":"酸味能收能涩，敛肺止咳、涩肠止泻、固精缩尿、敛汗止血诸药多具酸味，如五味子、乌梅、山茱萸之属。辛味发散行气，甘味补益和中，苦味泄降燥湿，咸味软坚散结，皆无收敛之性。敛肺止咳在于收敛肺气之耗散，故五味子、罂粟壳等均以酸涩为能"},{"q":"白果止咳平喘的机制是","o":["宣肺","润肺","清肺","敛肺","泻肺"],"a":3,"e":"白果甘苦涩平，有小毒，敛肺化痰定喘、收涩止带，其止咳平喘机制在于敛肺气之耗散，用于肺虚咳喘及哮喘痰多。宣肺为麻黄、桔梗之能，润肺为百合、川贝母之能，清肺为黄芩、桑白皮之能，泻肺为桑白皮、葶苈子之能，皆与白果收敛之性相反。白果兼收涩止带缩尿，肺虚久咳尤为适宜"},{"q":"常用以治疗小儿夜啼不安的药物是","o":["葛根","淡豆豉","牛蒡子","蝉蜕","薄荷"],"a":3,"e":"蝉蜕甘寒，疏散风热、利咽开音、透疹止痒、退翳明目、息风止痉，小儿夜啼不安多因心经有热或惊风，蝉蜕能清心经之热、镇惊安神，故为常用。葛根解肌升阳，淡豆豉解表除烦，牛蒡子疏散风热、利咽透疹，薄荷疏散风热、清利头目，均无镇惊止啼之专能"},{"q":"脾不统血、冲脉不固之虚寒性出血宜选用","o":["凉血止血药","温经止血药","收敛止血药","化瘀止血药","温肾止血药"],"a":1,"e":"温经止血药性温，能温经脉、散寒凝而止血，脾不统血、冲脉不固之虚寒性出血，症见便血、崩漏、色暗淡者最宜，如艾叶、炮姜之类。凉血止血药用于血热妄行，收敛止血药无温补之功，化瘀止血药针对瘀血阻络之出血，温肾止血之说并非止血药常规分类。虚寒出血当温经摄血"},{"q":"不属苦参功效的是","o":["清热","燥湿","祛风","杀虫","利尿"],"a":2,"e":"苦参苦寒，清热燥湿、杀虫、利尿，主治湿热黄疸、泻痢、带下、阴痒及小便不利，无祛风作用。祛风多取防风、羌活、白鲜皮之属，白鲜皮兼能清热燥湿、祛风止痒，可治湿疹瘙痒，与苦参专清下焦湿热有所区别。清热、燥湿、杀虫、利尿皆苦参本功，唯祛风非其所有"},{"q":"水火烫伤、痈肿疮毒，宜选","o":["大蓟","白及","地榆","侧柏叶","白茅根"],"a":2,"e":"地榆苦酸微寒，凉血止血、解毒敛疮，为治水火烫伤之要药，能清热凉血、收敛生肌，亦治痈肿疮毒及血热出血。大蓟凉血止血、散瘀消痈；白及收敛止血、消肿生肌，多用于咯血、吐血及疮疡；侧柏叶凉血止血、化痰止咳；白茅根凉血止血、清热利尿，皆非烫伤首选"},{"q":"平肝潜阳宜生用，收敛固涩宜煅用的药物是","o":["石膏","龙骨","琥珀","柏子仁","瓦楞子"],"a":1,"e":"龙骨甘涩平，生用平肝潜阳、镇惊安神，煅用收敛固涩，能敛汗、涩精、止泻、止血，故生煅功效有别。石膏生用清热泻火、煅用收湿敛疮；琥珀镇惊安神、活血散瘀，无煅用固涩之说；柏子仁养心安神、润肠；瓦楞子消痰化瘀、制酸止痛，皆非生潜阳煅固涩之品"},{"q":"治疗阴虚火旺，潮热盗汗，黄柏常相须配伍的药是","o":["黄芩","黄连","栀子","知母","石膏"],"a":3,"e":"黄柏苦寒，清热燥湿、泻火除蒸、解毒疗疮，善清下焦虚火；知母苦甘寒，清热泻火、滋阴润燥，二药相须为用，滋阴降火之力大增，治阴虚火旺、潮热盗汗、遗精等。黄芩、黄连清上中焦湿热，栀子泻火除烦、清热利湿，石膏清气分实热，均无滋阴除蒸之功"},{"q":"有“定风草”之称，获“治风神药”之誉的药物是","o":["天麻","牛黄","珍珠","钩藤","羚羊角"],"a":0,"e":"天麻甘平，息风止痉、平抑肝阳、祛风通络，为治肝风内动、惊痫抽搐之要药，凡眩晕、头痛、肢体麻木皆可用，故有定风草、治风神药之称。钩藤清热平肝、息风定惊，力较缓和；牛黄、羚羊角清热解毒、息风止痉，珍珠安神定惊，皆无定风草之誉。天麻专入肝经，为治风通用之品"},{"q":"治热结旁流常以大黄配","o":["番泻叶","甘遂","芒硝","火麻仁","生地黄"],"a":2,"e":"热结旁流乃实热积滞内结、燥屎不行，仅稀水自旁流出，治当峻下热结，大黄配芒硝，大黄泻下攻积，芒硝咸寒软坚润燥，相须为用，使燥屎得下、热结得去。番泻叶、火麻仁泻下力缓，不堪峻下；甘遂、牵牛子峻下逐水，非治燥屎坚结之配；生地黄滋阴润燥，无攻下之力"},{"q":"治疗外感发热，项背强痛，首选的药物是","o":["葛根","淡豆豉","牛蒡子","蝉蜕","薄荷"],"a":0,"e":"葛根解肌退热、升津舒筋，外感发热、项背强痛者首选，因其能解肌发表、升津液以濡养筋脉，缓解项背拘急。淡豆豉解表除烦，牛蒡子疏散风热、利咽，蝉蜕疏散风热、利咽退翳，薄荷清利头目，均无解肌升津、专治项背强痛之能。葛根归胃经，善治阳明经项背强几几"},{"q":"补血药的主要归经为","o":["肝肺经","心肾经","心肝经","心脾经","肺脾经"],"a":2,"e":"补血药多入心、肝经，心主血、肝藏血，补血以心肝为本，如当归、熟地黄、阿胶、白芍皆归心肝。肺主气、脾统血，肝肺经、心脾经、肺脾经之说皆非补血药主要归经；心肾经多属滋阴降火或安神药所归。补血兼顾心肝，方能充养血脉、濡养全身"},{"q":"冬虫夏草和紫河车均可用于治疗","o":["脾肾虚泻","口多唾涎","骨蒸劳嗽","肠燥便秘","筋伤骨折"],"a":2,"e":"冬虫夏草补肾益肺、止血化痰，紫河车温肾补精、益气养血，二者均能补肾益肺、止血化痰，故皆可用于肺肾两虚之骨蒸劳嗽。脾肾虚泻宜补骨脂、肉苁蓉；口多唾涎宜益智仁；肠燥便秘宜肉苁蓉、当归；筋伤骨折宜续断、骨碎补。骨蒸劳嗽属虚劳咳嗽，正合二药补肺肾之功"},{"q":"紫菀与款冬花均有的功效是","o":["清肺化痰，润肠通便","消痰行水，降逆止呕","纳气平喘，固精止带","润肺下气，化痰止咳","泻肺平喘，利水消肿"],"a":3,"e":"紫菀与款冬花均能润肺下气、化痰止咳，为治咳嗽之常用药对，无论外感内伤、寒热虚实之咳嗽皆可随证配伍。清肺化痰、润肠通便为瓜蒌仁之能；消痰行水、降逆止呕属旋覆花；纳气平喘、固精止带为蛤蚧、山药之类；泻肺平喘、利水消肿是桑白皮、葶苈子。二药性温而不燥，润肺止咳之力相仿"},{"q":"既能收敛止汗，又能镇惊安神的药物是","o":["磁石","龙骨","浮小麦","酸枣仁","五味子"],"a":1,"e":"龙骨甘涩平，煅用能收敛止汗、涩精止泻，生用可镇惊安神、平肝潜阳，故既能收敛止汗又能镇惊安神。磁石、琥珀镇惊安神但无收敛止汗之效；浮小麦益气除热止汗，无镇惊安神之功；酸枣仁养心安神、敛汗，五味子收敛止汗、宁心，然均无镇惊平肝之能。龙骨一身兼固涩与镇惊两长"},{"q":"上能温肺散寒以化痰饮，中能温脾运水以消痰，为寒饮喘咳之良药的是","o":["肉桂","桂枝","干姜","丁香","吴茱萸"],"a":2,"e":"干姜辛热，温中散寒、回阳通脉、温肺化饮，上能温肺散寒以化痰饮，中能温脾阳、运水湿以消痰，为寒饮喘咳之良药，如小青龙汤中用之。肉桂补火助阳、引火归元，桂枝解肌温经、通阳化气，丁香温中降逆、温肾助阳，吴茱萸散寒止痛、降逆止呕，皆非温肺化饮之专药"},{"q":"治疗肝肾不足，遗尿尿频，目黯不明，脾肾虚泻。最宜选择的药物是","o":["续断","桑寄生","枸杞子","补骨脂","菟丝子"],"a":4,"e":"菟丝子辛甘平，补肾益精、养肝明目、止泻、安胎、固精缩尿，肝肾不足之遗尿尿频、目黯不明及脾肾两虚之泄泻皆宜，故为最宜。续断补肝肾、强筋骨、止血安胎；桑寄生祛风湿、补肝肾、安胎；枸杞子滋补肝肾、明目；补骨脂温肾助阳、温脾止泻，皆不能兼顾明目与固涩"},{"q":"性沉降下行，善治下焦血热出血的药物是","o":["蒲黄","三七","大蓟","地榆","侧柏叶"],"a":3,"e":"地榆苦酸微寒，性沉降下行，专入下焦，凉血止血、解毒敛疮，善治下焦血热之便血、痔血、血痢及崩漏。蒲黄、三七化瘀止血，止血而不留瘀；大蓟凉血止血、散瘀消痈，偏走上焦；侧柏叶凉血止血、化痰止咳，多治上焦出血。地榆沉降，下焦出血尤为对证"},{"q":"治邪在少阳，寒热往来证，清半表半里之热，共收和解少阳之功，柴胡最宜配伍的药物是","o":["黄芩","黄连","黄柏","栀子","葛根"],"a":0,"e":"柴胡与黄芩相配，是和解少阳之核心药对，柴胡透泄少阳之邪、疏泄气机郁滞，黄芩清泄少阳之热，一散一清，共解半表半里之邪，治寒热往来、口苦咽干。黄连、黄柏、栀子清热燥湿或泻火除烦，入三焦、心、下焦，非少阳专药；葛根解肌升阳，无和解少阳之功"},{"q":"麻黄配石膏善治","o":["风水水肿","虚烦不眠","肺热喘咳","血瘀经闭","风湿痹痛"],"a":2,"e":"麻黄宣肺平喘、发汗解表，石膏清热泻火、除烦止渴，二药相配，清宣肺热而平喘，主治邪热壅肺之发热、喘咳、口渴，如麻杏石甘汤。风水水肿宜麻黄配甘草、生姜等；虚烦不眠宜栀子豉汤之类；血瘀经闭用活血通经药；风湿痹痛用祛风湿药。麻黄配石膏重在清肺热而平喘"},{"q":"杜仲、续断都能治疗的病证是","o":["肝肾不足、胎动不安","肝肾不足、阳虚冷泻","肝肾不足、肠燥便秘","肝肾不足、五更泄泻","肝肾不足、气血两虚"],"a":0,"e":"杜仲、续断均能补肝肾、强筋骨、安胎，肝肾不足之腰膝酸痛、胎动不安二者皆可应用。阳虚冷泻宜补骨脂、肉豆蔻；肠燥便秘宜肉苁蓉、当归；五更泄泻宜四神丸之属；气血两虚宜八珍之类。杜仲、续断同入肝肾，安胎之力亦相仿，故胎动不安为其共同主治"},{"q":"治阴血不足，筋失所养的挛急疼痛，白芍常配伍","o":["麦冬","甘草","川芎","延胡索","五味子"],"a":1,"e":"白芍养血敛阴、柔肝止痛、平抑肝阳，甘草益气和中、缓急止痛，二药相配即芍药甘草汤，酸甘化阴，能滋养阴血、缓急止痛，善治阴血不足、筋脉失养之挛急疼痛。麦冬养阴润肺、益胃生津；川芎活血行气；延胡索活血行气止痛；五味子收敛固涩，均无酸甘化阴缓急之配伍特点"},{"q":"能清肺止咳，降逆止呕的药物是","o":["紫菀","礞石","天竺黄","枇杷叶","款冬花"],"a":3,"e":"枇杷叶苦寒，清肺止咳、降逆止呕，主治肺热咳嗽及胃热呕哕。紫菀、款冬花润肺下气、化痰止咳，无降逆止呕之功；礞石滚痰、下气坠痰；天竺黄清热化痰、清心定惊，皆不入胃经降逆。枇杷叶清降肺胃之气，咳嗽兼呕逆者尤宜"},{"q":"具有补虚强壮之功，常用治脱力劳伤的药物是","o":["三七","白及","蒲黄","仙鹤草","血余炭"],"a":3,"e":"仙鹤草苦涩平，收敛止血、补虚、止痢、截疟，兼能补虚强壮，民间用于脱力劳伤、神疲乏力，故有脱力草之称。三七化瘀止血、活血定痛，白及收敛止血、消肿生肌，蒲黄止血化瘀，血余炭收敛止血、化瘀，皆无补虚强壮、治脱力劳伤之功。仙鹤草止血兼补虚，为其独有特点"},{"q":"不是用炒法制成的药物是","o":["艾叶炭","炒白术","炒苏子","荆芥炭","血余炭"],"a":4,"e":"血余炭为人发煅烧炭化而成，属煅炭法，非炒法所制。艾叶炭由艾叶炒炭，炒白术、炒苏子皆清炒或麸炒，荆芥炭为荆芥炒炭，均属炒法制品。炒法与煅炭法炮制工艺不同，血余炭须密闭煅烧至炭化，故不属于炒法制成的药物"},{"q":"白前的功效是","o":["降气祛痰","发散风寒","润肺止咳","清热泻火","泻肺平喘"],"a":0,"e":"白前辛苦微温，降气化痰、止咳，主治咳嗽痰多、气逆喘促，尤宜于痰湿壅肺、肺气不降之咳嗽。发散风寒为麻黄、桂枝之能；润肺止咳属百合、川贝母；清热泻火为石膏、知母；泻肺平喘是桑白皮、葶苈子。白前专主降气化痰，性温而不燥，为治痰咳气逆之常用药"},{"q":"生用涌吐风痰，炒用消食化痰的药物是","o":["山楂","神曲","麦芽","莱菔子","鸡内金"],"a":3,"e":"莱菔子辛甘平，生用可涌吐风痰，炒用则消食除胀、降气化痰，主治食积气滞、咳喘痰多。山楂消食化积、行气散瘀；神曲消食和胃；麦芽消食健胃、回乳；鸡内金消食健胃、涩精止遗，均无生用涌吐风痰之能。莱菔子生炒异用，炒后消食降气力增，故治食积咳喘多用炒品"},{"q":"拔毒化腐生肌药多含砷、汞、铅等元素，多具剧烈毒性或强大刺激性。下列使用方法中错误的是","o":["不可内服","应该视病情而确定使用","外用不可过量和过久应用","应该严格控制剂量和用法","有些药不宜用于头面及黏膜"],"a":0,"e":"拔毒化腐生肌药多含砷、汞、铅，毒性剧烈或刺激性强，用药须严格控量、视病情外用，不可过量久用，部分药物不宜用于头面及黏膜。此类药并非绝对不可内服，如轻粉少量内服可利水通便、逐水消积，故“不可内服”之说过于绝对，为错误用法。其余各项均为该类药物外用应遵循的原则"},{"q":"主要用于肺、胃阴虚证的药物是","o":["石斛","枸杞子","北沙参","墨旱莲","女贞子"],"a":2,"e":"北沙参甘微寒，养阴清肺、益胃生津，专入肺胃二经，主治肺阴虚之干咳少痰及胃阴虚之口干食少。石斛益胃生津、滋阴清热，重在胃肾；枸杞子滋补肝肾、明目；墨旱莲、女贞子滋补肝肾、凉血止血，均不归肺经养肺阴。肺胃阴虚并见者，北沙参最为对证"},{"q":"治胃火炽盛，牙龈肿痛，首选的药物是","o":["金银花","鱼腥草","蒲公英","山豆根","白头翁"],"a":3,"e":"山豆根苦寒，清热解毒、利咽消肿，兼清胃火，胃火炽盛之牙龈肿痛、咽喉肿痛用之可清胃泻火、消肿止痛。金银花清热解毒、疏散风热，鱼腥草清肺热、消肺痈，蒲公英消乳痈、散结，白头翁清血分热毒、治热痢，皆非治胃火牙痛之首选。山豆根归肺胃经，善清上焦胃腑之热毒"},{"q":"半夏的功效是","o":["燥湿化痰，祛风止痉，消痞散结","燥湿化痰，降逆止呕，通络止痛","燥湿化痰，降逆止呕，消痞散结","燥湿化痰，利气宽胸，消痞散结","燥湿化痰，祛风止痉，润肠通便"],"a":2,"e":"半夏辛温有毒，燥湿化痰、降逆止呕、消痞散结，外用消肿止痛，为燥湿化痰之要药。祛风止痉为天南星、白附子之能；通络止痛属白芷、威灵仙之类；利气宽胸为瓜蒌、薤白之所主；润肠通便更非半夏所有。半夏配以生姜可制其毒，并以降逆止呕见长，消痞散结治心下痞、梅核气"},{"q":"善治口中甜腻、多涎之脾瘅证的药物是","o":["香薷","佩兰","广藿香","砂仁","厚朴"],"a":1,"e":"佩兰辛平，芳香化湿、醒脾开胃、发表解暑，善治脾经湿热之口中甜腻、多涎、口气腐臭，即脾瘅证。香薷发汗解表、化湿和中，主夏月感寒；广藿香化浊止呕、发表解暑；砂仁化湿行气、温中止泻；厚朴燥湿消痰、下气除满，皆非治脾瘅口甜之专药。佩兰入脾经，化脾湿浊，故为要药"},{"q":"善治寒积便秘的药物是","o":["大黄","芒硝","番泻叶","巴豆霜","牵牛子"],"a":3,"e":"巴豆霜辛热，有大毒，峻下冷积、逐水退肿、祛痰利咽，寒积便秘、腹满胀痛者用之温下寒积，故为治寒积便秘之首选。大黄、芒硝、番泻叶皆苦寒泻下，主治热结便秘；牵牛子峻下逐水、去积杀虫，非温下寒积之药。巴豆霜得热则泻，寒积得温则行，故宜于寒积"},{"q":"治疗下元虚冷、肾不纳气之虚喘，最宜选用","o":["沉香","香附","佛手","橘皮","刀豆"],"a":0,"e":"沉香辛苦温，行气止痛、温中止呕、纳气平喘，下元虚冷、肾不纳气之虚喘，用之温肾纳气、降逆平喘。香附疏肝理气、调经；佛手疏肝理气、和胃化痰；橘皮理气健脾、燥湿化痰；刀豆温中降逆、补肾助阳，均无纳气平喘之功。沉香质重沉降，直入下焦，能引气归元"},{"q":"石决明的功效是","o":["平肝潜阳、清肺止咳","平肝潜阳、化痰开窍","平肝潜阳、息风止痉","平肝潜阳、清肝明目","平肝潜阳、解毒散结"],"a":3,"e":"石决明咸寒，平肝潜阳、清肝明目，为治肝阳上亢及目疾之要药，又能退翳。其无清肺止咳、化痰开窍、息风止痉、解毒散结之用。清肺止咳属桑白皮、黄芩；化痰开窍属石菖蒲、远志；息风止痉属羚羊角、钩藤；解毒散结属牛黄、山慈菇。石决明介类潜阳，清肝火以明目"},{"q":"内服不可过量或持续服用，且忌火煅的药物是","o":["磁石","牡蛎","朱砂","琥珀","珍珠母"],"a":2,"e":"朱砂甘寒有毒，清心镇惊、安神解毒，内服只宜入丸散，不可过量或持续服用，且忌火煅，火煅则析出水银而剧毒。磁石、牡蛎、珍珠母可煅用或久服，无火煅禁例；琥珀镇惊安神、活血散瘀，无此毒性。朱砂为汞化物，受热易分解析出汞，故用法用量须严格把控"},{"q":"现代常用治真性红细胞增多症、冠心病心绞痛的药物是","o":["水蛭","莪术","三棱","虻虫","土鳖虫"],"a":0,"e":"水蛭咸苦平，有小毒，破血通经、逐瘀消癥，抗凝血作用强，现代常用于真性红细胞增多症、冠心病心绞痛及脑血栓等瘀血证。莪术、三棱行气破血、消积止痛，虻虫、土鳖虫破血逐瘀，作用与水蛭相近，但现代用于上述病证者以水蛭最为常用，取其破血逐瘀、通络之效"},{"q":"党参的归经是","o":["心、脾经","心、肺经","脾、肺经","脾、肾经","肺、肾经"],"a":2,"e":"党参甘平，补中益气、健脾益肺、养血生津，主入脾、肺二经，为常用的补气健脾药，可代替人参用于脾肺气虚之轻证。心、脾经或心、肺经之说均非其主要归经；脾、肾经偏于补骨脂、山药之类；肺、肾经偏于蛤蚧、冬虫夏草。党参补中气、益肺气，故归脾肺"},{"q":"下列药物需要冲服的是","o":["半夏","连翘","蒲黄","天花粉","芒硝"],"a":4,"e":"芒硝咸苦寒，泻下通便、润燥软坚、清火消肿，入汤剂不宜煎煮，须冲入药汁中溶化服，或用开水冲服。半夏、连翘、天花粉均入煎剂；蒲黄包煎；芒硝为含结晶水的硫酸钠，久煎则失水或分解，故冲服。冲服适用于不宜煎煮、易溶或贵重细料之品"},{"q":"功能逐水通便，适用于水邪盛而正气尚能耐受攻伐，且一般利水药乏效的药物是","o":["茯苓","猪苓","轻粉","土茯苓","白花蛇舌草"],"a":2,"e":"轻粉辛寒，有大毒，外用杀虫、攻毒、敛疮，内服能利水通便、逐水消积，适用于水邪壅盛而正气尚能耐受攻伐、一般利水药无效者。茯苓、猪苓利水渗湿，性平和，无逐水通便之力；土茯苓解毒利湿、通利关节；白花蛇舌草清热解毒、利湿通淋，皆非峻烈逐水之品"},{"q":"不具有清热燥湿功效的药组是","o":["黄芩，黄连","黄芩，龙胆","黄柏，秦皮","青黛，三颗针","苦参，白鲜皮"],"a":3,"e":"青黛咸寒，清热解毒、凉血定惊、定喘，主治温毒发斑、血热吐衄及小儿惊风，无燥湿之功；三颗针苦寒，清热燥湿、泻火解毒，虽能燥湿，但青黛不能，故该药组不属清热燥湿药组。黄芩、黄连、黄柏、龙胆、秦皮、苦参、白鲜皮皆味苦性寒，功能清热燥湿，为典型清热燥湿药"},{"q":"肺热咳嗽，常与地骨皮配伍的药物是","o":["金银花","竹叶","决明子","桑白皮","栀子"],"a":3,"e":"桑白皮甘寒，泻肺平喘、利水消肿、清泻肺热；地骨皮甘寒，清虚热、凉血、清肺降火，二药相配即泻白散，清泻肺中伏火而止咳平喘，治肺热咳喘。金银花、竹叶清热，决明子清肝明目，栀子泻火除烦，均无泻肺平喘、与地骨皮配伍清肺热之专功"},{"q":"不具有润肠通便作用的药物是","o":["苦杏仁","桃仁","瓜蒌仁","酸枣仁","柏子仁"],"a":3,"e":"酸枣仁甘酸平，养心补肝、宁心安神、敛汗、生津，无润肠通便作用。苦杏仁、桃仁富含油脂，能降气止咳平喘、润肠通便；瓜蒌仁润肺化痰、滑肠通便；柏子仁养心安神、润肠通便。酸枣仁质润但偏于收敛安神，无滑肠之效，肠燥便秘者非其所宜"},{"q":"性味苦寒，有小毒的药物是","o":["礞石","浙贝母","黄药子","苦杏仁","天南星"],"a":2,"e":"黄药子苦寒，有小毒，化痰散结消瘿、清热解毒、凉血止血，主治瘰疬、瘿瘤、疮疡肿毒及血热出血。礞石咸寒，坠痰下气、平肝镇惊；浙贝母苦寒，清热化痰、散结消痈；苦杏仁苦温有小毒，降气止咳平喘；天南星苦辛温有毒，燥湿化痰、祛风解痉。性味苦寒且有小毒者当属黄药子"},{"q":"既能除虚热，又能益气阴的药是","o":["麻黄根","浮小麦","山茱萸","金樱子","刺五加"],"a":1,"e":"浮小麦甘凉，益气、除热、止汗，既能益气阴之不足，又能清虚热，主治自汗、盗汗及骨蒸劳热。麻黄根固表止汗，无益气除热之功；山茱萸、金樱子收敛固涩、补益肝肾；刺五加补气健脾、补肾安神，均无除虚热、益气阴兼备之效。浮小麦轻浮走表，益卫气而清虚热"},{"q":"能养血安神的补气药是","o":["山药","党参","大枣","甘草","白芍"],"a":2,"e":"大枣甘温，补中益气、养血安神、缓和药性，为补气药中兼能养血安神之品，用于脾虚食少、乏力便溏及血虚失眠。山药补气养阴、益肺脾肾；党参补中益气、养血生津；甘草补脾益气、清热解毒、调和诸药；白芍养血敛阴，属补血药而非补气药。大枣养血安神，故为能养血安神的补气药"},{"q":"下列药物尤宜于风湿顽痹，日久不愈者是","o":["独活","防己","木瓜","乌梢蛇","威灵仙"],"a":3,"e":"乌梢蛇甘平，祛风、通络、止痉，性善走窜，搜风通络之力较强，尤宜于风湿顽痹、日久不愈及麻木瘫痪。独活祛风湿、止痛，善治下半身痹痛；防己祛风湿、止痛、利水；木瓜舒筋活络、化湿和胃；威灵仙祛风湿、通经络、治骨鲠，搜风通络之力均不及乌梢蛇"},{"q":"为治疗肝阳上亢及目疾之要药是","o":["牡蛎","蒺藜","桑叶","石决明","羚羊角"],"a":3,"e":"石决明咸寒，平肝潜阳、清肝明目，为治肝阳上亢之头晕目眩及肝火目疾之要药。牡蛎咸寒，平肝潜阳、镇惊安神、软坚散结、收敛固涩，明目之力不及；蒺藜祛风明目、疏肝解郁；桑叶疏散风热、清肝明目；羚羊角平肝息风、清肝明目，长于息风止痉。石决明专为肝阳、目疾而设"},{"q":"银柴胡主要治疗","o":["少阳证寒热往来","表证发热","热病高热烦渴","温病伤阴，夜热早凉","阴虚发热，骨蒸劳热"],"a":4,"e":"银柴胡甘微寒，退虚热、清疳热，专治阴虚发热、骨蒸劳热及小儿疳热，无升散之性。少阳寒热往来宜柴胡、黄芩；表证发热宜荆芥、薄荷；热病高热烦渴宜石膏、知母；温病伤阴、夜热早凉宜青蒿、鳖甲。银柴胡但清虚热，不治外感及实热，故所主为阴虚骨蒸劳热"},{"q":"秦艽除能祛风湿外，还能","o":["补肝肾","消水肿","清虚热","治骨鲠","强筋骨"],"a":2,"e":"秦艽苦辛平，祛风湿、通经络、止痹痛、退虚热、清湿热，为风药中之润剂，治风湿痹痛兼虚热骨蒸者尤宜。补肝肾、强筋骨属杜仲、续断、五加皮；消水肿属防己、黄芪；治骨鲠为威灵仙之能；强筋骨亦非秦艽所主。秦艽退虚热之功可用于骨蒸潮热、小儿疳热"},{"q":"入汤剂，多宜后下的药物是","o":["牛黄","天麻","全蝎","钩藤","羚羊角"],"a":3,"e":"钩藤甘凉，清热平肝、息风定惊，含钩藤碱，久煎则有效成分被破坏、降压及止痉作用减弱，故入汤剂宜后下，煎煮时间不宜过长。牛黄多入丸散，天麻、全蝎可常规入煎，羚羊角另煎兑服，均非后下之品。钩藤后下是因其不耐热，久煎失效"},{"q":"栀子用治湿热黄疸，因其能","o":["泻火除烦","清热利湿","凉血解毒","消肿止痛","凉血止血"],"a":1,"e":"栀子苦寒，泻火除烦、清热利湿、凉血解毒、消肿止痛，治湿热黄疸乃取其清热利湿之功，使湿热从小便而去，如茵陈蒿汤中配茵陈、大黄。泻火除烦治热郁心烦，凉血解毒治血热出血、疮疡，消肿止痛治跌打损伤，凉血止血非其主要功效表述。栀子清利三焦湿热，故黄疸用之"},{"q":"既能安神，又能消肿，祛痰的药是","o":["远志","酸枣仁","首乌藤","夜交藤","合欢花"],"a":0,"e":"远志苦辛温，安神益智、祛痰开窍、消散痈肿，既能宁心安神治失眠健忘，又能祛痰开窍治痰阻心窍之癫痫，并可消肿治疮痈乳房肿痛。酸枣仁、首乌藤（夜交藤）、合欢花皆能安神，但无消肿、祛痰开窍之能；夜交藤与首乌藤为一药异名。远志祛痰开窍兼消肿，故为所问"},{"q":"血虚、血寒、血瘀皆可应用，被称为“血中之圣药”的药物是","o":["当归","阿胶","制首乌","熟地黄","龙眼肉"],"a":0,"e":"当归甘辛温，补血活血、调经止痛、润肠通便，血虚、血寒、血瘀所致月经不调、痛经、经闭及虚寒腹痛皆可应用，故被称为血中之圣药。阿胶滋阴补血、止血，制首乌补肝肾、益精血，熟地黄补血滋阴、益精填髓，龙眼肉补心脾、益气血，皆无活血行滞之能。当归补血兼行血，温而不燥"},{"q":"既能平肝潜阳、镇惊安神，又能纳气定喘的药物是","o":["龙骨","牡蛎","朱砂","磁石","石菖蒲"],"a":3,"e":"磁石咸寒，镇惊安神、平肝潜阳、聪耳明目、纳气定喘，既能重镇安神、平肝，又能益肾纳气以治虚喘。龙骨镇惊安神、平肝潜阳、收敛固涩，无纳气定喘之用；牡蛎平肝潜阳、软坚散结、收敛固涩；朱砂清心镇惊、安神解毒；石菖蒲开窍豁痰、醒神益智，皆不纳气。磁石色黑入肾，故能纳气归元"},{"q":"白术补气健脾，宜采用的炮制方法是","o":["生用","煅用","炒焦用","炒炭用","麸炒用"],"a":4,"e":"白术苦甘温，补气健脾、燥湿利水、止汗、安胎，补气健脾宜麸炒用，麸炒后燥性缓和，健脾益气之力增强。生用燥湿利水力胜，煅用、炒焦用、炒炭用均非补气健脾之常法。麸炒借麦麸甘平之性，缓和白术燥烈，增强补脾和胃之效，故补气健脾多用麸炒品"},{"q":"患者肾阳不足，精血亏虚，眩晕耳鸣，阴疽日久不敛，尤宜选用的药物是","o":["杜仲","鹿茸","核桃仁","菟丝子","韭菜子"],"a":1,"e":"鹿茸甘咸温，壮肾阳、益精血、强筋骨、调冲任、托疮毒，肾阳不足、精血亏虚之眩晕耳鸣、腰膝酸软及阴疽日久不敛者用之，能温阳益精、托毒生肌。杜仲补肝肾、强筋骨、安胎；核桃仁补肾温肺、润肠；菟丝子补肾益精、养肝明目；韭菜子温补肝肾、壮阳固精，均无托疮毒、益精血峻补之力"},{"q":"大黄粉生用治疗上消化道出血，是因其能","o":["收敛止血","凉血止血","温经止血","泻火解毒","泻下攻积"],"a":1,"e":"大黄苦寒，泻下攻积、清热泻火、凉血止血、逐瘀通经，生用研粉内服治上消化道出血，是因其能凉血止血、降气泄热，并逐瘀生新，使血热得清、瘀血得去而血止。收敛止血属白及、仙鹤草；温经止血属艾叶、炮姜；泻火解毒、泻下攻积虽大黄所有，非止血之直接机制。大黄止血不留瘀，为其特点"},{"q":"治疗湿痹、筋脉拘挛、吐泻转筋病证，最宜选用的药物是","o":["木瓜","防己","豨莶草","秦艽","伸筋草"],"a":0,"e":"木瓜酸温，舒筋活络、和胃化湿，为治湿痹、筋脉拘挛及吐泻转筋之要药，湿痹拘急得之舒筋，吐泻伤津之转筋得之和胃生津而舒筋。防己祛风湿、止痛、利水；豨莶草祛风湿、利关节、解毒；秦艽祛风湿、清虚热；伸筋草祛风除湿、舒筋活络，皆无和胃化湿、治吐泻转筋之功"},{"q":"擅治肝郁气滞证的药物是","o":["陈皮","枳实","香附","木香","砂仁"],"a":2,"e":"香附辛微苦平，疏肝解郁、理气宽中、调经止痛，为疏肝理气之要药，肝郁气滞之胁肋胀痛、月经不调、痛经皆宜，故有气病之总司、女科之主帅之称。陈皮理气健脾、燥湿化痰；枳实破气消积、化痰散痞；木香行气调中止痛；砂仁化湿行气、温中止泻，均不专入肝经解郁"},{"q":"易损害肾脏，肾功能不全者禁用的药物是","o":["半夏","浮海石","胖大海","海蛤壳","马兜铃"],"a":4,"e":"马兜铃苦微寒，清肺化痰、止咳平喘，含马兜铃酸，有明显肾毒性，可致马兜铃酸肾病、肾功能衰竭，肾功能不全者禁用。半夏燥湿化痰、降逆止呕，浮海石清肺化痰、软坚散结，胖大海清肺化痰、利咽开音，海蛤壳清肺化痰、软坚散结，均无此类肾毒性。马兜铃及含马兜铃酸药物均须严控使用"},{"q":"治疗虚寒泄泻，宜用","o":["黄芩","丁香","黄连","吴茱萸","小茴香"],"a":3,"e":"吴茱萸辛热，散寒止痛、降逆止呕、助阳止泻，脾肾阳虚之虚寒泄泻、五更泄泻用之温脾暖肾、涩肠止泻，如四神丸中配补骨脂、肉豆蔻。黄芩、黄连苦寒，清热燥湿止痢，虚寒泄泻忌用；丁香温中降逆、温肾助阳，止泻力弱；小茴香散寒止痛、理气和胃，无止泻之专功"},{"q":"豨莶草治风湿痹痛兼高血压病的患者常配伍","o":["臭梧桐","独活","雷公藤","羌活","威灵仙"],"a":0,"e":"豨莶草祛风湿、利关节、解毒、降血压，臭梧桐祛风湿、通经络、降血压，二者相须为用，治疗风湿痹痛兼高血压病尤为适宜。独活、羌活祛风湿、止痛，威灵仙通经络、治骨鲠，均无降压作用；雷公藤祛风除湿、活血通络，毒性大，非高血压痹痛常规配伍。二药合用痹痛与血压兼顾"},{"q":"白前与旋覆花均具有的功效是","o":["降气消痰","降逆止呕","疏散风热","利气散结","凉血止血"],"a":0,"e":"白前降气化痰、止咳，旋覆花降气化痰、降逆止呕、行水，二者均能降气消痰，为治痰壅气逆、咳嗽痰多之常用药。降逆止呕仅旋覆花具备，白前无之；疏散风热属薄荷、蝉蜕；利气散结属瓜蒌、薤白；凉血止血属白茅根、侧柏叶。二药所共有者，唯降气消痰一端"},{"q":"治疗感冒发热，寒热往来，首选的药物是","o":["葛根","升麻","牛蒡子","蝉蜕","柴胡"],"a":4,"e":"柴胡辛苦微寒，解表退热、疏肝解郁、升举阳气，善治邪在少阳之寒热往来、胸胁苦满，为和解少阳之要药，感冒发热见寒热往来者首选。葛根解肌退热，升麻发表透疹、升阳举陷，牛蒡子疏散风热、利咽，蝉蜕疏散风热、退翳，均无和解少阳、治寒热往来之专能"},{"q":"葛根的功效不包括","o":["生津止渴","通经活络","升阳止泻","活血止痛","解肌退热"],"a":3,"e":"葛根解肌退热、生津止渴、升阳止泻、通经活络、透疹，无活血止痛之功。生津止渴用于热病烦渴、消渴；通经活络用于痹证、中风；升阳止泻用于脾虚泄泻、湿热泻痢；解肌退热用于外感发热、项背强痛。活血止痛多取延胡索、川芎、乳香、没药之属，与葛根功用的升散、生津不同"},{"q":"安神药主归","o":["心、脾经","肝、胆经","心、肝经","肝、肾经","心、肺经"],"a":2,"e":"安神药主入心、肝经，心藏神、肝藏魂，神志活动与心肝关系最密，如朱砂、磁石、酸枣仁、远志皆归心肝。心、脾经多属补益气血药；肝、胆经多属疏肝利胆药；肝、肾经多属滋阴潜阳药；心、肺经多属清心润肺药。安神重在镇心、养肝，故以心肝经为主"},{"q":"药性和缓，且微温不烈，外感风寒、风热表证均可，还用于疮疡初起兼有表证的药物是","o":["桂枝","荆芥","苍耳子","香薷","紫苏叶"],"a":1,"e":"荆芥辛微温，药性和缓，微温不烈，既能解表散风，风寒、风热表证皆可应用，又能透疹、消疮，疮疡初起兼有表证者亦宜。桂枝辛温，专于散风寒；苍耳子散风寒、通鼻窍，有毒；香薷发汗解表、化湿和中，主夏月感寒；紫苏叶发汗解表、行气宽中。荆芥性平和，风寒风热表证与疮疡初起皆可随证配用"},{"q":"既能清虚热，又能解毒疗疮的药物是","o":["连翘","黄连","银柴胡","胡黄连","白薇"],"a":4,"e":"白薇苦咸寒，清热凉血、利尿通淋、解毒疗疮，既能清虚热、凉血以治阴虚内热、产后虚热，又能解毒疗疮以治疮痈肿毒、咽喉肿痛。连翘清热解毒、消肿散结，长于清心火、散上焦热；黄连清热燥湿、泻火解毒；银柴胡、胡黄连退虚热、清疳热，均无解毒疗疮之功。白薇清虚热兼解毒，故为所宜"},{"q":"既能发汗解表，又能利水消肿的一组药物是","o":["麻黄、香薷","香薷、紫苏叶","荆芥、防风","紫苏、生姜","麻黄、桂枝"],"a":0,"e":"麻黄发汗解表、宣肺平喘、利水消肿，香薷发汗解表、化湿和中、利水消肿，二者均能发汗解表、利水消肿，为夏季及水肿兼表证常用药对。紫苏叶发汗解表、行气宽中，无利水之功；荆芥、防风祛风解表；桂枝发汗解肌、温通经脉；麻黄、桂枝相须重在发汗解表，无利水消肿之共同功效"},{"q":"续断常用于治疗的病证有","o":["气滞血瘀、痰热互结","痰热咳喘、湿热泻痢","跌扑损伤、筋伤骨折","五更泄泻、腰膝酸软","肾虚作喘、筋伤骨折"],"a":2,"e":"续断苦辛微温，补肝肾、强筋骨、续折伤、止崩漏、安胎，跌扑损伤、筋伤骨折、腰膝酸软及胎动不安皆宜。气滞血瘀、痰热互结非其所主；痰热咳喘、湿热泻痢宜清化之品；五更泄泻宜温补脾肾；肾虚作喘宜补肾纳气。续断既能补肝肾，又能续筋骨、疗跌扑损伤，故为最宜"},{"q":"麻黄的功效是","o":["发汗解表，利水平喘，散寒止痛","发汗解表，宣肺平喘，利水消疮","发汗解表，宣肺平喘，利水消肿","发汗解表，宣肺平喘，通阳散结","发汗解表，宣肺平喘，化湿通淋"],"a":2,"e":"麻黄辛微苦温，发汗解表、宣肺平喘、利水消肿，为发汗解表之要药，主治风寒感冒、咳嗽气喘及风水水肿。利水平喘、散寒止痛非其功效表述；利水消疮不见于本草；通阳散结为薤白、瓜蒌之能；化湿通淋属萆薢、车前子之类。麻黄发汗力强，兼能宣肺利水，故功效当为发汗解表、宣肺平喘、利水消肿"},{"q":"下列哪一项不属于苏木的主治范围","o":["跌打损伤","痈肿疮毒","心腹瘀痛","耳鸣耳聋","血瘀经闭"],"a":3,"e":"苏木甘咸平，活血疗伤、祛瘀通经、止痛，主治跌打损伤、骨折筋伤、心腹瘀痛、血瘀经闭及痈肿疮毒。耳鸣耳聋多属肝肾亏虚、肝胆火旺或痰火郁结，当滋补肝肾、清肝泻火或化痰开窍，活血祛瘀非其主治。跌打损伤、心腹瘀痛、血瘀经闭皆取其活血祛瘀止痛，痈肿疮毒亦用其散瘀消肿"},{"q":"升降浮沉是指","o":["药物的作用趋向性","药物的作用部位的选择性","药物有无毒副作用","药物性能峻猛与否","药物有无补泻作用"],"a":0,"e":"升降浮沉指药物作用于人体的趋向性，升浮者趋向于上、向外，具有升阳、发表、祛风、散寒、涌吐、开窍等作用；沉降者趋向于下、向内，具有泻下、清热、重镇安神、平肝潜阳、降逆止呕、收敛固涩等作用。作用部位的选择性属归经；有无毒副作用、性能峻猛与否、有无补泻作用均非升降浮沉之意"},{"q":"血热夹瘀之出血病证，宜选用的药物是","o":["地榆","茜草","侧柏叶","血余炭","白茅根"],"a":1,"e":"茜草苦寒，凉血止血、活血化瘀、通经，止血而不留瘀，血热夹瘀之出血证用之最宜，尤宜于血热兼有瘀滞之吐血、衄血、崩漏等。地榆、侧柏叶、白茅根虽凉血止血，无活血散瘀之功；血余炭收敛止血、化瘀力弱。茜草性寒能清血热，味苦能行血瘀，故为血热夹瘀出血之要药"},{"q":"功能袪风湿，利关节，解毒。有生泄熟补特点的药物是","o":["豨莶草","臭梧桐叶","海桐皮","络石藤","老鹳草"],"a":0,"e":"豨莶草苦辛寒，祛风湿、利关节、解毒、降血压，生用性寒偏于清热利湿、祛风解毒，熟用性温偏于补肝肾、强筋骨，故有生泄熟补之说。臭梧桐祛风湿、通经络、降血压；海桐皮祛风湿、通经络、止痛；络石藤祛风通络、凉血消肿；老鹳草祛风通络、止泻，均无生泄熟补之特点"},{"q":"痰饮水肿，夜盲眼目昏涩，治宜选用的药物是","o":["茯苓","苍术","泽泻","厚朴","地肤子"],"a":1,"e":"苍术辛苦温，燥湿健脾、祛风散寒、明目，痰饮水肿因湿聚而成，用之燥湿健脾以绝生痰之源；夜盲、眼目昏涩因肝脾不足、精血不能上荣，苍术能明目，故治夜盲。茯苓、泽泻利水渗湿而无明目之功；厚朴燥湿消痰、下气除满；地肤子清热利湿、止痒，皆不治夜盲"},{"q":"下列哪项不是穿山甲的功效","o":["活血消癥","通经下乳","搜风通络","消肿排脓","消积止痛"],"a":4,"e":"穿山甲咸微寒，活血消癥、通经下乳、消肿排脓、搜风通络，主治癥瘕积聚、经闭、乳汁不通、痈肿疮毒及风湿痹痛。消积止痛为三棱、莪术、延胡索之能，非穿山甲所具。活血消癥取其破血逐瘀，通经下乳取其走窜通络，消肿排脓取其托毒外出，搜风通络取其性善走窜，皆与消积止痛不同"},{"q":"蜜炙黄芪一般不用于","o":["肺气亏虚","气血不足","中气下陷","脾气亏虚","疮疡脓成不溃"],"a":4,"e":"黄芪蜜炙后甘温，补中益气、升阳举陷之力增强，肺气亏虚、气血不足、中气下陷、脾气亏虚皆宜蜜炙品。疮疡脓成不溃需托毒排脓、生肌，多取生黄芪走表托毒，蜜炙黄芪偏于补中，非其所宜。生黄芪走表、蜜黄芪走里，故托毒排脓、固表利水多用生品，补中益气多用蜜炙品"},{"q":"具有消风祛斑作用，可用于斑秃、白癜风的活血药是","o":["苏木","土鳖虫","马钱子","骨碎补","自然铜"],"a":3,"e":"骨碎补苦温，补肾强骨、续伤止痛、活血，且能消风祛斑，外用或内服可治斑秃、白癜风，取其温通活血、祛风生新之力。苏木活血疗伤、祛瘀通经；土鳖虫破血逐瘀、续筋接骨；马钱子通络止痛、散结消肿，有大毒；自然铜散瘀止痛、接骨疗伤，均无消风祛斑、治斑秃白癜风之用"},{"q":"白鲜皮与防风的共同主治是","o":["麻疹不透","鼻渊头痛","风寒感冒","破伤风证","风疹瘙痒"],"a":4,"e":"白鲜皮苦寒，清热燥湿、祛风解毒、止痒；防风辛甘微温，祛风解表、胜湿止痛、止痉，二药均有祛风止痒之功，风疹瘙痒皆可用之。麻疹不透宜薄荷、蝉蜕、紫草；鼻渊头痛宜苍耳子、辛夷、白芷；风寒感冒宜麻黄、桂枝；破伤风证宜防风、天麻、白附子，非二药共同主治"},{"q":"既可清肺化痰、利咽开音，又可润肠通便的药为","o":["白果","菊花","贝母","胖大海","苦杏仁"],"a":3,"e":"胖大海甘寒，清肺化痰、利咽开音、润肠通便，主治肺热声哑、咽喉肿痛、咳嗽痰多及燥热便秘。白果敛肺定喘、止带缩尿；菊花疏散风热、清肝明目；贝母清热化痰、润肺散结；苦杏仁降气止咳平喘、润肠通便，均无利咽开音之能。胖大海轻清上行利咽喉，质润下行通腑气，故二者兼备"},{"q":"干姜治疗亡阳证常与哪项配伍","o":["生姜","炮姜","肉桂","附子","高良姜"],"a":3,"e":"干姜辛热，温中散寒、回阳通脉、温肺化饮，治亡阳证须与附子相须为用，附子回阳救逆、补火助阳，干姜助其回阳并温中，如四逆汤。生姜解表散寒、温中止呕；炮姜温经止血、温中止痛；肉桂补火助阳、引火归元；高良姜温胃止痛、散寒止呕，均无回阳救逆之功。干姜得附子，回阳之力大增"},{"q":"下列除哪项以外均是木香的主治病证","o":["肝胆失疏之湿热黄疸","脾胃气虚之食少吐泻","下痢腹痛、里急后重","脾胃气滞之脘腹胀痛","肺气不宣之咳嗽痰多"],"a":4,"e":"木香辛苦温，行气调中止痛、健脾消食、理气，主入脾胃、大肠经，善治脾胃气滞之脘腹胀满疼痛、食少吐泻、下痢腹痛里急后重及肝胆湿热黄疸等。肺气不宣之咳嗽痰多当宣肺化痰止咳，用桔梗、杏仁、紫菀之属，非木香所主。木香专入中焦，行胃肠之气，为治气滞腹痛、痢疾后重之要药，不入肺经宣肺止咳"},{"q":"中药炮制的常用液体辅料不含以下哪项","o":["油","蜜","醋","姜汁","盐水"],"a":0,"e":"中药炮制常用液体辅料有酒、醋、盐水、姜汁、蜜、甘草汁、黑豆汁、米泔水、胆汁等，分别具活血、入肝、入肾、温中、润燥、解毒等作用。油虽个别用于特殊炮制，一般不列入常用液体辅料之列。酒、醋、姜汁、盐水皆为最常用者，油非通例，故不属于常用液体辅料"},{"q":"药性苦寒，善清利肌表之湿热而解毒疗疮，用于湿疮瘙痒的是","o":["金钱草","虎杖","茵陈","萆薢","石韦"],"a":2,"e":"茵陈苦辛微寒，清利湿热、利胆退黄，为治黄疸之要药，且能清利肌表湿热、解毒疗疮，煎汤外洗可治湿疮瘙痒。金钱草利湿退黄、利尿通淋、解毒消肿；虎杖利湿退黄、清热解毒、散瘀止痛；萆薢利湿去浊、祛风除痹；石韦利尿通淋、清肺止咳，皆非清利肌表湿热、治湿疮瘙痒之首选"},{"q":"来源于石竹科植物孩儿参的块根的是","o":["人参","党参","玄参","太子参","南沙参"],"a":3,"e":"太子参甘微苦平，益气健脾、生津润肺，为石竹科植物孩儿参的干燥块根，补气之力较人参、党参为缓，宜于脾虚体倦、食欲不振及气阴不足之轻证。人参为五加科人参根；党参为桔梗科党参根；玄参为玄参科块根；南沙参为桔梗科沙参根，来源均不同。太子参又名孩儿参，来源须辨明"},{"q":"辛温有毒，性善走窜，通达内外，功似全蝎而止痉之力尤甚的是","o":["地龙","蜈蚣","僵蚕","蝉蜕","蕲蛇"],"a":1,"e":"蜈蚣辛温有毒，性善走窜，通达内外，能息风止痉、通络止痛、攻毒散结，功似全蝎而止痉之力尤甚，常用于急慢惊风、破伤风、癫痫及痹痛、疮毒。地龙咸寒，清热息风、通络平喘；僵蚕祛风定惊、化痰散结；蝉蜕疏散风热、利咽退翳；蕲蛇祛风通络、止痉，均无辛温大毒、止痉之力尤甚之特点"},{"q":"出血兼有瘀滞者，不宜选用的药物是","o":["蒲黄","藕节","棕榈炭","花蕊石","血余炭"],"a":2,"e":"棕榈炭苦涩平，收敛止血，性偏收涩，无散瘀之力，出血兼有瘀滞者用之易留瘀碍行，故不宜选用。蒲黄、花蕊石、血余炭、藕节均能止血兼散瘀，止血而不留瘀，适用于出血夹瘀之证。棕榈炭收涩止血力强，但无化瘀之功，故瘀血内阻之出血当忌用或配伍化瘀药"},{"q":"善治头痛，无论风寒、风热、风湿、血瘀、血虚皆可随证选用的是","o":["羌活","藁本","白芷","川芎","细辛"],"a":3,"e":"川芎辛温，活血行气、祛风止痛，为血中之气药，上行头目、下达血海、外彻皮毛、旁通四肢，治头痛无论风寒、风热、风湿、血瘀、血虚皆可随证配伍，故有头痛不离川芎之说。羌活、藁本善治太阳、阳明经头痛；白芷治阳明头痛；细辛治少阴头痛，皆各有专经，不及川芎通用"},{"q":"具有行气调中止痛功效的药物是","o":["柿蒂","香附","木香","乌药","薤白"],"a":2,"e":"木香辛苦温，行气调中止痛、健脾消食、理气，主入脾胃、大肠经，善治脾胃气滞之脘腹胀满疼痛、食少吐泻及大肠气滞之里急后重。柿蒂降气止呃；香附疏肝解郁、调经止痛；乌药行气止痛、温肾散寒；薤白通阳散结、行气导胸痹，均非行气调中止痛之主药。木香为行气调中之要药"},{"q":"理气药中，能降气止呃的是","o":["甘松","乌药","柿蒂","荔枝核","土木香"],"a":2,"e":"柿蒂苦涩平，专人胃经，降气止呃，为治呃逆之要药，无论寒热虚实之呃逆皆可随证配伍。甘松理气止痛、开郁醒脾；乌药行气止痛、温肾散寒；荔枝核行气散结、祛寒止痛；土木香行气止痛、健脾和胃，均无降气止呃之专能。柿蒂善降胃气上逆，故呃逆用之最宜"},{"q":"具有固精缩尿、明目、止泻功效的药物有","o":["肉苁蓉","菟丝子","补骨脂","淫羊藿","益智仁"],"a":1,"e":"菟丝子辛甘平，补肾益精、养肝明目、止泻、安胎、固精缩尿，兼具固精缩尿、明目、止泻三功。肉苁蓉补肾阳、益精血、润肠通便；补骨脂温肾助阳、纳气、温脾止泻；淫羊藿补肾阳、强筋骨、祛风湿；益智仁温脾止泻摄唾、暖肾固精缩尿，均无明目之功。菟丝子平补肝肾，三效兼备"},{"q":"治疗阴虚血热的出血证，宜首选","o":["艾叶","茜草","三七","仙鹤草","墨旱莲"],"a":4,"e":"墨旱莲甘酸寒，滋补肝肾、凉血止血，阴虚血热之出血证，症见吐血、衄血、尿血、便血及崩漏者宜之，常与女贞子配伍即二至丸。艾叶温经止血，性温不宜阴虚血热；茜草凉血止血、活血，养阴之力不足；三七化瘀止血；仙鹤草收敛止血、补虚，均无滋阴之功。墨旱莲滋阴兼凉血，故为首选"},{"q":"细辛的主治病证不包括","o":["风寒表证","阳虚外感","肺热喘咳","头风头痛","风寒湿痹"],"a":2,"e":"细辛辛温，祛风散寒、通窍止痛、温肺化饮，主治风寒表证、阳虚外感、头风头痛、风寒湿痹及寒饮喘咳。肺热喘咳当清肺泻热、化痰止咳，用黄芩、桑白皮、葶苈子之属，细辛温肺化饮，宜于寒饮而非肺热。风寒表证、阳虚外感、头风头痛、风寒湿痹皆取其辛温散寒通窍止痛"},{"q":"下列哪项不是寒凉性所表示的作用","o":["清热","凉血","泻火","化湿","解热毒"],"a":3,"e":"寒凉性药物具有清热、泻火、凉血、解毒、滋阴、降火等作用，适用于热证、阳证。化湿多取芳香温燥之品，如藿香、佩兰、砂仁、厚朴之属，性多温，用于湿浊内阻，非寒凉性所表示的作用。清热、凉血、泻火、解热毒皆属寒凉药的效应，化湿则属温性药之功，故不属寒凉性作用"},{"q":"以下哪类药物不属于妊娠禁用药","o":["剧毒药，如砒霜","破血逐瘀药，如三棱","破气行滞药，如枳实","峻下逐水药，如牵牛子","辛香走窜力强药，如麝香"],"a":2,"e":"妊娠禁用药多为剧毒、峻下逐水、破血逐瘀及辛香走窜力强者，如砒霜、三棱、牵牛子、麝香等，毒性大或药性峻猛，易致流产。破气行滞之枳实药力较缓，一般属妊娠慎用药而非禁用药，行气破气之中病即止。剧毒药、破血逐瘀药、峻下逐水药、辛香走窜力强药皆在禁用之列"},{"q":"肝郁气滞，月经不调，下列药物首选","o":["陈皮","青皮","香附","薤白","木香"],"a":2,"e":"香附疏肝解郁、理气宽中、调经止痛，为妇科调经之要药，肝郁气滞之月经不调、痛经、经闭及胁肋胀痛首选之。陈皮理气健脾、燥湿化痰；青皮破气疏肝、消积化滞，力猛不利于调经；薤白通阳散结、行气导滞；木香行气调中，均不专于疏肝调经。香附入肝经，疏肝气而和血调经，故为首选"},{"q":"磁石的功效不包括","o":["平肝潜阳","镇静安神","聪耳明目","息风止痉","纳气定喘"],"a":3,"e":"磁石咸寒，镇惊安神、平肝潜阳、聪耳明目、纳气定喘，无息风止痉之功。息风止痉多取羚羊角、钩藤、天麻、全蝎、蜈蚣之类，为肝风内动、惊痫抽搐所宜。平肝潜阳、镇静安神、聪耳明目、纳气定喘皆磁石所有，常用于心悸失眠、头晕目眩、耳鸣耳聋及肾虚气喘，唯息风止痉非其能"},{"q":"治疗尿频遗尿、腹中冷痛、口多唾涎常选用的药物是","o":["补骨脂","肉苁蓉","益智仁","核桃仁","淫羊藿"],"a":2,"e":"益智仁辛温，温脾止泻摄唾、暖肾固精缩尿，脾寒泄泻、腹中冷痛、口多唾涎及肾虚遗尿尿频皆宜。补骨脂温肾助阳、温脾止泻、纳气平喘；肉苁蓉补肾阳、益精血、润肠；核桃仁补肾温肺、润肠；淫羊藿补肾阳、强筋骨、祛风湿，均无温脾摄唾之专能。益智仁温脾暖肾，固涩之力尤佳"},{"q":"能解鱼蟹及半夏、天南星毒的药物是","o":["生姜","藿香","紫苏叶","香薷","白芷"],"a":0,"e":"生姜辛微温，解表散寒、温中止呕、化痰止咳、解毒，能解鱼蟹之毒及半夏、天南星之毒，故与半夏、天南星同用可以制其毒性。藿香化湿止呕、发表解暑；紫苏叶解表散寒、行气宽中，亦解鱼蟹毒但不解半夏、天南星毒；香薷发汗解表、化湿和中；白芷祛风解表、燥湿止痛，皆非解半夏、南星毒之品"},{"q":"患者，男，52岁。患肾病多年，水肿、小便不利，舌质暗，有瘀斑。证属水瘀互阻之水肿。最宜选用的药是","o":["丹参","红花","桃仁","益母草","车前子"],"a":3,"e":"益母草苦辛微寒，活血调经、利尿消肿、清热解毒，既能活血化瘀以通络，又能利水消肿以行水，水瘀互阻之水肿、小便不利而舌暗有瘀斑者最宜。丹参、红花、桃仁虽活血祛瘀，无利水消肿之功；车前子利尿通淋、渗湿止泻，无活血之能。益母草兼活血与利水，故为水瘀互阻水肿之要药"},{"q":"患者产后血虚，低热不退，治疗宜与当归、人参同用的药物是","o":["生石膏","白薇","青蒿","白芍","熟地黄"],"a":1,"e":"白薇苦咸寒，清热凉血、利尿通淋、解毒疗疮，善清虚热、凉血，产后血虚、低热不退者，与当归、人参同用，即白薇汤之意，养血益气与清热凉血并行。生石膏清气分实热，非虚热所宜；青蒿清虚热、截疟，多治温病夜热早凉；白芍养血敛阴；熟地黄滋阴补血，均无清虚热凉血之专功"},{"q":"尤善清心经实火的药组是","o":["石膏、知母","黄芩、龙胆","芦根、黄芩","黄柏、连翘","黄连、栀子"],"a":4,"e":"黄连苦寒，清热燥湿、泻火解毒，尤善清心经实火；栀子苦寒，泻火除烦、清热利湿、凉血解毒，通泻三焦之火，二药相须，清心泻火之力尤著。石膏、知母清气分实热；黄芩清上焦肺火，龙胆清肝胆火；芦根清热生津；黄柏清下焦虚火，连翘清心火、散上焦热，皆非清心经实火之最佳药组"},{"q":"月季花的功效是","o":["活血调经，疏肝解郁","活血调经，凉血祛风","活血行气，通络止痛","活血行气，下乳消痈","活血补血，调经止痛"],"a":0,"e":"月季花甘温，活血调经、疏肝解郁、消肿，主治月经不调、痛经、经闭及肝郁气滞之胸胁胀痛、瘰疬。凉血祛风属牡丹皮、赤芍之类；活血行气、通络止痛属川芎、延胡索；活血行气、下乳消痈属穿山甲、王不留行；活血补血、调经止痛属当归、鸡血藤。月季花调经兼疏肝，故为活血调经、疏肝解郁之品"},{"q":"治疗湿热黄疸，肝火头痛，应首选的药是","o":["夏枯草","天麻","龙胆","菊花","白鲜皮"],"a":2,"e":"龙胆苦寒，归肝胆经，既能清热燥湿以治湿热黄疸，又能泻肝胆实火以治肝火头痛、惊风抽搐，两证兼顾故为首选。夏枯草长于清肝明目散结，主治目赤肿痛、瘰疬；天麻、菊花均偏平肝息风或疏散风热，无燥湿退黄之力；白鲜皮虽能清热燥湿止痒，却无泻肝胆火之功"},{"q":"金钱草是全草入药，其法定的入药品种是","o":["豆科植物过路黄","唇形科植物活血丹","报春花科植物过路黄","伞形科植物白毛胡天荽","旋花科植物马蹄金"],"a":2,"e":"金钱草正品为报春花科植物过路黄的全草，故法定入药品种即此。唇形科活血丹为江苏金钱草（连钱草），旋花科马蹄金为广东金钱草，均属地区习用品而非正品；豆科过路黄、伞形科白毛胡天荽并非金钱草来源，属混淆品种"},{"q":"大血藤与败酱草的共同功效是","o":["祛瘀止痛","祛风止痛","散寒止痛","行气止痛","消食止痛"],"a":0,"e":"大血藤与败酱草同为清热解毒、活血止痛（祛瘀止痛）之品，均治肠痈腹痛、跌打瘀痛，故共有功效为祛瘀止痛。祛风止痛多属独活、威灵仙等祛风湿药；散寒止痛为附子、干姜之类；行气止痛如延胡索、木香；消食止痛则属山楂、麦芽，均非二药所长"},{"q":"雄黄内服的用量范围是","o":["0.05～0.1g","0.1～0.2g","0.15～0.2g","0.5～1g","1～2g"],"a":0,"e":"雄黄内服多入丸散，用量范围为0.05～0.1g，因含砷有毒不可量大或久服。0.5～1g、1～2g已远超安全剂量，易致中毒；0.15～0.2g亦非法定常用量。本品外用可适量，内服须严格控制在小量范围内"},{"q":"水牛角不具有的功效是","o":["清心","凉血","活血","解毒","定惊"],"a":2,"e":"水牛角咸寒，功能清热凉血、解毒定惊，为犀角替代品，主治热盛神昏、发斑发狂及小儿惊风。本品无活血之功，故不具有的功效为活血。清心、凉血、解毒、定惊皆其所有：清心泻火可治神昏谵语，凉血可治血热发斑，解毒可治疮疡，定惊可治抽搐"},{"q":"用治两侧头痛宜首选","o":["归太阳经的药物","归太阴经的药物","归阳明经的药物","归少阳经的药物","归厥阴经的药物"],"a":3,"e":"头两侧属少阳经循行部位，故两侧头痛（少阳头痛）宜首选归少阳经的药物，如柴胡、黄芩。太阳经头痛多在头后及项背，阳明经头痛在前额眉棱，厥阴经头痛在巅顶，太阴经头痛多伴腹胀便溏，归经各异，不可混用"},{"q":"柴胡与薄荷均具有的功效是","o":["疏肝","透疹","升阳","解毒","明目"],"a":0,"e":"柴胡与薄荷均能疏肝解郁，主治肝郁气滞之胁肋胀痛、月经不调，故共有功效为疏肝。透疹、利咽为薄荷独有而柴胡无；升阳举陷是柴胡所长，薄荷并不升阳；解毒、明目亦非二者共有，薄荷可清利头目但无解毒之功"},{"q":"药性苦、涩，凉，主要用于治疗绦虫病的药物是","o":["雷丸","槟榔","苦楝皮","鹤草芽","使君子"],"a":3,"e":"鹤草芽味苦涩、性凉，专入肝、小肠经，为驱杀绦虫的要药，故符合苦涩凉且治绦虫的描述。雷丸虽治绦虫但性寒味微苦而无涩味；槟榔味苦辛性温，行气导滞；苦楝皮苦寒，治蛔蛲虫；使君子甘温，主治蛔虫病，性味与主治均不相符"},{"q":"临床常用党参代替人参入药，以下病证中不宜应用党参的是","o":["脾虚食少便溏","气虚津伤口渴","肺气虚之咳喘","元气虚极欲脱证","气血两虚之头晕心悸"],"a":3,"e":"党参补中益气、健脾益肺，作用平和可代人参治脾虚食少便溏、肺虚咳喘、气血两虚及气虚津伤口渴，但无大补元气、复脉固脱之力。元气虚极欲脱证唯人参能峻补元气以救脱，党参力薄不能胜任，故不宜应用"},{"q":"牛膝、益母草均有的功效是","o":["活血、破气","活血、生肌","活血、润肠","活血、利水","活血、解毒"],"a":3,"e":"牛膝与益母草均能活血通经、利尿（利水），主治瘀血经闭及水肿小便不利，故共有功效为活血、利水。破气为枳实、青皮所主，生肌为乳香没药之能，润肠属当归、火麻仁，解毒为蒲公英等清热药功效，皆非二药共有"},{"q":"治乳痈、乳癖、乳房胀痛，宜选用的药物是","o":["夏枯草","淡竹叶","青葙子","决明子","密蒙花"],"a":0,"e":"夏枯草苦辛寒，归肝胆经，清肝火、散郁结，主治乳痈、乳癖及乳房胀痛，为治乳房疾患常用药。淡竹叶清心利尿，青葙子、决明子、密蒙花均为清肝明目之品，主治目赤翳障，无散结消痈、治乳癖之功"},{"q":"下列哪项不属于中药配伍的目的","o":["增强疗效","减轻毒副作用","扩大治疗范围","增加药物的反应性","适应复杂病情"],"a":3,"e":"中药配伍目的在于增强疗效、降低毒副作用、扩大治疗范围、适应复杂病情以及延缓耐药性等。增加药物的反应性并非配伍目的，反而配伍常是为缓和或制约药物偏性、减少不良反应，故该项不属于配伍目的"},{"q":"属于配伍禁忌的是","o":["人参与藜芦","人参与海藻","人参与大戟","人参与莱菔子","人参与五倍子"],"a":0,"e":"藜芦反人参、沙参、丹参、玄参、细辛、芍药，人参与藜芦同用属十八反，为配伍禁忌。人参配五倍子、莱菔子属相恶（降效）而非禁忌；海藻、大戟反甘草，与人参无涉，故其余配伍不属相反禁忌"},{"q":"煅龙骨功效长于","o":["平肝潜阳","息风止痉","收敛固涩","聪耳明目","镇惊安神"],"a":2,"e":"龙骨生用镇惊安神、平肝潜阳，煅后则收敛固涩之力增强，长于敛汗、涩精、止带、固脱，故煅龙骨功效长于收敛固涩。平肝潜阳、镇惊安神为生龙骨所长；息风止痉属羚羊角、钩藤；聪耳明目为磁石等品，均非煅制后所主"},{"q":"能上助心阳，中温脾阳，下补肾阳的药物是","o":["附子","花椒","细辛","高良姜","吴茱萸"],"a":0,"e":"附子辛热，走十二经，上助心阳以通脉，中温脾阳以助运，下补肾阳以益火，为补火助阳、温里散寒之要药。花椒、高良姜温中为主，细辛解表温肺，吴茱萸疏肝下气，均无上中下三焦阳气并补之能"},{"q":"均具有袪风湿，通络止痛功效的药物是","o":["秦艽、五加皮、威灵仙","威灵仙、秦艽、海桐皮","桑寄生、秦艽、松节","狗脊、威灵仙、寻骨风","秦艽、千年健、海风藤"],"a":1,"e":"威灵仙、秦艽、海桐皮三药均能祛风湿、通经络、止痛，主治风湿痹痛、筋脉拘挛，故为正确答案。五加皮、桑寄生、狗脊兼能补肝肾强筋骨，松节、寻骨风、千年健、海风藤虽祛风湿但或偏温燥、或专通络，均不具备三药共有的完整组合"},{"q":"鸡血藤、当归的共同功效是","o":["补血、活血","补血、止血","活血、止血","凉血、活血","活血、行气"],"a":0,"e":"鸡血藤与当归均能补血、活血，主治血虚萎黄、月经不调及瘀血诸证，故共有功效为补血、活血。止血为白及、三七所主；凉血属生地、丹皮；行气为香附、川芎之类，均非二药共有之效"},{"q":"关于朱砂的用法用量及使用注意，不正确的是","o":["孕妇忌服","宜暂用，不可久服","研末服，每次0、3~1g","醋淬，打碎后装瓶备用","肝肾功能不全者忌服"],"a":3,"e":"朱砂主含硫化汞，忌火煅，宜研末冲服或入丸散，每次0.3～1g，孕妇及肝肾功能不全者忌服，只可暂用不可久服。醋淬、打碎装瓶备用是赭石、磁石等矿物药的炮制用法，与朱砂无关，且火煅析出水银有毒，故该项不正确"},{"q":"具有凉肝息风作用的药物是","o":["温热药","寒凉药","升浮药","平性药","甘淡药"],"a":1,"e":"凉肝息风指清泄肝热以平息肝风，适用于热极生风之高热抽搐，羚羊角、牛黄等属此类，故具凉肝息风作用的为寒凉药。温热药反助热，升浮药主上行外达，平性药作用平和，甘淡药多补益渗利，均不能凉肝息风"},{"q":"以下哪个是云南的道地药材","o":["阿胶","三七","附子","人参","菊花"],"a":1,"e":"三七主产云南文山，为云南道地药材，善化瘀止血、活血定痛。阿胶以山东东阿为道地，附子主四川，人参以东北为佳，菊花以浙江、安徽等地著名，产地均与云南不符"},{"q":"性味甘，平。功能祛风，通络，活血，下乳的药物是","o":["老鹳草","雷公藤","海桐皮","丝瓜络","络石藤"],"a":3,"e":"丝瓜络味甘性平，功能祛风通络、活血、下乳，主治风湿痹痛、胸胁胀痛及乳汁不下，故描述符合。老鹳草祛风通络止泻，雷公藤有大毒且祛风除湿力强，海桐皮、络石藤均祛风通络但无下乳之功，性味亦异"},{"q":"川贝母与浙贝母相同的功效是","o":["润肺止咳，开郁","温肺化痰，止咳","清热化痰，散结","清热化痰，开郁","润肺化痰，散结"],"a":2,"e":"川贝母与浙贝母均能清热化痰、散结消痈，主治痰热咳嗽及瘰疬疮痈，故相同功效为清热化痰、散结。润肺止咳为川贝母独有，浙贝母性偏苦泄无润肺之能；温肺化痰属半夏、干姜；开郁化痰亦非二者共有"},{"q":"下列哪项是甘味药的作用","o":["温中止痛","缓急止痛","理气止痛","化瘀止痛","祛风止痛"],"a":1,"e":"甘味药能补益、和中、缓急、调和药性，缓急止痛即其典型作用，如甘草、饴糖治脘腹挛急疼痛。温中止痛属辛热药如干姜、花椒；理气止痛为香附、延胡索；化瘀止痛属五灵脂、乳香；祛风止痛为独活、威灵仙"},{"q":"木香、黄连均可治疗","o":["脾虚证","食积腹痛","胃热呕吐","湿热痢疾","脾胃气滞证"],"a":3,"e":"木香行气止痛、健脾消食，善治痢疾里急后重；黄连清热燥湿、泻火解毒，为治湿热痢疾要药，二者均可治湿热痢疾。脾虚证、脾胃气滞证非黄连所宜，胃热呕吐、食积腹痛亦非二者共同主治"},{"q":"患者阴虚发热，骨蒸潮热，心烦盗汗，宜选用","o":["牡丹皮","地骨皮","栀子","竹叶","黄芩"],"a":1,"e":"地骨皮甘寒，清虚热、凉血，善治阴虚发热、骨蒸潮热及盗汗，并能清肺降火，符合阴虚发热骨蒸盗汗之选。牡丹皮清虚热而无汗骨蒸为宜，栀子、黄芩清热燥湿泻火，竹叶清心利尿，均非治阴虚盗汗之品"},{"q":"为治疗肝胃不和，呕吐，吐酸要药的是","o":["生姜","紫苏","藿香","竹茹","吴茱萸"],"a":4,"e":"吴茱萸辛热，归肝脾胃肾经，能疏肝下气、温中燥湿、制酸止痛，为治肝胃不和、呕吐吞酸的要药。生姜、紫苏、藿香重在解表化湿止呕，竹茹清胃热止呕，均不能疏肝制酸，不适于肝胃不和之吐酸"},{"q":"既能活血补血，又能舒筋活络的药是","o":["大血藤","鸡血藤","络石藤","忍冬藤","首乌藤"],"a":1,"e":"鸡血藤苦甘温，既能补血活血，又能舒筋活络，主治血虚萎黄、月经不调及风湿痹痛、肢体麻木。大血藤清热解毒活血止痛而无补血之功；络石藤、忍冬藤、首乌藤虽通络但或凉血、或养血安神，均不兼补血"},{"q":"某医师治疗诸淋涩痛，擅用海金沙，此药味甘、咸，性寒。其主要功效是","o":["清热利尿，通气下乳","利尿通淋，活血通经","清热利尿，通淋","清热利湿，通淋止痛","利尿通淋，凉血止血"],"a":3,"e":"海金沙甘咸寒，功能清热利湿、通淋止痛，善治诸淋涩痛，尤宜于石淋、热淋，故其主要功效如此。通气下乳为木通、通草之能；活血通经属牛膝；凉血止血为白茅根、小蓟所主，均非海金沙功效"},{"q":"善清大肠湿热及血分热毒的药物是","o":["鱼腥草","紫花地丁","金荞麦","蒲公英","白头翁"],"a":4,"e":"白头翁苦寒，归大肠经，清热解毒、凉血止痢，专清大肠湿热及血分热毒，为治热毒血痢的要药。鱼腥草清肺热、紫花地丁解疔毒、金荞麦清肺化痰、蒲公英消痈散结，虽均清热解毒，但均不入大肠血分以治血痢"},{"q":"平补肺脾肾之气阴，且补而兼涩、补而不腻的药物是","o":["党参","山药","黄芪","人参","太子参"],"a":1,"e":"山药甘平，归脾肺肾经，平补肺脾肾之气阴，且补而兼涩、补而不腻，主治脾虚食少、肺虚喘咳、肾虚遗精及消渴。党参、太子参仅补脾肺之气，黄芪补气升阳，人参峻补元气，均无兼涩固肾、平补三脏气阴之特点"},{"q":"小便涩痛，淋沥不尽者，宜选用的药物是","o":["槐花","茜草","白茅根","花蕊石","苎麻根"],"a":2,"e":"白茅根甘寒，凉血止血、清热利尿，能清膀胱湿热而治小便涩痛、淋沥不尽。槐花、茜草、花蕊石、苎麻根虽均能止血，但无清热利尿通淋之功，主治下部出血或血热出血，不适于淋证涩痛"},{"q":"治疗惊风抽搐，破伤风，宜首选的药物是","o":["葛根","升麻","牛蒡子","蝉蜕","薄荷"],"a":3,"e":"蝉蜕甘寒，功能息风止痉、疏散风热、利咽开音、明目退翳，善治小儿惊风抽搐及破伤风，故为首选。葛根、升麻解肌升阳，牛蒡子、薄荷疏散风热利咽，均无息风止痉之力，不能治惊风破伤风"},{"q":"不属于桑螵蛸主治病证的是","o":["白浊","崩漏","阳痿","遗尿尿频","遗精滑精"],"a":1,"e":"桑螵蛸甘咸平，补肾助阳、固精缩尿，主治遗尿尿频、遗精滑精、白浊及阳痿等肾虚不固之证。崩漏多由冲任不固、血热或脾虚所致，当用固崩止血或清热凉血之品，非桑螵蛸固精缩尿所主，故不属其主治"},{"q":"二、八月最宜采集的药材是","o":["叶类","花类","全草类","果实类","根及根茎类"],"a":4,"e":"根及根茎类药材宜在秋末春初、植物地上部分枯萎时采挖，此时有效成分积累充盛，农历二月、八月正当其时。叶类多在开花前或盛花期采，花类宜含苞待放时采，果实类在成熟时采，均不以二八月为佳"},{"q":"治疗阴痒，湿疹瘙痒，蛔虫腹痛，宜选","o":["花椒","胡椒","干姜","吴茱萸","小茴香"],"a":0,"e":"花椒辛热，能杀虫止痒、温中止痛，外用治湿疹瘙痒、阴痒，内服治蛔虫腹痛，故切合题意。胡椒温中下气，干姜温中回阳，吴茱萸疏肝下气，小茴香理气和中，均无杀虫止痒治阴痒之功"},{"q":"因含微量砷，不宜长期服用的药物是","o":["赭石","蒺藜","牡蛎","天麻","钩藤"],"a":0,"e":"赭石为氧化物类矿物，主含三氧化二铁，并含微量砷，不宜长期大量服用以免蓄积中毒。蒺藜、牡蛎、天麻、钩藤均为常用无毒之品，不含砷，无须因此限制久服，故与题意不符"},{"q":"丹参与郁金的共同功效是","o":["活血、行气","活血、退黄","活血、养血","活血、利水","活血、凉血"],"a":4,"e":"丹参与郁金均能活血、凉血，主治血瘀经闭及血热诸证，故共有功效为活血、凉血。行气为郁金兼有而丹参无明显行气之功；退黄属郁金利胆退黄，丹参无之；养血为当归、熟地所主；利水属牛膝、益母草"},{"q":"治温病后期，阴虚发热，无汗骨蒸，宜首选的药物是","o":["青蒿","银柴胡","牡丹皮","玄参","地骨皮"],"a":2,"e":"牡丹皮苦辛微寒，清热凉血、活血散瘀，善治温病后期热入营血、阴虚发热之无汗骨蒸，故为首选。青蒿、银柴胡退虚热但无活血，玄参清热凉血解毒，地骨皮治有汗骨蒸盗汗，均非无汗骨蒸之主药"},{"q":"具有补益肝肾、安胎、明目功效的药物是","o":["杜仲","续断","鹿茸","菟丝子","紫河车"],"a":3,"e":"菟丝子辛甘平，补肾益精、养肝明目、止泻、安胎，兼具补益肝肾、安胎、明目之效。杜仲、续断补肝肾、安胎但无明目之功；鹿茸、紫河车温补肾阳益精血，亦不专于明目安胎，故惟菟丝子全备"},{"q":"下列药物性味辛、苦，微温。功能祛风除湿，通络止痛的是","o":["丁公藤","伸筋草","海风藤","青风藤","路路通"],"a":2,"e":"海风藤辛苦微温，祛风湿、通经络、止痛，主治风湿痹痛、筋脉拘挛，性味功效与题述相符。丁公藤、青风藤、路路通、伸筋草虽能祛风湿通络，但或性偏寒凉、或兼利水通经，与辛苦微温、专主通络止痛者不同"},{"q":"治扭挫伤痛，宜选用的药物是","o":["夏枯草","密蒙花","青葙子","决明子","栀子"],"a":4,"e":"栀子苦寒，泻火除烦、清热利湿、凉血解毒，外用消肿止痛，可治跌打扭挫伤痛（研末调敷）。夏枯草、密蒙花、青葙子、决明子均为清肝明目之品，无活血消肿、外敷治扭伤之功"},{"q":"荆芥炭长于","o":["祛风","止血","透疹","消疮","止痛"],"a":1,"e":"荆芥生用解表散风、透疹消疮，炒炭后辛散之力大减，转为收敛止血，主治便血、崩漏、吐血等，故荆芥炭长于止血。祛风、透疹、消疮为生荆芥所长，止痛非荆芥功效，均非炭制品所主"},{"q":"大黄泻下攻积，最宜用于","o":["阴虚肠燥便秘","血虚肠燥便秘","津枯肠燥便秘","实热积滞便秘","食积腹痛便秘"],"a":3,"e":"大黄苦寒，泻下攻积、清热泻火，善荡涤胃肠实热积滞，主治实热积滞便秘，配芒硝、枳实效更佳。阴虚、血虚、津枯肠燥便秘当用滋阴养血润肠之品，误用大黄更伤津液；食积腹痛宜消食导滞，非大黄所主"},{"q":"石膏配伍知母属于中药“七情”中的","o":["相使","相须","相杀","相畏","相反"],"a":1,"e":"石膏与知母均能清热泻火，二药合用可相互增强疗效，属七情配伍中的相须。相使为增效力之辅药配合主药（如黄芪配茯苓）；相杀、相畏指减毒（如生姜杀半夏毒）；相反指合用增毒（如乌头反半夏），均不同"},{"q":"板蓝根与大青叶除均能清热解毒外，还能","o":["凉血","定惊","驱虫","利尿","下乳"],"a":0,"e":"板蓝根与大青叶同为清热解毒要药，且均能凉血，主治温毒发斑、大头瘟疫及咽喉肿痛，故除清热解毒外还能凉血。定惊属羚羊角、牛黄；驱虫为槟榔、使君子；利尿为车前子；下乳为穿山甲、王不留行，均非二药共有"},{"q":"治血热毒盛，斑疹色紫黑，宜首选","o":["玄参","生地黄","蝉蜕","紫草","赤芍"],"a":3,"e":"紫草甘咸寒，凉血活血、解毒透疹，专入血分，善治血热毒盛之斑疹色紫黑或麻疹不透，故为首选。玄参、生地黄清热凉血但无透疹之力，蝉蜕疏散风热利咽，赤芍凉血散瘀，均非血热毒盛斑疹紫暗之主药"},{"q":"解表药的药味及归经是","o":["苦，入心","咸，入肾","甘，入脾","辛，入肺","酸，入肝"],"a":3,"e":"解表药多辛味，辛能发散，主入肺经，因肺主皮毛、开窍于鼻，外邪侵袭多从皮毛口鼻而入，故解表药归肺经。苦入心、咸入肾、甘入脾、酸入肝分别为五味归经的一般规律，非解表药的味与归经"},{"q":"陈皮与青皮的功效区别是","o":["青皮补气，陈皮破气","陈皮补气，青皮破气","青皮理脾胃之气，陈皮理肝气","陈皮兼能化痰，青皮兼能活血","陈皮理脾胃之气，青皮破肝胆之气"],"a":4,"e":"陈皮、青皮同源于橘，但陈皮成熟、性较和缓，理脾胃之气、健脾燥湿化痰；青皮未成熟、性较峻烈，疏肝破气、消积化滞，破肝胆之气。故区别为陈皮理脾胃之气、青皮破肝胆之气。补气非二者之功，陈皮亦不活血"},{"q":"治外感风寒表实无汗之要药是","o":["石膏","升麻","生姜","柴胡","麻黄"],"a":4,"e":"麻黄辛温，发汗解表、宣肺平喘、利水消肿，为治外感风寒表实无汗之要药，常配桂枝增强发汗。石膏清热、升麻升阳解毒、柴胡和解退热、生姜温中止呕，均无发汗解表治表实无汗之主效"},{"q":"桑螵蛸的入用部位是","o":["虫卵","卵鞘","若虫","成虫","内壳"],"a":1,"e":"桑螵蛸为螳螂科昆虫的卵鞘，故其入药部位是卵鞘。虫卵、若虫、成虫均非药用部位；内壳为海螵蛸等之部位，与桑螵蛸不同，故均非正确选项"},{"q":"善治痈肿疔疮、目赤肿痛、胃火牙痛的药物是","o":["秦皮","黄连","知母","龙胆","苦参"],"a":1,"e":"黄连苦寒，清热燥湿、泻火解毒，尤清心胃之火，善治胃火牙痛、目赤肿痛及痈肿疔疮。秦皮清热燥湿止痢明目，知母清热滋阴，龙胆泻肝胆火，苦参清热燥湿杀虫，均非清胃火、疗疮疡之主药"},{"q":"功能理气止痛、祛寒散滞，可以治疗肝胃气痛的药物是","o":["青皮","沉香","香附","陈皮","荔枝核"],"a":4,"e":"荔枝核辛微苦温，行气散结、祛寒止痛，专入肝胃经，善治肝胃气痛及疝气睾丸肿痛。青皮疏肝破气、沉香行气止痛、香附疏肝理气、陈皮理气健脾，虽均理气，但无祛寒散滞、专治肝胃气痛之特点"},{"q":"既治头晕目眩，又治呕吐噫气的药物是","o":["赭石","枇杷叶","石决明","珍珠母","旋覆花"],"a":0,"e":"赭石苦寒，平肝潜阳、重镇降逆、凉血止血，既能镇肝阳上亢之头晕目眩，又能降胃气上逆之呕吐噫气呃逆。枇杷叶、旋覆花降逆止呕但无平肝潜阳；石决明、珍珠母平肝潜阳而无降逆止呕之功，故惟赭石两擅其长"},{"q":"既能解毒杀虫疗疮，又能补火助阳通便的药是","o":["硫黄","麻黄","大黄","雄黄","牛黄"],"a":0,"e":"硫黄酸温有毒，外用解毒杀虫疗疮，治疥癣秃疮；内服补火助阳通便，治虚寒便秘、肾虚寒喘，故兼具所述功效。雄黄解毒杀虫但无补火通便；大黄泻下而非补火；牛黄、麻黄均无杀虫疗疮与助阳通便之能"},{"q":"生姜与干姜共同的功效是","o":["止呕，止泻","解表，化饮","理气，助阳","温中，温肺","通脉，解毒"],"a":2,"e":"官方答案为【理气，助阳】，但依据教材，正确答案为【温中，温肺】。生姜能温中止呕、温肺止咳，干姜能温中散寒、温肺化饮，二者共同功效为温中、温肺。理气并非二者所长，助阳（回阳）仅为干姜所有，生姜无补火助阳之力，故原答案不能成立"},{"q":"下列哪项不属于蛇床子的适用范围","o":["湿疹","疥癣","湿痹腰痛","虫蛇咬伤","宫冷不孕"],"a":3,"e":"蛇床子辛苦温，温肾壮阳、燥湿祛风、杀虫止痒，主治宫冷不孕、湿痹腰痛、湿疹疥癣。虫蛇咬伤需清热解毒、消肿止痛之品（如半边莲、白花蛇舌草），非蛇床子温燥杀虫所宜，故不属其适用范围"},{"q":"具有解毒润肠作用，可用于痈疽、瘰疬、血虚肠燥便秘的药物是","o":["甘草","当归","黄芪","何首乌","肉苁蓉"],"a":3,"e":"生何首乌苦甘涩微温，解毒、截疟、润肠通便，可治痈疽瘰疬及血虚肠燥便秘。甘草、黄芪补气而无解毒润肠通便之效；当归、肉苁蓉润肠但无解毒消痈之功，故符合题意者为何首乌"},{"q":"血竭可用于治疗","o":["皮肤湿疮","肾虚腰痛","肺热咳嗽","食积不化","外伤出血"],"a":4,"e":"血竭甘咸平，活血定痛、化瘀止血、敛疮生肌，为伤科要药，善治跌打损伤、外伤出血及疮疡不敛。皮肤湿疮宜清热燥湿，肾虚腰痛宜补肝肾，肺热咳嗽宜清肺，食积不化宜消食，均非血竭所主"},{"q":"具有小毒的药物是","o":["桑白皮","葶苈子","款冬花","马兜铃","苦杏仁"],"a":4,"e":"苦杏仁苦微温、有小毒，降气止咳平喘、润肠通便，所含苦杏仁苷水解可产生微量氢氰酸，过量易中毒，故为有小毒之品。桑白皮、葶苈子、款冬花、马兜铃虽或泻肺或止咳，均无小毒之标载"},{"q":"七情配伍中，具有协同作用能提高药效的配伍方法是","o":["相须、相使","相须、相畏","相须、相杀","相使、相畏","相使、相杀"],"a":0,"e":"相须指性能相类似的药物合用，相互增强疗效（如石膏配知母）；相使指性能功效有某种共性的药物主辅相配，辅药提高主药疗效（如黄芪配茯苓）。二者均有协同增效作用。相畏、相杀为减毒配伍，相恶、相反为减效或增毒，均非协同提高药效"},{"q":"临床上见恶寒发热，咳嗽咽痛等证，一般应选用","o":["归心经的药物","归肺经的药物","归肝经的药物","归肾经的药物","归脾经的药物"],"a":1,"e":"恶寒发热、咳嗽咽痛为外邪犯肺、肺卫失宣之表证，咳嗽咽痛病位在肺，故一般选用归肺经的药物以疏风宣肺解表。归心经多治神明神志病，归肝经治胁痛目疾，归肾经治腰膝水肿，归脾经治运化失常，均不对应本证"},{"q":"肺热咳喘兼胃热呕吐者，宜选用","o":["生姜","竹茹","砂仁","藿香","枇杷叶"],"a":4,"e":"枇杷叶苦微寒，清肺止咳、降逆止呕，肺热咳喘兼胃热呕吐者正宜，故为首选。生姜温中止呕且性温，助肺热；竹茹清胃热止呕但清肺力弱；砂仁、藿香化湿行气，均无清肺止咳与降逆止呕兼备之效"},{"q":"薄菏的性味是","o":["苦寒","苦温","辛凉","甘寒","甘凉"],"a":2,"e":"薄荷辛凉，归肺肝经，疏散风热、清利头目、利咽透疹、疏肝行气，为辛凉解表药，故其性味为辛凉。苦寒、苦温、甘寒、甘凉均非薄荷之味性，且其辛散凉清之性与苦降、甘补之性不同"},{"q":"有退黄之功，可治疗湿热黄疸的药组是","o":["茵陈、胡黄连","地骨皮、栀子","白薇、大黄","银柴胡、白鲜皮","青蒿、茵陈"],"a":4,"e":"青蒿、茵陈均能清热利湿而退黄，可治湿热黄疸，故该药组有退黄之功。胡黄连、白薇、银柴胡、地骨皮均属清虚热药，栀子虽利湿退黄但配地骨皮、白鲜皮等组合不专于退黄，均非最佳退黄药组"},{"q":"我国第一部药典性著作是","o":["《神农本草经》","《本草经集注》","《新修本草》","《证类本草》","《本草纲目》"],"a":2,"e":"《新修本草》成书于唐代，由政府组织编修颁行，是我国也是世界上最早的药典性著作，故为第一部药典性著作。《神农本草经》为最早的本草学专著但非官修药典，《本草经集注》《证类本草》为个人编著，《本草纲目》成书最晚"},{"q":"以治疗肝阳上亢之头晕目眩为主的中药属于","o":["重镇安神药","平抑肝阳药","豁痰开窍药","息风止痉药","滋阴潜阳药"],"a":1,"e":"肝阳上亢之头晕目眩，治宜平抑肝阳、滋阴潜阳，故此类中药属平抑肝阳药，如石决明、珍珠母、牡蛎。重镇安神药主安神定惊，豁痰开窍药主痰迷心窍，息风止痉药主肝风抽搐，滋阴潜阳药偏于滋阴，均非以治肝阳眩晕为主"},{"q":"大黄治头痛，目赤，易怒，便秘者，主要作用部位是","o":["脾经","胃经","大肠经","肝经","心包经"],"a":3,"e":"大黄归脾、胃、大肠、肝、心包经，其治头痛、目赤、易怒属肝火上炎，且能泻热通便，故主要作用部位在肝经。归脾经、胃经、大肠经主要关联其健脾、和胃、泻下通便之用，心包经非主治头痛目赤易怒之归经"},{"q":"味苦性凉，为清热解毒之良药，内服外用均宜的药是","o":["甘草","牛黄","冰片","羚羊角","珍珠母"],"a":1,"e":"牛黄性凉，气芳香，清热解毒之力强，内服入丸散、外用敷疮疡均可，为清热解毒之良药，主治咽喉肿痛、疮痈疔毒及热病神昏。甘草甘平偏补，冰片辛苦微寒重在开窍止痛，羚羊角、珍珠母咸寒分别主息风与潜阳安神，均非所述"},{"q":"治疗邪热壅肺之喘咳，宜选用的药对是","o":["白芥子、莱菔子","石膏、麻黄","半夏、天南星","陈皮、半夏","苦杏仁、白果"],"a":1,"e":"邪热壅肺之喘咳治宜清泻肺热、宣肺平喘，石膏清肺热，麻黄宣肺平喘，二药相制相成（麻杏石甘汤），故为首选药对。白芥子、莱菔子、半夏、天南星温化寒痰，陈皮、半夏燥湿，苦杏仁、白果降气敛肺，均非清泻肺热之配伍"},{"q":"属于“十九畏”的配伍药对是","o":["川乌与草乌","桃仁与红花","官桂与赤石脂","乌头与贝母","甘草与甘遂"],"a":2,"e":"十九畏载“官桂善能调冷气，若逢石脂便相欺”，故官桂与赤石脂属十九畏配伍。川乌与草乌、乌头与贝母、甘草与甘遂均属十八反；桃仁与红花为相须常用的活血药对，不属十九畏"},{"q":"石膏与寒水石入汤剂宜","o":["先煎","后下","包煎","另煎","烊化"],"a":0,"e":"石膏、寒水石均为矿物类药材，质地坚硬、有效成分不易溶出，入汤剂宜打碎先煎久煮。后下适用于芳香易挥发或久煎失效之品如薄荷、钩藤；包煎适用于花粉绒毛类如旋覆花；另煎用于人参等贵重药；烊化用于阿胶等胶类，均非矿物药用法"},{"q":"可广泛用于多种饮食积滞证，尤善消化谷麦酒食积滞的药物是","o":["山楂","神曲","麦芽","葛根","陈皮"],"a":1,"e":"神曲为面粉与药物混合发酵而成，消食和胃，尤善消化谷麦酒食积滞，广泛用于多种饮食积滞证。山楂善消肉食油腻，麦芽善消米面薯芋，葛根解肌升阳，陈皮理气健脾，均非以消化谷麦酒食见长"},{"q":"能补益肺肾，止咳平喘，可用治肺虚咳喘的药物是","o":["灵芝","远志","首乌藤","酸枣仁","合欢皮"],"a":0,"e":"灵芝甘平，补气安神、止咳平喘，能补益肺肾、止咳平喘，主治肺虚咳喘及虚劳短气。远志祛痰开窍，首乌藤养血安神，酸枣仁养心安神，合欢皮解郁安神，均无补肺肾、止咳平喘之功"},{"q":"钩藤入汤剂宜","o":["包煎","先煎","后下","另煎","烊化"],"a":2,"e":"钩藤含钩藤碱，久煎有效成分易被破坏而降低降压、息风之效，故入汤剂宜后下。先煎用于矿物、贝壳类；包煎用于花粉绒毛类；另煎用于贵重药；烊化用于胶类，均不符合钩藤后下的特殊要求"},{"q":"下列不属于道地药材的是","o":["四川的附子","浙江的白芍","陕西的当归","河南的地黄","山东的阿胶"],"a":2,"e":"当归道地药材主产甘肃岷县，以甘肃当归为佳，陕西并非当归道地产区。四川附子、浙江白芍、河南地黄、山东阿胶均为公认道地药材，产地与药材对应正确，故不属于道地药材的是陕西的当归"},{"q":"可用于治疗瘀血证的消食药是","o":["青皮","桃仁","红花","山楂","神曲"],"a":3,"e":"山楂酸甘微温，消食化积、行气散瘀，既能治肉食积滞，又能治产后瘀阻腹痛、痛经，故为可用于瘀血证的消食药。青皮、桃仁、红花虽能活血但非消食药；神曲消食而无活血散瘀之功"},{"q":"下列不属于蟾酥适用范围的是","o":["牙痛","咽喉肿痛","痈疽疔疮","痧胀腹痛","风湿痹痛"],"a":4,"e":"蟾酥辛温有毒，解毒、止痛、开窍醒神，主治痈疽疔疮、咽喉肿痛、牙痛及痧胀腹痛吐泻。风湿痹痛宜祛风湿通络止痛之品（如独活、威灵仙），非蟾酥解毒开窍止痛所主，故不属其适用范围"},{"q":"牛蒡子的归经是","o":["脾、胃、肺经","肺、肝经","肝、胆、肺经","膀胱、肝、胃经","肺、胃经"],"a":4,"e":"牛蒡子辛苦寒，疏散风热、宣肺透疹、解毒利咽，归肺、胃经，主治风热感冒、麻疹不透、咽喉肿痛。脾、胃、肺经（含脾）非其归经；肺、肝经、肝、胆、肺经、膀胱、肝、胃经均与牛蒡子归肺胃经不符"},{"q":"赤药具有而牡丹皮不具有的功效是","o":["清热凉血","清退虚热","活血化瘀","清肝泻火","解毒透疹"],"a":3,"e":"赤芍苦寒，清热凉血、散瘀止痛、清肝泻火，主治肝火上炎之目赤肿痛及血热瘀滞诸证。牡丹皮清热凉血、活血散瘀、退虚热，但无清肝泻火之功；二者共有清热凉血、活血化瘀，清肝泻火为赤芍所独"},{"q":"某些对胃肠有刺激性的药物宜","o":["饭前服","多次分服","空腹时服","饭后服","腹痛时服"],"a":3,"e":"对胃肠有刺激性的药物宜饭后服，使药物与食物混合，减少对胃黏膜的刺激。饭前服、空腹服多用于补益药或驱虫、泻下药以使充分吸收或发挥作用；多次分服用于呕吐或峻药；腹痛时服非定时服药原则"},{"q":"治疗久泄久痢的中药大多具有","o":["酸味","苦味","甘味","辛味","咸味"],"a":0,"e":"酸味药能收敛固涩，久泄久痢属滑脱失禁之证，宜用酸味药涩肠止泻，如五味子、乌梅、石榴皮。苦味清热燥湿，甘味补益缓急，辛味发散行气，咸味软坚泻下，均非治久泄久痢的主要药味"},{"q":"“温热天之阳，寒凉天之阴；阳则升，阴则降”，反映了四气与下列哪项的关系","o":["四气","五味","归经","升降浮沉","毒性"],"a":3,"e":"“温热天之阳，寒凉天之阴；阳则升，阴则降”说明药性寒热温凉与升降浮沉的关系：温热者多升浮，寒凉者多沉降，故反映的是四气与升降浮沉的关系。四气、五味、归经、毒性均为药物的其他性能，与此论述不直接对应"},{"q":"被称为“气病之总司，女科之主帅”的药物是","o":["香附","乌药","甘松","大腹皮","荔枝核"],"a":0,"e":"香附辛微苦甘平，疏肝理气、调经止痛，为疏肝解郁、调经要药，治肝郁气滞之月经不调、痛经及胁肋胀痛，故被誉为“气病之总司，女科之主帅”。乌药、甘松、大腹皮、荔枝核虽理气，但无调经主帅之称"},{"q":"治疗肺热咳嗽，高热烦渴，首选的药物是","o":["龙胆","黄连","黄芩","黄柏","苦参"],"a":2,"e":"黄芩苦寒，归肺经，清热燥湿、泻火解毒，尤清上焦肺火，主治肺热咳嗽、高热烦渴，故为首选。龙胆泻肝胆火，黄连清心胃火，黄柏泻下焦火，苦参清热燥湿杀虫，均非清肺热之主药"},{"q":"人参配莱菔子，莱菔子能削弱人参的补气作用，这种配伍关系属于","o":["相须","相使","相畏","相恶","相杀"],"a":3,"e":"人参补气，莱菔子消食行气，二者同用莱菔子能削弱人参的补气作用，属七情配伍中的相恶（即一种药物使另一种药物功效降低）。相须、相使为增效配伍；相畏、相杀为减毒配伍，均非此降效关系"},{"q":"下列病症中，哪种不宜用赭石治疗","o":["热证抽搐","烦躁不寐","血热吐血、崩漏","气逆之嗳气、呕吐","肝阳上亢之头痛、眩晕"],"a":0,"e":"赭石苦寒，平肝潜阳、重镇降逆、凉血止血，主治肝阳上亢之头痛眩晕、惊痫抽搐及血热吐衄崩漏。热证抽搐属热极生风，宜凉肝息风止痉（如羚羊角、钩藤、牛黄），赭石无息风止痉之功，故不宜用其治疗"},{"q":"下列不属于土荆皮临床应用范围的是","o":["体癣","湿疹","疮痈","头癣","手足癣"],"a":2,"e":"土荆皮辛温有毒，杀虫、疗癣、止痒，专供外用，主治体癣、头癣、手足癣及湿疹瘙痒。疮痈肿毒宜清热解毒、消肿溃坚之品（如蒲公英、紫花地丁），非土荆皮杀癣虫所宜，故不属其临床应用范围"},{"q":"水蛭、虻虫的相同功效是","o":["活血疗伤接骨","破血逐瘀消癥","散结消肿止痛","破血行气消积","活血消肿排脓"],"a":1,"e":"水蛭、虻虫均为破血逐瘀之虫类药，能破血逐瘀、消癥散结，主治瘀血经闭、癥瘕痞块及跌打瘀肿，故二者相同功效为破血逐瘀消癥。疗伤接骨属自然铜、骨碎补；散结消肿止痛、行气消积、活血排脓均非二药所长"},{"q":"不宜与砒石同用的药物是","o":["硼砂","雄黄","水银","轻粉","朴硝"],"a":2,"e":"十九畏载“水银莫与砒霜见”，砒石（砒霜）不宜与水银同用，故为不宜与砒石同用之药。硼砂、朴硝为矿物药，雄黄、轻粉虽有毒，但均无此配伍禁忌，不属与砒石相畏之列"},{"q":"患者，男。胃溃疡病史，近日发现大便隐血，伴胃脘冷痛，泛酸，四肢不温。医方中用到白及，同方中不应该同时出现的药物是","o":["半夏","瓜蒌","附子","贝母","五灵脂"],"a":2,"e":"白及反乌头（附子），属十八反，故方中既有白及，不应再用附子。半夏、瓜蒌、贝母虽亦反乌头，但本身不与白及相畏；五灵脂畏人参，与白及无涉。且附子辛热，于胃溃疡出血泛酸之证亦不相宜"},{"q":"能治疗肝郁气滞，胸胁胀痛，月经不调的药物是","o":["菊花","升麻","牛蒡子","蝉蜕","柴胡"],"a":4,"e":"柴胡辛苦微寒，归肝胆经，疏肝解郁、升举阳气，善治肝郁气滞之胸胁胀痛、月经不调及少阳证。菊花、蝉蜕疏散风热，升麻升阳解毒，牛蒡子利咽透疹，均无疏肝解郁、调经之功"},{"q":"茵陈的性味归经是","o":["辛、苦，寒。归肾、膀胱经","苦、辛，微寒。归脾、胃、肝、胆经","微苦，微寒。归肝、胆、肺经","苦，平。归肝、胆经","甘、淡，凉。归肝、胆、小肠经"],"a":1,"e":"茵陈苦、辛，微寒，归脾、胃、肝、胆经，清热利湿、利胆退黄，为治黄疸要药。辛、苦，寒归肾、膀胱经等描述与茵陈归经不符；微苦微寒归肝胆肺经、苦平归肝胆经、甘淡凉归肝胆小肠经均非茵陈之性味归经"},{"q":"不属于寒凉药所示的功效是","o":["清热利尿","凉血止血","凉肝息风","补肾助阳","泻火解毒"],"a":3,"e":"寒凉药具有清热、凉血、解毒、泻火、利尿等功效，适用于热证。补肾助阳属温热药的功效，如附子、肉桂、鹿茸之类，可助阳益火、祛寒，与寒凉药性相反，故不属于寒凉药所示的功效"},{"q":"来源于相同植物的药是","o":["猪苓、茯苓","羌活、独活","桑寄生、桑椹","干姜、高良姜","枸杞子、地骨皮"],"a":4,"e":"枸杞子为枸杞的成熟果实，地骨皮为枸杞的根皮，二者来源于同一种植物枸杞。茯苓、猪苓分别为茯苓菌核与猪苓菌核，羌活、独活为不同植物的根，桑寄生、桑椹来源不同，干姜、高良姜亦非同种，均不符合题意"},{"q":"玄参具有而生地黄不具有的功效是","o":["养阴生津","清热凉血","透疹消斑","解毒散结","活血化瘀"],"a":3,"e":"玄参苦甘咸寒，清热凉血、滋阴降火、解毒散结，可治瘰疬、疮痈及咽喉肿痛。生地黄清热凉血、养阴生津，但无解毒散结之功；养阴生津、清热凉血为二者共有，透疹消斑、活血化瘀均非玄参特有"},{"q":"大黄与芒硝配伍，当属七情配伍中的","o":["相须","相使","相恶","相反","相杀"],"a":0,"e":"大黄苦寒泻下攻积，芒硝咸寒软坚润燥，二药合用泻下软坚之力大增，相互增强疗效，属七情配伍中的相须。相使为辅助增效，相恶为减效，相反为增毒，相杀为减毒，均非二药配伍关系"},{"q":"石决明的药用部位是","o":["化石","贝壳","果实","树脂","种子"],"a":1,"e":"石决明为鲍科动物杂色鲍等的贝壳，故药用部位是贝壳，功能平肝潜阳、清肝明目。化石如龙骨，果实如瓜蒌，树脂如乳香，种子如决明子，均非石决明的药用部位"},{"q":"可虚实两清，既能治疗阴虚发热，又能治疗血热咯血衄血的药物是","o":["黄柏","地骨皮","白薇","白茅根","秦艽"],"a":1,"e":"地骨皮甘寒，清虚热、凉血，既能治阴虚发热、骨蒸盗汗，又能凉血止血，治血热咯血、衄血，故可虚实两清。黄柏、白薇偏清虚热而止血力弱，白茅根偏凉血止血，秦艽祛风湿清虚热，均不兼备"},{"q":"陈皮的功效是","o":["理气健脾，燥湿化痰","理气和中，化痰除痞","行气调中，杀虫疗癣","理气止痛，祛寒散滞","理气和中，疏肝化痰"],"a":0,"e":"陈皮辛苦温，理气健脾、燥湿化痰，主治脾胃气滞之脘腹胀满、食少吐泻及湿痰寒痰咳嗽。理气和中、化痰除痞为枳壳等；行气调中、杀虫疗癣为川楝子；理气止痛、祛寒散滞为荔枝核；疏肝化痰非陈皮所主"},{"q":"下焦血热所致的便血、崩漏，宜首选的药物是","o":["大蓟","小蓟","地榆","白茅根","侧柏叶"],"a":2,"e":"地榆苦酸涩微寒，归肝、大肠经，凉血止血、解毒敛疮，尤善治下焦血热之便血、痔血、血痢及崩漏。大蓟、小蓟凉血止血但偏治上部出血；白茅根清肺胃热；侧柏叶收敛止血，均非下焦便血崩漏之首选"},{"q":"薤白的功效为行气导滞","o":["通阳散结","疏肝解郁","行气宽中","降逆止呃","温肾助阳"],"a":0,"e":"薤白辛苦温，通阳散结、行气导滞，为治胸痹的要药，兼治胃肠气滞之脘腹胀痛、泻痢后重。疏肝解郁属柴胡、香附；行气宽中为紫苏梗；降逆止呃为旋覆花、柿蒂；温肾助阳为肉桂、附子，均非薤白之效"},{"q":"善滋养胃阴，兼清胃热，治胃阴虚有热之口渴多饮、饥不欲食的药是","o":["桑椹","天冬","楮实子","黑芝麻","北沙参"],"a":4,"e":"北沙参甘微苦微寒，养阴清肺、益胃生津，善滋养胃阴、兼清胃热，主治胃阴虚有热之口渴多饮、饥不欲食。桑椹、黑芝麻滋阴补血，天冬滋阴润燥，楮实子补肝肾，均无益胃生津、清胃热之专功"},{"q":"不宜与甘草同用的药物是","o":["海藻","昆布","海蛤壳","海浮石","瓦楞子"],"a":0,"e":"甘草反甘遂、大戟、海藻、芫花，属十八反，故海藻不宜与甘草同用。昆布、海蛤壳、海浮石、瓦楞子虽同为咸寒化痰散结之品，但与甘草无相反关系，可配伍使用"},{"q":"下列那项不是雄黄的功效","o":["解毒","杀虫","通便","截疟","燥湿祛痰"],"a":2,"e":"雄黄辛温有毒，解毒、杀虫、燥湿祛痰、截疟，主治痈肿疔疮、蛇虫咬伤、疟疾及痰饮咳喘。本品无通便之功，通便多属大黄、芒硝、火麻仁等，故通便不是雄黄的功效"},{"q":"清虚热药可用于","o":["温病初起","热病高热烦渴","温毒斑疹","温病后期夜热早凉","热入营分"],"a":3,"e":"清虚热药能清退虚热、凉血除蒸，适用于温病后期、邪热伤阴之夜热早凉、热退无汗及阴虚发热、骨蒸盗汗。温病初起、热病高热烦渴、温毒斑疹、热入营分均属实热或卫气营分证，宜解表、清热、凉血解毒，非清虚热药所主"},{"q":"湿阻、食积、气滞中满者宜慎用的药味是","o":["辛味","淡味","苦味","咸味","甘味"],"a":4,"e":"甘味药多滋腻，能补益和中，但湿阻、食积、气滞中满者服之易碍胃助湿、加重胀满，故宜慎用。辛味行散、淡味渗利、苦味燥湿、咸味软坚，均不易助湿碍胃中满，与甘味滋腻之弊不同"},{"q":"生用行气，煨用止泻的药物是","o":["香附","青皮","木香","沉香","土木香"],"a":2,"e":"木香辛苦温，行气止痛、健脾消食，生用行气力专，煨用则温中涩肠止泻，故生用行气、煨用止泻。香附疏肝调经，青皮破气消积，沉香降气温中，土木香行气健脾，均无生用行气、煨用止泻的用法特点"},{"q":"吴茱萸煎服时用量为","o":["1～3g","1～5g","2～5g","3～6g","3～10g"],"a":2,"e":"吴茱萸辛热有小毒，散寒止痛、降逆止呕、助阳止泻，煎服常用量为2～5g。1～3g、1～5g偏小，3～6g、3～10g超出常用范围，因本品辛热有毒，用量不宜过大，故2～5g为法定用量"},{"q":"既能涩肠止泻，又能收敛止血的药物是","o":["白及","紫珠","肉豆蔻","罂粟壳","禹余粮"],"a":4,"e":"禹余粮甘涩微寒，涩肠止泻、收敛止血、止带，主治久泻久痢及便血、崩漏等滑脱出血之证，故兼具涩肠止泻与收敛止血之功。白及、紫珠收敛止血但无涩肠止泻；肉豆蔻、罂粟壳涩肠止泻但无收敛止血，故惟禹余粮两全"},{"q":"能养阴生津，润肺清心的药物是","o":["石斛","天冬","麦冬","南沙参","北沙参"],"a":2,"e":"麦冬甘微苦微寒，养阴生津、润肺清心，主治肺燥干咳、阴虚劳嗽、津伤口渴及心烦失眠。石斛益胃生津、滋阴清热；天冬滋阴润燥力强；南沙参、北沙参养阴清肺益胃，均无润肺清心之效"},{"q":"不宜与南沙参、北沙参同用的药物是","o":["甘草","附子","藜芦","川乌","草乌"],"a":2,"e":"藜芦反诸参（人参、沙参、丹参、玄参、苦参）及细辛、芍药，故南沙参、北沙参不宜与藜芦同用。甘草、附子、川乌、草乌与沙参均无相反关系，其中川乌、草乌反半夏瓜蒌贝母白蔹白及，与沙参无涉"},{"q":"能固精止遗的药物是","o":["山楂","神曲","麦芽","莱菔子","鸡内金"],"a":4,"e":"鸡内金甘平，消食健胃、涩精止遗、通淋化石，主治饮食积滞、遗精遗尿及砂石淋证，故能固精止遗。山楂、神曲、麦芽、莱菔子均为消食药，但无固精止遗之功"},{"q":"具有补肝肾、续折伤、止崩漏功效的药物是","o":["杜仲","续断","仙茅","锁阳","蛤蚧"],"a":1,"e":"续断苦辛微温，补肝肾、强筋骨、续折伤、止崩漏、安胎，主治肝肾不足之腰膝酸软、跌打损伤、骨折及崩漏胎动不安。杜仲补肝肾安胎但无续折伤之能；仙茅、锁阳温阳，蛤蚧补肺肾定喘，均非续折伤止崩漏之药"},{"q":"芡实与白果的共同功效是","o":["止汗","止泻","止带","止痛","止咳"],"a":2,"e":"芡实甘涩平，益肾固精、补脾止泻、除湿止带；白果甘苦涩平，敛肺化痰定喘、止带缩尿，二者均能止带，主治带下过多。止汗、止泻、止痛、止咳仅为其中一药所有或均不具备，非二者共同功效"},{"q":"可治外感内伤、寒热虚实之咳嗽，为治肺痨咳嗽、久咳虚嗽之要药的是","o":["百部","枇杷叶","桑白皮","紫苏子","苦杏仁"],"a":0,"e":"百部甘苦微温，润肺下气、止咳杀虫，咳嗽无论外感内伤、寒热虚实皆可应用，尤善治肺痨咳嗽、久咳虚嗽，故为要药。枇杷叶清肺止咳，桑白皮泻肺，紫苏子降气化痰，苦杏仁降气止咳，均无润肺杀虫、治肺痨久咳之特长"},{"q":"治厥阴头痛，宜选","o":["花椒","白芷","羌活","干姜","吴茱萸"],"a":4,"e":"厥阴肝经循行巅顶，吴茱萸辛热，专入肝经，散寒止痛、疏肝下气，善治厥阴头痛（巅顶痛）及肝胃不和之呕吐吞酸。白芷治阳明眉棱骨痛，羌活治太阳后头项痛，花椒、干姜温中，均不专入厥阴治巅顶头痛"},{"q":"治脾虚胎动不安，最宜选用","o":["砂仁","杜仲","白术","紫苏梗","桑寄生"],"a":2,"e":"白术苦甘温，健脾益气、燥湿利水、止汗、安胎，主治脾虚食少、水肿及脾虚胎动不安，为健脾安胎要药，故最宜选用。砂仁、紫苏梗、桑寄生虽亦安胎，但砂仁偏化湿行气，紫苏梗理气，桑寄生补肝肾，均非健脾安胎之首选"},{"q":"知母治阴虚消渴，主要是因其能","o":["利尿通淋","除烦止渴","润燥通便","滋阴润燥","清热泻火"],"a":3,"e":"知母苦甘寒，清热泻火、滋阴润燥，既清肺胃实热，又滋肾阴、润燥，治阴虚消渴（内热消渴）主要取其滋阴润燥、生津止渴之功。利尿通淋、除烦止渴、润燥通便、清热泻火皆非其治消渴之核心机制"},{"q":"主归胃、肾经，既能益胃生津，又能滋阴清热的药物是","o":["黄精","玉竹","石斛","麦冬","百合"],"a":2,"e":"石斛甘微寒，归胃、肾经，益胃生津、滋阴清热，主治胃阴虚之口渴、病后虚热及肾阴虚之腰膝软弱。黄精、玉竹滋阴润肺，麦冬润肺清心，百合养阴润肺清心，均非主归胃肾、益胃生津兼滋阴清热之品"},{"q":"旋覆花不具有的功效是","o":["止血","行水","降气","止呕","消痰"],"a":0,"e":"旋覆花苦辛咸微温，降气化痰、降逆止呕、行水，主治痰饮蓄结之咳喘、噫气呕吐及水肿。本品无止血之功，止血属白及、三七、茜草等，故止血不是旋覆花的功效。行水、降气、止呕、消痰皆为其所有"},{"q":"既能化痰散结，又能清热解毒的药物是","o":["僵蚕","地龙","黄药子","天竺黄","天南星"],"a":2,"e":"黄药子苦寒有毒，化痰散结消瘿、清热解毒，主治瘰疬、瘿瘤及疮疡肿毒，故兼具化痰散结与清热解毒之功。僵蚕、地龙、天竺黄、天南星虽化痰，但或息风、或清热、或燥湿，均无清热解毒散结之全效"},{"q":"大黄长期服用致继发性便秘，是因其含有","o":["蒽醌类成分","生物碱","挥发油","鞣质","双蒽酮苷类成分"],"a":3,"e":"大黄含蒽醌类成分（结合型）泻下，同时含鞣质，小剂量或长期服用时鞣质的收敛作用占优势，可致继发性便秘。生物碱、挥发油非大黄主要成分；双蒽酮苷类为泻下成分之一，长期服用致便秘归因于鞣质收敛"},{"q":"孕妇忌服的药物是","o":["千年健","雪莲花","狗脊","桑寄生","五加皮"],"a":1,"e":"雪莲花甘苦温，祛风湿、补肝肾、强筋骨、活血通经，因其活血通经之力较强，孕妇忌服。千年健、狗脊、桑寄生、五加皮虽多祛风湿补肝肾，但无活血通经堕胎之弊，非孕妇忌服之列"},{"q":"与菊花相比，野菊花长于","o":["清热解毒","清泻肝火","平抑肝阳","疏散风热","清肺润燥"],"a":0,"e":"野菊花与菊花同源，但野菊花苦辛微寒，清热解毒之力远强于菊花，善治疮痈疔毒、目赤肿痛，故其长于清热解毒。疏散风热、平抑肝阳、清肝明目为菊花所长，野菊花清泻肝火亦非其突出之点，清肺润燥更非"},{"q":"治疗心气不足的心悸、脉结代，最宜选用的药是","o":["黄芪","白术","丹参","山药","炙甘草"],"a":4,"e":"炙甘草甘温，补脾和胃、益气复脉，主治心气不足之心动悸、脉结代（如炙甘草汤），故最宜选用。黄芪补气升阳，白术健脾，山药补气养阴，丹参活血凉血，均无益气复脉、治脉结代之专功"},{"q":"不属于何首乌功效的是","o":["固肾乌须","补益精血","止咳平喘","润肠通便","截疟解毒"],"a":2,"e":"制何首乌补益精血、固肾乌须，生何首乌解毒、截疟、润肠通便，故何首乌具固肾乌须、补益精血、润肠通便、截疟解毒之效。本品无止咳平喘之功，止咳平喘多属杏仁、苏子、百部等，故不属于何首乌功效"},{"q":"古人认为可“劫肝阴”，阴虚阳亢，肝风内动，阴虚火旺者忌用或慎用的药物是","o":["桑叶","升麻","牛蒡子","蝉蜕","柴胡"],"a":4,"e":"柴胡辛散升提，古人认为其能“劫肝阴”，故阴虚阳亢、肝风内动、阴虚火旺者忌用或慎用，以免升散耗伤阴液、助阳化风。桑叶、牛蒡子、蝉蜕疏散风热而不升提伤阴，升麻虽升阳但无劫肝阴之说"},{"q":"具有清热解毒，化痰散结之功，近年来广泛应用于癥瘕痞块和多种肿瘤的药物是","o":["金银花","败酱草","山慈菇","熊胆粉","白花蛇舌草"],"a":2,"e":"山慈菇甘微辛凉，清热解毒、化痰散结，善治痈肿疔毒、瘰疬及癥瘕痞块，近年来广泛用于多种肿瘤。金银花、败酱草、蒲公英、白花蛇舌草虽清热解毒消痈，但无化痰散结、治癥瘕痞块之专功"},{"q":"治风寒表实证兼喘咳，宜首选的药物是","o":["羌活","紫苏叶","麻黄","桂枝","防风"],"a":2,"e":"麻黄辛温，发汗解表、宣肺平喘，主治风寒表实无汗而兼喘咳者，发汗力强且能平喘，故为首选。羌活、防风祛风胜湿，紫苏叶、桂枝解表但无宣肺平喘之专效，桂枝更宜于表虚有汗"},{"q":"水蛭研末内服的用量是","o":["0、01～0、03g","0、04～0、06g","0、1～0、15g","0、3～0、5g","0、6～1g"],"a":3,"e":"水蛭咸苦平，有小毒，破血逐瘀消癥，研末服效用更佳，用量一般为0.3～0.5g，故研末内服用量如此。0.01～0.03g、0.04～0.06g、0.1～0.15g剂量过小难以起效，0.6～1g则偏大易致出血，均非研末常规用量"},{"q":"理气药中，擅于行气调中止痛的药物是","o":["木香","香附","沉香","土木香","九香虫"],"a":0,"e":"木香辛苦温，行气止痛、健脾消食，擅于行气调中止痛，主治脾胃气滞之脘腹胀痛、食少吐泻及痢疾里急后重。香附偏疏肝调经，沉香降气温中，土木香、九香虫虽理气但无行气调中之专长"},{"q":"浮小麦可用治","o":["脏躁证","久咳虚喘","骨蒸劳热","饮食积滞","失眠多梦"],"a":2,"e":"浮小麦甘凉，益气、除热、止汗，主治自汗、盗汗及骨蒸劳热，故可用治骨蒸劳热。脏躁证宜甘麦大枣汤之甘草、小麦；久咳虚喘宜补肺肾止咳平喘药；饮食积滞宜消食药；失眠多梦宜养心安神药，均非浮小麦所主"},{"q":"味甘性平，寒热虚实出血病证均宜选用的药物是","o":["大蓟","茜草","蒲黄","三七","槐花"],"a":2,"e":"蒲黄甘平，止血、化瘀、通淋，性平和，止血而不留瘀，寒热虚实各类出血病证经适当配伍均可应用。大蓟、槐花性寒凉，茜草、三七偏温通，均非寒热虚实出血皆宜之品，故惟蒲黄味甘性平"},{"q":"功能活血通经，凉血祛风的药是","o":["丹参","红花","川芎","延胡索","凌霄花"],"a":4,"e":"凌霄花辛微寒，活血通经、凉血祛风，主治血瘀经闭、癥瘕及血热风痒、皮肤瘙痒，故功效如此。丹参、红花、川芎、延胡索均能活血，但无凉血祛风之功，或偏凉血、或偏行气止痛，均不兼备"},{"q":"用治风湿痹证兼夜盲者宜选用","o":["苍术","砂仁","木瓜","豆蔻","厚朴"],"a":0,"e":"苍术辛苦温，燥湿健脾、祛风散寒、明目，主治风湿痹痛及夜盲症、眼目昏涩，故风湿痹证兼夜盲者宜选。砂仁、豆蔻化湿行气，厚朴燥湿消痰下气，木瓜舒筋活络化湿，均无明目治夜盲之效"},{"q":"天南星的功效是","o":["燥湿化痰，降逆止呕","燥湿化痰，利气散结","燥湿化痰，宽胸散结","燥湿化痰，祛风止痉","燥湿化痰，疏散风热"],"a":3,"e":"天南星苦辛温、有毒，燥湿化痰、祛风止痉、散结消肿，主治湿痰咳嗽、风痰眩晕、癫痫惊风及痈肿。降逆止呕为半夏，利气散结为白芥子，宽胸散结为瓜蒌，疏散风热为薄荷，均非天南星之功效"},{"q":"药物“七情”的含义是","o":["喜、怒、忧、思、悲、恐、惊","辛、甘、酸、苦、咸、淡、涩","相须、相使、相畏、相杀、相恶、相反、单行","寒、热、温、凉、平、无毒、有毒","肝、心、脾、肺、肾、大肠、小肠"],"a":2,"e":"药物七情指单行、相须、相使、相畏、相杀、相恶、相反七种配伍关系，概括了药物配伍后的不同效应。喜怒忧思悲恐惊为七情（情志），辛苦酸苦咸淡涩为五味，寒热温凉平无毒有毒为四气毒性，肝心脾肺肾等为归经，均与药物七情不同"},{"q":"不属秦皮功效的是","o":["燥湿","止痢","止带","明目","解毒"],"a":4,"e":"秦皮苦涩寒，清热燥湿、收涩止痢、止带、明目，主治湿热泻痢、带下及目赤肿痛，无解毒之功。燥湿、止痢、止带、明目皆为其功效，解毒非秦皮所主，故不属秦皮功效的是解毒"},{"q":"白芍与当归的共同适应证为","o":["月经不调","肝阳眩晕","跌打损伤","痈疽疮疡","泻痢腹痛"],"a":0,"e":"白芍养血敛阴、柔肝止痛、平抑肝阳，当归补血活血、调经止痛，二者均入肝经血分，均能调经，共同适应证为月经不调。肝阳眩晕为白芍所主，跌打损伤、痈疽疮疡非二者所宜，泻痢腹痛为白芍柔肝止痛之特定应用"},{"q":"既能清肺化痰，又能宽胸散结的药物是","o":["知母","白前","瓜蒌","桔梗","百部"],"a":2,"e":"瓜蒌甘微苦寒，清肺化痰、宽胸散结、润肠通便，主治痰热咳嗽、胸痹结胸及乳痈，故既能清肺化痰又能宽胸散结。知母清热滋阴，白前降气化痰，桔梗宣肺利咽排脓，百部润肺止咳，均无清肺化痰兼宽胸散结之效"},{"q":"既能解表散寒，又能宣通鼻窍、温肺化饮的药物是","o":["防风","桂枝","荆芥","生姜","细辛"],"a":4,"e":"细辛辛温，解表散寒、祛风止痛、宣通鼻窍、温肺化饮，主治风寒感冒、头痛鼻塞及寒痰咳喘，故兼具解表散寒、通鼻窍、温肺化饮之功。防风、荆芥解表但无温肺化饮，桂枝、生姜温通但无宣通鼻窍之专效"},{"q":"肺胃热盛之出血，宜选用的药物是","o":["芦根","大蓟","小蓟","石膏","白茅根"],"a":4,"e":"白茅根甘寒，凉血止血、清热利尿，主入肺胃经，能清肺胃之热而凉血止血，善治肺胃热盛之吐血、衄血。芦根清热生津，大蓟、小蓟凉血止血但不清胃热，石膏清气分实热，均非肺胃热盛出血之主药"},{"q":"金银花除能清热解毒，疏散风热外，还具有的功效是","o":["助阳止泻","健脾止泻","涩肠止泻","凉血止痢","渗湿止泻"],"a":3,"e":"金银花甘寒，清热解毒、疏散风热，且能凉血止痢，主治热毒血痢及温病发热。助阳止泻、健脾止泻、涩肠止泻、渗湿止泻分别属补火助阳、健脾、收涩、利水渗湿药的功效，均与金银花清热解毒、凉血止痢之性不符"},{"q":"蕲蛇的功效是","o":["祛风湿、止痛、补肝肾","祛风、通络、止痉","祛风湿、补肝肾、强筋骨","祛风活络、凉血定惊","祛风除湿、散寒止痛"],"a":1,"e":"蕲蛇（白花蛇）甘咸温、有毒，祛风、通络、止痉，善治风湿痹痛、筋脉拘挛、口眼歪斜及小儿惊风、破伤风。补肝肾强筋骨属桑寄生、五加皮；凉血定惊属羚羊角；散寒止痛属川乌，均非蕲蛇之功效"},{"q":"柴胡与升麻均具有的功效是","o":["生津","透疹","升阳","解毒","收敛"],"a":2,"e":"柴胡与升麻均能升举阳气，主治气虚下陷之久泻脱肛、子宫脱垂及各型气陷证，故共有功效为升阳。透疹为升麻、薄荷、蝉蜕之能；生津为葛根、知母；解毒为升麻、甘草；收敛为龙骨、牡蛎，均非二药共有"},{"q":"萹蓄除能利尿通淋外，还能","o":["杀虫止痒","祛风止痒","通淋止痛","活血通经","润肠通便"],"a":0,"e":"萹蓄苦寒，利尿通淋、杀虫止痒，主治热淋涩痛及蛔虫腹痛、湿疹瘙痒。祛风止痒属荆芥、白鲜皮；通淋止痛为海金沙、石韦；活血通经属牛膝；润肠通便为火麻仁、郁李仁，均非萹蓄之效"},{"q":"能益气托疮生肌，被称为“疮痈圣药”的是","o":["连翘","黄芪","白芷","蒲公英","紫花地丁"],"a":1,"e":"黄芪甘微温，补气升阳、固表止汗、利水消肿、托疮生肌，气血不足之疮疡久溃不敛用之可益气托毒、生肌收口，故被称为“疮痈圣药”。连翘、蒲公英、紫花地丁清热解毒消痈，白芷消肿排脓，均无益气托疮生肌之功"},{"q":"能补火助阳，益阳消阴，引火归元，为治命门火衰之要药的是","o":["干姜","桂枝","丁香","肉桂","吴茱萸"],"a":3,"e":"肉桂辛甘大热，补火助阳、引火归元、散寒止痛、温通经脉，善治命门火衰之腰膝冷痛、阳痿及虚阳上浮，故为要药。干姜温中回阳，桂枝温通经脉，丁香温中降逆，吴茱萸疏肝下气，均无引火归元、补命门火之专功"},{"q":"理气药中，用于治疗胃肠积滞、脘腹痞满，为破气除痞之要药的是","o":["青皮","甘松","枳实","佛手","荔枝核"],"a":2,"e":"枳实苦辛酸微寒，破气消积、化痰除痞，主治胃肠积滞、脘腹痞满胀痛及泻痢后重，为破气除痞之要药。青皮疏肝破气，佛手、荔枝核理气，甘松开郁醒脾，均无破气除痞、消积导滞之峻力"},{"q":"下列药物用法哪项是错误的","o":["旋覆花布包入汤剂","琥珀入汤剂","钩藤入汤剂后下","雷丸研末冷开水凋服","麝香入丸散服"],"a":1,"e":"琥珀为树脂类化石，不溶于水，入汤剂有效成分难以溶出，且受热易破坏，宜研末冲服或入丸散，故“琥珀入汤剂”用法错误。旋覆花布包煎、钩藤后下、雷丸研末冷开水调服、麝香入丸散均符合各药用法要求"},{"q":"青蒿治疟疾寒热往来，最佳用法是","o":["鲜用，绞汁服","阴干，久煎","鲜用，久煎","阴干，包煎","炒用，煎服"],"a":0,"e":"青蒿中所含青蒿素受热易被破坏，治疟疾寒热往来须鲜用绞汁服，方能保留抗疟有效成分。阴干久煎、炒用煎服或鲜用久煎均因高温而药效大减，包煎亦无必要。阴干者气味已泄，绞汁不经火炼，则青蒿素之抗疟力得以保全"},{"q":"患者，男，55岁。近2周常有下肢挛急作痛，最宜选用的药组是","o":["桂枝，白芍","细辛，干姜","甘草，白芍","独活，羌活","黄芪，防风"],"a":2,"e":"下肢挛急作痛属阴血不足、筋脉失养，甘草与白芍相配即芍药甘草汤，酸甘化阴、缓急止痛，最为对证。桂枝白芍偏调和营卫，细辛干姜温里散寒，独活羌活祛风湿，黄芪防风益气固表，均非缓急止痛之组。甘草白芍酸甘化阴，筋脉得养则挛急自止，配伍精简而力专"},{"q":"黄芪与茯苓配伍，茯苓能增强黄芪的补气利水作用，这种配伍关系是","o":["相须","相使","相反","相恶","相畏"],"a":1,"e":"相使指一药为主、一药为辅，辅药能提高主药功效。黄芪补气利水为主，茯苓健脾渗湿为辅，可增强黄芪补气利水之力，故属相使。相须为功效相似者互补，相反、相恶、相畏分属配伍禁忌、减效与毒性制约，均不符。相须双药并重无主辅之分，相使则明确主辅，茯苓于黄芪正是辅佐之品"},{"q":"下列药物中，可以治疗胃下垂、子宫脱垂的药物是","o":["甘松","枳实","乌药","荔枝核","川楝子"],"a":1,"e":"枳实行气力强，能升提中气，可用治胃下垂、子宫脱垂、脱肛等中气下陷之证。甘松行气开郁止痛，乌药行气散寒，荔枝核行气散结，川楝子行气泄热，皆无升提举陷之功。升提中气治脱垂多推升麻、柴胡、补中益气，枳实则以行气导滞见长，配益气药方显升提"},{"q":"出血过多，气随血脱时，宜急投大剂的","o":["收敛止血药","化瘀止血药","补气固脱药","温经止血药","凉血止血药"],"a":2,"e":"出血过多致气随血脱，阳气暴亡，须急投大剂补气固脱药以挽回将绝之阳气，此即有形之血不能速生、无形之气所当急固。各类止血药仅能塞其流，不能回其脱，故均非急投之品。此时当以人参、黄芪大剂浓煎顿服，先固其气，血脱者亦得有所附"},{"q":"具解毒散结之功，可用治赘疣，癌肿的药物是","o":["猪苓","香加皮","薏苡仁","滑石","泽泻"],"a":2,"e":"薏苡仁健脾渗湿之外，尚能解毒散结，可用于赘疣、癌肿及肠痈、肺痈。猪苓、泽泻、滑石纯为利水渗湿药，无解毒散结之功；香加皮祛风湿、强筋骨，于赘疣癌肿非其所长。赘疣、癌肿多属痰瘀毒结，薏苡仁解毒散结兼健脾，故可久服渐消"},{"q":"具有破血逐瘀之功，用于干血成劳，经闭腹痛的首选药是","o":["苏木","土鳖虫","马钱子","骨碎补","自然铜"],"a":1,"e":"土鳖虫咸寒，破血逐瘀、续筋接骨，善治干血成劳、经闭腹痛及癥瘕痞块。苏木活血疗伤，马钱子散结通络，骨碎补补肾续伤，自然铜散瘀接骨，均非干血经闭之首选。土鳖虫又能续筋接骨，跌打骨折亦常用，然破血逐瘀以治干血经闭为首功"},{"q":"大量服用可引起呃逆、眩晕、呕吐、腹泻等反应的药物是","o":["榧子","雷丸","槟榔","川楝子","使君子"],"a":4,"e":"使君子甘温，杀虫消积，大量服用可引起呃逆、眩晕、呕吐、腹泻等反应，故须控制剂量。槟榔行气导滞，川楝子行气泄热，榧子、雷丸杀虫力较缓，均无此典型不良反应。使君子杀虫消积，治蛔虫疳积，过量则呃逆，故小儿须按年龄定量"},{"q":"药用部位是花蕾的药物是","o":["丁香","夏枯草","高良姜","天花粉","小茴香"],"a":0,"e":"丁香为桃金娘科植物丁香的干燥花蕾，故药用部位是花蕾。夏枯草药用果穗，高良姜用根茎，天花粉为块根，小茴香用成熟果实，均非以花蕾入药。丁香含挥发油，芳香辛烈，花蕾中有效成分最丰，故以花蕾入药"},{"q":"具有纳气平喘作用的药物是","o":["香附","沉香","枳实","青皮","薤白"],"a":1,"e":"沉香辛微温，行气止痛、温中止呕、纳气平喘，可治肾不纳气之虚喘。香附疏肝理气，枳实破气消积，青皮疏肝破气，薤白通阳散结，均无纳气归肾之用。沉香质重沉降，直入下焦，温肾纳气使浮阳归原，故虚喘得以平复"},{"q":"磁石善于治疗","o":["肺气不足之虚喘","肾不纳气之虚喘","肺气壅滞之喘满","痰壅气逆之咳喘","热邪壅肺之咳喘"],"a":1,"e":"磁石咸寒，益肾养肝、聪耳明目、纳气平喘，善治肾不纳气之虚喘。肺气不足之虚喘宜补肺，肺气壅滞、痰壅气逆及热邪壅肺之喘满皆属实证，非磁石重镇纳气所主。磁石质重能吸铁，取其重镇之性纳气归肾，与蛤蚧、沉香纳气平喘相类"},{"q":"杨某，男，32岁。高热不退，已3日不大便，腹部胀满拒按，时有谵语，言语不清，面色红赤，脉沉实有力，宜首选","o":["生地黄","牡丹皮","大黄","巴豆霜","甘遂"],"a":2,"e":"高热不退、不大便、腹胀满拒按、谵语、脉沉实有力为阳明腑实重证，大黄苦寒泻下，荡涤肠胃、泻火逐瘀，当首选。巴豆霜、甘遂峻下逐水，性猛有毒，非热结燥屎所宜；生地、丹皮只清热凉血。大黄泻下在于结合型蒽醌，生用泻下峻猛，故热结燥屎非此不可"},{"q":"桑白皮最宜用于","o":["脾虚水肿见便溏","全身水肿兼喘咳","肾虚水肿下身肿著","全身水肿，面目发黄","水肿兼恶寒发热，汗出"],"a":1,"e":"桑白皮泻肺平喘、利水消肿，主治肺热咳喘及水肿尿少，以全身水肿兼喘咳最为对证。脾虚便溏水肿宜健脾，肾虚下身肿宜温肾，湿热发黄宜利湿退黄，风水恶寒发热宜发汗，皆非其主治。桑白皮泻肺中水气而平喘，水饮去则肿消，肺气降则咳止，水肿兼喘最宜"},{"q":"蒺藜与蝉蜕都能治疗的病症是","o":["中风面瘫","乳闭不通","风疹瘙痒","瘰疬痰核","急慢惊风"],"a":2,"e":"蒺藜祛风明目、疏肝解郁，蝉蜕疏散风热、利咽退翳止痉，二者均能疏风止痒，共治风疹瘙痒。中风面瘫、急慢惊风多取息风止痉药，乳闭不通、瘰疬痰核非二者共性。蒺藜兼疏肝明目，蝉蜕兼利咽退翳止痉，二者止痒皆取其疏散风热之力"},{"q":"发散风寒药的药性特点是","o":["苦，寒","苦，温","辛，凉","甘，寒","辛，温"],"a":4,"e":"发散风寒药多属辛温，辛能发散、温可祛寒，善治风寒表证。苦寒、甘寒性清泄，辛凉为发散风热药之性，苦温多燥湿，均非发散风寒药之药性特点。辛温之品如麻黄、桂枝、荆芥、防风，皆能开腠发汗、祛散风寒以解表"},{"q":"均可以疏肝理气的药物有","o":["陈皮、青皮","木香、沉香","薤白、甘松","香附、佛手","枳实、刀豆"],"a":3,"e":"香附疏肝理气、调经止痛，佛手疏肝理气、和中化痰，二者均可疏肝理气。陈皮、青皮偏理气健脾与破气，木香、沉香重在行气调中与降气，薤白、甘松开郁醒脾，枳实、刀豆降气止呃，非疏肝专药。香附为疏肝理气要药，佛手兼化痰和中，二者性较平和，常治肝郁气滞"},{"q":"治疗痰壅气逆，咳喘痰多之要药是","o":["百部","款冬花","桑白皮","紫苏子","苦杏仁"],"a":3,"e":"紫苏子降气化痰、止咳平喘、润肠通便，主痰壅气逆、咳喘痰多，为治痰咳气逆之要药。百部、款冬花润肺止咳，桑白皮泻肺，苦杏仁降气，均不以降气化痰见长。苏子降气之力峻，痰随气降则咳喘平，兼能润肠，使气逆得以下行"},{"q":"治疗营血亏虚，肝肾不足之痹痛的药物是","o":["蕲蛇","威灵仙","桑枝","桑寄生","海风藤"],"a":3,"e":"桑寄生祛风湿、补肝肾、强筋骨、养血安胎，尤宜营血亏虚、肝肾不足之痹痛腰膝酸软。蕲蛇、威灵仙、海风藤偏搜风通络，桑枝祛风通络利关节，均无补肝肾、养血之功。桑寄生补肝肾养血而祛风湿，标本兼顾，老人血虚风湿腰腿痛最宜"},{"q":"某医师治疗毒蛇咬伤时常用多味中药捣烂外敷，其中所含虎杖发挥的功效是","o":["清热利湿","清热解毒","敛疮生肌","消痰燥湿","散结消肿"],"a":1,"e":"虎杖外敷能清热解毒、散瘀止痛，治毒蛇咬伤正取其解毒之功。清热利湿主治湿热黄疸淋浊，敛疮生肌、消痰燥湿、散结消肿皆非其治蛇伤外敷所发挥之功效。虎杖外敷可解毒消肿、散瘀止痛，蛇毒局部敷之能消肿定痛，故为常用"},{"q":"某医师治疗小儿咳嗽，处方中擅于用车前子，其中车前子发挥的功效是","o":["润肺袪痰","清肺袪痰","滋阴润肺","温肺袪痰","降气祛痰"],"a":1,"e":"车前子清肺化痰止咳，小儿咳嗽痰多用之，取其清肺祛痰之效。润肺祛痰、滋阴润肺多用于肺燥阴虚，温肺祛痰治寒痰，降气祛痰重在苏子之类，均与车前子清利之性不符。车前子利水之余能清肺化痰，使痰从小便而去，肺热咳嗽痰多用之"},{"q":"木通除利尿通淋，清心除烦外，还能","o":["祛湿敛疮","明目，祛痰","祛风止痒","通经下乳","凉血止血"],"a":3,"e":"木通利尿通淋、清心除烦，又能通经下乳，可治经闭、乳少。祛湿敛疮、明目祛痰、祛风止痒、凉血止血均非木通功效，其兼能通利血脉以下乳为辨识要点。木通上能清心火、下能利湿热，通乳汁须配王不留行、穿山甲之类"},{"q":"紫苏叶的功效不包括","o":["发表散寒","理气安胎","疏肝解郁","行气宽中","解鱼蟹毒"],"a":2,"e":"紫苏叶发表散寒、行气宽中、理气安胎、解鱼蟹毒，并无疏肝解郁之功，故为不包括项。发表散寒、理气安胎、行气宽中、解鱼蟹毒皆其所有，疏肝解郁当求香附、柴胡一类。紫苏叶发表散寒、行气宽中，兼解鱼蟹毒、安胎，独无疏肝解郁之功"},{"q":"性能功效相类似的药物配合应用，可增强原有疗效的配伍关系是","o":["相须","相使","相畏","相杀、相畏","相恶"],"a":0,"e":"相须指性能功效相类似的药物配合应用，可相互增强原有疗效，如石膏配知母。相使以一药为主、一药为辅，相畏为毒性被它药制约，相杀为能解它药之毒，相恶为减效，均非功效相似互补。相须之药性能相类，无主辅之分，如知母配黄柏、大黄配芒硝之类"},{"q":"罂粟壳的使用注意不包括","o":["不宜常服","儿童禁用","孕妇禁用","老年人禁用","运动员慎用"],"a":3,"e":"罂粟壳酸涩有毒，易成瘾，不宜常服，孕妇、儿童禁用，运动员慎用；老年人并非绝对禁用，故为不包括项。其余四项均属其使用注意，重点在成瘾性与特殊人群。罂粟壳为麻醉药品，久服成瘾，故久咳久痢虽有敛涩之效亦当暂用"},{"q":"药性偏凉的药物是","o":["人参","黄芪","党参","白术","西洋参"],"a":4,"e":"西洋参甘微苦凉，补气养阴、清热生津，药性偏凉，宜气阴两虚兼热者。人参、黄芪、党参、白术均微温或平，重在补气温阳健脾，无清热之凉性。西洋参补气兼清热养阴，暑热耗气伤津者宜之，与红参温补迥异"},{"q":"只入心经的重镇安神药是","o":["朱砂","磁石","琥珀","龙骨","牡蛎"],"a":0,"e":"朱砂甘寒有毒，专入心经，重镇安神、清热解毒，为只入心经之重镇安神药。磁石入肝肾，琥珀入心肝膀胱，龙骨、牡蛎入心肝肾，归经皆非独入心经。朱砂色赤入心，质重镇怯，故专镇心神而解毒，不入余经"},{"q":"既能镇惊安神，又能平肝潜阳，还能收敛固涩的药是","o":["朱砂","龙骨","磁石","琥珀","龙齿"],"a":1,"e":"龙骨甘涩平，镇惊安神、平肝潜阳、收敛固涩，三功兼备。朱砂、琥珀重在安神，磁石、龙齿偏潜阳安神，均无收敛固涩之能；牡蛎虽能潜阳软坚，亦非三功俱全者。龙骨为古代动物骨骼化石，煅用收敛固涩之力增，治自汗、滑精、崩带"},{"q":"猪苓、茯苓的入药部位是","o":["根或根茎","菌核","根皮","花朵","花粉"],"a":1,"e":"猪苓、茯苓均为多孔菌科真菌的干燥菌核，故入药部位是菌核。根或根茎、根皮、花朵、花粉分属其他药材的药用部位，与二者来源不同。二药均寄生松根，茯苓菌核抱松根而生，猪苓菌核黑润，皆非植物根皮"},{"q":"治疗热病伤阴，虚烦不眠，首选","o":["豆豉、栀子","青蒿、鳖甲","黄连、朱砂","人参、茯苓","黄连、阿胶"],"a":4,"e":"热病伤阴、虚烦不眠属阴虚火旺、心肾不交，黄连阿胶汤清热降火、滋阴养血，故首选黄连、阿胶。青蒿、鳖甲治温病后期夜热早凉，豆豉、栀子治虚烦但无滋阴，人参、茯苓补气健脾。黄连阿胶汤中黄连清心火、阿胶滋肾阴，水火既济则烦躁不眠可除"},{"q":"佛手的功效是和中化痰，又能","o":["行气消积","疏肝理气","疏肝破气","行气散结","补肾纳气"],"a":1,"e":"佛手辛温，疏肝理气、和中化痰、行气止痛，故和中化痰之外又能疏肝理气。行气消积、行气散结非其长，疏肝破气为青皮之功，补肾纳气属沉香、蛤蚧。佛手芳香醒脾，疏肝不峻、理气不燥，肝郁胃痛、胸胁胀满常投"},{"q":"治温病热伤肺脏气阴所致的短气咳喘，最宜选用","o":["红参","麦冬","枇杷叶","西洋参","苦杏仁"],"a":3,"e":"西洋参补气养阴、清热生津，善治温病热伤肺脏气阴之短气咳喘。红参偏温补，麦冬养阴润肺而补气力弱，枇杷叶、苦杏仁降气止咳，均无益气养阴双补之长。西洋参性凉，补气而不助火，温病气阴两伤者用之无燥烈之弊"},{"q":"不属于丹参主治病证的是","o":["痛经","心悸失眠","癥瘕积聚","湿热黄疸","疮疡痈肿"],"a":3,"e":"丹参活血调经、凉血消痈、除烦安神，主治痛经经闭、癥瘕积聚、心悸失眠及疮疡痈肿；湿热黄疸非其主治，当用茵陈、栀子等利湿退黄之品。丹参功专活血调经、凉血消痈，湿热黄疸须用茵陈蒿汤一类清利"},{"q":"煅后水飞可点眼以治肝火目赤翳障的中药是","o":["地龙","天麻","蒺藜","赭石","石决明"],"a":4,"e":"石决明咸寒，平肝潜阳、清肝明目，煅后水飞点眼可治肝火目赤翳障。地龙、天麻、蒺藜均无煅制点眼之用，赭石虽煅用但主降逆止呕、凉血止血，不治目翳。石决明为鲍科贝壳，咸寒潜阳、清肝明目，煅后水飞点眼能退翳"},{"q":"有毒，孕妇及肝肾功能不全者应慎服的药物是","o":["榧子","雷丸","槟榔","苦楝皮","使君子"],"a":3,"e":"苦楝皮苦寒有毒，杀虫疗癣，内服宜慎，孕妇及肝肾功能不全者应慎服。榧子、使君子毒性较小，雷丸、槟榔虽可杀虫，但无此明确的肝肾功能不全慎用要求。苦楝皮内服宜慎，过量可致肝损伤，故肝病、孕妇及肾功能不全者忌服"},{"q":"蛇床子具有的药理作用是","o":["抗癌","止泻","止血","降血糖","抗细菌、真菌"],"a":4,"e":"蛇床子外用杀虫止痒、温肾壮阳，现代药理证实对细菌、真菌有抑制作用，故为抗细菌、真菌。抗癌、止泻、止血、降血糖均非其主要药理作用。蛇床子外用治湿疹阴痒，其抗真菌作用对皮肤癣证尤为明显"},{"q":"性大寒，专泻肺中水饮及痰火而平喘咳的药物为","o":["竹沥","前胡","贝母","桑白皮","葶苈子"],"a":4,"e":"葶苈子大寒，专泻肺中水饮及痰火而平喘咳，善治痰饮喘满、肺痈。竹沥清热滑痰，前胡、贝母降气化痰，桑白皮泻肺而力较缓，均非专泻肺中水饮痰火之峻药。葶苈子泻肺力猛，肺痈、胸水、喘不得卧者用之，专泻肺中水饮痰火"},{"q":"具有清热泻火，解毒，利水消肿功效的药物是","o":["夏枯草","密蒙花","青葙子","决明子","鸭跖草"],"a":4,"e":"鸭跖草甘寒，清热泻火、解毒、利水消肿，三功兼备。夏枯草清肝散结，密蒙花、青葙子、决明子均偏清肝明目，无利水消肿之效。鸭跖草为清热利水之品，热毒疮痈、水肿尿少及感冒发热皆可投，其利水兼能解毒，热淋涩痛亦宜"},{"q":"敛肺定喘，治哮喘咳嗽，宜选用","o":["桔梗","百部","白果","白前","半夏"],"a":2,"e":"白果甘苦涩平，敛肺定喘、收涩止带，治哮喘咳嗽、带下白浊。桔梗宣肺利咽，百部、款冬花润肺止咳，白前降气化痰，半夏燥湿化痰，均无敛肺定喘之功。白果有毒宜炒制去壳，敛肺定喘兼收涩止带，小儿用量宜慎"},{"q":"辛夷的主治证是","o":["风寒头痛，鼻渊","目赤肿痛","巅顶痛","牙痛","咽喉肿痛"],"a":0,"e":"辛夷辛温，发散风寒、宣通鼻窍，主治风寒头痛、鼻渊鼻塞流涕。目赤肿痛属肝火，巅顶痛多求藁本，牙痛、咽喉肿痛为火热上炎，均非辛夷所主。辛夷有毛，入煎宜包煎，专通鼻窍，为鼻渊头痛、鼻塞流涕之要药"},{"q":"金银花与连翘配伍使用，属于哪种配伍关系","o":["相杀","相畏","相反","相须","相使"],"a":3,"e":"金银花、连翘均能清热解毒、疏散风热，性能功效相类，合用相互增强，属相须。相杀、相畏为毒性制约关系，相反为配伍禁忌，相使有主辅之分，均非此类配伍。二药均清热解毒，银花偏散风热，连翘偏消痈散结，相须则解毒力倍增"},{"q":"临床外用可以治疗白癜风的药物有","o":["淫羊藿、肉苁蓉","补骨脂、益智仁","吴茱萸、肉苁蓉","补骨脂、菟丝子","益智仁、菟丝子"],"a":3,"e":"补骨脂、菟丝子均能补肾，外用可治白癜风，补骨脂含光敏成分尤为常用。淫羊藿、肉苁蓉偏补肾阳，益智仁温脾摄唾，均无外用治白癜风之长。补骨脂、菟丝子温补肾阳，外用酊剂涂擦可促黑色素生成以治白癜风"},{"q":"因心阳不振而致心悸、脉结代，宜用","o":["桂枝配白芍","桂枝配白术","桂枝配茯苓","桂枝配生姜","桂枝配甘草"],"a":4,"e":"心阳不振、心悸脉结代宜桂枝配甘草，即桂枝甘草汤，辛甘化阳以温通心阳。桂枝配白芍调和营卫，配白术健脾，配茯苓利水，配生姜解表散寒，均非温复心阳之配。桂枝甘草汤药简力专，桂枝温通心阳、甘草益气和中，辛甘化阳以复脉"},{"q":"治疗湿热脚气，痿证，苍术常配伍的药是","o":["黄柏","黄芩","黄连","知母","石膏"],"a":0,"e":"湿热脚气、痿证宜苍术配黄柏，即二妙散，苍术燥湿健脾、黄柏清热燥湿，相须为用。黄芩偏清上焦，黄连偏清中焦，知母、石膏清气分实热，均非治湿热下注之配。二妙散中苍术燥湿健脾治本，黄柏清热燥湿治标，湿热下注痿痹皆宜"},{"q":"酒炒可使药性转化为","o":["藏","沉","降","收","升"],"a":4,"e":"酒制能升提药性，故酒炒可使药性转化为升，引药上行。藏、沉、降多属沉降特性，收为酸涩之性，均与酒炒升散之性相反。酒性升散引药上行，故头面上焦之疾多用酒制，如酒大黄、酒黄芩；盐制则下行入肾，醋制则收敛入肝"},{"q":"无疏肝理气、和胃止痛作用的药物是","o":["香橼","梅花","娑罗子","九香虫","玫瑰花"],"a":3,"e":"九香虫理气止痛、温中壮阳，无疏肝理气、和胃止痛之功，故为无此项者。香橼、梅花、玫瑰花、娑罗子均能疏肝理气、和胃止痛，为常用疏肝和胃药。九香虫咸温，理气止痛、温中壮阳，治胃寒胀痛、肾虚阳痿，无疏肝功"},{"q":"虎杖除治疗湿热黄疸，淋浊，带下外，还可以治疗","o":["乳汁不下","疮痈肿毒","脾虚泄泻","目暗昏花","遗精滑泄"],"a":1,"e":"虎杖利湿退黄、利尿通淋、清热解毒、散瘀止痛，除湿热黄疸、淋浊、带下外，还可治疮痈肿毒、水火烫伤。乳汁不下、脾虚泄泻、目暗昏花、遗精滑泄均非其主治。虎杖又能散瘀通经、清热解毒，疮痈肿毒、跌打瘀痛、水火烫伤皆可治"},{"q":"具有清热燥湿作用的药物应具有何种药味","o":["酸","苦","甘","辛","咸"],"a":1,"e":"苦味能泄能燥，清热燥湿药多苦寒，苦寒相合既清热又燥湿，故具清热燥湿作用者应为苦味。酸味收敛，甘味补缓，辛味发散，咸味软坚，均非燥湿之味。苦能泄、能燥、能坚，清热燥湿药多苦寒，如芩、连、柏皆泄火燥湿"},{"q":"蜈蚣入汤剂的常规用量是","o":["0、5～1g","1～3g","3～5g","3～10g","9～15g"],"a":1,"e":"蜈蚣有毒，入汤剂常规用量为1～3g，研末冲服则量更小。0.5～1g多为研末用量，3～5g、3～10g、9～15g均超出常规汤剂用量，易致中毒。蜈蚣有毒用量不可过大，研末冲服每次0.5～1g，孕妇忌用"},{"q":"咸味药的功效包括","o":["活血破瘀","利水通淋","泻下通肠","养阴润燥","理气散结"],"a":2,"e":"咸味能软坚散结、泻下通肠，如芒硝咸寒泻下，故咸味药功效包括泻下通肠。活血破瘀多属辛，利水通淋多属淡，养阴润燥属甘寒，理气散结属辛，均非咸味所主。咸入肾，能软坚散结、泻下通便，瘰疬、痰核、便秘多用咸寒之品"},{"q":"三棱、莪术除破血行气外，又能","o":["通经止痛","消积止痛","消肿生肌","散积消癥","散结消肿"],"a":1,"e":"三棱、莪术破血行气、消积止痛，善治癥瘕痞块、瘀滞经闭及食积脘腹胀痛。通经止痛为活血调经药之功，消肿生肌、散结消肿多属外科敛疮之品，非二者并称之功效。三棱破血力峻，莪术行气力优，二者相须，瘀滞经闭、食积腹痛皆治"},{"q":"治疗鼻渊，流涕 ，头痛，宜首选的药物是","o":["桂枝","紫苏叶","葛根","藁本","苍耳子"],"a":4,"e":"苍耳子散风寒、通鼻窍、祛风湿，为治鼻渊头痛、鼻塞流涕之要药。桂枝、紫苏叶发散风寒但无通窍之长，葛根解肌升阳，藁本治巅顶头痛，均非鼻渊首选。苍耳子有小毒须炒用，专通鼻窍、散风湿，为鼻渊流涕头痛之要药"},{"q":"功效与龙骨相似，又长于软坚散结的药物是","o":["牡蛎","磁石","赭石","龙齿","珍珠母"],"a":0,"e":"牡蛎与龙骨均能镇惊安神、平肝潜阳、收敛固涩，且牡蛎咸寒软坚，长于消痰软坚散结，治瘰疬痰核。磁石、赭石偏潜阳降逆，龙齿专安神，珍珠母安神明目，均无软坚散结之功。牡蛎咸寒，生用潜阳、煅用固涩，又软坚散结，治瘰疬、盗汗、惊悸"},{"q":"用于凉血止血，宜选择","o":["熟大黄","生大黄","酒炒大黄","醋炒大黄","大黄炭"],"a":4,"e":"大黄炭性涩，泻下力大减，长于凉血止血，用于血热妄行之吐血、便血、尿血。生大黄泻下攻积，熟大黄泻下力和缓，酒炒大黄清上焦热，醋炒大黄活血，均非凉血止血之品。大黄炭泻下力微、止血力增，血热出血宜之，生大黄则主泻下攻积"},{"q":"十九畏中的意义相当于七情中的","o":["相畏","相须或相使","相畏或相杀","相恶或相反","相使"],"a":3,"e":"十九畏属配伍禁忌，两药同用相互制约或产生毒性，相当于七情中的相恶或相反。相畏、相杀为毒性被制约或能解毒，属有利配伍；相须、相使为增效配伍，皆非禁忌范畴。十九畏所列相克之药，同用则减效或增毒，属配伍禁忌，与相恶相反同类"},{"q":"大蓟、小蓟皆可用于治疗","o":["肝火目赤","肺热咳嗽","胃火牙痛","热淋涩痛","热毒疮疡"],"a":4,"e":"大蓟、小蓟均凉血止血、散瘀解毒消痈，除血热出血外，皆可用于热毒疮疡。肝火目赤、肺热咳嗽、胃火牙痛、热淋涩痛各有所专之药，非二蓟所共有主治。大蓟兼散瘀，小蓟兼利尿，二者凉血止血、解毒消痈，热毒疮疡可外敷内服"},{"q":"疏散退热宜生用，疏肝解郁宜醋炙，升举阳气可生用或酒炙的药物是","o":["菊花","柴胡","蝉蜕","淡豆豉","牛蒡子"],"a":1,"e":"柴胡生用疏散退热，醋炙增强疏肝解郁，生用或酒炙可升举阳气，炮制不同则功效各异。菊花、蝉蜕、牛蒡子、淡豆豉均无此生用、醋炙、酒炙的功效变化。柴胡生用升散退热，醋炙入肝增疏肝之力，酒炙升提阳气，炮制各有所宜"},{"q":"既能用于风湿痹证，腰膝酸软，下肢无力。又可用于遗尿，白带过多的药物是","o":["千年健","五加皮","桑寄生","狗脊","雪莲花"],"a":3,"e":"狗脊祛风湿、补肝肾、强筋骨、温腰膝，又能温肾固摄，治遗尿、白带过多。千年健、五加皮、桑寄生祛风湿、补肝肾但无固摄止带疗遗尿之功，雪莲花温肾助阳亦非所宜。狗脊有毛须去毛用，补肝肾、强腰膝、祛风湿，兼温肾固摄止遗止带"},{"q":"下列哪味药物麸炒后可降低其燥烈之性","o":["厚朴","佩兰","广藿香","苍术","肉豆蔻"],"a":3,"e":"苍术辛苦温燥，麸炒可缓和其燥烈之性并增强健脾作用。厚朴、佩兰、广藿香、肉豆蔻虽可炮制，但降低燥烈之性正是苍术麸炒的典型目的。苍术燥烈，麸炒后缓其性、增健脾，茅苍术尤良，湿盛困脾者宜炒用"},{"q":"功能疏散风热，清利头目，可用治风热上攻，目赤肿痛，目昏多泪，牙龈肿痛的药物是","o":["菊花","牛蒡子","蔓荆子","香薷","柴胡"],"a":2,"e":"蔓荆子疏散风热、清利头目，治风热上攻之目赤肿痛、目昏多泪及牙龈肿痛。菊花、柴胡虽疏散风热，清利头目兼治牙痛非其专长；牛蒡子偏利咽，香薷偏解表化湿。蔓荆子轻清上行，专清头目风热，目赤多泪、头胀牙痛、耳鸣皆治"},{"q":"患者风湿痹痛，尤以肩臂疼痛为甚，最宜选用的药是","o":["川芎","独活","乳香","姜黄","威灵仙"],"a":3,"e":"姜黄活血行气、通经止痛，尤长于治风湿痹痛以上肢肩臂为甚者。川芎活血行气祛风，独活善治下半身痹痛，乳香活血止痛，威灵仙通络，均无治肩臂痛之专功。姜黄辛温行散，横走肩臂，活血行气、通经止痛，风湿肩臂痛尤宜"},{"q":"治疗悬饮咳喘，胸胁胀痛，常用芥子，因其能","o":["燥湿化痰，祛风止痉","消痰散结，降逆止呕","温肺豁痰，利气宽胸","清热化痰，润肺止咳","温肺化饮，消痰软坚"],"a":2,"e":"芥子温肺豁痰、利气散结、通络止痛，治悬饮咳喘、胸胁胀痛，正取其温肺豁痰、利气宽胸。燥湿化痰、祛风止痉为白僵蚕一类，消痰散结、降逆止呕、清热化痰及温肺化饮消痰软坚均非芥子功效。芥子辛温走窜，善豁痰利气、通络散结，悬饮、痰饮、阴疽皆可投"},{"q":"苦寒泻下，荡涤肠胃，走而不守，有“将军”之称，为治热结便秘要药的是","o":["大黄","芒硝","番泻叶","牵牛子","巴豆"],"a":0,"e":"大黄苦寒泻下，荡涤肠胃、泻火解毒、逐瘀通经，走而不守，有将军之称，为治热结便秘之要药。芒硝软坚润燥，番泻叶缓泻，牵牛子逐水，巴豆辛热峻泻，均无将军之誉。大黄苦寒沉降，泻下、清热、凉血、逐瘀兼备，实热积滞、血热出血咸宜"},{"q":"善治情志忧郁，失眠，心神不安的药物是","o":["山药","灵芝","酸枣仁","合欢皮","珍珠母"],"a":3,"e":"合欢皮解郁安神、活血消肿，善治情志忧郁、心神不安、失眠。山药、灵芝、酸枣仁补益安神，珍珠母重镇安神，均无解郁之能。合欢皮甘平，解郁安神、活血消肿，情志不遂之失眠心烦、跌打瘀肿皆治"},{"q":"朱砂内服，正确的方法是","o":["先煎","后下","冲服","包煎","泡酒服"],"a":2,"e":"朱砂有毒，不宜入煎剂，内服多研末冲服或入丸散，以避高温增毒。先煎、后下、包煎皆为汤剂用法，泡酒服更助汞溶出而增毒，均非正确之法。朱砂主含硫化汞，遇热可分析出汞，故禁火煅，只宜研末冲服或入丸散"},{"q":"风寒感冒，肩背疼痛，腰以上风寒湿痹，最宜选用的药物是","o":["荆芥","香薷","辛夷","紫苏叶","羌活"],"a":4,"e":"羌活解表散寒、祛风除湿、止痛，善治风寒感冒、肩背疼痛及腰以上风寒湿痹。荆芥、紫苏叶解表力缓，香薷化湿，辛夷通鼻窍，均无祛上半身风湿之专功。羌活善走太阳经，祛上焦风湿而止痛，肩背头项痛及风寒感冒皆宜"},{"q":"不具有沉降作用的药物是","o":["大黄","芒硝","山楂","栀子","羌活"],"a":4,"e":"羌活辛温升散，主升浮，善走上焦肌表，故不具有沉降作用。大黄、芒硝泻下，栀子清热，山楂消导，均主沉降下行，与羌活升散之性相反。羌活辛温升散主升浮，善治上半身痹痛；独活沉降，专治下半身风湿"},{"q":"中药学中广义的“毒”不包括","o":["药物的总称","药物的偏性","药物剂量的大小","药物作用的强弱","药物的毒副作用"],"a":2,"e":"中药学广义之毒指药物的总称、药物的偏性以及毒副作用，即凡药皆有毒。药物剂量大小属用量范畴，不属广义之毒的内涵，故为不包括项。古之毒泛指药物，狭义方指毒副作用，药性偏性亦属毒，剂量大小不在其列"},{"q":"杜仲常用于治疗的病证有","o":["跌打损伤、痰热阻滞","肝阳上亢、视物昏花","肝肾亏虚、妊娠胎漏","肾不纳气、湿热淋证","肺热咳喘、妊娠胎漏"],"a":2,"e":"杜仲补肝肾、强筋骨、安胎，主治肝肾亏虚之腰膝酸痛、筋骨无力及妊娠胎漏、胎动不安。跌打损伤、肝阳上亢、肾不纳气、肺热咳喘皆非其主治。杜仲补肝肾、强筋骨，为腰膝酸痛、胎动不安要药，性温不燥可久服"},{"q":"黄芪通过补气作用不能达到的间接功效是","o":["生血","行血","摄血","生津","壮阳"],"a":4,"e":"黄芪补气升阳、固表止汗、利水消肿、托毒生肌，通过补气可生血、行血、摄血、生津，但无壮阳之功，不能温补肾阳，故壮阳为补气不能达到的间接功效。黄芪补气以生血、摄血、行血、生津，皆气旺之功，温阳壮火非其所长"},{"q":"既能化瘀止血，又能凉血止血的药物是","o":["生地","三七","茜草","蒲黄","大黄"],"a":2,"e":"茜草凉血止血、活血化瘀，止血而不留瘀，兼具化瘀止血与凉血止血两功。三七化瘀止血而无凉血之功，生地、大黄炭偏凉血，蒲黄收涩止血，均非两功兼备。茜草生用凉血止血、活血通经，炒炭则收敛止血，血热兼瘀者用之最宜"},{"q":"与佩兰功效相似而力稍强的药物是","o":["苍术","厚朴","砂仁","广藿香","白豆蔻"],"a":3,"e":"广藿香与佩兰均芳香化湿、解暑，广藿香兼能发表解暑、和中止呕，化湿之力较佩兰稍强。苍术燥湿力强但无解暑，厚朴、砂仁、白豆蔻偏行气，均非与佩兰相似之力强者。广藿香、佩兰皆化湿解暑，藿香兼和胃止呕、发表，其力较佩兰为峻"},{"q":"茵陈是利胆退黄常用药，其主治病证不包括","o":["湿热黄疸","寒湿黄疸","暑湿证","蓄血发黄","湿温证"],"a":3,"e":"茵陈清利湿热、利胆退黄，为治湿热阳黄之要药，配附子、干姜亦治寒湿阴黄，并可用于湿温、暑湿。蓄血发黄属瘀血内停，当用抵当汤类逐瘀，非茵陈所主。茵陈为治黄疸要药，阳黄配栀子、大黄，阴黄配附子、干姜，随证加减"},{"q":"既能养心安神，又能润肠通便的药是","o":["杏仁","桃仁","柏子仁","酸枣仁","郁李仁"],"a":2,"e":"柏子仁养心安神、润肠通便，主治心悸失眠及肠燥便秘。杏仁、桃仁、郁李仁润肠而无养心安神，酸枣仁安神而无润肠之功。柏子仁甘平质润，养心安神、润肠通便，失眠兼肠燥便秘者最宜；酸枣仁安神有余而润肠不足，杏仁、郁李仁则仅润肠"},{"q":"平性药的临床意义在于","o":["多可用做方中君药","可更好纠正寒热之偏","毒副作用相对较小","功擅调和气血","补益作用强"],"a":2,"e":"平性药寒热之性不明显，作用缓和，毒副作用相对较小，适用面广，此为其主要临床意义。多用为君药、专事调和气血、补益力强皆非平性药之必然特点。平性药寒热偏性小，作用和缓适用面广，无寒热之弊，老幼虚实皆可投"},{"q":"具有渗湿利水作用的药味是","o":["涩味","辛味","酸味","咸味","淡味"],"a":4,"e":"淡味能渗、能利，有渗湿利水作用，如茯苓、猪苓、薏苡仁。涩味收敛固涩，辛味发散行气，酸味收敛，咸味软坚泻下，均无渗湿利水之能。淡味渗湿利水，茯苓、猪苓、薏苡仁、冬瓜皮皆淡，治水肿、小便不利"},{"q":"善治肺胃出血的药物是","o":["小蓟","白及","槐花","茜草","三七"],"a":1,"e":"白及质黏，收敛止血、消肿生肌，主入肺胃，善治肺胃出血如咯血、吐血及外伤出血。小蓟、槐花、茜草、三七虽可止血，但无白及之黏敛生肌与肺胃出血专长。白及质黏敛涩，为肺胃出血要药，咯血、吐血及外伤出血皆可并消肿生肌"},{"q":"牡丹皮除清热凉血外，又能","o":["解毒透疹","活血化瘀","润肠通便","利尿通淋","燥湿止痒"],"a":1,"e":"牡丹皮清热凉血、活血化瘀，治温毒发斑、血热吐衄及瘀滞经闭、跌打伤痛。解毒透疹为紫草、升麻之功，润肠通便、利尿通淋、燥湿止痒均非其所有。丹皮辛苦微寒入心肝，清热凉血、活血散瘀，温毒发斑、无汗骨蒸皆治"},{"q":"青光眼患者禁用的药物是","o":["夏枯草","密蒙花","青葙子","决明子","鸭跖草"],"a":2,"e":"青葙子清肝明目、退翳，但有扩瞳作用，可致眼压升高，青光眼患者禁用。夏枯草、密蒙花、决明子、鸭跖草清肝明目而无扩瞳升眼压之弊。青葙子清肝火、退目翳，但能扩瞳升高眼压，青光眼及瞳孔散大者禁服"},{"q":"不属于熟地黄功效的是","o":["补血","滋阴","益精","填髓","益气"],"a":4,"e":"熟地黄补血滋阴、益精填髓，为补血要药，并无益气之功。补血、滋阴、益精、填髓皆其所有，益气当求人参、黄芪一类补气药。熟地甘温，补血滋阴、益精填髓，为虚劳、月经不调、肝肾阴虚要药；然性滋腻碍胃，脾虚食少便溏者当配健脾化湿之品"},{"q":"具有补气安神、止咳平喘功效的安神药是","o":["朱砂","远志","灵芝","首乌藤","酸枣仁"],"a":2,"e":"灵芝补气安神、止咳平喘，主治心神不宁、失眠心悸及虚劳咳喘。朱砂、酸枣仁、首乌藤安神但无补气，远志祛痰开窍，均无止咳平喘双补之效。灵芝甘平，补气安神、止咳平喘，虚劳、失眠、咳喘久病体弱者宜之"},{"q":"治疗风痰眩晕，中风，癫痫，破伤风，应首选的药物是","o":["半夏","瓜蒌","白前","天南星","旋覆花"],"a":3,"e":"天南星燥湿化痰、祛风解痉、散结消肿，善治风痰眩晕、中风癫痫、破伤风。半夏燥湿化痰降逆，瓜蒌、白前、旋覆花化痰降气，均无祛风止痉之长。天南星辛温有毒，燥湿化痰、祛风解痉，风痰眩晕、中风、破伤风皆用"},{"q":"被称为治湿热黄疸之良品，石淋要药的是","o":["茵陈","车前子","虎杖","金钱草","海金沙"],"a":3,"e":"金钱草利湿退黄、利尿通淋、解毒消肿，被誉为治湿热黄疸之良品、石淋要药。茵陈、虎杖退黄而排石力弱，车前子、海金沙利尿通淋，均非黄疸石淋兼顾之品。金钱草甘咸微寒，利湿退黄、通淋排石，为石淋、胆胀、湿热黄疸要药"},{"q":"三棱与莪术的共同主治证是","o":["癥瘕积聚","恶疮癌肿","风湿顽痹","赤白痢疾","跌打损伤"],"a":0,"e":"三棱、莪术均破血行气、消积止痛，共同主治癥瘕积聚、瘀滞经闭腹痛。恶疮癌肿、风湿顽痹、赤白痢疾、跌打损伤皆非二者共同主治。三棱、莪术破血行气、消积止痛，同为癥瘕积聚、瘀阻经闭之要药"},{"q":"既能活血通经，又能凉血止血的药物是","o":["蒲黄","三七","茜草","侧柏叶","白茅根"],"a":2,"e":"茜草凉血止血、活血通经，可治血热吐衄及血滞经闭、跌打瘀肿。蒲黄、三七化瘀止血但无凉血通经之能，侧柏叶、白茅根凉血止血而无活血通经之功。茜草凉血止血、活血通经，吐衄、崩漏、经闭、跌打瘀痛皆可用之"},{"q":"既能祛风散寒，又能除湿止痛的药物是","o":["香薷","荆芥","藁本","葱白","紫苏叶"],"a":2,"e":"藁本祛风散寒、除湿止痛，善治风寒感冒、巅顶头痛及风湿痹痛。香薷、紫苏叶、荆芥、葱白偏于解表，无除湿止痛之效，藁本兼能除湿为其特点。藁本辛温专走巅顶，祛风散寒、除湿止痛，头巅顶痛及风寒湿痹皆治"},{"q":"清热燥湿药的性味是","o":["辛寒","苦寒","甘寒","咸寒","淡寒"],"a":1,"e":"清热燥湿药多属苦寒，苦能燥湿，寒能清热，如黄芩、黄连、黄柏。辛寒、甘寒、咸寒、淡寒或偏发散、或偏补润、或偏软坚渗利，皆非燥湿之性味。苦寒相合既清泄火热又燥化湿邪，黄芩、黄连、黄柏皆然，为清热燥湿正味"},{"q":"治风湿痹痛，带下过多，最宜选用的药物是","o":["防风","苍耳子","羌活","桂枝","白芷"],"a":4,"e":"白芷祛风解表、除湿止痛、通鼻窍、排脓止带，可治风湿痹痛、带下过多。防风、羌活、苍耳子、桂枝祛风解表，均无止带之功，白芷除湿止带独具。白芷辛温，祛风解表、止痛、通鼻窍、排脓止带，阳明头痛带下疮疡皆治"},{"q":"治疗烦躁胸闷，虚烦不眠，首选的药物是","o":["葛根","升麻","牛蒡子","淡豆豉","柴胡"],"a":3,"e":"淡豆豉解表、除烦、宣发郁热，治烦躁胸闷、虚烦不眠，如栀子豉汤。葛根、升麻、柴胡升阳，牛蒡子疏散风热利咽，均无除烦之效。淡豆豉轻宣解表除烦、宣发郁热，外感初起、胸中烦闷、虚烦不眠皆用"},{"q":"诃子涩肠止泻，可用于治疗","o":["脾虚久泻","热毒血痢","湿热泄泻","湿热痢疾","暑湿泄泻"],"a":0,"e":"诃子酸涩，涩肠止泻、敛肺止咳，主治脾虚久泻、久痢脱肛。热毒血痢、湿热泄泻、湿热痢疾、暑湿泄泻皆宜清利，早用收涩反致邪恋。诃子酸涩，涩肠止泻、敛肺止咳，久泻久痢脱肛及肺虚喘咳宜之；湿热未清者早用反致闭门留寇，故湿热痢疾非其所宜"},{"q":"治疗胃寒呕吐，呃逆之要药是","o":["丁香","肉桂","苍术","藿香","花椒"],"a":0,"e":"丁香温中降逆、散寒止痛、温肾助阳，为治胃寒呕吐、呃逆之要药。肉桂温里助阳，苍术燥湿，藿香化湿止呕，花椒温中止痛，均无降逆止呃之专功。丁香味辛性温，温中降逆、散寒止痛，胃寒呕吐、呃逆、脘腹冷痛之要药"},{"q":"治水饮与热邪结聚所致的结胸证，选大黄、芒硝配","o":["甘遂","京大戟","芫花","牵牛子","商陆"],"a":0,"e":"水饮与热邪结聚之结胸证，以大黄、芒硝配甘遂，即大陷胸汤，甘遂峻下逐水、消肿散结。京大戟、芫花、牵牛子、商陆虽能逐水，但非结胸证之常用配伍。甘遂苦寒有毒，峻下逐水、消肿散结，大陷胸汤用之泻水饮热邪之结"},{"q":"炒炭的主要目的是","o":["止泻","止血","止痛","止呕","止痒"],"a":1,"e":"炒炭使药物部分炭化，其性变涩，增强了收敛止血作用，故炒炭主要目的是止血。止泻、止痛、止呕、止痒分别由其他炮制或药物实现，非炒炭之主要目的。药物炒炭后性涩，收敛止血之力增强，如大黄炭、地榆炭、侧柏炭皆然"},{"q":"老年人习惯性便秘，可小量泡服","o":["大黄","芒硝","番泻叶","芦荟","车前子"],"a":2,"e":"番泻叶甘寒，泻热行滞、通便，小量泡服可用于老年人习惯性便秘。大黄、芒硝泻下力强，芦荟峻下，车前子渗湿，均非小量泡服缓泻之品。番泻叶小剂量泡服缓泻，治习惯性便秘、热结便秘，量大则腹痛呕吐"},{"q":"解表生用，止咳平喘宜蜜炙用的药物是","o":["麻黄","桂枝","紫苏叶","生姜","香薷"],"a":0,"e":"麻黄发汗解表、宣肺平喘、利水消肿，解表宜生用，止咳平喘宜蜜炙，蜜炙可缓和发汗、增强平喘。桂枝、紫苏叶、生姜、香薷均无此生用与蜜炙的功效差异。麻黄生用发汗解表力强，蜜炙则发汗缓、平喘增，咳喘表证轻者宜炙用"},{"q":"矮地茶的主治证不包括","o":["咳喘痰多","湿热黄疸","经闭瘀阻","跌打损伤","带下白浊"],"a":4,"e":"矮地茶化痰止咳、清利湿热、活血化瘀，主治咳喘痰多、湿热黄疸、经闭瘀阻、跌打损伤；带下白浊非其主治。矮地茶辛苦平，化痰止咳、清利湿热、活血化瘀，湿热黄疸、跌打瘀肿、经闭瘀阻亦其所主；带下白浊多属湿热下注，非其专治"},{"q":"能温中止痛，又能杀虫止痒的药物是","o":["生姜","干姜","丁香","花椒","小茴香"],"a":3,"e":"花椒温中止痛、杀虫止痒，既治胃寒腹痛，又治湿疹瘙痒、蛲虫病。生姜、干姜温中而无杀虫止痒，丁香、小茴香温里止痛，均无杀虫之用。花椒辛热，温中止痛、杀虫止痒，胃寒冷痛呕吐、湿疹、蛲虫病皆治"},{"q":"妊娠慎用的药物不包括的是","o":["枳实","肉桂","附子","红花","莪术"],"a":4,"e":"莪术破血行气、消积止痛，药力峻猛，属妊娠禁用药而非慎用药，故为不包括项。枳实、肉桂、附子、红花攻伐温烈，均属妊娠慎用之列。莪术破血行气、消积止痛，药力峻猛为妊娠禁用；余药辛烈攻伐属慎用"},{"q":"不具有解毒功效的药物是","o":["山药","甘草","生姜","蜂蜜","白扁豆"],"a":0,"e":"山药补脾养胃、生津益肺、补肾涩精，并无解毒功效。甘草、生姜、蜂蜜、白扁豆均有不同程度的解毒作用，甘草解百毒、生姜解鱼蟹毒、白扁豆解酒毒。山药甘平，补脾肺肾、益气养阴而无解毒之功；甘草、扁豆、蜂蜜、生姜皆能解毒"},{"q":"清热凉血药主归","o":["肺、肝经","肝、肾经","心、脾经","心、肝经","肺、肾经"],"a":3,"e":"清热凉血药主归心、肝经，因心主血脉、肝藏血，血分有热多涉心肝，如生地、丹皮、玄参。肺肝、肝肾、心脾、肺肾等归经组合皆非清热凉血药之主要归属。心主血、肝藏血，血热多归心肝，生地、丹皮、玄参、赤芍皆入心肝经"},{"q":"治血热妄行之吐血、衄血、尿血，宜选用的药物是","o":["夏枯草","决明子","栀子","天花粉","芦根"],"a":2,"e":"栀子泻火除烦、清热利湿、凉血解毒，可治血热妄行之吐血、衄血、尿血。夏枯草、决明子清肝明目，天花粉、芦根清热生津，均无凉血止血之效。栀子苦寒，泻火除烦、凉血解毒、清利湿热，三焦火盛、血热出血、黄疸皆治"},{"q":"不属道地药材的是","o":["河南的地黄","江苏的薄荷","云南的玄参","山东的阿胶","东北的五味子"],"a":2,"e":"玄参道地产地为浙江，云南并非其道地产区，故不属道地药材。河南地黄、江苏薄荷、山东阿胶、东北五味子皆为公认之道地药材。玄参道地产于浙江，河南地黄、江苏薄荷、山东阿胶、东北五味子皆道地"},{"q":"消食药多属渐消缓散之品，适用于病情较缓，积滞不甚者；若食积难消，腹痛便秘，病情较为急重者，宜配伍","o":["理气药","温里药","清热药","攻下药","化湿药"],"a":3,"e":"消食药性缓，若食积难消、腹痛便秘、病情急重者，宜配伍攻下药以泻下通便、荡涤积滞。理气药、温里药、清热药、化湿药皆无峻下逐积之功。食积急重、便秘腹痛者，消食药力缓不济事，须配大黄、枳实等攻下导滞"},{"q":"可用以反映药物在补、泄、散、敛等方面作用特征的是","o":["四气","五味","归经","升降浮沉","毒性"],"a":1,"e":"五味能反映药物补、泄、散、敛等作用特征，如甘补、苦泄、辛散、酸涩收敛。四气示寒热，归经示作用部位，升降浮沉示作用趋向，毒性示安全，均非补泄散敛之特征。辛散、甘补、苦泄、酸收、咸软，五味各主一类作用，故能概括补泄散敛"},{"q":"薄荷与牛蒡子均具有的功效是","o":["透疹","清肝","升阳","解毒","宣肺"],"a":0,"e":"薄荷、牛蒡子均疏散风热、透疹利咽，共治麻疹不透、风热咽痛。清肝、升阳、解毒、宣肺虽为部分解表药所有，但非二者共有之功效。薄荷、牛蒡子均辛凉，疏散风热、透疹利咽，麻疹初起、风热咽痛常相须为用"},{"q":"川楝子配延胡索增强的作用是","o":["行气调中止痛","行气活血止痛","行气通阳散结","行气燥湿化痰","行气解毒消肿"],"a":1,"e":"川楝子行气泄热止痛，延胡索活血行气止痛，二者相配增强行气活血止痛，即金铃子散。行气调中止痛、通阳散结、燥湿化痰、解毒消肿皆非二者配伍之主功。川楝子行气泄热，延胡索活血行气，二药相须，气行血活则痛止，即金铃子散"},{"q":"具有健脾化湿、和中消暑功效，可用于治疗夏月暑湿伤中的药物是","o":["山药","黄芪","党参","藿香","白扁豆"],"a":4,"e":"白扁豆健脾化湿、和中消暑，主治夏月暑湿伤中之吐泻烦渴。山药、党参、黄芪补气而无消暑，藿香化湿解暑而无健脾补益，白扁豆兼顾健脾与消暑。白扁豆甘微温，健脾化湿、和中消暑，夏月暑湿吐泻、脾虚湿盛带下皆宜"},{"q":"覆盆子与鸡内金的共同功效是","o":["消食化积","养肝明目","化石消坚","涩肠止泻","固精缩尿"],"a":4,"e":"覆盆子益肾固精缩尿，鸡内金健胃消食、涩精止遗，二者均能固精缩尿。消食化积、化石消坚为鸡内金独有，养肝明目、涩肠止泻非二者共有。覆盆子益肾固精缩尿，鸡内金涩精止遗，同具固精缩尿之效，遗尿遗精可投"},{"q":"金银花用治热毒所致的咽喉肿痛，主要是因其能","o":["清热解毒","清心利尿","凉血止痢","清解暑热","消痈散结"],"a":0,"e":"金银花清热解毒、疏散风热，治热毒咽喉肿痛正取其清热解毒之功。清心利尿、凉血止痢、清解暑热、消痈散结虽为其兼效，但与咽喉肿痛最相关者为清热解毒。金银花甘寒，清热解毒、疏散风热，咽喉肿痛、温病初起、疮痈皆取解毒之力"},{"q":"鹿茸的用法正确是","o":["先煎久煎","研末冲服","后下泡服","煎汤代水","单煎另煎"],"a":1,"e":"鹿茸为贵重药材，不宜入煎，多研末冲服或入丸散，以保存有效成分。先煎久煎、后下泡服、煎汤代水、单煎另煎皆非鹿茸之常规用法。鹿茸甘咸温，壮肾阳、益精血、强筋骨，贵重宜研末冲服或入丸散，忌入煎剂"},{"q":"马兜铃与枇杷叶共有的功效是","o":["止咳平喘，清胃止呕","清肺化痰，清胃止呕","清肺化痰，利水消肿","清肺化痰，止咳平喘","清肺化痰，清肠消痔"],"a":3,"e":"马兜铃、枇杷叶均能清肺化痰、止咳平喘，共治肺热咳喘。清胃止呕为枇杷叶独有，清肠消痔为马兜铃兼有，利水消肿非二者共有，皆非共有效应。马兜铃、枇杷叶皆清肺化痰、止咳平喘，肺热咳喘常用，马兜铃兼清肠消痔"},{"q":"既能散寒解表，又能宣通鼻窍的药物是","o":["桂枝","紫苏叶","薄荷","羌活","辛夷"],"a":4,"e":"辛夷辛温，发散风寒、宣通鼻窍，主治风寒感冒鼻塞及鼻渊。桂枝、紫苏叶散寒而无通窍，薄荷辛凉，羌活祛风湿，均无宣通鼻窍之专功。辛夷辛温，发散风寒、宣通鼻窍，鼻渊、感冒鼻塞之要药，入煎宜包煎去毛"},{"q":"下列药物除哪项外，均善于滋补肝肾之阴","o":["枸杞子","女贞子","墨旱莲","北沙参","黑芝麻"],"a":3,"e":"北沙参养阴清肺、益胃生津，主入肺胃，无滋补肝肾之阴的作用，故为例外项。枸杞子、女贞子、墨旱莲、黑芝麻均能滋补肝肾之阴。北沙参甘微寒，养阴清肺、益胃生津，主入肺胃，不能滋补肝肾之阴"},{"q":"附子与肉桂共同的功效是","o":["补火助阳，降逆止呕","补火助阳，散寒止痛","补火助阳，回阳救逆","补火助阳，理气止痛","补火助阳，杀虫止痒"],"a":1,"e":"附子、肉桂均补火助阳、散寒止痛，治肾阳不足、寒邪内盛。回阳救逆为附子独有，降逆止呕、理气止痛、杀虫止痒皆非二者共同功效。附子、肉桂皆补火助阳、散寒止痛，附子并能回阳救逆，肉桂兼引火归元"},{"q":"尤长于清中焦湿热的药物是","o":["黄芩","黄连","黄柏","龙胆","苦参"],"a":1,"e":"黄连苦寒，清热燥湿、泻火解毒，尤长于清中焦湿热，治湿热痞满、呕吐泻痢。黄芩偏清上焦，黄柏偏清下焦，龙胆清肝胆实火，苦参祛风杀虫。黄连苦寒入心胃，清热燥湿、泻火解毒，中焦湿热、心火亢盛、胃热呕吐皆治"},{"q":"擅治中焦虚寒性吐血、便血的是","o":["生姜","艾叶","炮姜","地榆","白茅根"],"a":2,"e":"炮姜辛苦温，温中止血、温经止痛，善治中焦虚寒之吐血、便血、崩漏。生姜、干姜温中而止血力弱，艾叶温经止血偏于下焦，地榆、白茅根凉血止血。炮姜辛苦温，温中止血止泻，脾胃虚寒之吐血、便血、崩漏宜之，炒炭止血力增"},{"q":"药性苦燥寒清，治黄疸无论湿热阳黄、寒湿阴黄均为要药的是","o":["金钱草","茵陈","虎杖","车前子","滑石"],"a":1,"e":"茵陈苦燥寒清，清利湿热、利胆退黄，治黄疸无论湿热阳黄、寒湿阴黄皆为要药，阳黄配栀子、阴黄配干姜。金钱草、虎杖、车前子、滑石虽利湿，但非黄疸通用要药。茵陈苦寒清利、利胆退黄，为黄疸要药，湿热阳黄、寒湿阴黄皆可随证配伍"},{"q":"既能杀虫，又有消积行气利水作用的药物是","o":["雷丸","榧子","槟榔","使君子","苦楝皮"],"a":2,"e":"槟榔杀虫消积、行气利水、截疟，既能杀虫，又消积、行气、利水，治绦虫病、食积气滞、水肿脚气。雷丸、榧子、使君子、苦楝皮杀虫，但无消积行气利水之全功。槟榔辛温，杀虫消积、行气利水，绦虫、食积、脚气、水肿皆治，又能截疟"},{"q":"既归心、肝经，能清热凉血，又归肾经，能清透阴分伏热的药物是","o":["水牛角","赤芍","牡丹皮","玄参","紫草"],"a":2,"e":"牡丹皮苦辛微寒，归心、肝、肾经，清热凉血、活血散瘀，且能清透阴分伏热，治温毒发斑、无汗骨蒸。水牛角、赤芍、紫草凉血，玄参滋阴降火，均无透阴分伏热之长。丹皮入心肝而清营血之热，兼入肾经透阴分伏热，温毒、骨蒸、瘀斑皆用"},{"q":"桑白皮的主治证不包括","o":["肺热咳喘","胃热呕逆","水肿尿少","咳血，衄血","肝阳上亢，头晕目眩"],"a":1,"e":"桑白皮泻肺平喘、利水消肿，主治肺热咳喘、水肿尿少及咳血衄血、肝阳上亢头晕目眩；胃热呕逆当用清胃止呕之品，非桑白皮所主。桑白皮泻肺平喘、利水消肿，肺热咳喘、水肿、咳血及肝阳眩晕皆治"},{"q":"胆南星的功效是","o":["燥湿化痰，降逆止呕","燥湿化痰，祛风止痉","清热化痰，息风定惊","清热化痰，除烦止呕","清热化痰，利气宽胸"],"a":2,"e":"胆南星为天南星经牛胆汁拌制而成，性凉，清热化痰、息风定惊，治痰热咳嗽、癫痫惊风。燥湿化痰、降逆止呕、祛风止痉、利气宽胸多为天南星、半夏类功效，非胆南星所主。胆南星苦微寒，清热化痰、息风定惊，痰热咳嗽、癫痫、惊风、眩晕皆用"},{"q":"具有化痰止咳功效的药物是","o":["槐花","白及","白茅根","仙鹤草","侧柏叶"],"a":4,"e":"侧柏叶凉血止血、化痰止咳、生发乌发，其中化痰止咳可用于咳嗽痰多。槐花、白及、白茅根、仙鹤草均能止血，而无化痰止咳之功。侧柏叶苦涩微寒，凉血止血、化痰止咳、生发乌发，血热出血、咳嗽痰多皆治"},{"q":"具平肝息风之功，常与钩藤相须为用，治疗肝风内动、肝阳上亢之证的药是","o":["菊花","天麻","蜈蚣","全蝎","羚羊角"],"a":1,"e":"天麻甘平，平肝息风、止痉通络，常与钩藤相须为用，治肝风内动、肝阳上亢之眩晕头痛。菊花、羚羊角清肝明目，蜈蚣、全蝎息风止痉，均无与钩藤相须为用之配伍特点。天麻甘平，息风止痉、平肝潜阳，与钩藤相须治肝风肝阳之眩晕头痛惊痫"},{"q":"能温胃止呕，散寒止痛的药物是","o":["香薷","藿香","佩兰","苍术","高良姜"],"a":4,"e":"高良姜辛热，温胃止呕、散寒止痛，主治胃寒冷痛、呕吐泄泻。香薷、藿香、佩兰化湿解暑，苍术燥湿健脾，均无温胃止痛止呕之专功。高良姜辛热，温胃散寒、止痛止呕，胃寒冷痛呕吐泄泻宜之，与干姜温中相类"},{"q":"山茱萸的主治病证不包括","o":["阳痿","胃痛泛酸","遗精滑精","遗尿尿频","腰酸耳鸣"],"a":1,"e":"山茱萸酸涩微温，补益肝肾、收涩固脱，主治腰酸耳鸣、阳痿遗精、遗尿尿频及崩漏；胃痛泛酸非其主治，制酸当用煅瓦楞子、海螵蛸。山茱萸酸温，补肝肾、涩精固脱，腰膝酸软、遗精、遗尿、崩漏皆治"},{"q":"桃仁除活血祛瘀外，还能","o":["生肌、敛疮","润肠、止咳","通经、破气","补血、舒筋","利水、杀虫"],"a":1,"e":"桃仁苦平，活血祛瘀、润肠通便、止咳平喘，故除活血祛瘀外还能润肠、止咳。生肌敛疮、通经破气、补血舒筋、利水杀虫皆非桃仁功效。桃仁苦平，活血祛瘀、润肠通便、止咳平喘，瘀血诸证、肠燥便秘、咳嗽皆用"},{"q":"均有涩肠止泻之功的药组是","o":["乌梅、肉豆蔻","乌梅、覆盆子","五味子、覆盆子","五味子、桑螵蛸","桑螵蛸、肉豆蔻"],"a":0,"e":"乌梅、肉豆蔻均能涩肠止泻，治久泻久痢。覆盆子、桑螵蛸固精缩尿，五味子敛肺滋肾、涩精止泻而以敛肺见长，余药组合非皆涩肠止泻。乌梅、肉豆蔻皆涩肠止泻，久泻久痢宜之；覆盆子、桑螵蛸则固精缩尿"},{"q":"利水渗湿作用较强，长久使用时，尤其应注意观察水、电解质平衡是否失调的药物是","o":["茯苓","薏苡仁","猪苓","冬瓜皮","香加皮"],"a":2,"e":"猪苓利水渗湿作用较强，长期或大量使用易致水、电解质失衡，故久用尤须观察。茯苓、薏苡仁利水兼健脾，冬瓜皮利水轻缓，香加皮祛风湿，均无此明显弊端。猪苓甘淡平，利水渗湿力强而无补益，久服易伤津扰电解质，须注意观察"},{"q":"白芍具有的功效是","o":["补益精血，润肠通便","补血养阴，润肺止咳","平抑肝阳，柔肝止痛","养阴润肺，益胃生津","滋阴潜阳，清心除烦"],"a":2,"e":"白芍养血敛阴、柔肝止痛、平抑肝阳，主治肝郁血虚之胁痛腹痛及肝阳上亢头痛。补益精血润肠、补血养阴润肺、养阴润肺益胃、滋阴潜阳清心皆非白芍功效。白芍苦酸微寒，养血敛阴、柔肝止痛、平抑肝阳，血虚肝旺之胁痛腹痛头痛皆治"},{"q":"能治疗热痢，脾虚泄泻的药物是","o":["薄荷","牛蒡子","葛根","升麻","柴胡"],"a":2,"e":"葛根解肌退热、透疹、生津止渴、升阳止泻，煨用能健脾止泻，可治热痢、脾虚泄泻。薄荷、牛蒡子、升麻、柴胡虽升散解表，均无止痢止泻之功。葛根解肌退热、生津、升阳止泻，热痢、脾虚泄泻、项背强痛、消渴皆宜"},{"q":"枇杷叶的功效是","o":["止咳平喘，润肠通便","止咳平喘，清肠消痔","止咳平喘，解痉止痛","润肺下气，消痰止咳","清肺止咳，降逆止呕"],"a":4,"e":"枇杷叶苦寒，清肺止咳、降逆止呕，主治肺热咳嗽及胃热呕逆。润肠通便、清肠消痔、解痉止痛、润肺下气消痰皆非其功效，清肺降逆为其要点。枇杷叶苦寒，清肺止咳、降逆止呕，肺热咳嗽、胃热呕逆皆治，刷去毛免刺喉"},{"q":"中药归经的方法","o":["五色归经法","五味归经法","脏腑经络归经法","质地归经法","形状归经法"],"a":3,"e":"归经的方法之一是按药物质地归类，即质地归经法，如花叶质轻多入上焦肺经，矿石贝壳质重多入下焦肝肾经。脏腑经络归经法以脏腑经络学说为本，五味归经法以辛入肺、甘入脾等对应五脏，五色、形状归经亦属依据药物特性的旁支，各有依据"}];
